def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0:
        return "No Solution"

    # Precompute allowed (non-black) columns per row
    allowed_cols = []
    for r in range(n):
        cols = [c for c in range(n) if grid[r][c] != 'B']
        allowed_cols.append(cols)
        if not cols:  # Impossible if any row has no valid cells
            return "No Solution"

    assigned = [-1] * n  # assigned[row] = column of star, -1 = unassigned
    used_cols = set()

    def backtrack():
        # Return solution if all rows are assigned
        if all(x != -1 for x in assigned):
            res = [[None]*n for _ in range(n)]
            for r in range(n):
                res[r][assigned[r]] = 'S'
            return res

        # MRV heuristic: pick unassigned row with fewest valid options first
        min_options = float('inf')
        selected_row = -1
        for r in range(n):
            if assigned[r] == -1:
                valid_count = 0
                for c in allowed_cols[r]:
                    if c in used_cols:
                        continue
                    # Check adjacency with existing stars
                    valid = True
                    for dr in (-1, 0, 1):
                        nr = r + dr
                        if 0 <= nr < n and assigned[nr] != -1:
                            if abs(c - assigned[nr]) <= 1:
                                valid = False
                                break
                    if valid:
                        valid_count += 1
                if valid_count < min_options:
                    min_options = valid_count
                    selected_row = r
                    if min_options == 0:
                        return None  # No valid options, prune branch

        if selected_row == -1:
            return None

        # Get all valid columns for selected row
        valid_cols = []
        for c in allowed_cols[selected_row]:
            if c in used_cols:
                continue
            valid = True
            for dr in (-1, 0, 1):
                nr = selected_row + dr
                if 0 <= nr < n and assigned[nr] != -1:
                    if abs(c - assigned[nr]) <= 1:
                        valid = False
                        break
            if valid:
                valid_cols.append(c)

        # Try each valid column
        for c in valid_cols:
            assigned[selected_row] = c
            used_cols.add(c)
            solution = backtrack()
            if solution is not None:
                return solution
            # Backtrack
            assigned[selected_row] = -1
            used_cols.remove(c)

        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
