class DSU:
    def __init__(self, elements):
        self.parent = {e: e for e in elements}
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr != yr:
            self.parent[yr] = xr
    def is_all_connected(self):
        roots = set(self.find(e) for e in self.parent)
        return len(roots) == 1

def get_cells_between(u, v):
    r1, c1 = u
    r2, c2 = v
    cells = []
    if r1 == r2:
        min_c, max_c = min(c1, c2), max(c1, c2)
        for c in range(min_c + 1, max_c):
            cells.append((r1, c))
    elif c1 == c2:
        min_r, max_r = min(r1, r2), max(r1, r2)
        for r in range(min_r + 1, max_r):
            cells.append((r, c1))
    return cells

def precompute_neighbors(islands, islands_set, grid_size):
    neighbors = {}
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    for (r, c) in islands:
        nbs = []
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < grid_size and 0 <= nc < grid_size:
                if (nr, nc) in islands_set:
                    nbs.append((nr, nc))
                    break
                nr += dr
                nc += dc
        neighbors[(r, c)] = nbs
    return neighbors

def propagate(remaining, neighbors, bridges, blocked_cells, islands_set):
    changed = True
    while changed:
        changed = False
        for u in list(remaining.keys()):
            rem = remaining[u]
            if rem == 0:
                continue
            possible_edges = []
            total_max = 0
            edge_max = {}
            for v in neighbors[u]:
                edge = tuple(sorted((u, v)))
                curr = bridges.get(edge, 0)
                if curr >= 2:
                    continue
                if not is_bridge_allowed(u, v, blocked_cells, islands_set):
                    continue
                max_add = 2 - curr
                possible_edges.append((edge, v, max_add))
                total_max += max_add
                edge_max[edge] = max_add
            if rem < 0 or rem > total_max:
                return False
            if len(possible_edges) == 0:
                return False
            if rem == total_max:
                for edge, v, add in possible_edges:
                    if add == 0:
                        continue
                    prev = bridges.get(edge, 0)
                    bridges[edge] = prev + add
                    remaining[u] -= add
                    remaining[v] -= add
                    if prev == 0:
                        between = get_cells_between(*edge)
                        blocked_cells.update(between)
                    changed = True
                continue
            if rem == len(possible_edges):
                for edge, v, add in possible_edges:
                    if add < 1:
                        return False
                    prev = bridges.get(edge, 0)
                    if prev == 0:
                        bridges[edge] = 1
                        remaining[u] -= 1
                        remaining[v] -= 1
                        between = get_cells_between(*edge)
                        blocked_cells.update(between)
                        changed = True
                continue
    return True

def is_bridge_allowed(u, v, blocked_cells, islands_set):
    between = get_cells_between(u, v)
    for cell in between:
        if cell in islands_set or cell in blocked_cells:
            return False
    return True

def backtrack(remaining, neighbors, bridges, blocked_cells, islands_set, islands_list):
    valid = propagate(remaining, neighbors, bridges, blocked_cells, islands_set)
    if not valid:
        return None
    all_zero = all(v == 0 for v in remaining.values())
    if all_zero:
        dsu = DSU(islands_list)
        for (u, v) in bridges:
            dsu.union(u, v)
        if dsu.is_all_connected():
            return bridges.copy()
        return None
    candidates = []
    for u in remaining:
