            if not is_bridge_allowed(u, v, blocked_cells, islands_set):
                continue
            max_add = 2 - curr
            candidates.append((remaining[u], edge, u, v, max_add))
    if not candidates:
        return None
    candidates.sort()
    _, edge, u, v, max_add = candidates[0]
    prev_count = bridges.get(edge, 0)
    for add in range(1, max_add + 1):
        bridges[edge] = prev_count + add
        remaining[u] -= add
        remaining[v] -= add
        added_blocked = []
        if prev_count == 0:
