                blocked_cells.remove(cell)
        remaining[u] += add
        remaining[v] += add
    if prev_count == 0:
        if edge in bridges:
            del bridges[edge]
    else:
        bridges[edge] = prev_count
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    islands = []
    islands_set = set()
    remaining = {}
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                pos = (r, c)
                islands.append(pos)
                islands_set.add(pos)
                remaining[pos] = val
    if not islands:
        return {}
    neighbors = precompute_neighbors(islands, islands_set, n)
    bridges = {}
    blocked_cells = set()
    result = backtrack(remaining, neighbors, bridges, blocked_cells, islands_set, islands)
    return result if result is not None else "No Solution"

