from copy import deepcopy

def solve(observation):
    grid = observation['data']
    N = len(grid)
    if N == 0:
        return "No Solution"

    def get_adjacent(r, c):
        adj = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                adj.append((nr, nc))
        return adj

    def get_line_of_sight(r, c):
        los = [(r, c)]
        # Left
        curr_c = c - 1
        while curr_c >= 0:
            if grid[r][curr_c] is not None:
                break
            los.append((r, curr_c))
            curr_c -= 1
        # Right
        curr_c = c + 1
        while curr_c < N:
            if grid[r][curr_c] is not None:
                break
            los.append((r, curr_c))
            curr_c += 1
        # Up
        curr_r = r - 1
        while curr_r >= 0:
            if grid[curr_r][c] is not None:
                break
            los.append((curr_r, c))
            curr_r -= 1
        # Down
        curr_r = r + 1
        while curr_r < N:
            if grid[curr_r][c] is not None:
                break
            los.append((curr_r, c))
            curr_r += 1
        return los

    def is_valid_solution(bulbs):
        # Check rule 3: no bulb illuminates another
        for r in range(N):
            for c in range(N):
                if bulbs[r][c] is True:
                    los = get_line_of_sight(r, c)
                    for (lr, lc) in los:
                        if (lr != r or lc != c) and bulbs[lr][lc] is True:
                            return False
        # Check rule 4: numbered cells have correct adjacent bulbs
        for r in range(N):
            for c in range(N):
                val = grid[r][c]
                if val is None:
                    continue
                adj = get_adjacent(r, c)
                cnt = sum(1 for (ar, ac) in adj if bulbs[ar][ac] is True)
                if cnt != val:
                    return False
        # Check rule 1: all white cells are illuminated
        for r in range(N):
            for c in range(N):
                if grid[r][c] is not None:
                    continue
                illuminated = False
                for br in range(N):
                    for bc in range(N):
                        if bulbs[br][bc] is True:
                            if (r, c) in get_line_of_sight(br, bc):
                                illuminated = True
                                break
                    if illuminated:
                        break
                if not illuminated:
                    return False
        return True

    def apply_deductions(bulbs, forbidden):
        changed = True
        while changed:
            changed = False
            # Process numbered black cells
            for r in range(N):
                for c in range(N):
                    val = grid[r][c]
                    if val is None:
                        continue
                    adj = get_adjacent(r, c)
                    existing = 0
                    possible = []
                    for (ar, ac) in adj:
                        if bulbs[ar][ac] is True:
                            existing += 1
                        elif bulbs[ar][ac] is None and not forbidden[ar][ac]:
                            possible.append((ar, ac))
                    if existing > val:
                        return (bulbs, forbidden, False)
                    needed = val - existing
                    if needed < 0:
                        return (bulbs, forbidden, False)
                    # Place all possible if needed equals count
                    if needed == len(possible) and needed > 0:
                        for (pr, pc) in possible:
                            if bulbs[pr][pc] is True:
                                continue
                            if bulbs[pr][pc] is False or forbidden[pr][pc]:
                                return (bulbs, forbidden, False)
                            bulbs[pr][pc] = True
                            changed = True
                            # Mark LOS as forbidden
