                            for (lr, lc) in los:
                                if lr == pr and lc == pc:
                                    continue
                                if bulbs[lr][lc] is True:
                                    return (bulbs, forbidden, False)
                                if bulbs[lr][lc] is None:
                                    bulbs[lr][lc] = False
                                    forbidden[lr][lc] = True
                        continue
                    # Mark all possible as forbidden if no more needed
                    if needed == 0 and len(possible) > 0:
                        for (pr, pc) in possible:
                            if bulbs[pr][pc] is None:
                                bulbs[pr][pc] = False
                                forbidden[pr][pc] = True
                                changed = True
                        continue
            # Process cells that need illumination, only one possible bulb position
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is not None:
                        continue
                    if bulbs[r][c] is True:
                        continue
                    # Check if already illuminated
                    illuminated = False
                    for br in range(N):
                        for bc in range(N):
                            if bulbs[br][bc] is True:
                                if (r, c) in get_line_of_sight(br, bc):
                                    illuminated = True
                                    break
                        if illuminated:
                            break
                    if illuminated:
