                    # Same row right
                    curr_c = c + 1
                    while curr_c < N:
                        if grid[r][curr_c] is not None:
                            break
                        if bulbs[r][curr_c] is None and not forbidden[r][curr_c]:
                            possible.append((r, curr_c))
                        curr_c += 1
                    # Same column up
                    curr_r = r - 1
                    while curr_r >= 0:
                        if grid[curr_r][c] is not None:
                            break
                        if bulbs[curr_r][c] is None and not forbidden[curr_r][c]:
                            possible.append((curr_r, c))
                        curr_r -= 1
                    # Same column down
                    curr_r = r + 1
                    while curr_r < N:
                        if grid[curr_r][c] is not None:
                            break
                        if bulbs[curr_r][c] is None and not forbidden[curr_r][c]:
                            possible.append((curr_r, c))
                        curr_r += 1
                    # Self position
                    if bulbs[r][c] is None and not forbidden[r][c]:
                        possible.append((r, c))
                    possible = list(set(possible))
                    if len(possible) == 0:
                        return (bulbs, forbidden, False)
                    if len(possible) == 1:
                        pr, pc = possible[0]
                        if bulbs[pr][pc] is True:
                            continue
                        if bulbs[pr][pc] is False or forbidden[pr][pc]:
                            return (bulbs, forbidden, False)
                        bulbs[pr][pc] = True
                        changed = True
