                        for (lr, lc) in los:
                            if lr == pr and lc == pc:
                                continue
                            if bulbs[lr][lc] is True:
                                return (bulbs, forbidden, False)
                            if bulbs[lr][lc] is None:
                                bulbs[lr][lc] = False
                                forbidden[lr][lc] = True
        return (bulbs, forbidden, True)

    def backtrack(bulbs, forbidden):
        bulbs, forbidden, valid = apply_deductions(bulbs, forbidden)
        if not valid:
            return None
        # Check if all decided
        undecided = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and bulbs[r][c] is None and not forbidden[r][c]:
                    undecided.append((r, c))
        if not undecided:
            if is_valid_solution(bulbs):
                return bulbs
            return None
        # MRV heuristic: pick first undecided
        r, c = undecided[0]
        # Try placing bulb
        if not forbidden[r][c] and bulbs[r][c] is None:
            new_bulbs = deepcopy(bulbs)
            new_forbidden = deepcopy(forbidden)
            new_bulbs[r][c] = True
            conflict = False
            los = get_line_of_sight(r, c)
            for (lr, lc) in los:
                if lr == r and lc == c:
                    continue
                if new_bulbs[lr][lc] is True:
                    conflict = True
                    break
                if new_bulbs[lr][lc] is None:
                    new_bulbs[lr][lc] = False
                    new_forbidden[lr][lc] = True
            if not conflict:
                res = backtrack(new_bulbs, new_forbidden)
                if res is not None:
                    return res
        # Try not placing bulb
        new_bulbs = deepcopy(bulbs)
        new_forbidden = deepcopy(forbidden)
        new_bulbs[r][c] = False
        new_forbidden[r][c] = True
        res = backtrack(new_bulbs, new_forbidden)
        return res

    # Initial setup
    bulbs = [[None for _ in range(N)] for _ in range(N)]
    forbidden = [[False for _ in range(N)] for _ in range(N)]

    # Initial deduction pass
    bulbs, forbidden, valid = apply_deductions(bulbs, forbidden)
    if not valid:
        return "No Solution"

    # Check if already solved
    solved = True
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None and bulbs[r][c] is None:
                solved = False
                break
        if not solved:
            break
    if solved:
        if is_valid_solution(bulbs):
            output = [[None for _ in range(N)] for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    if bulbs[r][c] is True:
                        output[r][c] = 'B'
            return output
        return "No Solution"

    # Backtrack
    final_bulbs = backtrack(bulbs, forbidden)
    if final_bulbs is None:
        return "No Solution"

    # Convert to output format
    output = [[None for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if final_bulbs[r][c] is True:
                output[r][c] = 'B'
    return output

