import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    adj_set = set(tuple(p) for p in observation['adjacent'])

    # Initialize domain of possible values for each cell
    domains = []
    for i in range(N):
        row = []
        for j in range(N):
