        domains.append(row)

    def propagate(doms):
        """Apply all constraints iteratively until no more pruning possible"""
        changed = True
        while changed:
            changed = False

            # Constraint 1: Row uniqueness
            for i in range(N):
                used = set()
                for j in range(N):
                    if len(doms[i][j]) == 1:
                        used.add(next(iter(doms[i][j])))
                for j in range(N):
                    if len(doms[i][j]) > 1:
                        old = doms[i][j].copy()
                        doms[i][j] -= used
                        if not doms[i][j]:
                            return doms, False
                        if doms[i][j] != old:
                            changed = True

            # Constraint 2: Column uniqueness
            for j in range(N):
                used = set()
                for i in range(N):
                    if len(doms[i][j]) == 1:
                        used.add(next(iter(doms[i][j])))
                for i in range(N):
                    if len(doms[i][j]) > 1:
                        old = doms[i][j].copy()
                        doms[i][j] -= used
                        if not doms[i][j]:
