                    gap = (i, j + 0.5)
                    d1, d2 = doms[i][j], doms[i][j+1]
                    if gap in adj_set:
                        # Require consecutive values
                        new_d1 = {v for v in d1 if any(abs(v - u) == 1 for u in d2)}
                        new_d2 = {u for u in d2 if any(abs(v - u) == 1 for v in d1)}
                    else:
                        # Require non-consecutive values
                        new_d1 = {v for v in d1 if all(abs(v - u) != 1 for u in d2)}
                        new_d2 = {u for u in d2 if all(abs(v - u) != 1 for v in d1)}
                    if not new_d1 or not new_d2:
                        return doms, False
                    if new_d1 != d1:
                        doms[i][j] = new_d1
                        changed = True
                    if new_d2 != d2:
                        doms[i][j+1] = new_d2
                        changed = True

            # Constraint 4: Vertical adjacency rules
            for j in range(N):
                for i in range(N-1):
                    gap = (i + 0.5, j)
                    d1, d2 = doms[i][j], doms[i+1][j]
                    if gap in adj_set:
                        new_d1 = {v for v in d1 if any(abs(v - u) == 1 for u in d2)}
                        new_d2 = {u for u in d2 if any(abs(v - u) == 1 for v in d1)}
