        doms, valid = propagate(doms)
        if not valid:
            return None
        if is_solved(doms):
            return [[next(iter(doms[i][j])) for j in range(N)] for i in range(N)]

        # Select cell with minimum remaining values (MRV heuristic)
        min_len = float('inf')
        cell = None
        for i in range(N):
