            if min_len == 2:
                break
        i, j = cell

        # Try each possible value for the selected cell
        for val in sorted(doms[i][j]):
            new_doms = copy.deepcopy(doms)
            new_doms[i][j] = {val}
            res = backtrack(new_doms)
            if res is not None:
                return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
