def get_visible_cells(r, c, grid, n):
    visible = set()
    # Same row left
    for nc in range(c, -1, -1):
        if is_black(grid, r, nc):
            break
        visible.add((r, nc))
    # Same row right
    for nc in range(c + 1, n):
        if is_black(grid, r, nc):
            break
        visible.add((r, nc))
    # Same column up
    for nr in range(r, -1, -1):
        if is_black(grid, nr, c):
            break
        visible.add((nr, c))
    # Same column down
    for nr in range(r + 1, n):
        if is_black(grid, nr, c):
            break
        visible.add((nr, c))
    return visible

def get_possible_bulb_positions_for_cell(target_r, target_c, grid, n, forbidden):
