        if (r, c) not in forbidden:
            possible.add((r, c))
    # Check column down
    for r in range(target_r + 1, n):
        if is_black(grid, r, c):
            break
        if (r, c) not in forbidden:
            possible.add((r, c))
    return list(possible)

