from collections import deque
import copy

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    islands = []
    required = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val is not None:
                pos = (r, c)
                islands.append(pos)
                required[pos] = val
    if not islands:
        return "No Solution"

    neighbors = {pos: [] for pos in islands}
    for (r, c) in islands:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] is not None:
                    npos = (nr, nc)
                    if npos not in neighbors[(r,c)]:
                        neighbors[(r,c)].append(npos)
                    break
                nr += dr
                nc += dc

    possible_pairs = set()
    for a in islands:
        for b in neighbors[a]:
            if a < b:
                possible_pairs.add((a, b))

    def propagate(bridge_counts, remaining):
        while True:
            changed = False
            for pos in islands:
                rem = remaining[pos]
                if rem < 0:
                    return False
                pairs = [p for p in bridge_counts if pos in p]
                used = sum(bridge_counts[p] for p in pairs)
                rem = required[pos] - used
                remaining[pos] = rem
                if rem < 0:
                    return False
                max_add = sum(2 - bridge_counts[p] for p in pairs)
                if max_add < rem:
                    return False
                if rem == max_add and max_add > 0:
                    for p in pairs:
                        add = 2 - bridge_counts[p]
                        if add <= 0:
                            continue
                        bridge_counts[p] += add
                        changed = True
                        other = p[0] if p[1] == pos else p[1]
                        remaining[pos] -= add
                        remaining[other] -= add
                        if remaining[pos] < 0 or remaining[other] < 0:
                            return False
                available = [p for p in pairs if bridge_counts[p] < 2]
                if len(available) == rem and rem > 0:
                    for p in available:
                        if bridge_counts[p] >= 2:
                            continue
                        bridge_counts[p] += 1
                        changed = True
                        other = p[0] if p[1] == pos else p[1]
                        remaining[pos] -= 1
                        remaining[other] -= 1
                        if remaining[pos] < 0 or remaining[other] < 0:
                            return False
            if not changed:
                break
        return True

    def is_connected(bridge_counts):
        adj = {pos: [] for pos in islands}
        for (a, b), cnt in bridge_counts.items():
            if cnt > 0:
                adj[a].append(b)
                adj[b].append(a)
        visited = set()
        q = deque([islands[0]])
        visited.add(islands[0])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        return len(visited) == len(islands)

    def backtrack(bridge_counts, remaining):
        valid = propagate(bridge_counts, remaining)
        if not valid:
            return None
        all_zero = all(v == 0 for v in remaining.values())
        if all_zero:
            if is_connected(bridge_counts):
                res = {}
                for k, v in bridge_counts.items():
                    if v > 0:
                        res[k] = v
                return res
            return None
        candidates = []
        for p in possible_pairs:
            cnt = bridge_counts[p]
            if cnt >= 2:
                continue
            rem_a = remaining[p[0]]
            rem_b = remaining[p[1]]
            if rem_a <= 0 or rem_b <= 0:
                continue
            max_possible = min(2 - cnt, rem_a, rem_b)
            if max_possible <= 0:
                continue
            candidates.append((max_possible, p))
        if not candidates:
            return None
        candidates.sort()
        _, best_p = candidates[0]
        a, b = best_p
        max_cnt = min(2 - bridge_counts[best_p], remaining[a], remaining[b])
        for try_cnt in range(1, max_cnt + 1):
            new_bridges = copy.deepcopy(bridge_counts)
            new_remaining = copy.deepcopy(remaining)
            new_bridges[best_p] += try_cnt
            new_remaining[a] -= try_cnt
            new_remaining[b] -= try_cnt
            res = backtrack(new_bridges, new_remaining)
            if res is not None:
                return res
        return None

    initial_bridges = {p:0 for p in possible_pairs}
    initial_remaining = {pos: required[pos] for pos in islands}
    solution = backtrack(initial_bridges, initial_remaining)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
