            break
        illuminated[nr][nc] = True
        forbidden[nr][nc] = True
        nr -= 1
    # Down direction
    nr, nc = r + 1, c
    while nr < n:
        if grid[nr][nc] is not None:
            break
        illuminated[nr][nc] = True
        forbidden[nr][nc] = True
        nr += 1
    # Left direction
    nr, nc = r, c - 1
    while nc >= 0:
        if grid[nr][nc] is not None:
            break
        illuminated[nr][nc] = True
        forbidden[nr][nc] = True
        nc -= 1
    # Right direction
    nr, nc = r, c + 1
    while nc < n:
        if grid[nr][nc] is not None:
            break
        illuminated[nr][nc] = True
