                    return False
                # Place required bulbs if remaining matches available count
                if remaining == len(available) and remaining > 0:
                    for (nr, nc) in available:
                        if not bulbs[nr][nc]:
                            bulbs[nr][nc] = True
                            changed = True
                            mark_bulb_effects(nr, nc, grid, bulbs, forbidden, illuminated)
                # Mark remaining adjacent as forbidden if quota met
                if bulb_count == val:
