    for r in range(N):
        row_cells = [(r, c) for c in range(N)]
        for i in range(N):
            for j in range(i+1, N):
                a, b = row_cells[i], row_cells[j]
                constraints.append((a, b, lambda x,y: x != y))
                constraints.append((b, a, lambda x,y: x != y))
    for c in range(N):
        col_cells = [(r, c) for r in range(N)]
        for i in range(N):
            for j in range(i+1, N):
                a, b = col_cells[i], col_cells[j]
                constraints.append((a, b, lambda x,y: x != y))
                constraints.append((b, a, lambda x,y: x != y))
    # 2. Consecutive/non-consecutive constraints for orthogonal adjacent cells
    dirs = [(0,1), (1,0)] # right and down to avoid duplicate pairs
    for r in range(N):
        for c in range(N):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if nr >= N or nc >= N:
                    continue
                # Get midpoint
                if dr == 0: # horizontal adjacent: mid (r, c + 0.5)
                    mid = (float(r), float(c) + 0.5)
                else: # vertical adjacent: mid (r + 0.5, c)
                    mid = (float(r) + 0.5, float(c))
                a, b = (r,c), (nr, nc)
                if mid in adj_set:
                    # Must be consecutive
                    constraints.append((a, b, lambda x,y: abs(x - y) == 1))
                    constraints.append((b, a, lambda x,y: abs(x - y) == 1))
                else:
                    # Must NOT be consecutive
                    constraints.append((a, b, lambda x,y: abs(x - y) != 1))
                    constraints.append((b, a, lambda x,y: abs(x - y) != 1))

    # AC3 Constraint propagation
    def ac3(doms):
        q = deque(constraints)
        while q:
            a, b, cond = q.popleft()
            revised = False
            # Iterate over copy of a's domain to avoid modification during iteration
            for val_a in list(doms[a]):
                valid = any(cond(val_a, val_b) for val_b in doms[b])
                if not valid:
                    doms[a].remove(val_a)
                    revised = True
                    if not doms[a]:
                        return False # empty domain, no solution
            if revised:
                # Add all arcs pointing to a back to queue
                for na, nb, ncond in constraints:
                    if nb == a:
                        q.append((na, nb, ncond))
        return True

    # Initial AC3 run
    if not ac3(domains):
        return "No Solution"

    # Check if already solved
    def is_solved(doms):
        for cell in doms:
            if len(doms[cell]) != 1:
                return False
        return True

    if is_solved(domains):
        res = [[0]*N for _ in range(N)]
        for (r,c), s in domains.items():
            res[r][c] = next(iter(s))
        return res

    # MRV heuristic: pick cell with smallest domain size
    def select_cell(doms):
        min_size = float('inf')
        selected = None
        for cell in doms:
            sz = len(doms[cell])
            if sz > 1 and sz < min_size:
                min_size = sz
                selected = cell
        return selected

    # Least constraining value heuristic: sort values by how many options they leave for neighbors
    def order_values(cell, doms):
        r,c = cell
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0<=nr<N and 0<=nc<N:
                neighbors.append((nr, nc))
        val_scores = []
        for val in doms[cell]:
            count = 0
            for n in neighbors:
                for nval in doms[n]:
                    # Check all constraints between cell and n
                    valid = True
                    for a,b,cond in constraints:
                        if a == cell and b == n:
                            if not cond(val, nval):
                                valid = False
                                break
                    if valid:
                        count +=1
            val_scores.append((-count, val)) # sort by -count to get least constraining first
        val_scores.sort()
        return [v for (s,v) in val_scores]

    # Backtracking search
    def backtrack(doms):
        if is_solved(doms):
            res = [[0]*N for _ in range(N)]
            for (r,c), s in doms.items():
                res[r][c] = next(iter(s))
            return res
        cell = select_cell(doms)
        for val in order_values(cell, doms):
            # Create copy of domains
            new_doms = {k: set(v) for k,v in doms.items()}
            new_doms[cell] = {val}
            if ac3(new_doms):
                res = backtrack(new_doms)
                if res is not None:
                    return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

