OBSERVATION = {"data": [[None, 4, None, None, 1], [None, None, 8, None, None], [None, 6, 9, None, 5], [None, None, 6, None, None], [1, None, None, None, 3]]}

import copy
from collections import deque

def get_neighborhood(r, c, rows, cols):
    res = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                res.append((nr, nc))
    return res

def propagate(grid, rows, cols, clues, cell_to_clues):
    q = deque(range(len(clues)))
    while q:
        clue_idx = q.popleft()
        _, _, target, neigh = clues[clue_idx]
        cnt_b = 0
        unknown_cells = []
        for (x, y) in neigh:
            val = grid[x][y]
            if val == 'B':
                cnt_b += 1
            elif val is None:
                unknown_cells.append((x, y))
        cnt_unknown = len(unknown_cells)

        if cnt_b > target or cnt_b + cnt_unknown < target:
            return (False, None)

        if cnt_unknown == target - cnt_b:
            for (x, y) in unknown_cells:
                if grid[x][y] is None:
                    grid[x][y] = 'B'
                    for ci in cell_to_clues[(x, y)]:
                        q.append(ci)

        if cnt_b == target:
            for (x, y) in unknown_cells:
                if grid[x][y] is None:
                    grid[x][y] = 'W'
                    for ci in cell_to_clues[(x, y)]:
                        q.append(ci)
    return (True, grid)

def is_solved(grid):
    return all(cell is not None for row in grid for cell in row)

def select_guess_cell(grid, rows, cols, cell_to_clues):
    max_clues = -1
    best = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                cnt = len(cell_to_clues[(r, c)])
                if cnt > max_clues:
                    max_clues = cnt
                    best = (r, c)
    return best

def backtrack(grid, rows, cols, clues, cell_to_clues):
    valid, grid = propagate(grid, rows, cols, clues, cell_to_clues)
    if not valid:
        return None
    if is_solved(grid):
        for (_, _, target, neigh) in clues:
            if sum(1 for (x,y) in neigh if grid[x][y] == 'B') != target:
                return None
        return grid
    r, c = select_guess_cell(grid, rows, cols, cell_to_clues)
    for val in ('B', 'W'):
        new_grid = copy.deepcopy(grid)
        new_grid[r][c] = val
        res = backtrack(new_grid, rows, cols, clues, cell_to_clues)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return "No Solution"
    cols = len(data[0])
    clues = []
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                clues.append((r, c, val, get_neighborhood(r, c, rows, cols)))
    cell_to_clues = {(r,c): [] for r in range(rows) for c in range(cols)}
    for idx, (_, _, _, neigh) in enumerate(clues):
        for (x,y) in neigh:
            cell_to_clues[(x,y)].append(idx)
    initial_grid = [[None for _ in range(cols)] for _ in range(rows)]
    sol = backtrack(initial_grid, rows, cols, clues, cell_to_clues)
    if not sol:
        return "No Solution"
    return [['B' if cell == 'B' else None for cell in row] for row in sol]

if __name__ == "__main__":
    print(solve(OBSERVATION))
