def propagate_constraints(grid):
    N = len(grid)
    changed = True
    while changed:
        changed = False
        # Iterate all 2x2 blocks to apply 3-same rule
        for i in range(N-1):
            for j in range(N-1):
                cells = [(i,j), (i,j+1), (i+1,j), (i+1,j+1)]
                values = [grid[x][y] for x,y in cells]
                count_b = values.count('B')
                count_w = values.count('W')
                # 3 Bs -> remaining is W
                if count_b == 3 and count_w == 0:
                    for idx in range(4):
                        if values[idx] is None:
                            x, y = cells[idx]
                            grid[x][y] = 'W'
                            changed = True
                # 3 Ws -> remaining is B
                elif count_w == 3 and count_b == 0:
                    for idx in range(4):
                        if values[idx] is None:
                            x, y = cells[idx]
                            grid[x][y] = 'B'
                            changed = True
                # Immediate contradiction if 4 same
                elif count_b == 4 or count_w == 4:
                    return False, grid
    # Final check for all 2x2 blocks for contradictions
    for i in range(N-1):
        for j in range(N-1):
            vals = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if len(vals) == 1 and None not in vals:
                return False, grid
    return True, grid

def is_connected(grid, color):
    N = len(grid)
    # Find first cell of target color
    start = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == color:
                start = (i, j)
                break
        if start:
            break
    if not start:
        return True  # No cells of color, trivially connected
    # BFS to check connectedness
    visited = set([start])
    q = [start]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        x, y = q.pop(0)
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited and grid[nx][ny] == color:
                visited.add((nx, ny))
                q.append((nx, ny))
    # Compare visited count to total cells of color
    total_cells = sum(row.count(color) for row in grid)
    return len(visited) == total_cells

def is_complete(grid):
    return all(None not in row for row in grid)

def select_mrv_cell(grid):
    N = len(grid)
    min_options = 3  # Max possible options is 2, so initial value is higher
    best_cell = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] is None:
                options = 0
                # Check if B is valid
                grid[i][j] = 'B'
                valid_b = True
                for dx in (-1, 0):
                    for dy in (-1, 0):
                        x, y = i + dx, j + dy
                        if 0 <= x < N-1 and 0 <= y < N-1:
                            vals = {grid[x][y], grid[x][y+1], grid[x+1][y], grid[x+1][y+1]}
                            if len(vals) == 1:
                                valid_b = False
                                break
                    if not valid_b:
                        break
                if valid_b:
                    options += 1
                # Check if W is valid
                grid[i][j] = 'W'
                valid_w = True
                for dx in (-1, 0):
                    for dy in (-1, 0):
                        x, y = i + dx, j + dy
                        if 0 <= x < N-1 and 0 <= y < N-1:
                            vals = {grid[x][y], grid[x][y+1], grid[x+1][y], grid[x+1][y+1]}
                            if len(vals) == 1:
                                valid_w = False
                                break
                    if not valid_w:
                        break
                if valid_w:
                    options += 1
                # Reset cell
                grid[i][j] = None
                # Update MRV
                if options < min_options:
                    min_options = options
                    best_cell = (i, j)
                    if min_options == 1:  # Can't get better than 1 option
                        return best_cell
    return best_cell

def backtrack(grid):
    N = len(grid)
    # First run constraint propagation to fill deterministic cells
    valid, grid = propagate_constraints(grid)
    if not valid:
        return None
    # Check if grid is complete and valid
    if is_complete(grid):
        if is_connected(grid, 'B') and is_connected(grid, 'W'):
            return grid
        return None
    # Select most constrained cell (MRV heuristic)
    i, j = select_mrv_cell(grid)
    # Heuristic: try color with fewer existing cells first to aid connectedness
    count_b = sum(row.count('B') for row in grid)
    count_w = sum(row.count('W') for row in grid)
    color_order = ['B', 'W'] if count_b < count_w else ['W', 'B']
    for color in color_order:
        # Create copy of grid to avoid modifying original
        new_grid = [row.copy() for row in grid]
        new_grid[i][j] = color
        # Immediate 2x2 violation check
        valid = True
        for dx in (-1, 0):
            for dy in (-1, 0):
                x, y = i + dx, j + dy
                if 0 <= x < N-1 and 0 <= y < N-1:
                    vals = {new_grid[x][y], new_grid[x][y+1], new_grid[x+1][y], new_grid[x+1][y+1]}
                    if len(vals) == 1:
                        valid = False
                        break
            if not valid:
                break
        if not valid:
            continue
        # Recursive search
        solution = backtrack(new_grid)
        if solution is not None:
            return solution
    return None

def solve(observation):
    initial_grid = [row.copy() for row in observation['data']]
    result = backtrack(initial_grid)
    return result if result is not None else "No Solution"

