def solve(observation):
    grid_clues = observation['data']
    rows = len(grid_clues)
    cols = len(grid_clues[0]) if rows > 0 else 0

    def get_neighbors(r, c):
        neighbors = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbors.append((nr, nc))
        return neighbors

    def deduce(sol):
        changed = True
        while changed:
            changed = False
            for r in range(rows):
                for c in range(cols):
                    clue = grid_clues[r][c]
                    if clue is None:
                        continue
                    neighbors = get_neighbors(r, c)
                    flag_count = 0
                    unknowns = []
                    for (nr, nc) in neighbors:
                        if sol[nr][nc] == 'F':
                            flag_count += 1
                        elif sol[nr][nc] is None:
                            unknowns.append((nr, nc))
                    if flag_count > clue:
                        return False, sol
                    if flag_count + len(unknowns) < clue:
                        return False, sol
                    if flag_count == clue:
                        for (nr, nc) in unknowns:
                            sol[nr][nc] = 'S'
                            changed = True
                    elif flag_count + len(unknowns) == clue:
                        for (nr, nc) in unknowns:
                            sol[nr][nc] = 'F'
                            changed = True
        for r in range(rows):
            for c in range(cols):
                clue = grid_clues[r][c]
                if clue is None:
                    continue
                neighbors = get_neighbors(r, c)
                flag_count = sum(1 for (x,y) in neighbors if sol[x][y] == 'F')
                unknown_count = sum(1 for (x,y) in neighbors if sol[x][y] is None)
                if flag_count > clue or (flag_count + unknown_count < clue):
                    return False, sol
        return True, sol

    def backtrack(sol):
        valid, sol = deduce(sol)
        if not valid:
            return None
        unknowns = []
        for r in range(rows):
            for c in range(cols):
                if sol[r][c] is None:
                    unknowns.append((r, c))
        if not unknowns:
            return sol
        best_cell = None
        min_possible = float('inf')
        for (r,c) in unknowns:
            adj_min = 2
            for (nr, nc) in get_neighbors(r,c):
                if grid_clues[nr][nc] is not None:
                    n_neighbors = get_neighbors(nr, nc)
                    flag_cnt = sum(1 for (x,y) in n_neighbors if sol[x][y] == 'F')
                    rem = grid_clues[nr][nc] - flag_cnt
                    if rem < adj_min:
                        adj_min = rem
            if adj_min < min_possible:
                min_possible = adj_min
                best_cell = (r,c)
        r, c = best_cell
        sol_mine = [row.copy() for row in sol]
        sol_mine[r][c] = 'F'
        res_mine = backtrack(sol_mine)
        if res_mine is not None:
            return res_mine
        sol_safe = [row.copy() for row in sol]
        sol_safe[r][c] = 'S'
        res_safe = backtrack(sol_safe)
        return res_safe

    initial_sol = [[None for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid_clues[r][c] is not None:
                initial_sol[r][c] = 'S'
    solved = backtrack(initial_sol)
    if solved is None:
        return "No Solution"
    output = []
    for row in solved:
        out_row = []
        for cell in row:
            out_row.append('F' if cell == 'F' else None)
        output.append(out_row)
    return output

