    'col_water_counts': [1, 4, 3, 2, 2, 2, 5, 5, 8, 3]
}

def solve(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']
    R = len(row_target)
    C = len(col_target)

    # Preprocess regions: map id to list of (row, col) sorted descending by row (bottom first)
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))
    for rid in regions:
        regions[rid].sort(reverse=True, key=lambda x: x[0])  # bottom cells first

    region_ids = list(regions.keys())
    region_size = {rid: len(cells) for rid, cells in regions.items()}

    # Precompute for each region, for each possible h, which cells are water
    region_water_cells = {rid: [set() for _ in range(region_size[rid]+1)] for rid in region_ids}
    for rid in region_ids:
        cells = regions[rid]
        for h in range(1, region_size[rid]+1):
            region_water_cells[rid][h] = region_water_cells[rid][h-1].copy()
            region_water_cells[rid][h].add(cells[h-1])

    # Precompute for each row/column, which regions are present
    row_regions = [set() for _ in range(R)]
    col_regions = [set() for _ in range(C)]
    for rid in region_ids:
        for (r, c) in regions[rid]:
            row_regions[r].add(rid)
            col_regions[c].add(rid)

    def propagate(min_h, max_h):
        changed = True
        while changed:
            changed = False

            # Calculate min/max count per row
            row_min = [0]*R
            row_max = [0]*R
            for r in range(R):
                for rid in row_regions[r]:
                    cnt_min = sum(1 for (rr, cc) in regions[rid] if rr == r and (rr, cc) in region_water_cells[rid][min_h[rid]])
                    cnt_max = sum(1 for (rr, cc) in regions[rid] if rr == r and (rr, cc) in region_water_cells[rid][max_h[rid]])
                    row_min[r] += cnt_min
                    row_max[r] += cnt_max
                if row_min[r] > row_target[r] or row_max[r] < row_target[r]:
                    return False  # invalid

            # Calculate min/max count per column
            col_min = [0]*C
            col_max = [0]*C
            for c in range(C):
                for rid in col_regions[c]:
                    cnt_min = sum(1 for (rr, cc) in regions[rid] if cc == c and (rr, cc) in region_water_cells[rid][min_h[rid]])
                    cnt_max = sum(1 for (rr, cc) in regions[rid] if cc == c and (rr, cc) in region_water_cells[rid][max_h[rid]])
                    col_min[c] += cnt_min
                    col_max[c] += cnt_max
                if col_min[c] > col_target[c] or col_max[c] < col_target[c]:
                    return False  # invalid

            # Update region min/max based on row constraints
            for r in range(R):
                if row_min[r] == row_target[r]:
                    # No more water can be added to this row, so for all regions in row, max_h can't include any cells in this row or above
                    for rid in row_regions[r]:
                        cells_in_region_above_or_eq = sum(1 for (rr, cc) in regions[rid] if rr >= r)
                        new_max = min(max_h[rid], cells_in_region_above_or_eq - 1) if r < R else max_h[rid]
                        for h in range(max_h[rid], new_max, -1):
                            if any(rr == r for (rr, cc) in region_water_cells[rid][h]):
                                new_max = min(new_max, h-1)
                        if new_max < max_h[rid]:
                            max_h[rid] = new_max
                            changed = True
                            if min_h[rid] > max_h[rid]:
                                return False
                if row_max[r] == row_target[r]:
                    # All possible water is added, so min_h must include all cells in this row that are in max possible
                    for rid in row_regions[r]:
                        cells_in_region_below_or_eq = sum(1 for (rr, cc) in regions[rid] if rr <= r)
                        new_min = max(min_h[rid], cells_in_region_below_or_eq)
                        if new_min > min_h[rid]:
                            min_h[rid] = new_min
                            changed = True
                            if min_h[rid] > max_h[rid]:
                                return False

            # Update region min/max based on column constraints
            for c in range(C):
                if col_min[c] == col_target[c]:
                    for rid in col_regions[c]:
                        new_max = max_h[rid]
                        for h in range(max_h[rid], min_h[rid], -1):
                            if any(cc == c for (rr, cc) in region_water_cells[rid][h] - region_water_cells[rid][min_h[rid]]):
                                new_max = h-1
                                break
                        if new_max < max_h[rid]:
                            max_h[rid] = new_max
                            changed = True
                            if min_h[rid] > max_h[rid]:
                                return False
                if col_max[c] == col_target[c]:
                    for rid in col_regions[c]:
                        new_min = min_h[rid]
                        for h in range(min_h[rid], max_h[rid]+1):
                            if all(cc == c for (rr, cc) in region_water_cells[rid][max_h[rid]] - region_water_cells[rid][h]):
                                new_min = h
                                break
                        if new_min > min_h[rid]:
                            min_h[rid] = new_min
                            changed = True
                            if min_h[rid] > max_h[rid]:
                                return False

            # Clamp min and max
            for rid in region_ids:
                min_h[rid] = max(0, min_h[rid])
                max_h[rid] = min(region_size[rid], max_h[rid])
                if min_h[rid] > max_h[rid]:
                    return False
        return True

    def backtrack(min_h, max_h):
        if not propagate(min_h, max_h):
            return None

        # Check if all regions are fixed
        all_fixed = True
        for rid in region_ids:
            if min_h[rid] != max_h[rid]:
                all_fixed = False
                break
        if all_fixed:
            # Build solution
            grid = [[None for _ in range(C)] for _ in range(R)]
            for rid in region_ids:
                h = min_h[rid]
                for (r, c) in region_water_cells[rid][h]:
                    grid[r][c] = 'W'
            # Verify counts
            row_counts = [sum(1 for c in range(C) if grid[r][c] == 'W') for r in range(R)]
            col_counts = [sum(1 for r in range(R) if grid[r][c] == 'W') for c in range(C)]
            if row_counts == row_target and col_counts == col_target:
                return grid
            else:
                return None

        # Pick region with smallest domain
        candidate = None
        min_range = float('inf')
        for rid in region_ids:
            rng = max_h[rid] - min_h[rid]
            if rng > 0 and rng < min_range:
                min_range = rng
                candidate = rid

        # Try all possible values for candidate
        for h in range(min_h[candidate], max_h[candidate]+1):
            new_min = min_h.copy()
            new_max = max_h.copy()
            new_min[candidate] = h
            new_max[candidate] = h
            res = backtrack(new_min, new_max)
            if res is not None:
                return res
        return None

    # Initial min and max h for each region
    initial_min = {rid: 0 for rid in region_ids}
    initial_max = {rid: region_size[rid] for rid in region_ids}
    solution = backtrack(initial_min, initial_max)
    if not solution:
        return "No Solution"
    # Format to string output as required
    return '\n'.join(''.join(c if c == 'W' else '.' for c in row) for row in solution)

if __name__ == "__main__":
    print(solve(OBSERVATION))
