from collections import deque

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0

    def get_neighbors(r, c):
        neighbors = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbors.append((nr, nc))
        return neighbors

    def propagate(known, flags):
        k = [row[:] for row in known]
        f = [row[:] for row in flags]
        q = deque()
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is not None:
                    q.append((r, c))
        while q:
            r, c = q.popleft()
            clue = data[r][c]
            if clue is None:
                continue
            count_F = 0
            count_U = 0
            neighbors = get_neighbors(r, c)
            for nr, nc in neighbors:
                if k[nr][nc]:
                    count_F += 1 if f[nr][nc] else 0
                else:
                    count_U += 1
            remaining = clue - count_F
            if remaining < 0 or remaining > count_U:
                return (False, None, None)
            if remaining == count_U and count_U > 0:
                for nr, nc in neighbors:
                    if not k[nr][nc]:
                        k[nr][nc] = True
                        f[nr][nc] = True
                        for nnr, nnc in get_neighbors(nr, nc):
                            if data[nnr][nnc] is not None:
                                q.append((nnr, nnc))
            if remaining == 0 and count_U > 0:
                for nr, nc in neighbors:
                    if not k[nr][nc]:
                        k[nr][nc] = True
                        f[nr][nc] = False
                        for nnr, nnc in get_neighbors(nr, nc):
                            if data[nnr][nnc] is not None:
                                q.append((nnr, nnc))
        return (True, k, f)

    def is_complete(known):
        for r in range(rows):
            for c in range(cols):
                if not known[r][c]:
                    return False
        return True

    def select_cell(known):
        min_branch = float('inf')
        best_cell = None
        for r in range(rows):
            for c in range(cols):
                if not known[r][c]:
                    neighbors = get_neighbors(r, c)
                    for nr, nc in neighbors:
                        if data[nr][nc] is not None:
                            cnt_u = 0
                            for nnr, nnc in get_neighbors(nr, nc):
                                if not known[nnr][nnc]:
                                    cnt_u +=1
                            if cnt_u < min_branch:
                                min_branch = cnt_u
                                best_cell = (r,c)
        if best_cell is None:
            for r in range(rows):
                for c in range(cols):
                    if not known[r][c]:
                        return (r,c)
        return best_cell

    def backtrack(known, flags):
        valid, new_k, new_f = propagate(known, flags)
        if not valid:
            return None
        if is_complete(new_k):
            return new_f
        r, c = select_cell(new_k)
        # Try flag mine first
        gk1 = [row[:] for row in new_k]
        gf1 = [row[:] for row in new_f]
        gk1[r][c] = True
        gf1[r][c] = True
        res = backtrack(gk1, gf1)
        if res is not None:
            return res
        # Try safe cell
        gk2 = [row[:] for row in new_k]
        gf2 = [row[:] for row in new_f]
        gk2[r][c] = True
        gf2[r][c] = False
        return backtrack(gk2, gf2)

    initial_known = [[False]*cols for _ in range(rows)]
    initial_flags = [[False]*cols for _ in range(rows)]
    valid, start_k, start_f = propagate(initial_known, initial_flags)
    if not valid:
        return "No Solution"
    final_flags = backtrack(start_k, start_f)
    if final_flags is None:
        return "No Solution"
    ans = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('F' if final_flags[r][c] else None)
        ans.append(row)
    return ans

if __name__ == "__main__":
    print(solve(OBSERVATION))
