def get_connected_components(grid, color):
    n = len(grid)
    visited = set()
    components = []
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == color and (i,j) not in visited:
                q = [(i,j)]
                visited.add((i,j))
                comp = {(i,j)}
                while q:
                    x,y = q.pop(0)
                    for dx, dy in dirs:
                        nx, ny = x+dx, y+dy
                        if 0<=nx<n and 0<=ny<n and (nx,ny) not in visited and grid[nx][ny] == color:
                            visited.add((nx, ny))
                            comp.add((nx, ny))
                            q.append((nx, ny))
                components.append(comp)
    return components

def can_connect(grid, comp1, comp2, color):
    n = len(grid)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    visited = set()
    q = list(comp1)
    for pos in comp1:
        visited.add(pos)
    target = set(comp2)
    while q:
        x,y = q.pop(0)
        if (x,y) in target:
            return True
        for dx, dy in dirs:
            nx, ny = x+dx, y+dy
            if 0<=nx<n and 0<=ny<n and (nx,ny) not in visited:
                if grid[nx][ny] == color or grid[nx][ny] is None:
                    visited.add((nx, ny))
                    q.append((nx, ny))
    return False

def is_valid_partial(grid):
    n = len(grid)
    # Check no existing 2x2 monochromatic blocks
    for i in range(n-1):
        for j in range(n-1):
            vals = [grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]]
            if None not in vals:
                if all(v == 'B' for v in vals) or all(v == 'W' for v in vals):
                    return False
    # Check B components can be connected
    b_comps = get_connected_components(grid, 'B')
    for i in range(len(b_comps)):
        for j in range(i+1, len(b_comps)):
            if not can_connect(grid, b_comps[i], b_comps[j], 'B'):
                return False
    # Check W components can be connected
    w_comps = get_connected_components(grid, 'W')
    for i in range(len(w_comps)):
        for j in range(i+1, len(w_comps)):
            if not can_connect(grid, w_comps[i], w_comps[j], 'W'):
                return False
    return True

def apply_forced_moves(grid):
    n = len(grid)
    dirs_2x2 = [(0,0), (0,1), (1,0), (1,1)]
    changed = True
    while changed:
        changed = False
        for i in range(n-1):
            for j in range(n-1):
                cells = [(i+dx, j+dy) for dx, dy in dirs_2x2]
                vals = [grid[x][y] for x,y in cells]
                b_cnt = vals.count('B')
                w_cnt = vals.count('W')
                none_cnt = vals.count(None)
                if b_cnt == 4 or w_cnt == 4:
                    return False
                if none_cnt == 1:
                    idx = vals.index(None)
                    x,y = cells[idx]
                    if b_cnt == 3:
                        if grid[x][y] is None:
