    # Apply all forced moves first
    if not apply_forced_moves(grid):
        return None
    # Check if grid is fully filled
    all_filled = True
    empty_cells = []
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] is None:
                all_filled = False
                # Count filled neighbors to sort by constraint level
                neighbor_cnt = 0
                for dx, dy in dirs:
                    nx, ny = i+dx, j+dy
                    if 0<=nx<n and 0<=ny<n and grid[nx][ny] is not None:
                        neighbor_cnt += 1
                empty_cells.append((-neighbor_cnt, i, j))
    if all_filled:
        # Verify all final constraints
        if len(get_connected_components(grid, 'B')) != 1:
            return None
        if len(get_connected_components(grid, 'W')) != 1:
            return None
        return [row.copy() for row in grid]
    # Pick most constrained empty cell first
    empty_cells.sort()
    _, i, j = empty_cells[0]
    # Try both colors
    for color in ['B', 'W']:
        new_grid = [row.copy() for row in grid]
        new_grid[i][j] = color
        if is_valid_partial(new_grid):
            res = backtrack(new_grid)
            if res is not None:
                return res
    return None

def solve(observation):
