OBSERVATION = {"data": [[None, None, None, 1, None], [None, 2, 3, 4, None], [None, 3, 6, 6, None], [None, 5, None, 8, None], [None, None, 6, None, None]]}

def get_neighbors(r, c, rows, cols):
    """Return all valid cells in 3x3 neighborhood of (r,c) including itself"""
    neighbors = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                neighbors.append((nr, nc))
    return neighbors

def propagate(grid, numbered_cells, rows, cols):
    """Apply constraint propagation repeatedly until no more changes or invalid state found"""
    changed = True
    while changed:
        changed = False
        for (r, c, target) in numbered_cells:
            neighbors = get_neighbors(r, c, rows, cols)
            b_count = 0
            unknown_cells = []
            for (nr, nc) in neighbors:
                if grid[nr][nc] == 1:
                    b_count += 1
                elif grid[nr][nc] == 0:
                    unknown_cells.append((nr, nc))
            # Check for invalid state
            if b_count > target:
                return (False, grid)
            if b_count + len(unknown_cells) < target:
                return (False, grid)
            # All unknown cells must be black to reach target
            if b_count + len(unknown_cells) == target:
                for (nr, nc) in unknown_cells:
                    grid[nr][nc] = 1
                    changed = True
            # All unknown cells must be white as we already have enough blacks
            if b_count == target:
                for (nr, nc) in unknown_cells:
                    grid[nr][nc] = 2
                    changed = True
    return (True, grid)

def backtrack(grid, numbered_cells, rows, cols):
    """Backtracking with MRV heuristic to minimize branching factor"""
    # First run propagation to eliminate impossible options
    valid, updated_grid = propagate(grid, numbered_cells, rows, cols)
    if not valid:
        return None
    # Check if grid is fully solved
    is_solved = True
    for r in range(rows):
        for c in range(cols):
            if updated_grid[r][c] == 0:
                is_solved = False
                break
        if not is_solved:
            break
    if is_solved:
        return updated_grid
    # Select most constrained unknown cell (appears in most numbered cell neighborhoods)
    max_constraint_count = -1
    best_cell = None
    for r in range(rows):
        for c in range(cols):
            if updated_grid[r][c] == 0:
                constraint_cnt = 0
                for (nr, nc, _) in numbered_cells:
                    if abs(r - nr) <= 1 and abs(c - nc) <= 1:
                        constraint_cnt += 1
                if constraint_cnt > max_constraint_count:
                    max_constraint_count = constraint_cnt
                    best_cell = (r, c)
    if not best_cell:
        return None
    r_guess, c_guess = best_cell
    # Try black first
    grid_try_b = [row.copy() for row in updated_grid]
    grid_try_b[r_guess][c_guess] = 1
    res_b = backtrack(grid_try_b, numbered_cells, rows, cols)
    if res_b:
        return res_b
    # Try white
    grid_try_w = [row.copy() for row in updated_grid]
    grid_try_w[r_guess][c_guess] = 2
    res_w = backtrack(grid_try_w, numbered_cells, rows, cols)
    return res_w

def solve(observation):
    grid_data = observation["data"]
    rows = len(grid_data)
    if rows == 0:
        return []
    cols = len(grid_data[0])
    # Extract all numbered cells once for efficiency
    numbered_cells = []
    for r in range(rows):
        for c in range(cols):
            val = grid_data[r][c]
            if val is not None:
                numbered_cells.append((r, c, val))
    # Initialize internal grid: 0 = unknown, 1 = black, 2 = white
    initial_grid = [[0 for _ in range(cols)] for _ in range(rows)]
    solved_grid = backtrack(initial_grid, numbered_cells, rows, cols)
    if not solved_grid:
        return "No Solution"
    # Convert to required output format
    output_grid = []
    for r in range(rows):
        output_row = []
        for c in range(cols):
            output_row.append('B' if solved_grid[r][c] == 1 else None)
        output_grid.append(output_row)
    return output_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))
