                    if (val == 'B' and cnt_b_r >= half) or (val == 'W' and cnt_w_r >= half):
                        continue
                    # Check count constraints for column
                    cnt_b_c = sum(1 for i in range(n) if g[i][c] == 'B')
                    cnt_w_c = sum(1 for i in range(n) if g[i][c] == 'W')
                    if (val == 'B' and cnt_b_c >= half) or (val == 'W' and cnt_w_c >= half):
                        continue
                    # Check row consecutive constraints
                    valid = True
                    if c >= 2 and g[r][c-1] == g[r][c-2] == val:
                        valid = False
                    if c <= n-3 and g[r][c+1] == g[r][c+2] == val:
                        valid = False
                    if 1 <= c <= n-2 and g[r][c-1] == g[r][c+1] == val:
                        valid = False
                    if not valid:
                        continue
                    # Check column consecutive constraints
                    if r >= 2 and g[r-1][c] == g[r-2][c] == val:
                        valid = False
                    if r <= n-3 and g[r+1][c] == g[r+2][c] == val:
                        valid = False
                    if 1 <= r <= n-2 and g[r-1][c] == g[r+1][c] == val:
                        valid = False
                    if valid:
                        options.append(val)
                if len(options) == 0:
                    return None
                if len(options) < min_options:
                    min_options = len(options)
                    best_cell = (r, c)
                    best_options = options
                    if min_options == 1:
                        break
            if min_options == 1:
                break
        # Try all valid options for best cell
        r, c = best_cell
        for val in best_options:
            new_grid = [row.copy() for row in g]
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res is not None:
                return res
        return None

    result = backtrack(grid)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
