def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    N = len(data)
    if N == 0:
        return "No Solution"

    # Preprocess adjacency information
    adj_info = {}
    for (y, x) in adjacent:
        if y == int(y):  # Horizontal gap between cells in same row
            r = int(y)
            c_left = int(x - 0.5)
            c_right = c_left + 1
            pair = frozenset({(r, c_left), (r, c_right)})
            adj_info[pair] = True
        else:  # Vertical gap between cells in same column
            c = int(x)
            r_top = int(y - 0.5)
            r_bottom = r_top + 1
            pair = frozenset({(r_top, c), (r_bottom, c)})
            adj_info[pair] = True

    # Add all other orthogonal adjacent pairs as no dot
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                pair = frozenset({(r, c), (r, c+1)})
                if pair not in adj_info:
                    adj_info[pair] = False
            if r + 1 < N:
                pair = frozenset({(r, c), (r+1, c)})
                if pair not in adj_info:
                    adj_info[pair] = False

    # Initialize domain of possible values for each cell
    domains = [[set() for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c].add(data[r][c])
            else:
                domains[r][c] = set(range(1, N+1))

    def propagate(doms):
        """Apply all constraints to reduce domains, return (new_domains, is_valid)"""
        new_doms = [[set(s) for s in row] for row in doms]
        from collections import deque
        q = deque()

        # Initialize queue with cells that have fixed values
        for r in range(N):
            for c in range(N):
                if len(new_doms[r][c]) == 1:
                    q.append((r, c))

        # Process queue for fixed value constraints
        while q:
            r, c = q.popleft()
            val = next(iter(new_doms[r][c]))

            # Remove value from all other cells in same row
            for col in range(N):
                if col == c:
                    continue
                if val in new_doms[r][col]:
                    new_doms[r][col].remove(val)
                    if len(new_doms[r][col]) == 0:
                        return (new_doms, False)
                    if len(new_doms[r][col]) == 1:
                        q.append((r, col))

            # Remove value from all other cells in same column
            for row in range(N):
                if row == r:
                    continue
                if val in new_doms[row][c]:
                    new_doms[row][c].remove(val)
                    if len(new_doms[row][c]) == 0:
                        return (new_doms, False)
                    if len(new_doms[row][c]) == 1:
                        q.append((row, c))

            # Process adjacent cell constraints
            neighbors = []
            if r > 0:
                neighbors.append((r-1, c))
            if r < N-1:
                neighbors.append((r+1, c))
            if c > 0:
                neighbors.append((r, c-1))
            if c < N-1:
                neighbors.append((r, c+1))

            for (nr, nc) in neighbors:
                pair = frozenset({(r, c), (nr, nc)})
                has_dot = adj_info[pair]
                n_dom = new_doms[nr][nc]

                if has_dot:
                    allowed = {val - 1, val + 1}
                    new_n_dom = n_dom & allowed
                else:
                    forbidden = {val - 1, val + 1}
                    new_n_dom = n_dom - forbidden

                if new_n_dom != n_dom:
                    new_doms[nr][nc] = new_n_dom
                    if len(new_n_dom) == 0:
                        return (new_doms, False)
                    if len(new_n_dom) == 1:
                        q.append((nr, nc))

        # Process pairwise consistency for all adjacent pairs
        changed = True
        while changed:
            changed = False
            for pair, has_dot in adj_info.items():
                (r1, c1), (r2, c2) = tuple(pair)
                d1 = new_doms[r1][c1]
                d2 = new_doms[r2][c2]

                # Filter domain of first cell
                new_d1 = set()
                for v in d1:
                    if has_dot:
                        if (v + 1 in d2) or (v - 1 in d2):
                            new_d1.add(v)
                    else:
                        if (v + 1 not in d2) and (v - 1 not in d2):
                            new_d1.add(v)
                if new_d1 != d1:
                    changed = True
                    new_doms[r1][c1] = new_d1
                    if len(new_d1) == 0:
                        return (new_doms, False)
                    if len(new_d1) == 1:
                        q.append((r1, c1))

                # Filter domain of second cell
                new_d2 = set()
                for v in d2:
                    if has_dot:
                        if (v + 1 in d1) or (v - 1 in d1):
                            new_d2.add(v)
                    else:
                        if (v + 1 not in d1) and (v - 1 not in d1):
                            new_d2.add(v)
                if new_d2 != d2:
                    changed = True
                    new_doms[r2][c2] = new_d2
                    if len(new_d2) == 0:
                        return (new_doms, False)
                    if len(new_d2) == 1:
                        q.append((r2, c2))

            # Process any new fixed values from pairwise filtering
            while q:
                r, c = q.popleft()
                val = next(iter(new_doms[r][c]))
                # Same row elimination
                for col in range(N):
                    if col == c:
                        continue
                    if val in new_doms[r][col]:
                        new_doms[r][col].remove(val)
                        if len(new_doms[r][col]) == 0:
                            return (new_doms, False)
                        if len(new_doms[r][col]) == 1:
                            q.append((r, col))
                # Same column elimination
                for row in range(N):
                    if row == r:
                        continue
                    if val in new_doms[row][c]:
                        new_doms[row][c].remove(val)
                        if len(new_doms[row][c]) == 0:
                            return (new_doms, False)
                        if len(new_doms[row][c]) == 1:
                            q.append((row, c))
                # Neighbor constraint processing
                neighbors = []
                if r > 0: neighbors.append((r-1, c))
                if r < N-1: neighbors.append((r+1, c))
                if c > 0: neighbors.append((r, c-1))
                if c < N-1: neighbors.append((r, c+1))
                for (nr, nc) in neighbors:
                    pair = frozenset({(r,c), (nr, nc)})
                    has_dot = adj_info[pair]
                    n_dom = new_doms[nr][nc]
                    if has_dot:
                        allowed = {val-1, val+1}
                        new_n_dom = n_dom & allowed
                    else:
                        forbidden = {val-1, val+1}
                        new_n_dom = n_dom - forbidden
                    if new_n_dom != n_dom:
                        new_doms[nr][nc] = new_n_dom
                        if len(new_n_dom) == 0:
                            return (new_doms, False)
                        if len(new_n_dom) == 1:
                            q.append((nr, nc))

        return (new_doms, True)

    # Initial propagation
    domains, valid = propagate(domains)
    if not valid:
        return "No Solution"

    def is_solved(doms):
        """Check if all cells have exactly one possible value"""
        for r in range(N):
            for c in range(N):
                if len(doms[r][c]) != 1:
                    return False
        return True

    if is_solved(domains):
        res = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(next(iter(domains[r][c])))
            res.append(row)
        return res

    def backtrack(doms):
        """Backtracking search with MRV heuristic"""
        # Find cell with smallest domain size > 1 (MRV heuristic)
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                s = len(doms[r][c])
                if s > 1 and s < min_size:
                    min_size = s
                    best_cell = (r, c)
                    if min_size == 2:  # Can't get smaller than 2, early exit
                        break
            if min_size == 2:
                break

        if best_cell is None:
            if is_solved(doms):
                res = []
                for r in range(N):
                    row = []
                    for c in range(N):
                        row.append(next(iter(doms[r][c])))
                    res.append(row)
                return res
            return None

        r, c = best_cell
        # Try each possible value for the cell
        for val in doms[r][c]:
            new_doms = [[set(s) for s in row] for row in doms]
            new_doms[r][c] = {val}
            propagated_doms, valid = propagate(new_doms)
            if not valid:
                continue
            solution = backtrack(propagated_doms)
            if solution is not None:
                return solution
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
