import copy

def solve(observation):
    data = observation['data']
    n = len(data)
    adj_list = observation['adjacent']

    # Build adjacency set of cell pairs
    adj_set = set()
    for coord in adj_list:
        y, x = coord
        if y.is_integer():
            # Horizontal gap: same row
            r = int(y)
            c1 = int(x - 0.5)
            c2 = c1 + 1
            adj_set.add(frozenset({(r, c1), (r, c2)}))
        else:
            # Vertical gap: same column
            c = int(x)
            r1 = int(y - 0.5)
            r2 = r1 + 1
            adj_set.add(frozenset({(r1, c), (r2, c)}))

    # Precompute adjacent cells for each cell
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    adj_cells = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    adj_cells[r][c].append((nr, nc))

    # Initialize possible values
    possible = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                possible[r][c] = {val}

    def propagate(poss):
        while True:
            changed = False
            # Row uniqueness constraint
            for r in range(n):
                fixed = set()
                for c in range(n):
                    if len(poss[r][c]) == 1:
                        fixed.add(next(iter(poss[r][c])))
                for c in range(n):
                    if len(poss[r][c]) > 1:
                        remove = poss[r][c] & fixed
                        if remove:
                            poss[r][c] -= remove
                            changed = True
                            if not poss[r][c]:
                                return False
            # Column uniqueness constraint
            for c in range(n):
                fixed = set()
                for r in range(n):
                    if len(poss[r][c]) == 1:
                        fixed.add(next(iter(poss[r][c])))
                for r in range(n):
                    if len(poss[r][c]) > 1:
                        remove = poss[r][c] & fixed
                        if remove:
                            poss[r][c] -= remove
                            changed = True
                            if not poss[r][c]:
                                return False
            # Adjacency constraints
            for r in range(n):
                for c in range(n):
                    curr = poss[r][c]
                    if not curr:
                        return False
                    for (nr, nc) in adj_cells[r][c]:
                        nb = poss[nr][nc]
                        if not nb:
                            return False
                        pair = frozenset({(r,c), (nr, nc)})
                        has_dot = pair in adj_set
                        valid = set()
                        if has_dot:
                            # Values must be consecutive
                            for val in curr:
                                if (val + 1 in nb) or (val - 1 in nb):
                                    valid.add(val)
                        else:
                            # Values must NOT be consecutive
                            for val in curr:
                                if any(abs(val - nb_val) != 1 for nb_val in nb):
                                    valid.add(val)
                        if valid != curr:
                            poss[r][c] = valid
                            changed = True
                            if not poss[r][c]:
                                return False
            if not changed:
                break
        # Final check for empty possible sets
        for r in range(n):
            for c in range(n):
                if not poss[r][c]:
                    return False
        return True

    def is_solved(poss):
        for r in range(n):
            for c in range(n):
                if len(poss[r][c]) != 1:
                    return False
        return True

    def get_grid(poss):
        grid = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append(next(iter(poss[r][c])))
            grid.append(row)
        return grid

    def backtrack(poss):
        if not propagate(poss):
            return None
        if is_solved(poss):
            return get_grid(poss)
        # Select cell with Minimum Remaining Values (MRV) heuristic
        min_len = float('inf')
        best_cell = None
        for r in range(n):
            for c in range(n):
                l = len(poss[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    best_cell = (r, c)
                    if min_len == 2: # Early exit, can't get smaller than 2
                        break
            if min_len == 2:
                break
        r, c = best_cell
        # Try each possible value for selected cell
        for val in sorted(poss[r][c]):
            new_poss = copy.deepcopy(poss)
            new_poss[r][c] = {val}
            res = backtrack(new_poss)
            if res is not None:
                return res
        return None

    result = backtrack(possible)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
