OBSERVATION = {'data': [[2, None, None, None, None, None, 2], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, 2], [None, None, None, None, None, None, None], [5, None, None, None, None, None, 3], [None, None, None, None, None, None, None], [4, None, None, None, 3, None, 2]]}

from copy import deepcopy

def solve(observation):
    data = observation['data']
    N = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                pos_to_idx[(r,c)] = len(islands)
                islands.append((r,c, data[r][c]))
    if not islands:
        return {}

    # Precompute all candidate edges (sorted to avoid duplicates)
    candidate_edges = set()
    dirs = [(0,1), (1,0), (0,-1), (-1,0)]
    for idx, (r,c, val) in enumerate(islands):
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                if data[nr][nc] is not None:
                    u = (r,c)
                    v = (nr, nc)
                    if u < v:
                        candidate_edges.add((u, v))
                    break
                nr += dr
                nc += dc
    candidate_edges = list(candidate_edges)

    # Initial state
    remaining = {(r,c): val for r,c,val in islands}
    edges_count = {e:0 for e in candidate_edges}
    occupied = [[False for _ in range(N)] for _ in range(N)]

    def is_valid_edge(u, v):
        r1,c1 = u
        r2,c2 = v
        if r1 == r2:
            r = r1
            minc, maxc = min(c1,c2), max(c1,c2)
            for c in range(minc+1, maxc):
                if occupied[r][c]:
                    return False
        else:
            c = c1
            minr, maxr = min(r1,r2), max(r1,r2)
            for r in range(minr+1, maxr):
                if occupied[r][c]:
                    return False
        return True

    def add_bridge(e, cnt):
        u, v = e
        r1,c1 = u
        r2,c2 = v
        edges_count[e] += cnt
        remaining[u] -= cnt
        remaining[v] -= cnt
        if r1 == r2:
            r = r1
            minc, maxc = min(c1,c2), max(c1,c2)
            for c in range(minc+1, maxc):
                occupied[r][c] = True
        else:
            c = c1
            minr, maxr = min(r1,r2), max(r1,r2)
            for r in range(minr+1, maxr):
                occupied[r][c] = True

    def remove_bridge(e, cnt):
        u, v = e
        r1,c1 = u
        r2,c2 = v
        edges_count[e] -= cnt
        remaining[u] += cnt
        remaining[v] += cnt
        if r1 == r2:
            r = r1
            minc, maxc = min(c1,c2), max(c1,c2)
            for c in range(minc+1, maxc):
                occupied[r][c] = False
        else:
            c = c1
            minr, maxr = min(r1,r2), max(r1,r2)
            for r in range(minr+1, maxr):
                occupied[r][c] = False

    def apply_deductions():
        changed = True
        while changed:
            changed = False
            # Check if any remaining is negative
            for pos in remaining:
                if remaining[pos] < 0:
                    return False
            # Get available edges per island
            avail_edges = {pos:[] for pos in remaining}
            for e in candidate_edges:
                u, v = e
                if edges_count[e] < 2 and is_valid_edge(u, v):
                    avail_edges[u].append(e)
                    avail_edges[v].append(e)
            # Check if any island has remaining > 2 * available edges: invalid
            for pos in remaining:
                if remaining[pos] > 2 * len(avail_edges[pos]):
                    return False
            # Rule 1: remaining == 2 * len(avail_edges): add 2 to all
            for pos in remaining:
                rem = remaining[pos]
                edges = avail_edges[pos]
                if rem == 2 * len(edges) and rem > 0:
                    for e in edges:
                        if edges_count[e] == 0:
                            add_bridge(e, 2)
                            changed = True
                    if changed:
                        break
            if changed:
                continue
            # Rule 2: remaining == len(avail_edges): add 1 to all
            for pos in remaining:
                rem = remaining[pos]
                edges = avail_edges[pos]
                if rem == len(edges) and rem > 0:
                    for e in edges:
                        if edges_count[e] == 0:
                            add_bridge(e, 1)
                            changed = True
                    if changed:
                        break
            if changed:
                continue
            # Rule 3: edge max possible is min(rem u, rem v, 2 - current count)
            for e in candidate_edges:
                u, v = e
                curr = edges_count[e]
                if curr >= 2:
                    continue
                max_possible = min(remaining[u], remaining[v], 2 - curr)
                if max_possible <= 0:
                    continue
                # If only 1 possible, add it
                if max_possible == 1 and curr == 0:
                    add_bridge(e, 1)
                    changed = True
                    break
            if changed:
                continue
        return True

    # Check connectivity
    def is_connected():
        adj = {pos:[] for pos in remaining}
        for e, cnt in edges_count.items():
            if cnt > 0:
                u, v = e
                adj[u].append(v)
                adj[v].append(u)
        start = next(iter(adj.keys()))
        visited = set()
        stack = [start]
        visited.add(start)
        while stack:
            pos = stack.pop()
            for neighbor in adj[pos]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
        return len(visited) == len(islands)

    # Backtracking function
    def backtrack():
        # Apply deductions first
        if not apply_deductions():
            return None
        # Check if all remaining are zero
        all_zero = all(v == 0 for v in remaining.values())
        if all_zero:
            if is_connected():
                return {e: cnt for e, cnt in edges_count.items() if cnt > 0}
            else:
                return None
        # Find next edge to guess: pick edge with least possible options
        candidate = None
        min_options = 3
        for e in candidate_edges:
            u, v = e
            curr = edges_count[e]
            if curr >= 2:
                continue
            if not is_valid_edge(u, v):
                continue
            max_possible = min(remaining[u], remaining[v], 2 - curr)
            if max_possible <= 0:
                continue
            options = max_possible
            if options < min_options:
                min_options = options
                candidate = e
                if min_options == 1:
                    break
        if candidate is None:
            return None
        # Try counts from 1 to max possible
        u, v = candidate
        max_possible = min(remaining[u], remaining[v], 2 - edges_count[candidate])
        for cnt in range(1, max_possible + 1):
            add_bridge(candidate, cnt)
            res = backtrack()
            if res is not None:
                return res
            remove_bridge(candidate, cnt)
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
