def solve(observation):
    grid = [row.copy() for row in observation['data']]
    N = len(grid)
    req = N // 2
    opposite = {'B': 'W', 'W': 'B'}

    def count_colors(line):
        b = w = 0
        for c in line:
            if c == 'B':
                b += 1
            elif c == 'W':
                w += 1
        return b, w

    def has_three_consecutive(line):
        for i in range(N - 2):
            if line[i] == line[i+1] == line[i+2] and line[i] is not None:
                return True
        return False

    def get_complete_duplicates(lines):
        seen = set()
        for line in lines:
            if None not in line:
                t = tuple(line)
                if t in seen:
                    return True
                seen.add(t)
        return False

    def propagate(g):
        changed = True
        while changed:
            changed = False
            # Process all rows
            for r in range(N):
                row = g[r]
                b, w = count_colors(row)
                # Fill remaining if count meets requirement
                if b == req:
                    for c in range(N):
                        if row[c] is None:
                            row[c] = 'W'
                            changed = True
                if w == req:
                    for c in range(N):
                        if row[c] is None:
                            row[c] = 'B'
                            changed = True
                # Two consecutive same, adjacent must be opposite
                for c in range(N - 2):
                    if row[c] == row[c+1] and row[c] is not None:
                        if row[c+2] is None:
                            row[c+2] = opposite[row[c]]
                            changed = True
                        elif row[c+2] == row[c]:
                            return False
                for c in range(2, N):
                    if row[c] == row[c-1] and row[c] is not None:
                        if row[c-2] is None:
                            row[c-2] = opposite[row[c]]
                            changed = True
                        elif row[c-2] == row[c]:
                            return False
                # X?X pattern, middle must be opposite
                for c in range(1, N-1):
                    if row[c-1] == row[c+1] and row[c-1] is not None:
                        if row[c] is None:
                            row[c] = opposite[row[c-1]]
                            changed = True
                        elif row[c] == row[c-1]:
                            return False
                if has_three_consecutive(row):
                    return False
            # Process all columns
            for c in range(N):
                col = [g[r][c] for r in range(N)]
                b, w = count_colors(col)
                # Fill remaining if count meets requirement
                if b == req:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                if w == req:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True
                # Two consecutive same, adjacent must be opposite
                for r in range(N - 2):
                    if col[r] == col[r+1] and col[r] is not None:
                        if col[r+2] is None:
                            g[r+2][c] = opposite[col[r]]
                            changed = True
                        elif g[r+2][c] == col[r]:
                            return False
                for r in range(2, N):
                    if col[r] == col[r-1] and col[r] is not None:
                        if col[r-2] is None:
                            g[r-2][c] = opposite[col[r]]
                            changed = True
                        elif g[r-2][c] == col[r]:
                            return False
                # X?X pattern, middle must be opposite
                for r in range(1, N-1):
                    if col[r-1] == col[r+1] and col[r-1] is not None:
                        if col[r] is None:
                            g[r][c] = opposite[col[r-1]]
                            changed = True
                        elif g[r][c] == col[r-1]:
                            return False
                new_col = [g[r][c] for r in range(N)]
                if has_three_consecutive(new_col):
                    return False
            # Check for duplicate complete rows/columns
            if get_complete_duplicates(g):
                return False
            cols = [[g[r][c] for r in range(N)] for c in range(N)]
            if get_complete_duplicates(cols):
                return False
        # Post-propagation validation
        for row in g:
            b, w = count_colors(row)
            if b > req or w > req or has_three_consecutive(row):
                return False
        for c in range(N):
            col = [g[r][c] for r in range(N)]
            b, w = count_colors(col)
            if b > req or w > req or has_three_consecutive(col):
                return False
        if get_complete_duplicates(g) or get_complete_duplicates([[g[r][c] for r in range(N)] for c in range(N)]):
            return False
        return True

    # Initial propagation check
    if not propagate(grid):
        return "No Solution"

    def is_complete(g):
        return all(None not in row for row in g)

    if is_complete(grid):
        return grid

    # MRV heuristic to select next cell
    def get_mrv_cell(g):
        min_options = 3
        best = None
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    possible = []
                    row_b, row_w = count_colors(g[r])
                    col = [g[i][c] for i in range(N)]
                    col_b, col_w = count_colors(col)
                    for val in ['B', 'W']:
                        # Check count limits
                        if (val == 'B' and row_b >= req) or (val == 'W' and row_w >= req):
                            continue
                        if (val == 'B' and col_b >= req) or (val == 'W' and col_w >= req):
                            continue
                        # Check consecutive rules
                        temp_row = g[r].copy()
                        temp_row[c] = val
                        if has_three_consecutive(temp_row):
                            continue
                        temp_col = col.copy()
                        temp_col[r] = val
                        if has_three_consecutive(temp_col):
                            continue
                        possible.append(val)
                    if not possible:
                        return None
                    if len(possible) < min_options:
                        min_options = len(possible)
                        best = (r, c, possible)
                        if min_options == 1:
                            return best
        return best

    # Backtracking search
    def backtrack(g):
        if not propagate(g):
            return None
        if is_complete(g):
            # Final full validation
            rows = [tuple(row) for row in g]
            if len(set(rows)) != N:
                return None
            cols = [tuple([g[r][c] for r in range(N)]) for c in range(N)]
            if len(set(cols)) != N:
                return None
            return g
        cell = get_mrv_cell(g)
        if not cell:
            return None
        r, c, options = cell
        for val in options:
            new_grid = [row.copy() for row in g]
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res:
                return res
        return None

    solution = backtrack(grid)
    return solution if solution else "No Solution"

