from copy import deepcopy

def solve(observation):
    grid = observation['data']
    n = len(grid)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_black(r, c):
        return grid[r][c] is not None

    def get_adjacent(r, c):
        res = []
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                res.append((nr, nc))
        return res

    def get_bulb_illumination(r, c):
        ill = set()
        # Left
        for nc in range(c, -1, -1):
            if is_black(r, nc):
                break
            ill.add((r, nc))
        # Right
        for nc in range(c, n):
            if is_black(r, nc):
                break
            ill.add((r, nc))
        # Up
        for nr in range(r, -1, -1):
            if is_black(nr, c):
                break
            ill.add((nr, c))
        # Down
        for nr in range(r, n):
            if is_black(nr, c):
                break
            ill.add((nr, c))
        return ill

    def get_possible_bulbs_for_cell(r, c, forbidden):
        if is_black(r, c):
            return []
        poss = set()
        # Same row left
        for nc in range(c, -1, -1):
            if is_black(r, nc):
                break
            if (r, nc) not in forbidden:
                poss.add((r, nc))
        # Same row right
        for nc in range(c, n):
            if is_black(r, nc):
                break
            if (r, nc) not in forbidden:
                poss.add((r, nc))
        # Same column up
        for nr in range(r, -1, -1):
            if is_black(nr, c):
                break
            if (nr, c) not in forbidden:
                poss.add((nr, c))
        # Same column down
        for nr in range(r, n):
            if is_black(nr, c):
                break
            if (nr, c) not in forbidden:
                poss.add((nr, c))
        return list(poss)

    def propagate(bulbs, forbidden, illuminated):
        changed = True
        while changed:
            changed = False
            # Process numbered cells first
            for r in range(n):
                for c in range(n):
                    val = grid[r][c]
                    if val is None or val == -1:
                        continue
                    adj = get_adjacent(r, c)
                    adj_bulbs = [pos for pos in adj if pos in bulbs]
                    if len(adj_bulbs) > val:
                        return False, bulbs, forbidden, illuminated
                    remaining = val - len(adj_bulbs)
                    adj_available = [pos for pos in adj if not is_black(*pos) and pos not in forbidden and pos not in bulbs]
                    if remaining > len(adj_available):
                        return False, bulbs, forbidden, illuminated
                    if remaining == len(adj_available) and remaining > 0:
                        for pos in adj_available:
                            if pos in bulbs:
                                continue
                            bulbs.add(pos)
                            ill = get_bulb_illumination(*pos)
                            for p in ill:
                                illuminated.add(p)
                                if not is_black(*p) and p not in bulbs:
                                    forbidden.add(p)
                            changed = True
                    if remaining == 0:
                        for pos in adj_available:
                            if pos not in forbidden:
                                forbidden.add(pos)
                                changed = True
            # Process unlit cells
            for r in range(n):
                for c in range(n):
                    if is_black(r, c) or (r,c) in illuminated:
                        continue
                    poss = get_possible_bulbs_for_cell(r, c, forbidden)
                    if not poss:
                        return False, bulbs, forbidden, illuminated
                    if len(poss) == 1:
                        pos = poss[0]
                        if pos in forbidden:
                            return False, bulbs, forbidden, illuminated
                        if pos not in bulbs:
                            bulbs.add(pos)
                            ill = get_bulb_illumination(*pos)
                            for p in ill:
                                illuminated.add(p)
                                if not is_black(*p) and p not in bulbs:
                                    forbidden.add(p)
                            changed = True
        # Final validity check
        for r in range(n):
            for c in range(n):
                val = grid[r][c]
                if val is None or val == -1:
                    continue
                adj_bulbs = [pos for pos in get_adjacent(r,c) if pos in bulbs]
                if len(adj_bulbs) > val:
                    return False, bulbs, forbidden, illuminated
        return True, bulbs, forbidden, illuminated

    def is_solved(bulbs, illuminated):
        # All white cells illuminated
        for r in range(n):
            for c in range(n):
                if not is_black(r,c) and (r,c) not in illuminated:
                    return False
        # All numbered cells have correct bulb count
        for r in range(n):
            for c in range(n):
                val = grid[r][c]
                if val is None or val == -1:
                    continue
                adj_bulbs = len([pos for pos in get_adjacent(r,c) if pos in bulbs])
                if adj_bulbs != val:
                    return False
        return True

    def select_next_branch(bulbs, forbidden, illuminated):
        # First priority: numbered cells with remaining bulbs, smallest available adjacency
        min_opt = float('inf')
        best_pos = None
        for r in range(n):
            for c in range(n):
                val = grid[r][c]
                if val is None or val == -1:
                    continue
                adj_bulbs = len([pos for pos in get_adjacent(r,c) if pos in bulbs])
                remaining = val - adj_bulbs
                if remaining <= 0:
                    continue
                adj_available = [pos for pos in get_adjacent(r,c) if not is_black(*pos) and pos not in forbidden and pos not in bulbs]
                if len(adj_available) < min_opt and len(adj_available) > 0:
                    min_opt = len(adj_available)
                    best_pos = ('num', adj_available, remaining)
        if best_pos is not None:
            return best_pos
        # Second priority: unlit cells with fewest possible bulb positions
        min_opt = float('inf')
        best_poss = None
        for r in range(n):
            for c in range(n):
                if is_black(r,c) or (r,c) in illuminated:
                    continue
                poss = get_possible_bulbs_for_cell(r,c, forbidden)
                if len(poss) < min_opt and len(poss) > 0:
                    min_opt = len(poss)
                    best_poss = ('cell', poss)
        return best_poss if best_poss is not None else None

    def backtrack(bulbs, forbidden, illuminated):
        valid, new_bulbs, new_forbidden, new_illuminated = propagate(deepcopy(bulbs), deepcopy(forbidden), deepcopy(illuminated))
        if not valid:
            return None
        if is_solved(new_bulbs, new_illuminated):
            return new_bulbs
        branch = select_next_branch(new_bulbs, new_forbidden, new_illuminated)
        if branch is None:
            return None
        if branch[0] == 'num':
            options = branch[1]
            required = branch[2]
            # Try all combinations of required bulbs from options, but for simplicity try individual positions first
            for pos in options:
                if pos in new_forbidden or pos in new_bulbs:
                    continue
                temp_bulbs = deepcopy(new_bulbs)
                temp_forbidden = deepcopy(new_forbidden)
                temp_illuminated = deepcopy(new_illuminated)
                temp_bulbs.add(pos)
                ill = get_bulb_illumination(*pos)
                for p in ill:
                    temp_illuminated.add(p)
                    if not is_black(*p) and p not in temp_bulbs:
                        temp_forbidden.add(p)
                res = backtrack(temp_bulbs, temp_forbidden, temp_illuminated)
                if res is not None:
                    return res
        else:
            options = branch[1]
            for pos in options:
                if pos in new_forbidden or pos in new_bulbs:
                    continue
                temp_bulbs = deepcopy(new_bulbs)
                temp_forbidden = deepcopy(new_forbidden)
                temp_illuminated = deepcopy(new_illuminated)
                temp_bulbs.add(pos)
                ill = get_bulb_illumination(*pos)
                for p in ill:
                    temp_illuminated.add(p)
                    if not is_black(*p) and p not in temp_bulbs:
                        temp_forbidden.add(p)
                res = backtrack(temp_bulbs, temp_forbidden, temp_illuminated)
                if res is not None:
                    return res
        return None

    # Initialize state
    initial_bulbs = set()
    initial_forbidden = set()
    initial_illuminated = set()
    # Process 0 cells first
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                for pos in get_adjacent(r,c):
                    if not is_black(*pos):
                        initial_forbidden.add(pos)
    # Run initial propagation
    valid, bulbs, forbidden, illuminated = propagate(initial_bulbs, initial_forbidden, initial_illuminated)
    if not valid:
        return "No Solution"
    solution_bulbs = backtrack(bulbs, forbidden, illuminated)
    if solution_bulbs is None:
        return "No Solution"
    # Build output grid
    output = [[None for _ in range(n)] for _ in range(n)]
    for (r,c) in solution_bulbs:
        output[r][c] = 'B'
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
