        if bulb_grid[r][nc] == 'B':
            return False
        illuminated[r][nc] = True
    # Illuminate column up
    for nr in range(r-1, -1, -1):
        if is_black(data, nr, c):
            break
        if bulb_grid[nr][c] == 'B':
            return False
        illuminated[nr][c] = True
    # Illuminate column down
    for nr in range(r+1, N):
        if is_black(data, nr, c):
