            for nc in range(c, -1, -1):
                if is_black(data, r, nc):
                    break
                if bulb_grid[r][nc] is None and not illuminated[r][nc]:
                    possible.append((r, nc))
            # Check row right
            for nc in range(c+1, N):
                if is_black(data, r, nc):
                    break
                if bulb_grid[r][nc] is None and not illuminated[r][nc]:
                    possible.append((r, nc))
            # Check column up
            for nr in range(r-1, -1, -1):
                if is_black(data, nr, c):
                    break
                if bulb_grid[nr][c] is None and not illuminated[nr][c]:
                    possible.append((nr, c))
            # Check column down
            for nr in range(r+1, N):
                if is_black(data, nr, c):
                    break
                if bulb_grid[nr][c] is None and not illuminated[nr][c]:
                    possible.append((nr, c))
            possible = list(set(possible))
            if len(possible) < min_options:
                min_options = len(possible)
                best_cell = (r, c)
    if best_cell is None:
        return None
    r, c = best_cell
    # Try placing bulb
    new_bulb = copy.deepcopy(bulb_grid)
    new_illum = copy.deepcopy(illuminated)
    if place_bulb(r, c, data, new_bulb, new_illum, N):
        res = backtrack(data, new_bulb, new_illum, N)
        if res is not None:
            return res
    # Try marking as forbidden
    new_bulb2 = copy.deepcopy(bulb_grid)
    new_illum2 = copy.deepcopy(illuminated)
    new_bulb2[r][c] = 'F'
    res2 = backtrack(data, new_bulb2, new_illum2, N)
    if res2 is not None:
        return res2
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    bulb_grid = [[None for _ in range(N)] for _ in range(N)]
    illuminated = [[False for _ in range(N)] for _ in range(N)]
    solution = backtrack(data, bulb_grid, illuminated, N)
    return solution if solution is not None else "No Solution"

