from collections import deque
import copy

def solve(observation):
    grid = observation['data']
    N = len(grid)
    islands = []
    pos_to_idx = {}
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            if val is not None:
                pos_to_idx[(r,c)] = len(islands)
                islands.append((r,c,val))
    M = len(islands)
    if M == 0:
        return {}

    adj = [[] for _ in range(M)]
    for i in range(M):
        r,c,_ = islands[i]
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N:
                if (nr, nc) in pos_to_idx:
                    j = pos_to_idx[(nr, nc)]
                    if j > i:
                        adj[i].append(j)
                        adj[j].append(i)
                    break
                nr += dr
                nc += dc

    edge_keys = []
    edge_to_idx = {}
    for i in range(M):
        for j in adj[i]:
            if j > i:
                k = frozenset((i,j))
                if k not in edge_to_idx:
                    edge_to_idx[k] = len(edge_keys)
                    edge_keys.append(k)
    E = len(edge_keys)

    def propagate(remaining, edges):
        rem = copy.deepcopy(remaining)
        edg = copy.deepcopy(edges)
        changed = True
        while changed:
            changed = False
            for i in range(M):
                if rem[i] < 0:
                    return (False, None, None)
                possible = []
                sum_min = 0
                sum_max = 0
                for j in adj[i]:
                    k = frozenset((i,j))
                    e_idx = edge_to_idx[k]
                    val = edg[e_idx]
                    if val is None:
                        possible.append(e_idx)
                        sum_min += 0
                        sum_max += 2
                    else:
                        sum_min += val
                        sum_max += val
                if sum_min > rem[i] or sum_max < rem[i]:
                    return (False, None, None)
                if rem[i] == sum_max:
                    for e_idx in possible:
                        k = edge_keys[e_idx]
                        a,b = tuple(k)
                        other = b if a == i else a
                        if edg[e_idx] is None:
                            edg[e_idx] = 2
                            rem[i] -= 2
                            rem[other] -= 2
                            changed = True
                if rem[i] == sum_min:
                    for e_idx in possible:
                        if edg[e_idx] is None:
                            edg[e_idx] = 0
                            changed = True
            for e_idx in range(E):
                val = edg[e_idx]
                if val is None:
                    continue
                a,b = tuple(edge_keys[e_idx])
                if val < 0 or val > 2:
                    return (False, None, None)
                if rem[a] < 0 or rem[b] < 0:
                    return (False, None, None)
        for i in range(M):
            if rem[i] != 0:
                for j in adj[i]:
                    k = frozenset((i,j))
                    e_idx = edge_to_idx[k]
                    if edg[e_idx] is None:
                        max_possible = min(2, rem[i], rem[j])
                        if max_possible < 0:
                            return (False, None, None)
        return (True, rem, edg)

    def is_connected(edges):
        adj_bridge = [[] for _ in range(M)]
        for e_idx in range(E):
            val = edges[e_idx]
            if val <= 0:
                continue
            a,b = tuple(edge_keys[e_idx])
            adj_bridge[a].append(b)
            adj_bridge[b].append(a)
        visited = [False]*M
        q = deque([0])
        visited[0] = True
        cnt = 1
        while q:
            u = q.popleft()
            for v in adj_bridge[u]:
                if not visited[v]:
                    visited[v] = True
                    cnt += 1
                    q.append(v)
        return cnt == M

    def backtrack(rem, edg):
        valid, new_rem, new_edg = propagate(rem, edg)
        if not valid:
            return None
        unknown = [e for e in range(E) if new_edg[e] is None]
        if not unknown:
            if all(r == 0 for r in new_rem) and is_connected(new_edg):
                res = {}
                for e_idx in range(E):
                    val = new_edg[e_idx]
                    if val <= 0:
                        continue
                    a,b = tuple(edge_keys[e_idx])
                    (r1,c1,_) = islands[a]
                    (r2,c2,_) = islands[b]
                    if (r1,c1) > (r2,c2):
                        (r1,c1), (r2,c2) = (r2,c2), (r1,c1)
                    res[((r1,c1), (r2,c2))] = val
                return res
            return None
        e_idx = min(unknown, key=lambda x: 2)
        a,b = tuple(edge_keys[e_idx])
        max_val = min(2, new_rem[a], new_rem[b])
        for val in [max_val, max_val-1, 0]:
            if val < 0:
                continue
            temp_edg = copy.deepcopy(new_edg)
            temp_rem = copy.deepcopy(new_rem)
            temp_edg[e_idx] = val
            temp_rem[a] -= val
            temp_rem[b] -= val
            res = backtrack(temp_rem, temp_edg)
            if res is not None:
                return res
        return None

    initial_rem = [isl[2] for isl in islands]
    initial_edg = [None]*E
    solution = backtrack(initial_rem, initial_edg)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
