def solve(observation):
    region_grid = observation['region']
    row_counts = observation['row_water_counts']
    col_counts = observation['col_water_counts']
    R = len(row_counts)
    C = len(col_counts)

    # Step 1: Collect regions and sort cells by row descending (lowest first)
    regions = {}
    for i in range(R):
        for j in range(C):
            rid = region_grid[i][j]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((i,j))
    region_ids = list(regions.keys())
    for rid in region_ids:
        # Sort cells from lowest row (highest index) to highest row
        regions[rid].sort(key=lambda x: (-x[0], x[1]))

    # Step 2: Precompute contributions for each region and each possible level
    region_info = {}
    for rid in region_ids:
        cells = regions[rid]
        size = len(cells)
        contribs = []
        for l in range(size + 1):
            row_contrib = [0]*R
            col_contrib = [0]*C
            for (i,j) in cells[:l]:
                row_contrib[i] += 1
                col_contrib[j] += 1
            # Precompute max possible contribution for this region (l = size)
            max_row = row_contrib.copy() if l == size else None
            max_col = col_contrib.copy() if l == size else None
            contribs.append((row_contrib, col_contrib))
        max_row = contribs[-1][0]
        max_col = contribs[-1][1]
        region_info[rid] = {
            'cells': cells,
            'size': size,
            'contribs': contribs,
            'max_row': max_row,
            'max_col': max_col
        }

    # Precompute total max possible row and column contributions
    total_max_row = [0]*R
    total_max_col = [0]*C
    for rid in region_ids:
        mr = region_info[rid]['max_row']
        mc = region_info[rid]['max_col']
        for i in range(R):
            total_max_row[i] += mr[i]
        for j in range(C):
            total_max_col[j] += mc[j]

    # Check if even max possible is less than required: no solution
    for i in range(R):
        if total_max_row[i] < row_counts[i]:
            return "No Solution"
    for j in range(C):
        if total_max_col[j] < col_counts[j]:
            return "No Solution"

    # Backtracking with MRV heuristic and pruning
    assignment = {}
    assigned = set()

    def backtrack():
        if len(assigned) == len(region_ids):
            # Check if all counts match
            cur_row = [0]*R
            cur_col = [0]*C
            for rid in assignment:
                l = assignment[rid]
                rc, cc = region_info[rid]['contribs'][l]
                for i in range(R):
                    cur_row[i] += rc[i]
                for j in range(C):
                    cur_col[j] += cc[j]
            if cur_row == row_counts and cur_col == col_counts:
                # Build result grid
                res = [[None for _ in range(C)] for _ in range(R)]
                for rid in assignment:
                    l = assignment[rid]
                    cells = region_info[rid]['cells']
                    for (i,j) in cells[:l]:
                        res[i][j] = 'W'
                return res
            return None

        # MRV: pick region with fewest possible valid levels
        best_rid = None
        min_options = float('inf')
        cur_row = [0]*R
        cur_col = [0]*C
        for rid in assigned:
            l = assignment[rid]
            rc, cc = region_info[rid]['contribs'][l]
            for i in range(R):
                cur_row[i] += rc[i]
            for j in range(C):
                cur_col[j] += cc[j]

        # Compute remaining max contributions
        rem_max_row = [total_max_row[i] - cur_row[i] for i in range(R)]
        rem_max_col = [total_max_col[j] - cur_col[j] for j in range(C)]

        for rid in region_ids:
            if rid in assigned:
                continue
            # Count valid levels for this region
            valid = 0
            size = region_info[rid]['size']
            mr = region_info[rid]['max_row']
            mc = region_info[rid]['max_col']
            for l in range(size + 1):
                rc, cc = region_info[rid]['contribs'][l]
                # Check if adding this level keeps cur <= required
                ok = True
                for i in range(R):
                    if cur_row[i] + rc[i] > row_counts[i]:
                        ok = False
                        break
                if not ok:
                    continue
                for j in range(C):
                    if cur_col[j] + cc[j] > col_counts[j]:
                        ok = False
                        break
                if not ok:
                    continue
                # Check if remaining can reach required
                for i in range(R):
                    if cur_row[i] + rc[i] + (rem_max_row[i] - mr[i]) < row_counts[i]:
                        ok = False
                        break
                if not ok:
                    continue
                for j in range(C):
                    if cur_col[j] + cc[j] + (rem_max_col[j] - mc[j]) < col_counts[j]:
                        ok = False
                        break
                if ok:
                    valid += 1
            if valid < min_options:
                min_options = valid
                best_rid = rid
                if min_options == 0:
                    return None

        # Try all valid levels for best_rid
        rid = best_rid
        size = region_info[rid]['size']
        mr = region_info[rid]['max_row']
        mc = region_info[rid]['max_col']
        for l in range(size + 1):
            rc, cc = region_info[rid]['contribs'][l]
            # Check validity
            ok = True
            for i in range(R):
                if cur_row[i] + rc[i] > row_counts[i]:
                    ok = False
                    break
            if not ok:
                continue
            for j in range(C):
                if cur_col[j] + cc[j] > col_counts[j]:
                    ok = False
                    break
            if not ok:
                continue
            for i in range(R):
                if cur_row[i] + rc[i] + (rem_max_row[i] - mr[i]) < row_counts[i]:
                    ok = False
                    break
            if not ok:
                continue
            for j in range(C):
                if cur_col[j] + cc[j] + (rem_max_col[j] - mc[j]) < col_counts[j]:
                    ok = False
                    break
            if not ok:
                continue

            # Assign
            assignment[rid] = l
            assigned.add(rid)
            res = backtrack()
            if res is not None:
                return res
            # Unassign
            del assignment[rid]
            assigned.remove(rid)

        return None

    result = backtrack()
    return result if result is not None else "No Solution"

