def solve(observation):
    data = observation["data"]
    adj_list = observation["adjacent"]
    N = len(data)
    adj_set = set(tuple(p) for p in adj_list)

    # Generate all adjacent pairs: dot and non-dot
    dot_pairs = []
    non_dot_pairs = []
    # Horizontal pairs
    for r in range(N):
        for c in range(N-1):
            mid = (r, c + 0.5)
            if mid in adj_set:
                dot_pairs.append(((r,c), (r,c+1)))
            else:
                non_dot_pairs.append(((r,c), (r,c+1)))
    # Vertical pairs
    for c in range(N):
        for r in range(N-1):
            mid = (r + 0.5, c)
            if mid in adj_set:
                dot_pairs.append(((r,c), (r+1,c)))
            else:
                non_dot_pairs.append(((r,c), (r+1,c)))

    # Initialize possible value sets
    possible = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                possible[r][c].add(val)
            else:
                possible[r][c] = set(range(1, N+1))

    # Constraint propagation function
    def propagate(poss):
        changed = True
        while changed:
            changed = False
            # 1. Sudoku row/column constraints
            # Process rows
            for r in range(N):
                fixed = set()
                for c in range(N):
                    if len(poss[r][c]) == 1:
                        fixed.add(next(iter(poss[r][c])))
                for c in range(N):
                    if len(poss[r][c]) > 1:
                        orig_len = len(poss[r][c])
                        poss[r][c] -= fixed
                        if len(poss[r][c]) == 0:
                            return None
                        if len(poss[r][c]) != orig_len:
                            changed = True
            # Process columns
            for c in range(N):
                fixed = set()
                for r in range(N):
                    if len(poss[r][c]) == 1:
                        fixed.add(next(iter(poss[r][c])))
                for r in range(N):
                    if len(poss[r][c]) > 1:
                        orig_len = len(poss[r][c])
                        poss[r][c] -= fixed
                        if len(poss[r][c]) == 0:
                            return None
                        if len(poss[r][c]) != orig_len:
                            changed = True
            # 2. Dot pair consecutive constraint
            for (a, b) in dot_pairs:
                (r1, c1), (r2, c2) = a, b
                s1, s2 = poss[r1][c1], poss[r2][c2]
                # Filter s1
                new_s1 = {v for v in s1 if (v-1 in s2 or v+1 in s2)}
                if len(new_s1) == 0:
                    return None
                if new_s1 != s1:
                    poss[r1][c1] = new_s1
                    changed = True
                # Filter s2
                new_s2 = {v for v in s2 if (v-1 in s1 or v+1 in s1)}
                if len(new_s2) == 0:
                    return None
                if new_s2 != s2:
                    poss[r2][c2] = new_s2
                    changed = True
            # 3. Non-dot pair non-consecutive constraint
            for (a, b) in non_dot_pairs:
                (r1, c1), (r2, c2) = a, b
                s1, s2 = poss[r1][c1], poss[r2][c2]
                if len(s1) == 1:
                    v = next(iter(s1))
                    forbidden = {v-1, v+1}
                    orig_len = len(s2)
                    s2 -= forbidden
                    if len(s2) == 0:
                        return None
                    if len(s2) != orig_len:
                        poss[r2][c2] = s2
                        changed = True
                if len(s2) == 1:
                    v = next(iter(s2))
                    forbidden = {v-1, v+1}
                    orig_len = len(s1)
                    s1 -= forbidden
                    if len(s1) == 0:
                        return None
                    if len(s1) != orig_len:
                        poss[r1][c1] = s1
                        changed = True
        return poss

    # Check if grid is fully solved
    def is_solved(poss):
        for r in range(N):
            for c in range(N):
                if len(poss[r][c]) != 1:
                    return False
        return True

    # Initial propagation
    initial_poss = propagate(possible)
    if initial_poss is None:
        return "No Solution"
    if is_solved(initial_poss):
        return [[next(iter(cell)) for cell in row] for row in initial_poss]

    # Backtracking with Minimum Remaining Value heuristic
    def backtrack(poss):
        poss = propagate(poss)
        if poss is None:
            return None
        if is_solved(poss):
            return [[next(iter(cell)) for cell in row] for row in poss]
        # Find cell with smallest number of possible values
        min_len = N + 1
        min_cell = None
        for r in range(N):
            for c in range(N):
                l = len(poss[r][c])
                if 1 < l < min_len:
                    min_len = l
                    min_cell = (r, c)
                    if min_len == 2:
                        break
            if min_len == 2:
                break
        r, c = min_cell
        # Try each candidate value
        for val in sorted(poss[r][c]):
            new_poss = [[set(cell) for cell in row] for row in poss]
            new_poss[r][c] = {val}
            res = backtrack(new_poss)
            if res is not None:
                return res
        return None

    solution = backtrack(initial_poss)
    return solution if solution is not None else "No Solution"

