        for row in full_grid:
            if row.count('B') != required or row.count('W') != required:
                return False
            for i in range(N-2):
                if row[i] == row[i+1] == row[i+2]:
                    return False
            row_tuple = tuple(row)
            if row_tuple in row_set:
                return False
            row_set.add(row_tuple)
        col_set = set()
        for c in range(N):
