            if col.count('B') != required or col.count('W') != required:
                return False
            for i in range(N-2):
                if col[i] == col[i+1] == col[i+2]:
                    return False
            col_tuple = tuple(col)
            if col_tuple in col_set:
                return False
            col_set.add(col_tuple)
        return True

    def propagate(current_grid):
