                    for c in range(N):
                        if row[c] is None:
                            row[c] = 'W'
                            changed = True
                if cnt_w == required:
                    for c in range(N):
                        if row[c] is None:
                            row[c] = 'B'
                            changed = True
                for c in range(N-2):
                    a, b, d = row[c], row[c+1], row[c+2]
                    if a == b and a is not None:
                        if d == a:
                            return None, False
                        if d is None:
                            row[c+2] = 'W' if a == 'B' else 'B'
                            changed = True
                    if b == d and b is not None:
                        if a == b:
                            return None, False
                        if a is None:
                            row[c] = 'W' if b == 'B' else 'B'
                            changed = True
            for c in range(N):
                cnt_b = sum(1 for r in range(N) if current_grid[r][c] == 'B')
                cnt_w = sum(1 for r in range(N) if current_grid[r][c] == 'W')
                if cnt_b > required or cnt_w > required:
                    return None, False
                if cnt_b == required:
                    for r in range(N):
                        if current_grid[r][c] is None:
                            current_grid[r][c] = 'W'
                            changed = True
                if cnt_w == required:
                    for r in range(N):
                        if current_grid[r][c] is None:
                            current_grid[r][c] = 'B'
                            changed = True
                for r in range(N-2):
                    a, b, d = current_grid[r][c], current_grid[r+1][c], current_grid[r+2][c]
                    if a == b and a is not None:
                        if d == a:
                            return None, False
                        if d is None:
                            current_grid[r+2][c] = 'W' if a == 'B' else 'B'
                            changed = True
                    if b == d and b is not None:
                        if a == b:
                            return None, False
                        if a is None:
                            current_grid[r][c] = 'W' if b == 'B' else 'B'
                            changed = True
            complete_rows = set()
            for r in range(N):
                if all(x is not None for x in current_grid[r]):
                    t = tuple(current_grid[r])
                    if t in complete_rows:
                        return None, False
                    complete_rows.add(t)
            complete_cols = set()
            for c in range(N):
                col = [current_grid[r][c] for r in range(N)]
                if all(x is not None for x in col):
                    t = tuple(col)
                    if t in complete_cols:
                        return None, False
                    complete_cols.add(t)
        return current_grid, True

    grid, valid = propagate(grid)
    if not valid:
        return "No Solution"

    if all(all(x is not None for x in row) for row in grid):
        return grid if is_valid(grid) else "No Solution"

    def backtrack(current_grid):
        min_options = 3
        best_cell = None
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None:
                    possible = []
                    row_cnt_b = current_grid[r].count('B')
                    row_cnt_w = current_grid[r].count('W')
                    col_cnt_b = sum(1 for i in range(N) if current_grid[i][c] == 'B')
                    col_cnt_w = sum(1 for i in range(N) if current_grid[i][c] == 'W')
                    for val in ['B', 'W']:
                        if val == 'B' and (row_cnt_b >= required or col_cnt_b >= required):
                            continue
                        if val == 'W' and (row_cnt_w >= required or col_cnt_w >= required):
                            continue
                        ok = True
                        if c >= 2 and current_grid[r][c-1] == current_grid[r][c-2] == val:
                            ok = False
                        if c <= N-3 and current_grid[r][c+1] == current_grid[r][c+2] == val:
                            ok = False
                        if r >= 2 and current_grid[r-1][c] == current_grid[r-2][c] == val:
                            ok = False
                        if r <= N-3 and current_grid[r+1][c] == current_grid[r+2][c] == val:
                            ok = False
                        if ok:
                            possible.append(val)
                    if not possible:
                        return None
                    if len(possible) < min_options:
                        min_options = len(possible)
                        best_cell = (r, c, possible)
                        if min_options == 1:
                            break
            if best_cell and min_options == 1:
                break
        if not best_cell:
            return current_grid if is_valid(current_grid) else None
        r, c, possible = best_cell
        for val in possible:
            new_grid = [row.copy() for row in current_grid]
            new_grid[r][c] = val
            propagated, valid = propagate(new_grid)
            if not valid:
                continue
            res = backtrack(propagated)
            if res is not None:
                return res
        return None

    result = backtrack(grid)
    return result if result is not None else "No Solution"

