from collections import deque

def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return []
    cols = len(data[0])

    # Collect all numeric constraints
    constraints = []
    for r in range(rows):
        for c in range(cols):
            k = data[r][c]
            if k is not None:
                constraints.append((r, c, k))

    # Precompute map from cell to all constraints that include it in their 3x3 neighborhood
    cell_to_constraints = [[[] for _ in range(cols)] for _ in range(rows)]
    for (cr, cc, k) in constraints:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    cell_to_constraints[nr][nc].append((cr, cc, k))

    # Get valid 3x3 neighborhood for a given cell
    def get_neighborhood(cr, cc):
        res = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    res.append((nr, nc))
        return res

    # Constraint propagation: apply deductive rules until no more changes or invalid
    def propagate(initial_state):
        st = [[set(cell) for cell in row] for row in initial_state]
        q = deque()
        in_queue = set()
        for con in constraints:
            q.append(con)
            in_queue.add(con)

        while q:
            cr, cc, k = q.popleft()
            in_queue.remove((cr, cc, k))
            neighborhood = get_neighborhood(cr, cc)

            b = 0
            w = 0
            unknown = []
            for (r, c) in neighborhood:
                s = st[r][c]
                if s == {'B'}:
                    b += 1
                elif s == {'W'}:
                    w += 1
                else:
                    unknown.append((r, c))
            u = len(unknown)

            # Check for invalid state
            if b > k or (b + u) < k:
                return None

            # All remaining unknowns must be white
            if b == k:
                for (r, c) in unknown:
                    if 'W' not in st[r][c]:
                        return None
                    if st[r][c] != {'W'}:
                        st[r][c] = {'W'}
                        for con in cell_to_constraints[r][c]:
                            if con not in in_queue:
                                q.append(con)
                                in_queue.add(con)
            # All remaining unknowns must be black
            elif (b + u) == k:
                for (r, c) in unknown:
                    if 'B' not in st[r][c]:
                        return None
                    if st[r][c] != {'B'}:
                        st[r][c] = {'B'}
                        for con in cell_to_constraints[r][c]:
                            if con not in in_queue:
                                q.append(con)
                                in_queue.add(con)
        return st

    # Initial state: all cells unknown
    initial_state = [[{'B', 'W'} for _ in range(cols)] for _ in range(rows)]
    initial_propagated = propagate(initial_state)
    if initial_propagated is None:
        return "No Solution"

    # Backtracking with minimum remaining value heuristic
    def backtrack(st):
        st = propagate(st)
        if st is None:
            return None

        # Find most constrained unknown cell
        min_len = 3
        candidate = None
        for r in range(rows):
            for c in range(cols):
                l = len(st[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    candidate = (r, c)
                    if min_len == 2:
                        break
            if candidate:
                break

        # All cells solved
        if not candidate:
            res = []
            for r in range(rows):
                row = []
                for c in range(cols):
                    row.append('B' if st[r][c] == {'B'} else None)
                res.append(row)
            return res

        r, c = candidate
        # Try both possible values
        for val in ['B', 'W']:
            if val not in st[r][c]:
                continue
            new_st = [[set(cell) for cell in row] for row in st]
            new_st[r][c] = {val}
            sol = backtrack(new_st)
            if sol is not None:
                return sol
        return None

    solution = backtrack(initial_propagated)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
