def get_adjacent_pairs(adjacent_list, N):
    consecutive_pairs = set()
    for y, x in adjacent_list:
        if y == int(y):
            r = int(y)
            c1 = int(x - 0.5)
            c2 = int(x + 0.5)
            consecutive_pairs.add(((r, c1), (r, c2)))
            consecutive_pairs.add(((r, c2), (r, c1)))
        else:
            c = int(x)
            r1 = int(y - 0.5)
            r2 = int(y + 0.5)
            consecutive_pairs.add(((r1, c), (r2, c)))
            consecutive_pairs.add(((r2, c), (r1, c)))
    all_orthogonal = set()
    for r in range(N):
        for c in range(N):
            if c < N - 1:
                all_orthogonal.add(((r, c), (r, c + 1)))
            if r < N - 1:
                all_orthogonal.add(((r, c), (r + 1, c)))
    non_consecutive_pairs = all_orthogonal - consecutive_pairs
    return consecutive_pairs, non_consecutive_pairs

def propagate(domains, N, consecutive_pairs, non_consecutive_pairs):
    changed = True
    while changed:
        changed = False
        # Row uniqueness constraint
        for r in range(N):
            fixed_vals = set()
            for c in range(N):
                if len(domains[r][c]) == 1:
                    fixed_vals.add(next(iter(domains[r][c])))
            for c in range(N):
                if len(domains[r][c]) > 1:
                    orig_len = len(domains[r][c])
                    domains[r][c] -= fixed_vals
                    if not domains[r][c]:
                        return None
                    if len(domains[r][c]) != orig_len:
                        changed = True
        # Column uniqueness constraint
        for c in range(N):
            fixed_vals = set()
            for r in range(N):
                if len(domains[r][c]) == 1:
                    fixed_vals.add(next(iter(domains[r][c])))
            for r in range(N):
                if len(domains[r][c]) > 1:
                    orig_len = len(domains[r][c])
                    domains[r][c] -= fixed_vals
                    if not domains[r][c]:
                        return None
                    if len(domains[r][c]) != orig_len:
                        changed = True
        # Consecutive pairs constraint
        for (cell1, cell2) in consecutive_pairs:
            (r1, c1), (r2, c2) = cell1, cell2
            d1, d2 = domains[r1][c1], domains[r2][c2]
            # Prune d2
            new_d2 = set(v2 for v2 in d2 if any(abs(v1 - v2) == 1 for v1 in d1))
            if len(new_d2) != len(d2):
                domains[r2][c2] = new_d2
                if not new_d2:
                    return None
                changed = True
            # Prune d1
            new_d1 = set(v1 for v1 in d1 if any(abs(v1 - v2) == 1 for v2 in d2))
            if len(new_d1) != len(d1):
                domains[r1][c1] = new_d1
                if not new_d1:
                    return None
                changed = True
        # Non-consecutive pairs constraint
        for (cell1, cell2) in non_consecutive_pairs:
            (r1, c1), (r2, c2) = cell1, cell2
            d1, d2 = domains[r1][c1], domains[r2][c2]
            if len(d1) == 1:
                v1 = next(iter(d1))
                orig_len = len(d2)
                domains[r2][c2] = set(v2 for v2 in d2 if abs(v1 - v2) != 1)
                if not domains[r2][c2]:
                    return None
                if len(domains[r2][c2]) != orig_len:
                    changed = True
            if len(d2) == 1:
                v2 = next(iter(d2))
                orig_len = len(d1)
                domains[r1][c1] = set(v1 for v1 in d1 if abs(v1 - v2) != 1)
                if not domains[r1][c1]:
                    return None
                if len(domains[r1][c1]) != orig_len:
                    changed = True
    return domains

def backtrack(domains, N, consecutive_pairs, non_consecutive_pairs):
    # Check if solved
    min_len = float('inf')
    next_cell = None
    solved = True
    for r in range(N):
        for c in range(N):
            l = len(domains[r][c])
            if l > 1:
                solved = False
                if l < min_len:
                    min_len = l
                    next_cell = (r, c)
    if solved:
        return [[next(iter(cell)) for cell in row] for row in domains]
    r, c = next_cell
    for val in sorted(domains[r][c]):
        new_domains = [[set(cell) for cell in row] for row in domains]
        new_domains[r][c] = {val}
        propagated = propagate(new_domains, N, consecutive_pairs, non_consecutive_pairs)
        if propagated is not None:
            res = backtrack(propagated, N, consecutive_pairs, non_consecutive_pairs)
            if res is not None:
                return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    # Initialize domains
    domains = []
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            if val is not None:
                row.append({val})
            else:
                row.append(set(range(1, N+1)))
        domains.append(row)
    consecutive_pairs, non_consecutive_pairs = get_adjacent_pairs(observation['adjacent'], N)
    initial_propagate = propagate(domains, N, consecutive_pairs, non_consecutive_pairs)
    if initial_propagate is None:
        return "No Solution"
    solution = backtrack(initial_propagate, N, consecutive_pairs, non_consecutive_pairs)
    return solution if solution is not None else "No Solution"

