from collections import deque

def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return []
    cols = len(data[0])
    clues = []
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                clues.append((r, c, val))

    def get_neigh(r, c):
        res = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    res.append((nr, nc))
        return res

    def propagate(grid):
        q = deque()
        in_q = set()
        for clue in clues:
            q.append(clue)
            in_q.add(clue)
        while q:
            r, c, val = q.popleft()
            in_q.remove((r, c, val))
            neigh = get_neigh(r, c)
            b_cnt = 0
            unk_cnt = 0
            for nr, nc in neigh:
                if grid[nr][nc] == 'B':
                    b_cnt += 1
                elif grid[nr][nc] is None:
                    unk_cnt += 1
            rem = val - b_cnt
            if rem < 0 or rem > unk_cnt:
                return False, grid
            updated = []
            if rem == 0:
                for nr, nc in neigh:
                    if grid[nr][nc] is None:
                        grid[nr][nc] = 'W'
                        updated.append((nr, nc))
            elif rem == unk_cnt:
                for nr, nc in neigh:
                    if grid[nr][nc] is None:
                        grid[nr][nc] = 'B'
                        updated.append((nr, nc))
            for nr, nc in updated:
                for cr, cc, cv in clues:
                    if abs(cr - nr) <= 1 and abs(cc - nc) <= 1:
                        clue = (cr, cc, cv)
                        if clue not in in_q:
                            q.append(clue)
                            in_q.add(clue)
        # Final validity check
        for r, c, val in clues:
            neigh = get_neigh(r, c)
            b = sum(1 for x, y in neigh if grid[x][y] == 'B')
            unk = sum(1 for x, y in neigh if grid[x][y] is None)
            if b > val or (b + unk) < val:
                return False, grid
        return True, grid

    def backtrack(grid):
        valid, grid = propagate(grid)
        if not valid:
            return None
        # Find most constrained unknown cell
        candidate = None
        max_clue_count = -1
        all_filled = True
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is None:
                    all_filled = False
                    cnt = 0
                    for cr, cc, _ in clues:
                        if abs(cr - r) <= 1 and abs(cc - c) <= 1:
                            cnt += 1
                    if cnt > max_clue_count:
                        max_clue_count = cnt
                        candidate = (r, c)
        if all_filled:
            return grid
        r, c = candidate
        # Try black first
        grid_b = [row.copy() for row in grid]
        grid_b[r][c] = 'B'
        res_b = backtrack(grid_b)
        if res_b is not None:
            return res_b
        # Try white
        grid_w = [row.copy() for row in grid]
        grid_w[r][c] = 'W'
        return backtrack(grid_w)

    initial_grid = [[None for _ in range(cols)] for _ in range(rows)]
    solution = backtrack(initial_grid)
    if solution is None:
        return "No Solution"
    # Convert to required output format
    output = []
    for row in solution:
        output_row = []
        for cell in row:
            output_row.append('B' if cell == 'B' else None)
        output.append(output_row)
    return output

