def is_valid_complete(grid, N, target):
    # Check row counts
    for r in range(N):
        if grid[r].count('B') != target or grid[r].count('W') != target:
            return False
    # Check column counts
    for c in range(N):
        b = sum(1 for r in range(N) if grid[r][c] == 'B')
        w = sum(1 for r in range(N) if grid[r][c] == 'W')
        if b != target or w != target:
            return False
    # Check row triplets
    for r in range(N):
        for c in range(N-2):
            if grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                return False
    # Check column triplets
    for c in range(N):
        for r in range(N-2):
            if grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                return False
    # Check unique rows
    rows = [tuple(row) for row in grid]
    if len(set(rows)) != N:
        return False
    # Check unique columns
    cols = []
    for c in range(N):
        cols.append(tuple(grid[r][c] for r in range(N)))
    if len(set(cols)) != N:
        return False
    return True

def select_cell(grid, N, target):
    min_options = 3
    best = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                opts = 0
                # Check B validity
                b_r = grid[r].count('B')
                b_c = sum(1 for i in range(N) if grid[i][c] == 'B')
                if b_r + 1 <= target and b_c + 1 <= target:
                    valid = True
                    # Row checks
                    if c >=2 and grid[r][c-1] == 'B' and grid[r][c-2] == 'B': valid = False
                    if c <= N-3 and grid[r][c+1] == 'B' and grid[r][c+2] == 'B': valid = False
                    if 0 < c < N-1 and grid[r][c-1] == 'B' and grid[r][c+1] == 'B': valid = False
                    # Column checks
                    if valid and r >=2 and grid[r-1][c] == 'B' and grid[r-2][c] == 'B': valid = False
                    if valid and r <= N-3 and grid[r+1][c] == 'B' and grid[r+2][c] == 'B': valid = False
                    if valid and 0 < r < N-1 and grid[r-1][c] == 'B' and grid[r+1][c] == 'B': valid = False
                    if valid: opts +=1
                # Check W validity
                w_r = grid[r].count('W')
                w_c = sum(1 for i in range(N) if grid[i][c] == 'W')
                if w_r + 1 <= target and w_c + 1 <= target:
                    valid = True
                    # Row checks
                    if c >=2 and grid[r][c-1] == 'W' and grid[r][c-2] == 'W': valid = False
                    if c <= N-3 and grid[r][c+1] == 'W' and grid[r][c+2] == 'W': valid = False
                    if 0 < c < N-1 and grid[r][c-1] == 'W' and grid[r][c+1] == 'W': valid = False
                    # Column checks
                    if valid and r >=2 and grid[r-1][c] == 'W' and grid[r-2][c] == 'W': valid = False
                    if valid and r <= N-3 and grid[r+1][c] == 'W' and grid[r+2][c] == 'W': valid = False
                    if valid and 0 < r < N-1 and grid[r-1][c] == 'W' and grid[r+1][c] == 'W': valid = False
                    if valid: opts +=1
                if opts == 0:
                    return (r,c)
                if opts < min_options:
                    min_options = opts
                    best = (r,c)
    return best

def backtrack(grid, N, target):
    if not propagate(grid, N, target):
