        if valid and 0 < r < N-1 and grid[r-1][c] == 'B' and grid[r+1][c] == 'B': valid = False
        if valid: possible.append('B')
    # Check W
    w_r = grid[r].count('W')
    w_c = sum(1 for i in range(N) if grid[i][c] == 'W')
