from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    islands = []
    island_set = set()
    remaining = {}
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                islands.append((r, c, val))
                island_set.add((r, c))
                remaining[(r, c)] = val
    if not islands:
        return {}

    # Precompute all possible valid bridge pairs
    possible_pairs = set()
    for (r1, c1, _) in islands:
        # Check right same row
        for c2 in range(c1 + 1, n):
            if (r1, c2) in island_set:
                blocked = False
                for c in range(c1 + 1, c2):
                    if (r1, c) in island_set:
                        blocked = True
                        break
                if not blocked:
                    pair = tuple(sorted(((r1, c1), (r1, c2))))
                    possible_pairs.add(pair)
                break
        # Check down same column
        for r2 in range(r1 + 1, n):
            if (r2, c1) in island_set:
                blocked = False
                for r in range(r1 + 1, r2):
                    if (r, c1) in island_set:
                        blocked = True
                        break
                if not blocked:
                    pair = tuple(sorted(((r1, c1), (r2, c1))))
                    possible_pairs.add(pair)
                break

    bridge_counts = {p: 0 for p in possible_pairs}
    used_cells = set()

    def is_connected():
        adj = {pos: [] for pos in remaining.keys()}
        for (a, b), cnt in bridge_counts.items():
            if cnt > 0:
                adj[a].append(b)
                adj[b].append(a)
        start = next(iter(adj.keys()))
        visited = set([start])
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        return len(visited) == len(islands)

    def apply_forced():
        changed = True
        while changed:
            changed = False
            for pos, rem in remaining.items():
                if rem == 0:
                    continue
                # Get valid neighbors
                neighbors = []
                for pair in possible_pairs:
                    a, b = pair
                    if pos not in (a, b):
                        continue
                    other = b if a == pos else a
                    cnt = bridge_counts[pair]
                    if cnt >= 2:
                        continue
                    # Check path clear
                    clear = True
                    if a[0] == b[0]:
                        rw = a[0]
                        cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                        for c in range(cmin + 1, cmax):
                            if (rw, c) in used_cells:
                                clear = False
                                break
                    else:
                        col = a[1]
                        rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                        for r in range(rmin + 1, rmax):
                            if (r, col) in used_cells:
                                clear = False
                                break
                    if clear:
                        max_add = 2 - cnt
                        neighbors.append((other, max_add, pair))
                max_possible = sum(m for _, m, _ in neighbors)
                if rem > max_possible or rem < 0:
                    return False
                if rem == max_possible and max_possible > 0:
                    # Add max possible to each neighbor
                    for (_, add, pair) in neighbors:
                        if add == 0:
                            continue
                        a, b = pair
                        prev_cnt = bridge_counts[pair]
                        bridge_counts[pair] += add
                        remaining[a] -= add
                        remaining[b] -= add
                        if prev_cnt == 0:
                            # Mark cells as used
                            if a[0] == b[0]:
                                rw = a[0]
                                cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                                for c in range(cmin + 1, cmax):
                                    used_cells.add((rw, c))
                            else:
                                col = a[1]
                                rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                                for r in range(rmin + 1, rmax):
                                    used_cells.add((r, col))
                        changed = True
                    continue
                if rem == len(neighbors) and len(neighbors) > 0:
                    # Add 1 to each neighbor
                    valid = True
                    for _, add, _ in neighbors:
                        if add < 1:
                            valid = False
                            break
                    if valid:
                        for (_, _, pair) in neighbors:
                            a, b = pair
                            prev_cnt = bridge_counts[pair]
                            bridge_counts[pair] += 1
                            remaining[a] -= 1
                            remaining[b] -= 1
                            if prev_cnt == 0:
                                if a[0] == b[0]:
                                    rw = a[0]
                                    cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                                    for c in range(cmin + 1, cmax):
                                        used_cells.add((rw, c))
                                else:
                                    col = a[1]
                                    rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                                    for r in range(rmin + 1, rmax):
                                        used_cells.add((r, col))
                            changed = True
                    continue
        return True

    def backtrack():
        # Apply forced moves first
        valid = apply_forced()
        if not valid:
            return None
        # Check if done
        all_zero = all(v == 0 for v in remaining.values())
        if all_zero:
            if is_connected():
                return {k: v for k, v in bridge_counts.items() if v > 0}
            else:
                return None
        # Pick most constrained island to branch
        candidates = []
        for pos, rem in remaining.items():
            if rem == 0:
                continue
            possible = 0
            for pair in possible_pairs:
                a, b = pair
                if pos not in (a, b):
                    continue
                cnt = bridge_counts[pair]
                if cnt >= 2:
                    continue
                # Check path clear
                clear = True
                if a[0] == b[0]:
                    rw = a[0]
                    cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                    for c in range(cmin + 1, cmax):
                        if (rw, c) in used_cells:
                            clear = False
                            break
                else:
                    col = a[1]
                    rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                    for r in range(rmin + 1, rmax):
                        if (r, col) in used_cells:
                            clear = False
                            break
                if clear:
                    possible += 1
            if possible > 0:
                candidates.append((rem, possible, pos))
        if not candidates:
            return None
        # Pick smallest remaining, then smallest possible options
        candidates.sort()
        target_pos = candidates[0][2]
        # Get all possible pairs for this pos
        target_pairs = []
        for pair in possible_pairs:
            a, b = pair
            if target_pos not in (a, b):
                continue
            cnt = bridge_counts[pair]
            if cnt >= 2:
                continue
            # Check path clear
            clear = True
            if a[0] == b[0]:
                rw = a[0]
                cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                for c in range(cmin + 1, cmax):
                    if (rw, c) in used_cells:
                        clear = False
                        break
            else:
                col = a[1]
                rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                for r in range(rmin + 1, rmax):
                    if (r, col) in used_cells:
                        clear = False
                        break
            if clear:
                target_pairs.append(pair)
        # Try each possible pair
        for pair in target_pairs:
            a, b = pair
            prev_cnt = bridge_counts[pair]
            max_add = 2 - prev_cnt
            # Try adding 1 first
            for add in [1, 2] if max_add >= 2 else [1]:
                if remaining[a] < add or remaining[b] < add:
                    continue
                # Apply change
                bridge_counts[pair] += add
                remaining[a] -= add
                remaining[b] -= add
                added_cells = []
                if prev_cnt == 0:
                    if a[0] == b[0]:
                        rw = a[0]
                        cmin, cmax = min(a[1], b[1]), max(a[1], b[1])
                        for c in range(cmin + 1, cmax):
                            used_cells.add((rw, c))
                            added_cells.append((rw, c))
                    else:
                        col = a[1]
                        rmin, rmax = min(a[0], b[0]), max(a[0], b[0])
                        for r in range(rmin + 1, rmax):
                            used_cells.add((r, col))
                            added_cells.append((r, col))
                # Recurse
                res = backtrack()
                if res is not None:
                    return res
                # Undo
                bridge_counts[pair] -= add
                remaining[a] += add
                remaining[b] += add
                for cell in added_cells:
                    used_cells.remove(cell)
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

