def get_region_pairs_and_candidates(region_grid, N):
    pairs = {}
    # Process horizontal adjacent cells
    for r in range(N):
        for c in range(N-1):
            r1 = region_grid[r][c]
            r2 = region_grid[r][c+1]
            if r1 != r2:
                pair = tuple(sorted((r1, r2)))
                stitch = ((r, c), (r, c+1))
                if pair not in pairs:
                    pairs[pair] = set()
                pairs[pair].add(stitch)
    # Process vertical adjacent cells
    for r in range(N-1):
        for c in range(N):
            r1 = region_grid[r][c]
            r2 = region_grid[r+1][c]
            if r1 != r2:
                pair = tuple(sorted((r1, r2)))
                stitch = ((r, c), (r+1, c))
                if pair not in pairs:
                    pairs[pair] = set()
                pairs[pair].add(stitch)
    # Convert sets to lists for easier manipulation
    for p in pairs:
        pairs[p] = list(pairs[p])
    return pairs

def propagate(pairs, used, rem_row, rem_col, stitches):
    N = len(rem_row)
    # Create copies of state to modify without affecting original
    current_pairs = {p: cs.copy() for p, cs in pairs.items()}
    current_used = [row.copy() for row in used]
    current_rem_r = rem_row.copy()
    current_rem_c = rem_col.copy()
    current_stitches = stitches.copy()

    # Initialize queue with pairs that have only 1 candidate (forced moves)
    queue = [p for p in current_pairs if len(current_pairs[p]) == 1]

    while queue:
        p = queue.pop(0)
        if p not in current_pairs:
            continue
        candidates = current_pairs[p]
        if len(candidates) == 0:
            return (False, None, None, None, None, None)

        stitch = candidates[0]
        (r1, c1), (r2, c2) = stitch

        # Check if this stitch is valid
        if current_used[r1][c1] or current_used[r2][c2]:
            return (False, None, None, None, None, None)
        if current_rem_r[r1] <= 0 or current_rem_r[r2] <= 0:
            return (False, None, None, None, None, None)
        if current_rem_c[c1] <= 0 or current_rem_c[c2] <= 0:
            return (False, None, None, None, None, None)

        # Apply this stitch
        current_stitches.append(stitch)
        current_used[r1][c1] = True
        current_used[r2][c2] = True
        current_rem_r[r1] -= 1
        current_rem_r[r2] -= 1
        current_rem_c[c1] -= 1
        current_rem_c[c2] -= 1

        # Check for negative counts
        if current_rem_r[r1] < 0 or current_rem_r[r2] < 0 or current_rem_c[c1] < 0 or current_rem_c[c2] < 0:
            return (False, None, None, None, None, None)

        # Remove processed pair
        del current_pairs[p]

        # Remove all conflicting candidates from remaining pairs
        for other_p in list(current_pairs.keys()):
            filtered = []
            for s in current_pairs[other_p]:
                (sr1, sc1), (sr2, sc2) = s
                if (sr1 == r1 and sc1 == c1) or (sr1 == r2 and sc1 == c2) or (sr2 == r1 and sc2 == c1) or (sr2 == r2 and sc2 == c2):
                    continue
                filtered.append(s)
            if len(filtered) == 0:
                return (False, None, None, None, None, None)
            current_pairs[other_p] = filtered
            if len(filtered) == 1:
                queue.append(other_p)

    # Prune: check if remaining counts are possible
    for r in range(N):
        unused = sum(1 for c in range(N) if not current_used[r][c])
        if current_rem_r[r] < 0 or current_rem_r[r] > unused:
            return (False, None, None, None, None, None)
    for c in range(N):
        unused = sum(1 for r in range(N) if not current_used[r][c])
        if current_rem_c[c] < 0 or current_rem_c[c] > unused:
            return (False, None, None, None, None, None)

    # Prune: sum of remaining holes must be even (each stitch uses 2 holes)
    if sum(current_rem_r) % 2 != 0:
        return (False, None, None, None, None, None)

    return (True, current_pairs, current_used, current_rem_r, current_rem_c, current_stitches)

def backtrack(pairs, used, rem_row, rem_col, stitches):
    # First propagate all forced moves
    valid, new_pairs, new_used, new_rem_r, new_rem_c, new_stitches = propagate(pairs, used, rem_row, rem_col, stitches)
    if not valid:
        return None

    # Check if we've processed all region pairs
    if not new_pairs:
        if all(x == 0 for x in new_rem_r) and all(x == 0 for x in new_rem_c):
            return new_stitches
        return None

    # Select pair with minimum remaining candidates (MRV heuristic to reduce branching)
    min_len = float('inf')
    selected_pair = None
    for p in new_pairs:
        l = len(new_pairs[p])
        if l < min_len:
            min_len = l
            selected_pair = p

    # Try each candidate for the selected pair
    for stitch in new_pairs[selected_pair]:
        (r1, c1), (r2, c2) = stitch
        # Skip invalid candidates
        if new_used[r1][c1] or new_used[r2][c2]:
            continue
        if new_rem_r[r1] <= 0 or new_rem_r[r2] <= 0:
            continue
        if new_rem_c[c1] <= 0 or new_rem_c[c2] <= 0:
            continue

        # Create new state for this candidate
        temp_used = [row.copy() for row in new_used]
        temp_used[r1][c1] = True
        temp_used[r2][c2] = True
        temp_rem_r = new_rem_r.copy()
        temp_rem_r[r1] -= 1
        temp_rem_r[r2] -= 1
        temp_rem_c = new_rem_c.copy()
        temp_rem_c[c1] -= 1
        temp_rem_c[c2] -= 1

        # Check for negative counts
        if temp_rem_r[r1] < 0 or temp_rem_r[r2] < 0 or temp_rem_c[c1] < 0 or temp_rem_c[c2] < 0:
            continue

        # Filter remaining pairs to remove conflicting candidates
        temp_pairs = {}
        valid_temp = True
        for p in new_pairs:
            if p == selected_pair:
                continue
            filtered = []
            for s in new_pairs[p]:
                (sr1, sc1), (sr2, sc2) = s
                if (sr1 == r1 and sc1 == c1) or (sr1 == r2 and sc1 == c2) or (sr2 == r1 and sc2 == c1) or (sr2 == r2 and sc2 == c2):
                    continue
                filtered.append(s)
            if len(filtered) == 0:
                valid_temp = False
                break
            temp_pairs[p] = filtered
        if not valid_temp:
            continue

        temp_stitches = new_stitches.copy()
        temp_stitches.append(stitch)

        # Recursive search
        result = backtrack(temp_pairs, temp_used, temp_rem_r, temp_rem_c, temp_stitches)
        if result is not None:
            return result

    return None

def solve(observation):
    region_grid = observation['region']
    N = len(region_grid)
    row_counts = observation['row_stitch_counts']
    col_counts = observation['col_stitch_counts']

    # Get initial region pairs and their candidate stitches
    pairs = get_region_pairs_and_candidates(region_grid, N)
    used = [[False]*N for _ in range(N)]
    solution = backtrack(pairs, used, row_counts.copy(), col_counts.copy(), [])

    if solution is None:
        return "No Solution"
    # Convert to required output format (list of lists)
    return [list(s) for s in solution]

