def solve(observation):
    data = observation['data']
    adj_dots = set(tuple(p) for p in observation['adjacent'])
    N = len(data)
    if N == 0:
        return []

    # Initialize domain for each cell: set of possible values
    domains = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c].add(val)
            else:
                domains[r][c] = set(range(1, N+1))

    # Precompute adjacency list for each cell: (neighbor_row, neighbor_col, has_dot_between)
    dirs = [
        (-1, 0, lambda r, c: (r - 0.5, c)),  # up
        (1, 0, lambda r, c: (r + 0.5, c)),   # down
        (0, -1, lambda r, c: (r, c - 0.5)),  # left
        (0, 1, lambda r, c: (r, c + 0.5))    # right
    ]
    adj = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            for dr, dc, gap_func in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    gap = gap_func(r, c)
                    adj[r][c].append((nr, nc, gap in adj_dots))

    # Constraint propagation function: returns True if valid, False if conflict
    def propagate(doms):
        changed = True
        while changed:
            changed = False
            # Rule 1: Unique values per row and column (Sudoku rule)
            for r in range(N):
                for c in range(N):
                    if len(doms[r][c]) != 1:
                        continue
                    fixed_val = next(iter(doms[r][c]))
                    # Remove from same row
                    for cc in range(N):
                        if cc == c:
                            continue
                        if fixed_val in doms[r][cc]:
                            doms[r][cc].remove(fixed_val)
                            changed = True
                            if len(doms[r][cc]) == 0:
                                return False
                    # Remove from same column
                    for rr in range(N):
                        if rr == r:
                            continue
                        if fixed_val in doms[rr][c]:
                            doms[rr][c].remove(fixed_val)
                            changed = True
                            if len(doms[rr][c]) == 0:
                                return False
            # Rule 2: Adjacency dot rules
            for r in range(N):
                for c in range(N):
                    for (nr, nc, has_dot) in adj[r][c]:
                        curr_dom = doms[r][c]
                        neighbor_dom = doms[nr][nc]
                        if has_dot:
                            # Values must be consecutive: prune values with no consecutive match in neighbor
                            to_remove = set()
                            for v in curr_dom:
                                if (v + 1 not in neighbor_dom) and (v - 1 not in neighbor_dom):
                                    to_remove.add(v)
                            if to_remove:
                                changed = True
                                curr_dom -= to_remove
                                if len(curr_dom) == 0:
                                    return False
                        else:
                            # Values must NOT be consecutive: prune values where all neighbor values are consecutive
                            to_remove = set()
                            for v in curr_dom:
                                all_consecutive = True
                                for nv in neighbor_dom:
                                    if abs(v - nv) != 1:
                                        all_consecutive = False
                                        break
                                if all_consecutive:
                                    to_remove.add(v)
                            if to_remove:
                                changed = True
                                curr_dom -= to_remove
                                if len(curr_dom) == 0:
                                    return False
        return True

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    # Check if already solved
    def is_solved(doms):
        for r in range(N):
            for c in range(N):
                if len(doms[r][c]) != 1:
                    return False
        return True

    if is_solved(domains):
        return [[next(iter(cell)) for cell in row] for row in domains]

    # Backtracking with Minimum Remaining Values (MRV) heuristic
    def backtrack(doms):
        if is_solved(doms):
            return [[next(iter(cell)) for cell in row] for row in doms]
        # Find cell with smallest domain size > 1
        min_size = N + 1
        mr, mc = -1, -1
        for r in range(N):
            for c in range(N):
                s = len(doms[r][c])
                if 1 < s < min_size:
                    min_size = s
                    mr, mc = r, c
        # Try each possible value for MRV cell
        for val in sorted(doms[mr][mc]):
            # Make copy of domains
            new_doms = [[set(cell) for cell in row] for row in doms]
            new_doms[mr][mc] = {val}
            # Propagate constraints
            if propagate(new_doms):
                res = backtrack(new_doms)
                if res is not None:
                    return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

