from itertools import combinations, product

def generate_tetromino_shapes():
    tet_bases = {
        'I': [[(0,0), (1,0), (2,0), (3,0)]],
        'L': [[(0,0), (1,0), (2,0), (2,1)]],
        'T': [[(0,1), (1,0), (1,1), (1,2)]],
        'S': [[(0,1), (0,2), (1,0), (1,1)]]
    }
    def rotate90(points):
        return [(y, -x) for x,y in points]
    def reflect(points):
        return [(-x, y) for x,y in points]
    def normalize(points):
        min_r = min(p[0] for p in points)
        min_c = min(p[1] for p in points)
        return frozenset((r - min_r, c - min_c) for r,c in points)
    shapes = {}
    for ttype, bases in tet_bases.items():
        unique = set()
        for base in bases:
            current = base
            for _ in range(4):
                unique.add(normalize(current))
                unique.add(normalize(reflect(current)))
                current = rotate90(current)
        shapes[ttype] = unique
    return shapes

TET_SHAPES = generate_tetromino_shapes()

def get_region_cells(grid):
    reg_cells = {}
    N = len(grid)
    for r,c in product(range(N), range(N)):
        rid = grid[r][c]
        if rid not in reg_cells:
            reg_cells[rid] = []
        reg_cells[rid].append((r,c))
    return reg_cells

def get_region_adjacency(grid):
    adj = {}
    N = len(grid)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for r,c in product(range(N), range(N)):
        rid = grid[r][c]
        if rid not in adj:
            adj[rid] = set()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                nrid = grid[nr][nc]
                if nrid != rid:
                    adj[rid].add(nrid)
    return adj

def generate_region_candidates(cells):
    candidates = []
    cell_set = set(cells)
    for combo in combinations(cells, 4):
        rel = [(r - combo[0][0], c - combo[0][1]) for r,c in combo]
        norm = normalize(rel)
        for ttype, shapes in TET_SHAPES.items():
            if norm in shapes:
                candidates.append((ttype, frozenset(combo)))
                break
    return list(dict.fromkeys(candidates))

def normalize(points):
    min_r = min(p[0] for p in points)
    min_c = min(p[1] for p in points)
    return frozenset((r - min_r, c - min_c) for r,c in points)

def has_2x2_shaded(new_cells, existing_shaded, N):
    all_shaded = existing_shaded.union(new_cells)
    for r,c in new_cells:
        for tr, tc in [(r-1, c-1), (r-1, c), (r, c-1), (r, c)]:
            if tr < 0 or tc < 0 or tr +1 >= N or tc +1 >= N:
                continue
            if (tr,tc) in all_shaded and (tr, tc+1) in all_shaded and (tr+1, tc) in all_shaded and (tr+1, tc+1) in all_shaded:
                return True
    return False

def is_connected(shaded_cells):
    if not shaded_cells:
        return True
    start = next(iter(shaded_cells))
    visited = set()
    stack = [start]
    visited.add(start)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while stack:
        r,c = stack.pop()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in shaded_cells and (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))
    return len(visited) == len(shaded_cells)

def solve(observation):
    region_grid = observation['data']
    N = len(region_grid)
    reg_cells = get_region_cells(region_grid)
    reg_adj = get_region_adjacency(region_grid)
    reg_candidates = {rid: generate_region_candidates(reg_cells[rid]) for rid in reg_cells}
    region_order = sorted(reg_candidates.keys(), key=lambda x: len(reg_candidates[x]))
    total_regions = len(region_order)
    def backtrack(idx, assigned, shaded):
        if idx == total_regions:
            if is_connected(shaded):
                res = [[None for _ in range(N)] for _ in range(N)]
                for rid, (ttype, cells) in assigned.items():
                    for r,c in cells:
                        res[r][c] = ttype
                return res
            return None
        current_rid = region_order[idx]
        for cand_type, cand_cells in reg_candidates[current_rid]:
            valid = True
            for adj_rid in reg_adj[current_rid]:
                if adj_rid in assigned and assigned[adj_rid][0] == cand_type:
                    valid = False
                    break
            if not valid:
                continue
            if has_2x2_shaded(cand_cells, shaded, N):
                continue
            assigned[current_rid] = (cand_type, cand_cells)
            new_shaded = shaded.union(cand_cells)
            res = backtrack(idx + 1, assigned, new_shaded)
            if res is not None:
                return res
            del assigned[current_rid]
        return None
    result = backtrack(0, {}, set())
    return result if result is not None else "No Solution"

