def solve(observation):
    data = observation['data']
    N = len(data)

    # Collect all islands with their required bridge count
    islands = {}
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                islands[(r, c)] = val
    if not islands:
        return {}

    # Precompute all valid candidate bridge pairs (no duplicates, no islands in between)
    candidates = set()
    # Check right neighbors in same row
    for (r, c) in islands:
        cc = c + 1
        while cc < N:
            if data[r][cc] is not None:
                a, b = (r, c), (r, cc)
                if a < b:
                    candidates.add((a, b))
                break
            cc += 1
    # Check down neighbors in same column
    for (r, c) in islands:
        rr = r + 1
        while rr < N:
            if data[rr][c] is not None:
                a, b = (r, c), (rr, c)
                if a < b:
                    candidates.add((a, b))
                break
            rr += 1
    candidates = list(candidates)

    # Check if two bridges cross each other
    def crosses(b1, b2):
        (a1, a2), (b1_, b2_) = b1, b2
        h1 = (a1[0] == a2[0])
        h2 = (b1_[0] == b2_[0])
        if h1 == h2: # Same direction, no cross
            return False
        # Separate horizontal and vertical bridge
        h, v = (b1, b2) if h1 else (b2, b1)
        hr = h[0][0]
        hc1, hc2 = min(h[0][1], h[1][1]), max(h[0][1], h[1][1])
        vc = v[0][1]
        vr1, vr2 = min(v[0][0], v[1][0]), max(v[0][0], v[1][0])
        return (vr1 < hr < vr2) and (hc1 < vc < hc2)

    # Check if all islands are connected via bridges
    def is_connected(bridges):
        adj = {isl: [] for isl in islands}
        for (a, b), cnt in bridges.items():
            if cnt > 0:
                adj[a].append(b)
                adj[b].append(a)
        start = next(iter(islands.keys()))
        visited, q = set([start]), [start]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        return len(visited) == len(islands)

    # Backtracking with constraint propagation
    def backtrack(bridges, remaining, available_candidates):
        # Check if solution found
        if all(v == 0 for v in remaining.values()):
            if is_connected(bridges):
                return bridges.copy()
            return None

        # Prune invalid states early
        for isl, rem in remaining.items():
            if rem < 0:
                return None
            max_possible = 0
            for cand in available_candidates:
                a, b = cand
                if isl in (a, b):
                    max_possible += 2 - bridges.get(cand, 0)
            if rem > max_possible:
                return None

        # Constraint propagation loop
        changed = True
        temp_bridges = bridges.copy()
        temp_remaining = remaining.copy()
        temp_available = available_candidates.copy()

        while changed:
            changed = False
            for isl in islands:
                rem = temp_remaining[isl]
                if rem == 0:
                    continue
                # Get all valid candidates for current island
                isl_cands = []
                for cand in temp_available:
                    a, b = cand
                    if isl in (a, b):
                        cnt = temp_bridges.get(cand, 0)
                        if cnt < 2:
                            isl_cands.append((cand, 2 - cnt))
                if not isl_cands:
                    return None if rem > 0 else continue

                num_cands = len(isl_cands)
                max_total = sum(m for _, m in isl_cands)
                if rem > max_total:
                    return None

                # Rule 1: Remaining equals number of candidates, add 1 to each
                if rem == num_cands:
                    for cand, m in isl_cands:
                        curr = temp_bridges.get(cand, 0)
                        if curr >= 1:
                            continue
                        a, b = cand
                        temp_bridges[cand] = curr + 1
                        temp_remaining[a] -= 1
                        temp_remaining[b] -= 1
                        # Remove crossing candidates
                        to_remove = [c for c in temp_available if c != cand and crosses(cand, c)]
                        for rc in to_remove:
                            temp_available.remove(rc)
                        changed = True
                    continue

                # Rule 2: Remaining equals max possible bridges, add max to each
                if rem == max_total:
                    for cand, m in isl_cands:
                        curr = temp_bridges.get(cand, 0)
                        if curr == 2:
                            continue
                        a, b = cand
                        temp_bridges[cand] = 2
                        temp_remaining[a] -= m
                        temp_remaining[b] -= m
                        to_remove = [c for c in temp_available if c != cand and crosses(cand, c)]
                        for rc in to_remove:
                            temp_available.remove(rc)
                        changed = True
                    continue

                # Rule 3: Forced bridges: even max of other candidates can't cover remaining
                for i, (cand, m) in enumerate(isl_cands):
                    sum_others = sum(m2 for j, (_, m2) in enumerate(isl_cands) if j != i)
                    needed = rem - sum_others
                    if needed <= 0:
                        continue
                    curr = temp_bridges.get(cand, 0)
                    if curr + needed > 2:
                        return None
                    if curr >= needed:
                        continue
                    add = needed - curr
                    a, b = cand
                    temp_bridges[cand] = curr + add
                    temp_remaining[a] -= add
                    temp_remaining[b] -= add
                    to_remove = [c for c in temp_available if c != cand and crosses(cand, c)]
                    for rc in to_remove:
                        temp_available.remove(rc)
                    changed = True

        # Check if propagation found solution
        if all(v == 0 for v in temp_remaining.values()):
            if is_connected(temp_bridges):
                return temp_bridges

        # Select candidate with minimum possible options (MRV heuristic)
        best_cand, min_options = None, float('inf')
        for cand in temp_available:
            a, b = cand
            cnt = temp_bridges.get(cand, 0)
            if cnt >= 2:
                continue
            rem_a, rem_b = temp_remaining[a], temp_remaining[b]
            max_add = min(2 - cnt, rem_a, rem_b)
            if max_add < 0:
                continue
            options = max_add + 1
            if options < min_options:
                min_options = options
                best_cand = cand

        if best_cand is None:
            return None

        a, b = best_cand
        current_cnt = temp_bridges.get(best_cand, 0)
        max_add = min(2 - current_cnt, temp_remaining[a], temp_remaining[b])

        # Try all possible counts from highest to lowest to find solution faster
        for add in range(max_add, -1, -1):
            new_bridges = temp_bridges.copy()
            new_remaining = temp_remaining.copy()
            if add == 0:
                new_available = [c for c in temp_available if c != best_cand]
            else:
                new_bridges[best_cand] = current_cnt + add
                new_remaining[a] -= add
                new_remaining[b] -= add
                new_available = [c for c in temp_available if c != best_cand and not crosses(best_cand, c)]

            res = backtrack(new_bridges, new_remaining, new_available)
            if res is not None:
                return res

        return None

    # Initialize state
    initial_bridges = {}
    initial_remaining = {isl: val for isl, val in islands.items()}
    initial_available = candidates.copy()
    solution = backtrack(initial_bridges, initial_remaining, initial_available)

    if solution is None:
        return "No Solution"
    # Filter out zero count bridges
    return {k: v for k, v in solution.items() if v > 0}

if __name__ == "__main__":
    print(solve(OBSERVATION))
