                    grid[r-1][c] = opp
                    changed = True
                if r + 2 < n and grid[r+2][c] is None:
                    grid[r+2][c] = opp
                    changed = True
            # Rule: same values with 1 gap → middle opposite
            for r in range(n-2):
                if grid[r][c] is None or grid[r+2][c] is None or grid[r][c] != grid[r+2][c]:
                    continue
                if grid[r+1][c] is None:
                    grid[r+1][c] = 'W' if grid[r][c] == 'B' else 'B'
                    changed = True
            if has_three_consecutive([grid[r][c] for r in range(n)]):
                return None
        # Check duplicate completed rows
        seen_rows = set()
        for r in range(n):
            if all(x is not None for x in grid[r]):
                row_tuple = tuple(grid[r])
                if row_tuple in seen_rows:
                    return None
                seen_rows.add(row_tuple)
        # Check duplicate completed columns
        seen_cols = set()
        for c in range(n):
            col_tuple = tuple(grid[r][c] for r in range(n))
            if all(x is not None for x in col_tuple):
                if col_tuple in seen_cols:
                    return None
                seen_cols.add(col_tuple)
    return grid

def solve(observation):
    initial_grid = [row.copy() for row in observation['data']]
    n = len(initial_grid)
    half = n // 2

    def backtrack(grid):
        # Apply all deterministic deductions first
        deduced = apply_deductions(grid)
        if deduced is None:
            return None
        grid = deduced
        # Check if grid is fully filled
        full = True
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    full = False
                    break
            if not full:
                break
        if full:
            # Final check for unique rows and columns
            rows = [tuple(r) for r in grid]
            if len(set(rows)) != n:
                return None
            cols = [tuple(grid[r][c] for r in range(n)) for c in range(n)]
            if len(set(cols)) != n:
                return None
            return grid
        # Find cell with minimum remaining values (MRV heuristic)
        min_options = 3
        best_cell = None
        best_options = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] is not None:
                    continue
                allowed = []
                for val in ['B', 'W']:
                    # Check row validity
                    temp_row = grid[r].copy()
                    temp_row[c] = val
                    if has_three_consecutive(temp_row):
                        continue
                    b = temp_row.count('B')
                    w = temp_row.count('W')
                    if b > half or w > half:
                        continue
                    # Check column validity
                    temp_col = [grid[i][c] for i in range(n)]
                    temp_col[r] = val
                    if has_three_consecutive(temp_col):
                        continue
                    b_col = temp_col.count('B')
                    w_col = temp_col.count('W')
                    if b_col > half or w_col > half:
                        continue
                    allowed.append(val)
                if not allowed:
                    return None
                if len(allowed) < min_options:
                    min_options = len(allowed)
                    best_cell = (r, c)
                    best_options = allowed
                    if min_options == 1:
                        break
            if min_options == 1:
                break
        # Try all valid candidates for best cell
        r, c = best_cell
        for val in best_options:
            new_grid = [row.copy() for row in grid]
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res is not None:
                return res
        return None

    solution = backtrack(initial_grid)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
