import copy
from collections import deque

def propagate(domains, adj, N):
    dom = copy.deepcopy(domains)
    while True:
        q = deque()
        for (r,c) in adj:
            for (nr, nc, has_dot) in adj[(r,c)]:
                q.append(((r,c), (nr, nc), has_dot))
        ac3_changed = False
        while q:
            (r1,c1), (r2,c2), has_dot = q.popleft()
            to_remove = set()
            for a in dom[r1][c1]:
                valid = False
                for b in dom[r2][c2]:
                    if has_dot:
                        if abs(a - b) == 1:
                            valid = True
                            break
                    else:
                        if abs(a - b) != 1:
                            valid = True
                            break
                if not valid:
                    to_remove.add(a)
            if to_remove:
                dom[r1][c1] -= to_remove
                ac3_changed = True
                if not dom[r1][c1]:
                    return False, None
                for (nr, nc, hd) in adj[(r1,c1)]:
                    if (nr, nc) != (r2,c2):
                        q.append(((nr, nc), (r1,c1), hd))
        unique_changed = False
        for r in range(N):
            fixed = set()
            for c in range(N):
                if len(dom[r][c]) == 1:
                    fixed.add(next(iter(dom[r][c])))
            for c in range(N):
                if len(dom[r][c]) > 1:
                    intersect = dom[r][c] & fixed
                    if intersect:
                        dom[r][c] -= intersect
                        unique_changed = True
                        if not dom[r][c]:
                            return False, None
        for c in range(N):
            fixed = set()
            for r in range(N):
                if len(dom[r][c]) == 1:
                    fixed.add(next(iter(dom[r][c])))
            for r in range(N):
                if len(dom[r][c]) > 1:
                    intersect = dom[r][c] & fixed
                    if intersect:
                        dom[r][c] -= intersect
                        unique_changed = True
                        if not dom[r][c]:
                            return False, None
        if not ac3_changed and not unique_changed:
            break
    return True, dom

def backtrack(domains, adj, N):
    solved = True
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) != 1:
                solved = False
                break
        if not solved:
            break
    if solved:
        res = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(next(iter(domains[r][c])))
            res.append(row)
        return res
    min_size = float('inf')
    cell = None
    for r in range(N):
        for c in range(N):
            s = len(domains[r][c])
            if s > 1 and s < min_size:
                min_size = s
                cell = (r,c)
                if min_size == 2:
                    break
        if min_size == 2:
            break
    r,c = cell
    for val in sorted(domains[r][c]):
        new_dom = copy.deepcopy(domains)
        new_dom[r][c] = {val}
        valid, propagated = propagate(new_dom, adj, N)
        if not valid:
            continue
        res = backtrack(propagated, adj, N)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    if N == 0:
        return "No Solution"
    dot_set = set((x,y) for x,y in observation['adjacent'])
    adj = {}
    for r in range(N):
        for c in range(N):
            neighbors = []
            if r > 0:
                nr, nc = r-1, c
                mid = ((r + nr)/2, c)
                has_dot = mid in dot_set
                neighbors.append((nr, nc, has_dot))
            if r < N-1:
                nr, nc = r+1, c
                mid = ((r + nr)/2, c)
                has_dot = mid in dot_set
                neighbors.append((nr, nc, has_dot))
            if c > 0:
                nr, nc = r, c-1
                mid = (r, (c + nc)/2)
                has_dot = mid in dot_set
                neighbors.append((nr, nc, has_dot))
            if c < N-1:
                nr, nc = r, c+1
                mid = (r, (c + nc)/2)
                has_dot = mid in dot_set
                neighbors.append((nr, nc, has_dot))
            adj[(r,c)] = neighbors
    domains = []
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            if val is not None:
                row.append({val})
            else:
                row.append(set(range(1, N+1)))
        domains.append(row)
    valid, propagated = propagate(domains, adj, N)
    if not valid:
        return "No Solution"
    solution = backtrack(propagated, adj, N)
    return solution if solution is not None else "No Solution"

