def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return []
    cols = len(data[0])
    if cols == 0:
        return [[] for _ in range(rows)]

    # Precompute all constraints and cell-to-constraint mapping
    constraints = []
    cell_to_constraints = [[[] for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            target = data[r][c]
            if target is None:
                continue
            neighborhood = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighborhood.append((nr, nc))
            const = {'target': target, 'neighborhood': neighborhood}
            constraints.append(const)
            for (nr, nc) in neighborhood:
                cell_to_constraints[nr][nc].append(const)

    def backtrack(grid):
        # Constraint propagation loop
        while True:
            changed = False
            # Update constraint counts and apply deduction rules
            for const in constraints:
                b_count = 0
                unknown_count = 0
                for (nr, nc) in const['neighborhood']:
                    val = grid[nr][nc]
                    if val == 'B':
                        b_count += 1
                    elif val is None:
                        unknown_count += 1
                # Check for immediate contradiction
                if b_count > const['target'] or (b_count + unknown_count) < const['target']:
                    return None
                # Rule 1: All remaining unknowns must be black
                needed = const['target'] - b_count
                if needed == unknown_count and unknown_count > 0:
                    for (nr, nc) in const['neighborhood']:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'B'
                            changed = True
                # Rule 2: All remaining unknowns must be white
                elif b_count == const['target'] and unknown_count > 0:
                    for (nr, nc) in const['neighborhood']:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
            if not changed:
                break

        # Check if grid is fully solved
        all_filled = True
        candidate_cell = None
        max_constraint_count = -1
        # Select most constrained cell for guessing
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is None:
                    all_filled = False
                    constraint_count = len(cell_to_constraints[r][c])
                    if constraint_count > max_constraint_count:
                        max_constraint_count = constraint_count
                        candidate_cell = (r, c)

        if all_filled:
            # Convert white cells to None per output requirement
            return [['B' if cell == 'B' else None for cell in row] for row in grid]

        # Unconstrained cells can all be white
        if candidate_cell is None:
            return [['B' if cell == 'B' else None for cell in row] for row in grid]

        cr, cc = candidate_cell
        # Try black first
        grid_black = [row.copy() for row in grid]
        grid_black[cr][cc] = 'B'
        res_black = backtrack(grid_black)
        if res_black is not None:
            return res_black
        # Try white
        grid_white = [row.copy() for row in grid]
        grid_white[cr][cc] = 'W'
        res_white = backtrack(grid_white)
        if res_white is not None:
            return res_white

        return None

    initial_grid = [[None for _ in range(cols)] for _ in range(rows)]
    solution = backtrack(initial_grid)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
