from copy import deepcopy

def get_3x3(r, c, rows, cols):
    res = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                res.append((nr, nc))
    return res

def propagate(grid, numbered_cells, rows, cols):
    queue = []
    # Precompute reverse map: cell -> list of constraints that include it
    rev_map = [[[] for _ in range(cols)] for _ in range(rows)]
    for (cr, cc, cv) in numbered_cells:
        for (nr, nc) in get_3x3(cr, cc, rows, cols):
            rev_map[nr][nc].append((cr, cc, cv))
    # Initial process all 0 constraints first
    for (cr, cc, cv) in numbered_cells:
        if cv == 0:
            for (nr, nc) in get_3x3(cr, cc, rows, cols):
                if grid[nr][nc] is None:
                    grid[nr][nc] = False
                    queue.append((nr, nc))
                elif grid[nr][nc] is True:
                    return False, grid
    # Process queue
    while queue:
        r, c = queue.pop()
        for (cr, cc, cv) in rev_map[r][c]:
            neighbors = get_3x3(cr, cc, rows, cols)
            b_count = 0
            undecided = []
            for (nr, nc) in neighbors:
                val = grid[nr][nc]
                if val is True:
                    b_count += 1
                elif val is None:
                    undecided.append((nr, nc))
            remaining = cv - b_count
            if remaining < 0 or remaining > len(undecided):
                return False, grid
            if remaining == 0:
                for (nr, nc) in undecided:
                    if grid[nr][nc] is None:
                        grid[nr][nc] = False
                        queue.append((nr, nc))
                    elif grid[nr][nc] is True:
                        return False, grid
            elif remaining == len(undecided):
                for (nr, nc) in undecided:
                    if grid[nr][nc] is None:
                        grid[nr][nc] = True
                        queue.append((nr, nc))
                    elif grid[nr][nc] is False:
                        return False, grid
    return True, grid

def is_complete(grid, numbered_cells, rows, cols):
    # Check all cells are decided
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                return False
    # Verify all constraints
    for (cr, cc, cv) in numbered_cells:
        b_count = 0
        for (nr, nc) in get_3x3(cr, cc, rows, cols):
            if grid[nr][nc] is True:
                b_count += 1
        if b_count != cv:
            return False
    return True

def backtrack(grid, numbered_cells, rows, cols):
    valid, grid = propagate(grid, numbered_cells, rows, cols)
    if not valid:
        return None
    if is_complete(grid, numbered_cells, rows, cols):
        return grid
    # Pick MRV cell (undecided with most constraints)
    min_undecided = float('inf')
    best_cell = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                cnt = 0
                for (cr, cc, cv) in numbered_cells:
                    if abs(r - cr) <= 1 and abs(c - cc) <= 1:
                        cnt +=1
                if cnt > min_undecided or best_cell is None:
                    min_undecided = cnt
                    best_cell = (r, c)
    if not best_cell:
        return None
    r, c = best_cell
    # Try B first
    new_grid = deepcopy(grid)
    new_grid[r][c] = True
    res = backtrack(new_grid, numbered_cells, rows, cols)
    if res:
        return res
    # Try W
    new_grid = deepcopy(grid)
    new_grid[r][c] = False
    res = backtrack(new_grid, numbered_cells, rows, cols)
    return res

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    numbered_cells = []
    for r in range(rows):
        for c in range(cols):
            val = data[r][c]
            if val is not None:
                numbered_cells.append((r, c, val))
    # Initialize grid: None=undecided, True=B, False=W
    grid = [[None for _ in range(cols)] for _ in range(rows)]
    solution = backtrack(grid, numbered_cells, rows, cols)
    if not solution:
        return "No Solution"
    # Convert to output format
    output = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('B' if solution[r][c] else None)
        output.append(row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
