def solve(observation):
    # Parse grid parameters
    sub_h, sub_w = map(int, observation['unit'].split('x'))
    N = sub_h * sub_w
    grid = [row.copy() for row in observation['data']]

    # Get valid candidates for cell (i,j)
    def get_candidates(i, j):
        if grid[i][j] is not None:
            return set()
        used = set()
        # Check row
        for val in grid[i]:
            if val is not None:
                used.add(val)
        # Check column
        for x in range(N):
            val = grid[x][j]
            if val is not None:
                used.add(val)
        # Check subgrid
        si = (i // sub_h) * sub_h
        sj = (j // sub_w) * sub_w
        for di in range(sub_h):
            for dj in range(sub_w):
                val = grid[si + di][sj + dj]
                if val is not None:
                    used.add(val)
        return set(range(1, N+1)) - used

    # Constraint propagation: naked singles + hidden singles
    def propagate():
        while True:
            updated = False
            # Process naked singles
            for i in range(N):
                for j in range(N):
                    if grid[i][j] is None:
                        cand = get_candidates(i, j)
                        if not cand:
                            return False  # Invalid state
                        if len(cand) == 1:
                            grid[i][j] = cand.pop()
                            updated = True
            if updated:
                continue
            # Process hidden singles per row
            for i in range(N):
                for num in range(1, N+1):
                    possible = []
                    for j in range(N):
                        if grid[i][j] is None and num in get_candidates(i, j):
                            possible.append(j)
                            if len(possible) > 1:
                                break
                    if len(possible) == 1:
                        grid[i][possible[0]] = num
                        updated = True
            if updated:
                continue
            # Process hidden singles per column
            for j in range(N):
                for num in range(1, N+1):
                    possible = []
                    for i in range(N):
                        if grid[i][j] is None and num in get_candidates(i, j):
                            possible.append(i)
                            if len(possible) > 1:
                                break
                    if len(possible) == 1:
                        grid[possible[0]][j] = num
                        updated = True
            if updated:
                continue
            # Process hidden singles per subgrid
            for si in range(0, N, sub_h):
                for sj in range(0, N, sub_w):
                    for num in range(1, N+1):
                        possible = []
                        for di in range(sub_h):
                            for dj in range(sub_w):
                                i = si + di
                                j = sj + dj
                                if grid[i][j] is None and num in get_candidates(i, j):
                                    possible.append((i, j))
                                    if len(possible) > 1:
                                        break
                            if len(possible) > 1:
                                break
                        if len(possible) == 1:
                            i, j = possible[0]
                            grid[i][j] = num
                            updated = True
            if not updated:
                return True  # No more possible deductions

    # Backtracking search with minimum remaining values heuristic
    def backtrack():
        if not propagate():
            return None
        # Check if grid is fully solved
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    break
            else:
                continue
            break
        else:
            return [row.copy() for row in grid]
        # Find cell with fewest candidates to minimize branching
        min_len = float('inf')
        best_cell = None
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    cand = get_candidates(i, j)
                    l = len(cand)
                    if l < min_len:
                        min_len = l
                        best_cell = (i, j, cand)
                        if min_len == 2:  # Can't get better than 2 options
                            break
            if min_len == 2:
                break
        i, j, cands = best_cell
        for num in cands:
            grid[i][j] = num
            res = backtrack()
            if res is not None:
                return res
            grid[i][j] = None  # Undo move
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
