        [None, 'B', None, 'W', None, None, 'W', 'B', None, None]
    ]
}

def solve(observation):
    grid = [row.copy() for row in observation['data']]
    n = len(grid)
    if n == 0 or len(grid[0]) != n or n % 2 != 0:
        return "No Solution"
    required = n // 2

    def count_row_b(r):
        return sum(1 for c in range(n) if grid[r][c] == 'B')

    def count_row_w(r):
        return sum(1 for c in range(n) if grid[r][c] == 'W')

    def count_col_b(c):
        return sum(1 for r in range(n) if grid[r][c] == 'B')

    def count_col_w(c):
        return sum(1 for r in range(n) if grid[r][c] == 'W')

    def get_possible(r, c):
        if grid[r][c] is not None:
            return [grid[r][c]]
        possible = []
        for val in ['B', 'W']:
            if val == 'B':
                if count_row_b(r) + 1 > required or count_col_b(c) + 1 > required:
                    continue
            else:
                if count_row_w(r) + 1 > required or count_col_w(c) + 1 > required:
                    continue
            # Check row triplets
            valid_row = True
            if c >= 2 and grid[r][c-1] == val and grid[r][c-2] == val:
                valid_row = False
            if 1 <= c <= n-2 and grid[r][c-1] == val and grid[r][c+1] == val:
                valid_row = False
            if c <= n-3 and grid[r][c+1] == val and grid[r][c+2] == val:
                valid_row = False
            if not valid_row:
                continue
            # Check column triplets
            valid_col = True
            if r >= 2 and grid[r-1][c] == val and grid[r-2][c] == val:
                valid_col = False
            if 1 <= r <= n-2 and grid[r-1][c] == val and grid[r+1][c] == val:
                valid_col = False
            if r <= n-3 and grid[r+1][c] == val and grid[r+2][c] == val:
                valid_col = False
            if valid_col:
                possible.append(val)
        return possible

    def deduce():
        changed = True
        while changed:
            changed = False
            # Validate row/column count feasibility
            for r in range(n):
                b, w = count_row_b(r), count_row_w(r)
                rem = n - b - w
                need_b, need_w = required - b, required - w
                if need_b < 0 or need_w < 0 or need_b > rem or need_w > rem:
                    return False
            for c in range(n):
                b, w = count_col_b(c), count_col_w(c)
                rem = n - b - w
                need_b, need_w = required - b, required - w
                if need_b < 0 or need_w < 0 or need_b > rem or need_w > rem:
                    return False
            # Fill rows where remaining cells are all same color
            for r in range(n):
                b, w = count_row_b(r), count_row_w(r)
                rem = n - b - w
                need_b, need_w = required - b, required - w
                if need_b == rem and need_b > 0:
                    for c in range(n):
                        if grid[r][c] is None:
                            grid[r][c] = 'B'
                            changed = True
                elif need_w == rem and need_w > 0:
                    for c in range(n):
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True
            # Fill columns where remaining cells are all same color
            for c in range(n):
                b, w = count_col_b(c), count_col_w(c)
                rem = n - b - w
                need_b, need_w = required - b, required - w
                if need_b == rem and need_b > 0:
                    for r in range(n):
                        if grid[r][c] is None:
                            grid[r][c] = 'B'
                            changed = True
                elif need_w == rem and need_w > 0:
                    for r in range(n):
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True
            # Fill cells with only one possible value
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is None:
                        poss = get_possible(r, c)
                        if len(poss) == 0:
                            return False
                        if len(poss) == 1:
                            grid[r][c] = poss[0]
                            changed = True
            # Check for duplicate completed rows
            seen_rows = set()
            for r in range(n):
                if all(x is not None for x in grid[r]):
                    row_tup = tuple(grid[r])
                    if row_tup in seen_rows:
                        return False
                    seen_rows.add(row_tup)
            # Check for duplicate completed columns
            seen_cols = set()
            for c in range(n):
                col = [grid[r][c] for r in range(n)]
                if all(x is not None for x in col):
                    col_tup = tuple(col)
                    if col_tup in seen_cols:
                        return False
                    seen_cols.add(col_tup)
        return True

    if not deduce():
        return "No Solution"

    def is_full():
        return all(all(x is not None for x in row) for row in grid)

    if is_full():
        rows = [tuple(r) for r in grid]
        cols = [tuple(grid[r][c] for r in range(n)) for c in range(n)]
        if len(set(rows)) == n and len(set(cols)) == n:
            return grid
        return "No Solution"

    # Select MRV cell
    min_options = 3
    best_cell = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                opts = len(get_possible(r, c))
                if opts < min_options:
                    min_options = opts
                    best_cell = (r, c)
                    if min_options == 2:
                        break
        if min_options == 2:
            break
    r, c = best_cell

    for val in get_possible(r, c):
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = val
        res = solve({'data': new_grid})
        if res != "No Solution":
            return res

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
