from copy import deepcopy

def solve(observation):
    # Parse input parameters
    data = observation['data']
    r_unit, c_unit = map(int, observation['unit'].split('x'))
    N = r_unit * c_unit
    all_nums = set(range(1, N+1))

    # Initialize possible values grid: each cell is a set of allowed values
    possible = []
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            if val is not None:
                row.append({val})
            else:
                row.append(set(all_nums))
        possible.append(row)

    # Helper: get all cells in the same subgrid as (r,c)
    def get_subgrid_peers(r, c):
        sg_r_start = (r // r_unit) * r_unit
        sg_c_start = (c // c_unit) * c_unit
        peers = []
        for dr in range(r_unit):
            for dc in range(c_unit):
                peers.append((sg_r_start + dr, sg_c_start + dc))
        return peers

    # Constraint propagation function: apply naked and hidden singles until no changes or invalid
    def propagate(poss):
        changed = True
        while changed:
            changed = False
            # Step 1: Naked singles: cells with exactly 1 possible value, remove from peers
            for r in range(N):
                for c in range(N):
                    if len(poss[r][c]) == 1:
                        val = next(iter(poss[r][c]))
                        # Remove from same row
                        for cc in range(N):
                            if cc != c and val in poss[r][cc]:
                                poss[r][cc].remove(val)
                                changed = True
                                if len(poss[r][cc]) == 0:
                                    return False
                        # Remove from same column
                        for rr in range(N):
                            if rr != r and val in poss[rr][c]:
                                poss[rr][c].remove(val)
                                changed = True
                                if len(poss[rr][c]) == 0:
                                    return False
                        # Remove from same subgrid
                        for (rr, cc) in get_subgrid_peers(r, c):
                            if (rr != r or cc != c) and val in poss[rr][cc]:
                                poss[rr][cc].remove(val)
                                changed = True
                                if len(poss[rr][cc]) == 0:
                                    return False

            # Step 2: Hidden singles: check each value in row/col/subgrid has exactly one possible cell
            # Check rows
            for r in range(N):
                for num in all_nums:
                    candidates = []
                    for c in range(N):
                        if num in poss[r][c]:
                            candidates.append(c)
                    if len(candidates) == 1:
                        c = candidates[0]
                        if poss[r][c] != {num}:
                            poss[r][c] = {num}
                            changed = True
                    if len(candidates) == 0:
                        return False
            # Check columns
            for c in range(N):
                for num in all_nums:
                    candidates = []
                    for r in range(N):
                        if num in poss[r][c]:
                            candidates.append(r)
                    if len(candidates) == 1:
                        r = candidates[0]
                        if poss[r][c] != {num}:
                            poss[r][c] = {num}
                            changed = True
                    if len(candidates) == 0:
                        return False
            # Check subgrids
            for sg_r in range(0, N, r_unit):
                for sg_c in range(0, N, c_unit):
                    for num in all_nums:
                        candidates = []
                        for dr in range(r_unit):
                            for dc in range(c_unit):
                                r = sg_r + dr
                                c = sg_c + dc
                                if num in poss[r][c]:
                                    candidates.append((r,c))
                        if len(candidates) == 1:
                            r, c = candidates[0]
                            if poss[r][c] != {num}:
                                poss[r][c] = {num}
                                changed = True
                        if len(candidates) == 0:
                            return False
        return True

    # Initial propagation
    if not propagate(possible):
        return "No Solution"

    # Check if already solved
    solved = True
    for r in range(N):
        for c in range(N):
            if len(possible[r][c]) != 1:
                solved = False
                break
        if not solved:
            break
    if solved:
        return [[next(iter(cell)) for cell in row] for row in possible]

    # Backtracking with MRV heuristic (minimum remaining values)
    def backtrack(poss):
        # Find cell with smallest number of possible values > 1
        min_len = N + 1
        target = None
        for r in range(N):
            for c in range(N):
                l = len(poss[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    target = (r, c)
                    if min_len == 2:  # Can't get smaller than 2, early exit
                        break
            if min_len == 2:
                break
        if target is None:
            # All cells have 1 value, solved
            return [[next(iter(cell)) for cell in row] for row in poss]
        r, c = target
        # Try each possible value
        for val in sorted(poss[r][c]):
            new_poss = deepcopy(poss)
            new_poss[r][c] = {val}
            if propagate(new_poss):
                res = backtrack(new_poss)
                if res != "No Solution":
                    return res
        return "No Solution"

    return backtrack(possible)

