        return False

    def get_possible_illuminators(y, x, state):
        possible = []
        # Left
        nx = x - 1
        while nx >= 0 and (y, nx) not in black:
            if state[y][nx] == 'B':
                return [(y, nx)]
            if state[y][nx] is None:
                possible.append((y, nx))
            nx -= 1
        # Right
        nx = x + 1
        while nx < n and (y, nx) not in black:
            if state[y][nx] == 'B':
                return [(y, nx)]
            if state[y][nx] is None:
                possible.append((y, nx))
            nx += 1
        # Up
        ny = y - 1
        while ny >= 0 and (ny, x) not in black:
            if state[ny][x] == 'B':
                return [(ny, x)]
            if state[ny][x] is None:
                possible.append((ny, x))
            ny -= 1
        # Down
        ny = y + 1
        while ny < n and (ny, x) not in black:
            if state[ny][x] == 'B':
                return [(ny, x)]
            if state[ny][x] is None:
                possible.append((ny, x))
            ny += 1
        return possible

    def is_solved(state, counts):
        for (y, x, num) in numbered:
            if counts[(y, x)] != num:
                return False
        for y in range(n):
            for x in range(n):
                if (y, x) not in black and not is_illuminated(y, x, state):
                    return False
        return True

    # Preprocess board
    black = set()
    numbered = []
    initial_counts = {}
    for y in range(n):
        for x in range(n):
            val = data[y][x]
            if val is not None:
                black.add((y, x))
                if 0 <= val <= 4:
                    numbered.append((y, x, val))
                    initial_counts[(y, x)] = 0

    def backtrack(state, counts):
        # Run deduction loop
        changed = True
        while changed:
            changed = False
            # Process numbered cells
            for (y, x, num) in numbered:
                current = counts[(y, x)]
                remaining = num - current
                if remaining < 0:
                    return None
                adj = get_adjacent(y, x)
                available = []
                for ny, nx in adj:
                    if (ny, nx) not in black and state[ny][nx] != 'F':
                        available.append((ny, nx))
                if remaining == len(available):
                    for ny, nx in available:
                        if state[ny][nx] == 'B':
                            continue
                        if not place_bulb(ny, nx, state, counts):
                            return None
                        changed = True
                elif remaining == 0:
                    for ny, nx in available:
                        if state[ny][nx] is None:
                            state[ny][nx] = 'F'
                            changed = True
            # Process unilluminated cells
            for y in range(n):
                for x in range(n):
                    if (y, x) in black:
                        continue
                    if is_illuminated(y, x, state):
                        continue
                    possible = get_possible_illuminators(y, x, state)
                    if len(possible) == 0:
                        return None
                    elif len(possible) == 1:
                        ny, nx = possible[0]
                        if state[ny][nx] == 'B':
                            continue
                        if not place_bulb(ny, nx, state, counts):
                            return None
                        changed = True
        # Check if solved
        if is_solved(state, counts):
            output = [[None for _ in range(n)] for _ in range(n)]
            for y in range(n):
                for x in range(n):
                    if state[y][x] == 'B':
                        output[y][x] = 'B'
            return output
        # Find unknown cells
        unknown = []
        for y in range(n):
            for x in range(n):
                if (y, x) not in black and state[y][x] is None:
                    unknown.append((y, x))
        if not unknown:
            return None
        # Pick first unknown cell for branching
        y, x = unknown[0]
        # Try placing bulb
        new_state = [r.copy() for r in state]
        new_counts = counts.copy()
        if place_bulb(y, x, new_state, new_counts):
            res = backtrack(new_state, new_counts)
            if res is not None:
                return res
        # Try marking as forbidden
        new_state = [r.copy() for r in state]
        new_counts = counts.copy()
        new_state[y][x] = 'F'
        res = backtrack(new_state, new_counts)
        if res is not None:
            return res
        return None

    initial_state = [[None for _ in range(n)] for _ in range(n)]
    solution = backtrack(initial_state, initial_counts.copy())
    return solution if solution is not None else "No Solution"

