from itertools import combinations
from copy import deepcopy

def generate_patterns(length, clues):
    total_blacks = sum(clues)
    num_clues = len(clues)
    if total_blacks + (num_clues - 1) > length:
        return []
    free_spaces = length - total_blacks - (num_clues - 1)
    gaps = num_clues + 1
    patterns = []
    for splits in combinations(range(free_spaces + gaps - 1), gaps - 1):
        spaces = [splits[0]]
        for i in range(1, len(splits)):
            spaces.append(splits[i] - splits[i-1] - 1)
        spaces.append((free_spaces + gaps -1) - splits[-1] - 1 + 1)
        pattern = []
        for i in range(num_clues):
            pattern.extend([None]*spaces[i])
            pattern.extend(['B']*clues[i])
            if i != num_clues - 1:
                pattern.append(None)
        pattern.extend([None]*spaces[-1])
        patterns.append(pattern)
    return patterns

def propagate(grid, row_patterns, col_patterns, rows, cols):
    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is not None:
                    continue
                row_vals = {pat[c] for pat in row_patterns[r]}
                col_vals = {pat[r] for pat in col_patterns[c]}
                valid_vals = row_vals.intersection(col_vals)
                if not valid_vals:
                    return False, row_patterns, col_patterns, grid
                if len(valid_vals) == 1:
                    grid[r][c] = next(iter(valid_vals))
                    changed = True
        for r in range(rows):
            new_pats = []
            for pat in row_patterns[r]:
                valid = True
                for c in range(cols):
                    if grid[r][c] is not None and pat[c] != grid[r][c]:
                        valid = False
                        break
                if valid:
                    new_pats.append(pat)
            if not new_pats:
                return False, row_patterns, col_patterns, grid
            if len(new_pats) != len(row_patterns[r]):
                changed = True
                row_patterns[r] = new_pats
        for c in range(cols):
            new_pats = []
            for pat in col_patterns[c]:
                valid = True
                for r in range(rows):
                    if grid[r][c] is not None and pat[r] != grid[r][c]:
                        valid = False
                        break
                if valid:
                    new_pats.append(pat)
            if not new_pats:
                return False, row_patterns, col_patterns, grid
            if len(new_pats) != len(col_patterns[c]):
                changed = True
                col_patterns[c] = new_pats
    return True, row_patterns, col_patterns, grid

def backtrack(grid, row_patterns, col_patterns, rows, cols):
    valid, rp, cp, g = propagate(deepcopy(grid), deepcopy(row_patterns), deepcopy(col_patterns), rows, cols)
    if not valid:
        return None
    all_fixed = True
    for r in range(rows):
        for c in range(cols):
            if g[r][c] is None:
                all_fixed = False
                break
        if not all_fixed:
            break
    if all_fixed:
        return g
    row_order = sorted(range(rows), key=lambda x: len(rp[x]))
    for r in row_order:
        if len(rp[r]) > 1:
            for pat in rp[r]:
                new_grid = deepcopy(g)
                for c in range(cols):
                    new_grid[r][c] = pat[c]
                res = backtrack(new_grid, rp, cp, rows, cols)
                if res is not None:
                    return res
            return None
    return None

def solve(observation):
    row_clues = observation["row_black_runs"]
    col_clues = observation["col_black_runs"]
    rows = len(row_clues)
    cols = len(col_clues)
    row_patterns = []
    for clues in row_clues:
        pats = generate_patterns(cols, clues)
        if not pats:
            return "No Solution"
        row_patterns.append(pats)
    col_patterns = []
    for clues in col_clues:
        pats = generate_patterns(rows, clues)
        if not pats:
            return "No Solution"
        col_patterns.append(pats)
    grid = [[None for _ in range(cols)] for _ in range(rows)]
    solution = backtrack(grid, row_patterns, col_patterns, rows, cols)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
