def generate_subset_masks(weights, target):
    n = len(weights)
    masks = []
    for mask in range(0, 1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += weights[i]
                if total > target:
                    break
        if total == target:
            masks.append(mask)
    return masks

def propagate(row_possible, col_possible, n_rows, n_cols):
    rp = [list(masks) for masks in row_possible]
    cp = [list(masks) for masks in col_possible]
    changed = True
    while changed:
        changed = False
        required = [[None for _ in range(n_cols)] for _ in range(n_rows)]
        # Process rows for required/forbidden cells
        for i in range(n_rows):
            masks = rp[i]
            if not masks:
                return None, None, False
            all_set = masks[0]
            all_unset = masks[0]
            for m in masks[1:]:
                all_set &= m
                all_unset |= m
            for j in range(n_cols):
                if all_set & (1 << j):
                    if required[i][j] is False:
                        return None, None, False
                    required[i][j] = True
                if not (all_unset & (1 << j)):
                    if required[i][j] is True:
                        return None, None, False
                    required[i][j] = False
        # Process columns for required/forbidden cells
        for j in range(n_cols):
            masks = cp[j]
            if not masks:
                return None, None, False
            all_set = masks[0]
            all_unset = masks[0]
            for m in masks[1:]:
                all_set &= m
                all_unset |= m
            for i in range(n_rows):
                if all_set & (1 << i):
                    if required[i][j] is False:
                        return None, None, False
                    required[i][j] = True
                if not (all_unset & (1 << i)):
                    if required[i][j] is True:
                        return None, None, False
                    required[i][j] = False
        # Filter row masks
        for i in range(n_rows):
            new_masks = []
            for m in rp[i]:
                valid = True
                for j in range(n_cols):
                    if required[i][j] is True and not (m & (1 << j)):
                        valid = False
                        break
                    if required[i][j] is False and (m & (1 << j)):
                        valid = False
                        break
                if valid:
                    new_masks.append(m)
            if len(new_masks) != len(rp[i]):
                changed = True
                rp[i] = new_masks
                if not rp[i]:
                    return None, None, False
        # Filter column masks
        for j in range(n_cols):
            new_masks = []
            for m in cp[j]:
                valid = True
                for i in range(n_rows):
                    if required[i][j] is True and not (m & (1 << i)):
                        valid = False
                        break
                    if required[i][j] is False and (m & (1 << i)):
                        valid = False
                        break
                if valid:
                    new_masks.append(m)
            if len(new_masks) != len(cp[j]):
                changed = True
                cp[j] = new_masks
                if not cp[j]:
                    return None, None, False
    return rp, cp, True

def backtrack(rp, cp, n_rows, n_cols):
    rp, cp, valid = propagate(rp, cp, n_rows, n_cols)
    if not valid:
        return None
    # Check if solution is found
    complete = True
    for i in range(n_rows):
        if len(rp[i]) != 1:
            complete = False
            break
    if complete:
        grid = []
        for i in range(n_rows):
            mask = rp[i][0]
            row = []
            for j in range(n_cols):
                row.append('B' if (mask & (1 << j)) else None)
            grid.append(row)
        return grid
    # Pick row with smallest number of remaining possibilities
    min_len = float('inf')
    pick_row = -1
    for i in range(n_rows):
        l = len(rp[i])
        if 1 < l < min_len:
            min_len = l
            pick_row = i
    # Try all possible masks for picked row
    for mask in rp[pick_row]:
        new_rp = [list(m) for m in rp]
        new_rp[pick_row] = [mask]
        res = backtrack(new_rp, cp, n_rows, n_cols)
        if res is not None:
            return res
    return None

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n_rows = len(row_sum)
    n_cols = len(col_sum)
    row_weights = [i + 1 for i in range(n_rows)]
    col_weights = [j + 1 for j in range(n_cols)]
    # Generate initial possible masks
    row_possible = []
    for rs in row_sum:
        masks = generate_subset_masks(col_weights, rs)
        if not masks:
            return "No Solution"
        row_possible.append(masks)
    col_possible = []
    for cs in col_sum:
        masks = generate_subset_masks(row_weights, cs)
        if not masks:
            return "No Solution"
        col_possible.append(masks)
    result = backtrack(row_possible, col_possible, n_rows, n_cols)
    return result if result is not None else "No Solution"

