from typing import List, Tuple, Dict, Optional

Edge = Tuple[str, int, int]
Vertex = Tuple[int, int]

def get_cell_edges(i: int, j: int) -> List[Edge]:
    return [('h', i, j), ('h', i+1, j), ('v', i, j), ('v', i, j+1)]

def get_vertex_edges(r: int, c: int, N: int) -> List[Edge]:
    edges = []
    if r > 0: edges.append(('v', r-1, c))
    if r < N: edges.append(('v', r, c))
    if c > 0: edges.append(('h', r, c-1))
    if c < N: edges.append(('h', r, c))
    return edges

def propagate(edges: Dict[Edge, Optional[bool]], clues: List[List[Optional[int]]], N: int) -> bool:
    changed = True
    while changed:
        changed = False
        # Process cell clues
        for i in range(N):
            for j in range(N):
                k = clues[i][j]
                if k is None: continue
                cell_edges = get_cell_edges(i,j)
                t = 0
                f = 0
                u = []
                for e in cell_edges:
                    s = edges[e]
                    if s is True: t += 1
                    elif s is False: f +=1
                    else: u.append(e)
                if t > k or (t + len(u)) < k:
                    return False
                if t == k:
                    for e in u:
                        if edges[e] is None:
                            edges[e] = False
                            changed = True
                if (t + len(u)) == k:
                    for e in u:
                        if edges[e] is None:
                            edges[e] = True
                            changed = True
        # Process vertices
        for r in range(N+1):
            for c in range(N+1):
                v_edges = get_vertex_edges(r, c, N)
                t = 0
                u = []
                for e in v_edges:
                    s = edges[e]
                    if s is True: t +=1
                    elif s is None: u.append(e)
                if t > 2 or (t + len(u)) < 2:
                    return False
                if t == 2:
                    for e in u:
                        if edges[e] is None:
                            edges[e] = False
                            changed = True
                if t == 1 and len(u) == 1:
                    e = u[0]
                    if edges[e] is None:
                        edges[e] = True
                        changed = True
    return True

def is_complete(edges: Dict[Edge, Optional[bool]]) -> bool:
    return all(s is not None for s in edges.values())

def pick_branch_edge(edges: Dict[Edge, Optional[bool]]) -> Optional[Edge]:
    for e, s in edges.items():
        if s is None:
            return e
    return None

def build_loop(edges: Dict[Edge, Optional[bool]], N: int) -> Optional[List[Vertex]]:
    adj: Dict[Vertex, List[Vertex]] = {}
    for r in range(N+1):
        for c in range(N+1):
            adj[(r,c)] = []
    for e, s in edges.items():
        if s is not True: continue
        if e[0] == 'h':
            r, c = e[1], e[2]
            adj[(r,c)].append((r, c+1))
            adj[(r,c+1)].append((r,c))
        else:
            r, c = e[1], e[2]
            adj[(r,c)].append((r+1, c))
            adj[(r+1,c)].append((r,c))
    start = None
    for v, neighbors in adj.items():
        if len(neighbors) == 2:
            start = v
            break
    if start is None:
        return None
    path = [start]
    prev = None
    current = start
    while True:
        next_nodes = [n for n in adj[current] if n != prev]
        if len(next_nodes) != 1:
            return None
        prev = current
        current = next_nodes[0]
        path.append(current)
        if current == start:
            break
    expected_edges = sum(1 for s in edges.values() if s is True)
    if len(path) - 1 != expected_edges:
        return None
    return path

def backtrack(edges: Dict[Edge, Optional[bool]], clues: List[List[Optional[int]]], N: int) -> Optional[List[Vertex]]:
    if not propagate(edges, clues, N):
        return None
    if is_complete(edges):
        return build_loop(edges, N)
    e = pick_branch_edge(edges)
    if e is None:
        return None
    for val in [True, False]:
        new_edges = edges.copy()
        new_edges[e] = val
        res = backtrack(new_edges, clues, N)
        if res is not None:
            return res
    return None

def solve(observation: Dict) -> List[Tuple[int, int]] | str:
    clues = observation['data']
    N = len(clues)
    edges: Dict[Edge, Optional[bool]] = {}
    for r in range(N+1):
        for c in range(N):
            edges[('h', r, c)] = None
    for r in range(N):
        for c in range(N+1):
            edges[('v', r, c)] = None
    solution = backtrack(edges, clues, N)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
