def solve(observation):
    data = observation['data']
    dots = set(observation['adjacent'])
    N = len(data)
    if N == 0:
        return "No Solution"

    # Precompute adjacency list for each cell: list of (neighbor_row, neighbor_col, has_dot)
    adj = [[[] for _ in range(N)] for _ in range(N)]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for r in range(N):
        for c in range(N):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    # Calculate midpoint
                    if dr != 0: # vertical adjacency, midpoint is (min(r,nr)+0.5, c)
                        mid = (min(r, nr) + 0.5, c)
                    else: # horizontal adjacency, midpoint is (r, min(c, nc)+0.5)
                        mid = (r, min(c, nc) + 0.5)
                    has_dot = mid in dots
                    adj[r][c].append((nr, nc, has_dot))

    # Initialize domains: set of possible values per cell
    domains = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                domains[r][c].add(val)
            else:
                domains[r][c] = set(range(1, N+1))

    # Constraint propagation function, returns (updated_domains, is_valid)
    def propagate(dom):
        # Make copy to modify
        dom = [[set(s) for s in row] for row in dom]
        changed = True
        while changed:
            changed = False
            # 1. Uniqueness constraint: row
            for r in range(N):
                fixed = set()
                for c in range(N):
                    if len(dom[r][c]) == 1:
                        fixed.add(next(iter(dom[r][c])))
                for c in range(N):
                    if len(dom[r][c]) > 1:
                        orig_len = len(dom[r][c])
                        dom[r][c] -= fixed
                        if len(dom[r][c]) == 0:
                            return dom, False
                        if len(dom[r][c]) != orig_len:
                            changed = True
            # 2. Uniqueness constraint: column
            for c in range(N):
                fixed = set()
                for r in range(N):
                    if len(dom[r][c]) == 1:
                        fixed.add(next(iter(dom[r][c])))
                for r in range(N):
                    if len(dom[r][c]) > 1:
                        orig_len = len(dom[r][c])
                        dom[r][c] -= fixed
                        if len(dom[r][c]) == 0:
                            return dom, False
                        if len(dom[r][c]) != orig_len:
                            changed = True
            # 3. Adjacency constraints (dot and no dot)
            for r in range(N):
                for c in range(N):
                    for (nr, nc, has_dot) in adj[r][c]:
                        d1 = dom[r][c]
                        d2 = dom[nr][nc]
                        if has_dot:
                            # Must be consecutive: prune d1 values with no consecutive in d2
                            new_d1 = set()
                            for v in d1:
                                if (v+1 in d2) or (v-1 in d2):
                                    new_d1.add(v)
                            if new_d1 != d1:
                                if not new_d1:
                                    return dom, False
                                dom[r][c] = new_d1
                                changed = True
                            # Prune d2
                            new_d2 = set()
                            for v in d2:
                                if (v+1 in d1) or (v-1 in d1):
                                    new_d2.add(v)
                            if new_d2 != d2:
                                if not new_d2:
                                    return dom, False
                                dom[nr][nc] = new_d2
                                changed = True
                        else:
                            # Must NOT be consecutive: prune values with all consecutive in other domain
                            # First check if all pairs are consecutive: invalid
                            all_consec = True
                            for v1 in d1:
                                for v2 in d2:
                                    if abs(v1 - v2) != 1:
                                        all_consec = False
                                        break
                                if not all_consec:
                                    break
                            if all_consec:
                                return dom, False
                            # Prune d1
                            new_d1 = set()
                            for v1 in d1:
                                has_valid = False
                                for v2 in d2:
                                    if abs(v1 - v2) != 1:
                                        has_valid = True
                                        break
                                if has_valid:
                                    new_d1.add(v1)
                            if new_d1 != d1:
                                if not new_d1:
                                    return dom, False
                                dom[r][c] = new_d1
                                changed = True
                            # Prune d2
                            new_d2 = set()
                            for v2 in d2:
                                has_valid = False
                                for v1 in d1:
                                    if abs(v2 - v1) != 1:
                                        has_valid = True
                                        break
                                if has_valid:
                                    new_d2.add(v2)
                            if new_d2 != d2:
                                if not new_d2:
                                    return dom, False
                                dom[nr][nc] = new_d2
                                changed = True
        # Final validity check
        for r in range(N):
            for c in range(N):
                if not dom[r][c]:
                    return dom, False
        return dom, True

    # Initial propagation
    domains, valid = propagate(domains)
    if not valid:
        return "No Solution"

    # Backtracking search with MRV heuristic
    def backtrack(dom):
        # Check if solved
        solved = True
        min_size = N+1
        best_cell = None
        for r in range(N):
            for c in range(N):
                s = len(dom[r][c])
                if s > 1:
                    solved = False
                    if s < min_size:
                        min_size = s
                        best_cell = (r,c)
        if solved:
            # Convert to solution grid
            res = []
            for r in range(N):
                row = []
                for c in range(N):
                    row.append(next(iter(dom[r][c])))
                res.append(row)
            return res

        r,c = best_cell
        # Try each possible value in domain
        for val in sorted(dom[r][c]):
            # Create new domain with this value assigned
            new_dom = [[set(s) for s in row] for row in dom]
            new_dom[r][c] = {val}
            # Propagate constraints
            new_dom, valid = propagate(new_dom)
            if not valid:
                continue
            # Recurse
            res = backtrack(new_dom)
            if res is not None:
                return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
