def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    N = len(row_sum)
    M = len(col_sum)
    row_weights = list(range(1, N + 1))
    col_weights = list(range(1, M + 1))

    # Precompute all valid masks for each row
    row_possible = []
    for i in range(N):
        target = row_sum[i]
        valid_masks = []
        for mask in range(0, 1 << M):
            total = 0
            for j in range(M):
                if mask & (1 << j):
                    total += col_weights[j]
            if total == target:
                valid_masks.append(mask)
        if not valid_masks:
            return "No Solution"
        row_possible.append(valid_masks)

    # Precompute all valid masks for each column
    col_possible = []
    for j in range(M):
        target = col_sum[j]
        valid_masks = []
        for mask in range(0, 1 << N):
            total = 0
            for i in range(N):
                if mask & (1 << i):
                    total += row_weights[i]
            if total == target:
                valid_masks.append(mask)
        if not valid_masks:
            return "No Solution"
        col_possible.append(valid_masks)

    # Constraint propagation function
    def propagate(rp, cp):
        changed = True
        while changed:
            changed = False
            # Process rows to force column values
            for i in range(N):
                masks = rp[i]
                if not masks:
                    return None, None
                for j in range(M):
                    all_set = all((m & (1 << j)) != 0 for m in masks)
                    all_unset = all((m & (1 << j)) == 0 for m in masks)
                    if all_set or all_unset:
                        val = 1 if all_set else 0
                        # Filter column masks
                        new_cp = [m for m in cp[j] if ((m >> i) & 1) == val]
                        if len(new_cp) != len(cp[j]):
                            cp[j] = new_cp
                            changed = True
                            if not cp[j]:
                                return None, None
            # Process columns to force row values
            for j in range(M):
                masks = cp[j]
                if not masks:
                    return None, None
                for i in range(N):
                    all_set = all((m & (1 << i)) != 0 for m in masks)
                    all_unset = all((m & (1 << i)) == 0 for m in masks)
                    if all_set or all_unset:
                        val = 1 if all_set else 0
                        # Filter row masks
                        new_rp = [m for m in rp[i] if ((m >> j) & 1) == val]
                        if len(new_rp) != len(rp[i]):
                            rp[i] = new_rp
                            changed = True
                            if not rp[i]:
                                return None, None
        return rp, cp

    # Initial propagation
    row_possible, col_possible = propagate([m[:] for m in row_possible], [m[:] for m in col_possible])
    if row_possible is None:
        return "No Solution"

    # Backtracking search with most constrained first heuristic
    def backtrack(rp, cp):
        # Propagate constraints first
        curr_rp, curr_cp = propagate([m[:] for m in rp], [m[:] for m in cp])
        if curr_rp is None:
            return None

        # Check if we have a complete solution
        if all(len(m) == 1 for m in curr_rp):
            grid = [[None for _ in range(M)] for _ in range(N)]
            for i in range(N):
                mask = curr_rp[i][0]
                for j in range(M):
                    if mask & (1 << j):
                        grid[i][j] = 'B'
            # Verify column sums (safety check)
            for j in range(M):
                total = 0
                for i in range(N):
                    if grid[i][j] == 'B':
                        total += row_weights[i]
                if total != col_sum[j]:
                    return None
            return grid

        # Select row with fewest possible options (min branching factor)
        min_len = float('inf')
        selected_row = -1
        for i in range(N):
            l = len(curr_rp[i])
            if l > 1 and l < min_len:
                min_len = l
                selected_row = i

        # Try each valid mask for selected row
        for mask in curr_rp[selected_row]:
            new_rp = [m[:] for m in curr_rp]
            new_rp[selected_row] = [mask]
            res = backtrack(new_rp, curr_cp)
            if res is not None:
                return res

        return None

    solution = backtrack(row_possible, col_possible)
    return solution if solution is not None else "No Solution"

