def generate_patterns(length, clues):
    patterns = []
    if not clues:
        return [['W'] * length]
    total_black = sum(clues)
    required_whites = len(clues) - 1
    total_required = total_black + required_whites
    if total_required > length:
        return []
    extra_whites = length - total_required

    def backtrack(extra_left, clue_idx, current):
        if clue_idx == len(clues):
            current += ['W'] * extra_left
            patterns.append(current.copy())
            return
        if clue_idx > 0:
            current.append('W')
        for x in range(extra_left + 1):
            current += ['W'] * x
            current += ['B'] * clues[clue_idx]
            backtrack(extra_left - x, clue_idx + 1, current)
            del current[-(x + clues[clue_idx]):]
        if clue_idx > 0:
            current.pop()

    backtrack(extra_whites, 0, [])
    return patterns

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    n_rows = len(row_clues)
    n_cols = len(col_clues)

    row_patterns = [generate_patterns(n_cols, clues) for clues in row_clues]
    col_patterns = [generate_patterns(n_rows, clues) for clues in col_clues]
    grid = [[None for _ in range(n_cols)] for _ in range(n_rows)]

    def propagate():
        changed = True
        while changed:
            changed = False
            # Fix cells from row patterns
            for r in range(n_rows):
                patterns = row_patterns[r]
                if not patterns:
                    return False
                for c in range(n_cols):
                    if grid[r][c] is not None:
                        continue
                    vals = {p[c] for p in patterns}
                    if len(vals) == 1:
                        grid[r][c] = vals.pop()
                        changed = True
            # Fix cells from column patterns
            for c in range(n_cols):
                patterns = col_patterns[c]
                if not patterns:
                    return False
                for r in range(n_rows):
                    if grid[r][c] is not None:
                        continue
                    vals = {p[r] for p in patterns}
                    if len(vals) == 1:
                        grid[r][c] = vals.pop()
                        changed = True
            # Prune invalid row patterns
            for r in range(n_rows):
                original_len = len(row_patterns[r])
                row_patterns[r] = [
                    p for p in row_patterns[r]
                    if all(grid[r][c] is None or p[c] == grid[r][c] for c in range(n_cols))
                ]
                if len(row_patterns[r]) != original_len:
                    changed = True
                if not row_patterns[r]:
                    return False
            # Prune invalid column patterns
            for c in range(n_cols):
                original_len = len(col_patterns[c])
                col_patterns[c] = [
                    p for p in col_patterns[c]
                    if all(grid[r][c] is None or p[r] == grid[r][c] for r in range(n_rows))
                ]
                if len(col_patterns[c]) != original_len:
                    changed = True
                if not col_patterns[c]:
                    return False
        return True

    if not propagate():
        return "No Solution"

    def is_complete():
        return all(len(p) == 1 for p in row_patterns)

    if is_complete():
        return [['B' if cell == 'B' else None for cell in row] for row in grid]

    def backtrack():
        # Select most constrained row (minimum remaining patterns)
        min_cnt = float('inf')
        target_row = -1
        for r in range(n_rows):
            cnt = len(row_patterns[r])
            if cnt > 1 and cnt < min_cnt:
                min_cnt = cnt
                target_row = r
        if target_row == -1:
            return [['B' if cell == 'B' else None for cell in row] for row in grid]

        # Save state for backtracking
        orig_row_pats = row_patterns[target_row].copy()
        orig_col_pats = [p.copy() for p in col_patterns]
        orig_grid = [row.copy() for row in grid]

        for pat in orig_row_pats:
            # Apply pattern to target row
            for c in range(n_cols):
                grid[target_row][c] = pat[c]
            row_patterns[target_row] = [pat]
            if propagate():
                res = backtrack()
                if res != "No Solution":
                    return res
            # Restore state
            row_patterns[target_row] = orig_row_pats
            col_patterns[:] = orig_col_pats
            grid[:] = orig_grid
        return "No Solution"

    return backtrack()

if __name__ == "__main__":
    print(solve(OBSERVATION))
