from itertools import combinations

def normalize_shape(points):
    min_r = min(p[0] for p in points)
    min_c = min(p[1] for p in points)
    translated = [(p[0] - min_r, p[1] - min_c) for p in points]

    def rotate90(p): return (-p[1], p[0])
    def flip_h(p): return (p[0], -p[1])

    transforms = []
    current = translated
    for _ in range(4):
        transforms.append(tuple(sorted(current)))
        transforms.append(tuple(sorted([flip_h(p) for p in current])))
        current = [rotate90(p) for p in current]

    canonical = min(transforms)
    shape_map = {
        ((0, 0), (1, 0), (2, 0), (2, 1)): 'L',
        ((0, 0), (1, 0), (2, 0), (3, 0)): 'I',
        ((0, 1), (1, 0), (1, 1), (1, 2)): 'T',
        ((0, 0), (0, 1), (1, 1), (1, 2)): 'S'
    }
    return shape_map.get(canonical, None)

def preprocess_regions(grid):
    regions = {}
    n = len(grid)
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_options = {}
    for rid, cells in regions.items():
        options = []
        for combo in combinations(cells, 4):
            rs = set(p[0] for p in combo)
            cs = set(p[1] for p in combo)
            if len(rs) == 2 and len(cs) == 2:
                continue
            t = normalize_shape(combo)
            if t is not None:
                options.append((set(combo), t))
        region_options[rid] = options

    adj = {rid: set() for rid in regions}
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    nrid = grid[nr][nc]
                    if nrid != rid:
                        adj[rid].add(nrid)
    return regions, region_options, adj

def ac3(region_options, adj):
    queue = []
    for rid in adj:
        for nrid in adj[rid]:
            queue.append((rid, nrid))
    while queue:
        rid, nrid = queue.pop(0)
        removed = False
        to_remove = []
        for i, (points, t) in enumerate(region_options[rid]):
            has_compatible = any(opt_t != t for (_, opt_t) in region_options[nrid])
            if not has_compatible:
                to_remove.append(i)
                removed = True
        for i in reversed(to_remove):
            del region_options[rid][i]
        if removed:
            if len(region_options[rid]) == 0:
                return False
            for neighbor in adj[rid]:
                if neighbor != nrid:
                    queue.append((neighbor, rid))
    return True

def has_2x2(shaded, n):
    for r in range(n-1):
        for c in range(n-1):
            if (r,c) in shaded and (r,c+1) in shaded and (r+1,c) in shaded and (r+1,c+1) in shaded:
                return True
    return False

def is_connected(shaded):
    if not shaded:
        return True
    start = next(iter(shaded))
    visited = set([start])
    stack = [start]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while stack:
        r, c = stack.pop()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in shaded and (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))
    return len(visited) == len(shaded)

def backtrack(assigned, shaded, region_options, regions, adj, n):
    if len(assigned) == len(regions):
        if not has_2x2(shaded, n) and is_connected(shaded):
            return assigned
        return None
    unassigned = [rid for rid in regions if rid not in assigned]
    unassigned.sort(key=lambda x: len(region_options[x]))
    rid = unassigned[0]
    for (points, t) in region_options[rid]:
        conflict = False
        for nrid in adj[rid]:
            if nrid in assigned and assigned[nrid][1] == t:
                conflict = True
                break
        if conflict:
            continue
        new_shaded = shaded.union(points)
        if has_2x2(new_shaded, n):
            continue
        new_opts = {k: v.copy() for k, v in region_options.items()}
        valid = True
        for nrid in adj[rid]:
            if nrid not in assigned:
                new_opts[nrid] = [opt for opt in new_opts[nrid] if opt[1] != t]
                if len(new_opts[nrid]) == 0:
                    valid = False
                    break
        if not valid:
            continue
        if not ac3(new_opts, adj):
            continue
        assigned[rid] = (points, t)
        res = backtrack(assigned, new_shaded, new_opts, regions, adj, n)
        if res is not None:
            return res
        del assigned[rid]
    return None

def solve(observation):
    grid = observation['data']
    n = len(grid)
    regions, region_options, adj = preprocess_regions(grid)
    if not ac3(region_options, adj):
        return "No Solution"
    assigned = backtrack({}, set(), region_options, regions, adj, n)
    if assigned is None:
        return "No Solution"
    output = [[None]*n for _ in range(n)]
    for rid in assigned:
        points, t = assigned[rid]
        for (r,c) in points:
            output[r][c] = t
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
