FORBIDDEN_O = {(0,0), (0,1), (1,0), (1,1)}

def get_tetromino_type(cells):
    cells = list(cells)
    min_r = min(r for r,c in cells)
    min_c = min(c for r,c in cells)
    norm = {(r - min_r, c - min_c) for r,c in cells}
    if norm == FORBIDDEN_O:
        return None
    for t, shapes in TETROMINOES.items():
        if norm in shapes:
            return t
    return None

def is_connected(cells):
    cells_set = set(cells)
    start = next(iter(cells_set))
    visited = set([start])
    q = deque([start])
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        r,c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in cells_set and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(cells_set)

def generate_region_placements(region_cells):
    placements = []
