    # Generate all 4-cell subsets
    from itertools import combinations
    for subset in combinations(region_cells, 4):
        subset_set = set(subset)
        if not is_connected(subset_set):
            continue
        t = get_tetromino_type(subset_set)
        if t is None:
            continue
        placements.append((t, subset_set))
