def is_globally_connected(shaded_set):
    if not shaded_set:
        return True
    start = next(iter(shaded_set))
    visited = set([start])
    q = deque([start])
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        r,c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in shaded_set and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(shaded_set)

def solve(observation):
    region_grid = observation['data']
    rows = len(region_grid)
    cols = len(region_grid[0])

    # Step 1: Map regions to their cells
    regions = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            rid = region_grid[r][c]
            regions[rid].append((r,c))
    region_ids = list(regions.keys())

    # Step 2: Get adjacent regions
    adj_regions = get_adjacent_regions(region_grid, regions)

