    region_placements = {}
    for rid in region_ids:
        placements = generate_region_placements(regions[rid])
        if not placements:
            return "No Solution"
        region_placements[rid] = placements

    # Backtracking state: assignments = {rid: (type, cells)}, shaded_set = set of all shaded cells, used_types = {rid: type}
    def backtrack(assignments, shaded_set, used_types):
        if len(assignments) == len(region_ids):
            # Check final constraints
            if not check_2x2(shaded_set, rows, cols):
                return None
            if not is_globally_connected(shaded_set):
                return None
            # Build result grid
            res = [[None for _ in range(cols)] for _ in range(rows)]
            for rid in assignments:
                t, cells = assignments[rid]
                for r,c in cells:
