            return res

        # MRV heuristic: pick region with least possible placements
        unassigned = [rid for rid in region_ids if rid not in assignments]
        rid = min(unassigned, key=lambda x: len([p for p in region_placements[x] if p[0] not in {used_types.get(neigh, None) for neigh in adj_regions[x]}]))

        # Get valid placements for this region
        forbidden_types = {used_types.get(neigh, None) for neigh in adj_regions[rid]}
        valid_placements = [p for p in region_placements[rid] if p[0] not in forbidden_types]

        for t, cells in valid_placements:
            # Check no 2x2 block created
            new_shaded = shaded_set.union(cells)
            if not check_2x2(new_shaded, rows, cols):
                continue
            # Check connectivity possible (at least one cell adjacent to existing shaded if not first)
            if shaded_set:
                adjacent = False
                dirs = [(-1,0),(1,0),(0,-1),(0,1)]
                for r,c in cells:
                    for dr, dc in dirs:
                        if (r+dr, c+dc) in shaded_set:
                            adjacent = True
                            break
                    if adjacent:
                        break
                if not adjacent:
                    # Check if any unassigned region is adjacent to both current shaded and this region's cells
                    bridge = False
                    for urid in unassigned:
                        if urid == rid:
                            continue
                        ucells = set(regions[urid])
                        adj_shaded = False
                        for r,c in ucells:
                            for dr, dc in dirs:
                                if (r+dr, c+dc) in shaded_set:
                                    adj_shaded = True
                                    break
                            if adj_shaded:
                                break
                        if not adj_shaded:
                            continue
                        adj_new = False
                        for r,c in ucells:
                            for dr, dc in dirs:
                                if (r+dr, c+dc) in cells:
                                    adj_new = True
                                    break
                            if adj_new:
                                break
                        if adj_new:
                            bridge = True
                            break
                    if not bridge:
                        continue
            # Proceed with assignment
            assignments[rid] = (t, cells)
            used_types[rid] = t
            res = backtrack(assignments, new_shaded, used_types)
            if res is not None:
                return res
            # Backtrack
            del assignments[rid]
            del used_types[rid]
        return None

    result = backtrack({}, set(), {})
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
