from collections import defaultdict

def solve(observation):
    region = observation['region']
    row_counts = observation['row_stitch_counts'].copy()
    col_counts = observation['col_stitch_counts'].copy()
    N = len(region)

    # Step 1: Find all adjacent region pairs
    adjacent_pairs = set()
    for r in range(N):
        for c in range(N):
            curr = region[r][c]
            if c + 1 < N and region[r][c+1] != curr:
                adjacent_pairs.add(tuple(sorted((curr, region[r][c+1]))))
            if r + 1 < N and region[r+1][c] != curr:
                adjacent_pairs.add(tuple(sorted((curr, region[r+1][c]))))
    adjacent_pairs = list(adjacent_pairs)

    # Step 2: Map each region pair to all possible stitches
    pair_to_stitches = defaultdict(list)
    # Horizontal stitches
    for r in range(N):
        for c in range(N-1):
            a, b = region[r][c], region[r][c+1]
            if a != b:
                pair = tuple(sorted((a, b)))
                stitch = ((r, c), (r, c+1))
                pair_to_stitches[pair].append(stitch)
    # Vertical stitches
    for r in range(N-1):
        for c in range(N):
            a, b = region[r][c], region[r+1][c]
            if a != b:
                pair = tuple(sorted((a, b)))
                stitch = ((r, c), (r+1, c))
                pair_to_stitches[pair].append(stitch)

    # Helper function to propagate constraints
    def propagate(used_holes, rem_row, rem_col, rem_pairs, pair_stitch_map):
        changed = True
        while changed:
            changed = False
            # Eliminate invalid stitches from all pairs
            for pair in list(pair_stitch_map.keys()):
                valid_stitches = []
                for st in pair_stitch_map[pair]:
                    (r1, c1), (r2, c2) = st
                    if (r1, c1) in used_holes or (r2, c2) in used_holes:
                        continue
                    if rem_row[r1] < 1 or rem_row[r2] < 1:
                        continue
                    if rem_col[c1] < 1 or rem_col[c2] < 1:
                        continue
                    valid_stitches.append(st)
                if not valid_stitches:
                    return (False, None, None, None, None)
                if len(valid_stitches) != len(pair_stitch_map[pair]):
                    pair_stitch_map[pair] = valid_stitches
                    changed = True
                # If only one stitch left, we have to take it
                if len(valid_stitches) == 1 and pair in rem_pairs:
                    st = valid_stitches[0]
                    (r1, c1), (r2, c2) = st
                    used_holes.add((r1, c1))
                    used_holes.add((r2, c2))
                    rem_row[r1] -= 1
                    rem_row[r2] -= 1
                    rem_col[c1] -= 1
                    rem_col[c2] -= 1
                    if rem_row[r1] < 0 or rem_row[r2] < 0 or rem_col[c1] < 0 or rem_col[c2] < 0:
                        return (False, None, None, None, None)
                    rem_pairs.remove(pair)
                    changed = True
            # Remove stitches in rows/cols with 0 remaining count
            for r in range(N):
                if rem_row[r] == 0:
                    for pair in pair_stitch_map:
                        new_stitches = [st for st in pair_stitch_map[pair] if st[0][0] != r and st[1][0] != r]
                        if len(new_stitches) != len(pair_stitch_map[pair]):
                            pair_stitch_map[pair] = new_stitches
                            changed = True
            for c in range(N):
                if rem_col[c] == 0:
                    for pair in pair_stitch_map:
                        new_stitches = [st for st in pair_stitch_map[pair] if st[0][1] != c and st[1][1] != c]
                        if len(new_stitches) != len(pair_stitch_map[pair]):
                            pair_stitch_map[pair] = new_stitches
                            changed = True
            # Check if any pair has no valid stitches left
            for pair in pair_stitch_map:
                if not pair_stitch_map[pair]:
                    return (False, None, None, None, None)
        return (True, used_holes, rem_row, rem_col, rem_pairs, pair_stitch_map)

    # Backtracking function
    def backtrack(used_holes, rem_row, rem_col, rem_pairs, pair_stitch_map, selected):
        # Propagate constraints first
        res = propagate(used_holes.copy(), rem_row.copy(), rem_col.copy(), rem_pairs.copy(), {k:v.copy() for k,v in pair_stitch_map.items()})
        if not res[0]:
            return None
        _, used_holes, rem_row, rem_col, rem_pairs, pair_stitch_map = res
        # If all pairs are processed, check if counts are exactly 0
        if not rem_pairs:
            if all(x == 0 for x in rem_row) and all(x == 0 for x in rem_col):
                return selected
            return None
        # Select pair with fewest options (MRV heuristic)
        rem_pairs.sort(key=lambda p: len(pair_stitch_map[p]))
        curr_pair = rem_pairs[0]
        # Try each possible stitch for this pair
        for stitch in pair_stitch_map[curr_pair]:
            (r1, c1), (r2, c2) = stitch
            if (r1, c1) in used_holes or (r2, c2) in used_holes:
                continue
            if rem_row[r1] < 1 or rem_row[r2] < 1 or rem_col[c1] < 1 or rem_col[c2] < 1:
                continue
            # Create new state
            new_used = used_holes.copy()
            new_used.add((r1, c1))
            new_used.add((r2, c2))
            new_rem_row = rem_row.copy()
            new_rem_row[r1] -= 1
            new_rem_row[r2] -= 1
            new_rem_col = rem_col.copy()
            new_rem_col[c1] -= 1
            new_rem_col[c2] -= 1
            new_rem_pairs = [p for p in rem_pairs if p != curr_pair]
            new_selected = selected + [stitch]
            # Recurse
            solution = backtrack(new_used, new_rem_row, new_rem_col, new_rem_pairs, pair_stitch_map, new_selected)
            if solution is not None:
                return solution
        return None

    # Initial state
    initial_used = set()
    initial_rem_row = row_counts.copy()
    initial_rem_col = col_counts.copy()
    initial_rem_pairs = adjacent_pairs.copy()
    initial_pair_map = {k:v.copy() for k,v in pair_to_stitches.items()}

    solution = backtrack(initial_used, initial_rem_row, initial_rem_col, initial_rem_pairs, initial_pair_map, [])
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
