OBSERVATION = {'row_sum': [6, 4, 9, 7, 11], 'col_sum': [4, 9, 3, 7, 13]}

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)
    row_weights = [i + 1 for i in range(R)]
    col_weights = [j + 1 for j in range(C)]

    # Generate all valid bitmasks for given weights and target sum
    def generate_masks(weights, target):
        masks = []
        n = len(weights)
        def backtrack(pos, current_sum, mask):
            if current_sum == target:
                masks.append(mask)
                return
            if pos >= n or current_sum > target:
                return
            # Include current weight
            backtrack(pos + 1, current_sum + weights[pos], mask | (1 << pos))
            # Exclude current weight
            backtrack(pos + 1, current_sum, mask)
        backtrack(0, 0, 0)
        return masks

    # Precompute initial possible masks for each row and column
    possible_rows = [generate_masks(col_weights, rs) for rs in row_sum]
    possible_cols = [generate_masks(row_weights, cs) for cs in col_sum]

    # Early exit if any row/column has no valid options initially
    for pr in possible_rows:
        if not pr:
            return "No Solution"
    for pc in possible_cols:
        if not pc:
            return "No Solution"

    # Grid initialization: None = unknown, 'B' = black, None = confirmed non-black once set
    grid = [[None for _ in range(C)] for _ in range(R)]

    # Constraint propagation function: returns (changed_flag, is_valid_flag)
    def propagate():
        changed = False
        # Process all rows
        for i in range(R):
            # Filter masks that conflict with known cells
            new_pr = []
            for mask in possible_rows[i]:
                valid = True
                for j in range(C):
                    if grid[i][j] is None:
                        continue
                    expected = 1 if grid[i][j] == 'B' else 0
                    actual = (mask >> j) & 1
                    if expected != actual:
                        valid = False
                        break
                if valid:
                    new_pr.append(mask)
            if not new_pr:
                return (False, False)
            if new_pr != possible_rows[i]:
                changed = True
                possible_rows[i] = new_pr
            # Detect forced cells in current row
            for j in range(C):
                if grid[i][j] is not None:
                    continue
                all_set = all((m >> j) & 1 for m in possible_rows[i])
                all_unset = all(not (m >> j) & 1 for m in possible_rows[i])
                if all_set:
                    grid[i][j] = 'B'
                    changed = True
                elif all_unset:
                    grid[i][j] = None
                    changed = True
        # Process all columns
        for j in range(C):
            # Filter masks that conflict with known cells
            new_pc = []
            for mask in possible_cols[j]:
                valid = True
                for i in range(R):
                    if grid[i][j] is None:
                        continue
                    expected = 1 if grid[i][j] == 'B' else 0
                    actual = (mask >> i) & 1
                    if expected != actual:
                        valid = False
                        break
                if valid:
                    new_pc.append(mask)
            if not new_pc:
                return (False, False)
            if new_pc != possible_cols[j]:
                changed = True
                possible_cols[j] = new_pc
            # Detect forced cells in current column
            for i in range(R):
                if grid[i][j] is not None:
                    continue
                all_set = all((m >> i) & 1 for m in possible_cols[j])
                all_unset = all(not (m >> i) & 1 for m in possible_cols[j])
                if all_set:
                    grid[i][j] = 'B'
                    changed = True
                elif all_unset:
                    grid[i][j] = None
                    changed = True
        return (changed, True)

    # Initial propagation loop to resolve all forced cells
    while True:
        changed, valid = propagate()
        if not valid:
            return "No Solution"
        if not changed:
            break

    # Check if grid is completely filled
    def is_complete():
        for row in grid:
            if any(c is None for c in row):
                return False
        return True

    # Validate complete solution
    def validate_solution(sol):
        # Check row sums
        for i in range(R):
            s = 0
            for j in range(C):
                if sol[i][j] == 'B':
                    s += col_weights[j]
            if s != row_sum[i]:
                return False
        # Check column sums
        for j in range(C):
            s = 0
            for i in range(R):
                if sol[i][j] == 'B':
                    s += row_weights[i]
            if s != col_sum[j]:
                return False
        return True

    if is_complete():
        return grid if validate_solution(grid) else "No Solution"

    # Select Minimum Remaining Value (MRV) cell for branching (human-like heuristic)
    def select_mrv_cell():
        min_score = float('inf')
        best_cell = None
        for i in range(R):
            for j in range(C):
                if grid[i][j] is not None:
                    continue
                # Calculate branching options score
                row_set = sum(1 for m in possible_rows[i] if (m >> j) & 1)
                row_unset = len(possible_rows[i]) - row_set
                col_set = sum(1 for m in possible_cols[j] if (m >> i) & 1)
                col_unset = len(possible_cols[j]) - col_set
                score = min(row_set, row_unset) + min(col_set, col_unset)
                if score < min_score:
                    min_score = score
                    best_cell = (i, j)
        return best_cell

    # Backtracking search
    def backtrack():
        # Propagate constraints first
        while True:
            changed, valid = propagate()
            if not valid:
                return None
            if not changed:
                break
        if is_complete():
            return [r.copy() for r in grid] if validate_solution(grid) else None
        i, j = select_mrv_cell()
        if i is None:
            return None
        # Save current state
        saved_grid = [r.copy() for r in grid]
        saved_pr = [pr.copy() for pr in possible_rows]
        saved_pc = [pc.copy() for pc in possible_cols]
        # Try setting cell to black
        grid[i][j] = 'B'
        res = backtrack()
        if res is not None:
            return res
        # Undo and try setting cell to non-black
        for r in range(R):
            grid[r] = saved_grid[r].copy()
        possible_rows[:] = [pr.copy() for pr in saved_pr]
        possible_cols[:] = [pc.copy() for pc in saved_pc]
        grid[i][j] = None
        res = backtrack()
        if res is not None:
            return res
        # Undo all changes
        for r in range(R):
            grid[r] = saved_grid[r].copy()
        possible_rows[:] = [pr.copy() for pr in saved_pr]
        possible_cols[:] = [pc.copy() for pc in saved_pc]
        return None

    solution = backtrack()
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
