import copy

def solve(observation, possible=None):
    data = observation['data']
    adj = set(tuple(pair) for pair in observation['adjacent'])
    N = len(data)
    if N == 0:
        return "No Solution"

    # Initialize possible value sets if not provided (first call)
    if possible is None:
        possible = [[set() for _ in range(N)] for __ in range(N)]
        for r in range(N):
            for c in range(N):
                if data[r][c] is not None:
                    possible[r][c].add(data[r][c])
                else:
                    possible[r][c] = set(range(1, N+1))
    else:
        # Deep copy input possible state for recursive branch
        possible = copy.deepcopy(possible)

    # Constraint propagation function: returns False if invalid state
    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: Row and column uniqueness (Sudoku rule)
            for r in range(N):
                for c in range(N):
                    if len(possible[r][c]) == 1:
                        val = next(iter(possible[r][c]))
                        # Remove value from other cells in same row
                        for cc in range(N):
                            if cc != c and val in possible[r][cc]:
                                possible[r][cc].remove(val)
                                changed = True
                                if len(possible[r][cc]) == 0:
                                    return False
                        # Remove value from other cells in same column
                        for rr in range(N):
                            if rr != r and val in possible[rr][c]:
                                possible[rr][c].remove(val)
                                changed = True
                                if len(possible[rr][c]) == 0:
                                    return False

            # Rule 2 + 3: Horizontal adjacency constraints
            for r in range(N):
                for c in range(N-1):
                    has_dot = (r, c+0.5) in adj
                    s1, s2 = possible[r][c], possible[r][c+1]
                    if has_dot:
                        # Values must be consecutive: filter possible values
                        new_s1 = {v for v in s1 if (v-1 in s2 or v+1 in s2)}
                        if new_s1 != s1:
                            possible[r][c] = new_s1
                            changed = True
                            if not new_s1:
                                return False
                        new_s2 = {v for v in s2 if (v-1 in s1 or v+1 in s1)}
                        if new_s2 != s2:
                            possible[r][c+1] = new_s2
                            changed = True
                            if not new_s2:
                                return False
                    else:
                        # Values must NOT be consecutive: filter if one is fixed
                        if len(s1) == 1:
                            v = next(iter(s1))
                            forbidden = {v-1, v+1}
                            new_s2 = s2 - forbidden
                            if new_s2 != s2:
                                possible[r][c+1] = new_s2
                                changed = True
                                if not new_s2:
                                    return False
                        if len(s2) == 1:
                            v = next(iter(s2))
                            forbidden = {v-1, v+1}
                            new_s1 = s1 - forbidden
                            if new_s1 != s1:
                                possible[r][c] = new_s1
                                changed = True
                                if not new_s1:
                                    return False

            # Rule 2 + 3: Vertical adjacency constraints
            for c in range(N):
                for r in range(N-1):
                    has_dot = (r+0.5, c) in adj
                    s1, s2 = possible[r][c], possible[r+1][c]
                    if has_dot:
                        # Values must be consecutive: filter possible values
                        new_s1 = {v for v in s1 if (v-1 in s2 or v+1 in s2)}
                        if new_s1 != s1:
                            possible[r][c] = new_s1
                            changed = True
                            if not new_s1:
                                return False
                        new_s2 = {v for v in s2 if (v-1 in s1 or v+1 in s1)}
                        if new_s2 != s2:
                            possible[r+1][c] = new_s2
                            changed = True
                            if not new_s2:
                                return False
                    else:
                        # Values must NOT be consecutive: filter if one is fixed
                        if len(s1) == 1:
                            v = next(iter(s1))
                            forbidden = {v-1, v+1}
                            new_s2 = s2 - forbidden
                            if new_s2 != s2:
                                possible[r+1][c] = new_s2
                                changed = True
                                if not new_s2:
                                    return False
                        if len(s2) == 1:
                            v = next(iter(s2))
                            forbidden = {v-1, v+1}
                            new_s1 = s1 - forbidden
                            if new_s1 != s1:
                                possible[r][c] = new_s1
                                changed = True
                                if not new_s1:
                                    return False
        return True

    # Run initial propagation
    if not propagate():
        return "No Solution"

    # Check if puzzle is fully solved
    solved = True
    solution = []
    for r in range(N):
        row = []
        for c in range(N):
            if len(possible[r][c]) != 1:
                solved = False
            row.append(next(iter(possible[r][c])) if len(possible[r][c]) == 1 else None)
        solution.append(row)
    if solved:
        return solution

    # Pick cell with minimum remaining values (MRV heuristic) to minimize branching
    min_options = float('inf')
    best_r, best_c = -1, -1
    for r in range(N):
        for c in range(N):
            opt_count = len(possible[r][c])
            if 1 < opt_count < min_options:
                min_options = opt_count
                best_r, best_c = r, c
                if min_options == 2: # Can't get better than 2 options, early exit
                    break
        if min_options == 2:
            break

    # Try each possible value for the selected cell
    for candidate_val in sorted(possible[best_r][best_c]):
        new_possible = copy.deepcopy(possible)
        new_possible[best_r][best_c] = {candidate_val}
        sub_result = solve(observation, new_possible)
        if sub_result != "No Solution":
            return sub_result

    # No valid solution found in any branch
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
