        valid = True
        for i in range(n):
            if mask & (1 << i):
                current_sum += weights[i]
                if current_sum > target:
                    valid = False
                    break
        if valid and current_sum == target:
            masks.append(mask)
    return masks

def propagate(row_possible, col_possible, grid, n_rows, n_cols):
