        # Deduce cells from row possibilities
        for r in range(n_rows):
            masks = row_possible[r]
            if not masks:
                return False
            for c in range(n_cols):
                all_set = all((m & (1 << c)) != 0 for m in masks)
                none_set = all((m & (1 << c)) == 0 for m in masks)
                if all_set:
                    if grid[r][c] is False:
                        return False
                    if grid[r][c] is None:
                        grid[r][c] = True
                        changed = True
                elif none_set:
                    if grid[r][c] is True:
                        return False
                    if grid[r][c] is None:
                        grid[r][c] = False
                        changed = True
        # Deduce cells from column possibilities
        for c in range(n_cols):
            masks = col_possible[c]
            if not masks:
                return False
            for r in range(n_rows):
                all_set = all((m & (1 << r)) != 0 for m in masks)
                none_set = all((m & (1 << r)) == 0 for m in masks)
                if all_set:
                    if grid[r][c] is False:
                        return False
                    if grid[r][c] is None:
                        grid[r][c] = True
                        changed = True
                elif none_set:
                    if grid[r][c] is True:
                        return False
                    if grid[r][c] is None:
                        grid[r][c] = False
                        changed = True
        # Filter row possibilities
        for r in range(n_rows):
            original = row_possible[r]
            filtered = []
            for m in original:
                valid = True
                for c in range(n_cols):
                    val = grid[r][c]
                    if val is None:
                        continue
                    bit_set = (m & (1 << c)) != 0
                    if val != bit_set:
                        valid = False
                        break
                if valid:
                    filtered.append(m)
            if len(filtered) != len(original):
                changed = True
                row_possible[r] = filtered
                if not filtered:
                    return False
        # Filter column possibilities
        for c in range(n_cols):
            original = col_possible[c]
            filtered = []
            for m in original:
                valid = True
                for r in range(n_rows):
                    val = grid[r][c]
                    if val is None:
                        continue
                    bit_set = (m & (1 << r)) != 0
                    if val != bit_set:
                        valid = False
                        break
                if valid:
                    filtered.append(m)
            if len(filtered) != len(original):
                changed = True
                col_possible[c] = filtered
                if not filtered:
                    return False
    return True

def backtrack(row_possible, col_possible, grid, n_rows, n_cols):
    valid = propagate(row_possible, col_possible, grid, n_rows, n_cols)
    if not valid:
        return None
    # Check if all cells are known
    all_known = True
    candidate = None
    min_branch = float('inf')
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] is None:
                all_known = False
                # Calculate branching factor for this cell
                row_true = sum(1 for m in row_possible[r] if m & (1 << c))
                row_false = len(row_possible[r]) - row_true
                col_true = sum(1 for m in col_possible[c] if m & (1 << r))
                col_false = len(col_possible[c]) - col_true
                branch = min(row_true + col_true, row_false + col_false)
                if branch < min_branch:
                    min_branch = branch
                    candidate = (r, c)
    if all_known:
        return [['B' if cell else None for cell in row] for row in grid]
    if not candidate:
        return None
    r, c = candidate
    # Try True first
    new_row = [m.copy() for m in row_possible]
    new_col = [m.copy() for m in col_possible]
    new_grid = [row.copy() for row in grid]
    new_grid[r][c] = True
    res = backtrack(new_row, new_col, new_grid, n_rows, n_cols)
    if res:
        return res
    # Try False
    new_row = [m.copy() for m in row_possible]
    new_col = [m.copy() for m in col_possible]
    new_grid = [row.copy() for row in grid]
    new_grid[r][c] = False
    return backtrack(new_row, new_col, new_grid, n_rows, n_cols)

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n_rows = len(row_sum)
    n_cols = len(col_sum)
    row_weights = [i+1 for i in range(n_rows)]
    col_weights = [i+1 for i in range(n_cols)]
    # Generate initial possible masks
    row_possible = []
    for rs in row_sum:
        masks = generate_possible_masks(col_weights, rs)
        if not masks:
            return "No Solution"
        row_possible.append(masks)
    col_possible = []
    for cs in col_sum:
        masks = generate_possible_masks(row_weights, cs)
        if not masks:
            return "No Solution"
        col_possible.append(masks)
    # Initialize empty grid
    grid = [[None for _ in range(n_cols)] for _ in range(n_rows)]
    solution = backtrack(row_possible, col_possible, grid, n_rows, n_cols)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
