        if cc != c:
            peers.add((r, cc))
    # Same column peers
    for rr in range(N):
        if rr != r:
            peers.add((rr, c))
    # Same subgrid peers
    sub_r_start = (r // unit_r) * unit_r
    sub_c_start = (c // unit_c) * unit_c
    for rr in range(sub_r_start, sub_r_start + unit_r):
        for cc in range(sub_c_start, sub_c_start + unit_c):
            if (rr, cc) != (r, c):
                peers.add((rr, cc))
    return peers

def propagate(grid, candidates, unit_r, unit_c, N):
    while True:
        changed = False
        # Process Naked Singles
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and len(candidates[r][c]) == 1:
                    val = next(iter(candidates[r][c]))
                    grid[r][c] = val
                    changed = True
