                            candidates[pr][pc].remove(val)
                            if len(candidates[pr][pc]) == 0:
                                return (False, None, None)
        if changed:
            continue

        # Process Hidden Singles in Subgrids
        for sub_r_start in range(0, N, unit_r):
            for sub_c_start in range(0, N, unit_c):
                for val in range(1, N+1):
                    possible = []
                    for r in range(sub_r_start, sub_r_start + unit_r):
