                            if val in candidates[pr][pc]:
                                candidates[pr][pc].remove(val)
                                if len(candidates[pr][pc]) == 0:
                                    return (False, None, None)
        if not changed:
            break
    return (True, grid, candidates)

def backtrack(grid, candidates, unit_r, unit_c, N):
    # Select cell with Minimum Remaining Values (MRV heuristic)
    min_candidate_count = float('inf')
    target_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None and len(candidates[r][c]) < min_candidate_count:
                min_candidate_count = len(candidates[r][c])
                target_cell = (r, c)
                if min_candidate_count == 2:
                    break
        if min_candidate_count == 2:
            break

    if target_cell is None:
        return grid  # All cells filled, solution found

    r, c = target_cell
    for val in sorted(candidates[r][c]):
        # Create copies of state for this candidate
        new_grid = [row.copy() for row in grid]
        new_candidates = [[cell.copy() for cell in row] for row in candidates]
        new_grid[r][c] = val
        new_candidates[r][c] = {val}

        # Run constraint propagation
        valid, prop_grid, prop_candidates = propagate(new_grid, new_candidates, unit_r, unit_c, N)
        if not valid:
            continue

        # Check if solved after propagation
        if all(all(cell is not None for cell in row) for row in prop_grid):
            return prop_grid

        # Recursive backtrack
        result = backtrack(prop_grid, prop_candidates, unit_r, unit_c, N)
        if result != "No Solution":
            return result

    return "No Solution"

def solve(observation):
    data = observation['data']
    unit_r, unit_c = map(int, observation['unit'].split('x'))
    N = unit_r * unit_c

    # Initialize grid and candidate sets
    grid = [row.copy() for row in data]
    candidates = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                candidates[r][c].add(grid[r][c])
            else:
                candidates[r][c] = set(range(1, N+1))

    # Initial propagation
    valid, grid, candidates = propagate(grid, candidates, unit_r, unit_c, N)
    if not valid:
        return "No Solution"

    # Check if already solved after propagation
    if all(all(cell is not None for cell in row) for row in grid):
        return grid

    # Run backtracking search
    return backtrack(grid, candidates, unit_r, unit_c, N)

