from copy import deepcopy

def propagate(h_edges, v_edges, N, clues):
    changed = True
    while changed:
        changed = False
        # Process cell rules
        for i in range(N):
            for j in range(N):
                clue = clues[i][j]
                if clue is None:
                    continue
                edges = [
                    h_edges[i][j], h_edges[i+1][j],
                    v_edges[i][j], v_edges[i][j+1]
                ]
                cnt1 = sum(1 for e in edges if e == 1)
                cnt0 = sum(1 for e in edges if e == 0)
                cnt_unknown = 4 - cnt1 - cnt0
                if cnt1 > clue:
                    return (False, h_edges, v_edges)
                if cnt_unknown == 0:
                    if cnt1 != clue:
                        return (False, h_edges, v_edges)
                    continue
                # Rule C: remaining edges are 0
                if cnt1 == clue:
                    idx = 0
                    if h_edges[i][j] == 2:
                        h_edges[i][j] = 0
                        changed = True
                    if h_edges[i+1][j] == 2:
                        h_edges[i+1][j] = 0
                        changed = True
                    if v_edges[i][j] == 2:
                        v_edges[i][j] = 0
                        changed = True
                    if v_edges[i][j+1] == 2:
                        v_edges[i][j+1] = 0
                        changed = True
                # Rule B: remaining edges are 1
                elif (clue - cnt1) == cnt_unknown:
                    if h_edges[i][j] == 2:
                        h_edges[i][j] = 1
                        changed = True
                    if h_edges[i+1][j] == 2:
                        h_edges[i+1][j] = 1
                        changed = True
                    if v_edges[i][j] == 2:
                        v_edges[i][j] = 1
                        changed = True
                    if v_edges[i][j+1] == 2:
                        v_edges[i][j+1] = 1
                        changed = True
        # Process dot rules
        for i in range(N+1):
            for j in range(N+1):
                edges = []
                # up: v_edges[i-1][j] if i>0
                if i > 0: edges.append(v_edges[i-1][j])
                # down: v_edges[i][j] if i < N
                if i < N: edges.append(v_edges[i][j])
                # left: h_edges[i][j-1] if j>0
                if j > 0: edges.append(h_edges[i][j-1])
                # right: h_edges[i][j] if j < N
                if j < N: edges.append(h_edges[i][j])
                cnt1 = sum(1 for e in edges if e == 1)
                cnt0 = sum(1 for e in edges if e == 0)
                cnt_unknown = len(edges) - cnt1 - cnt0
                if cnt1 > 2:
                    return (False, h_edges, v_edges)
                if cnt_unknown == 0:
                    if cnt1 not in (0,2):
                        return (False, h_edges, v_edges)
                    continue
                # Rule D: already 2 edges, rest 0
                if cnt1 == 2:
                    if i > 0 and v_edges[i-1][j] == 2:
                        v_edges[i-1][j] = 0
                        changed = True
                    if i < N and v_edges[i][j] == 2:
                        v_edges[i][j] = 0
                        changed = True
                    if j > 0 and h_edges[i][j-1] == 2:
                        h_edges[i][j-1] = 0
                        changed = True
                    if j < N and h_edges[i][j] == 2:
                        h_edges[i][j] = 0
                        changed = True
                # Rule E: need more edges, fill unknown with 1
                elif (2 - cnt1) == cnt_unknown:
                    if i > 0 and v_edges[i-1][j] == 2:
                        v_edges[i-1][j] = 1
                        changed = True
                    if i < N and v_edges[i][j] == 2:
                        v_edges[i][j] = 1
                        changed = True
                    if j > 0 and h_edges[i][j-1] == 2:
                        h_edges[i][j-1] = 1
                        changed = True
                    if j < N and h_edges[i][j] == 2:
                        h_edges[i][j] = 1
                        changed = True
    return (True, h_edges, v_edges)

def is_complete(h_edges, v_edges, N):
    for i in range(N+1):
        for j in range(N):
            if h_edges[i][j] == 2:
                return False
    for i in range(N):
        for j in range(N+1):
            if v_edges[i][j] == 2:
                return False
    return True

def check_single_loop(h_edges, v_edges, N):
    # Find start point
    start = None
    for i in range(N+1):
        for j in range(N+1):
            deg = 0
            if i>0 and v_edges[i-1][j]==1: deg +=1
            if i<N and v_edges[i][j]==1: deg +=1
            if j>0 and h_edges[i][j-1]==1: deg +=1
            if j<N and h_edges[i][j]==1: deg +=1
            if deg == 2:
                start = (i,j)
                break
        if start:
            break
    if not start:
        return False, []
    # Traverse loop
    path = [start]
    prev = None
    curr = start
    while True:
        i,j = curr
        next_nodes = []
        if i>0 and v_edges[i-1][j]==1:
            nxt = (i-1,j)
            if nxt != prev: next_nodes.append(nxt)
        if i<N and v_edges[i][j]==1:
            nxt = (i+1,j)
            if nxt != prev: next_nodes.append(nxt)
        if j>0 and h_edges[i][j-1]==1:
            nxt = (i,j-1)
            if nxt != prev: next_nodes.append(nxt)
        if j<N and h_edges[i][j]==1:
            nxt = (i,j+1)
            if nxt != prev: next_nodes.append(nxt)
        if len(next_nodes) != 1:
            return False, []
        nxt = next_nodes[0]
        if nxt == start:
            path.append(nxt)
            break
        path.append(nxt)
        prev = curr
        curr = nxt
    # Count total edges to make sure it's the only loop
    total_edges = 0
    for i in range(N+1):
        total_edges += sum(1 for e in h_edges[i] if e ==1)
    for i in range(N):
        total_edges += sum(1 for e in v_edges[i] if e ==1)
    if len(path)-1 != total_edges//1:
        return False, []
    return True, path

def backtrack(h_edges, v_edges, N, clues):
    valid, h, v = propagate(deepcopy(h_edges), deepcopy(v_edges), N, clues)
    if not valid:
        return None
    if is_complete(h, v, N):
        is_loop, path = check_single_loop(h, v, N)
        return path if is_loop else None
    # Find first unknown edge
    for i in range(N+1):
        for j in range(N):
            if h[i][j] == 2:
                # Try 1 first
                h1 = deepcopy(h)
                h1[i][j] = 1
                res = backtrack(h1, v, N, clues)
                if res:
                    return res
                # Try 0
                h0 = deepcopy(h)
                h0[i][j] = 0
                res = backtrack(h0, v, N, clues)
                return res
    for i in range(N):
        for j in range(N+1):
            if v[i][j] == 2:
                v1 = deepcopy(v)
                v1[i][j] =1
                res = backtrack(h, v1, N, clues)
                if res:
                    return res
                v0 = deepcopy(v)
                v0[i][j] = 0
                res = backtrack(h, v0, N, clues)
                return res
    return None

def solve(observation):
    clues = observation['data']
    N = len(clues)
    # Initialize edges: 2=unknown, 1=edge, 0=no edge
    h_edges = [[2 for _ in range(N)] for __ in range(N+1)]
    v_edges = [[2 for _ in range(N+1)] for __ in range(N)]
    solution = backtrack(h_edges, v_edges, N, clues)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
