from copy import deepcopy

DIRS = [(-1,0,'up'), (1,0,'down'), (0,-1,'left'), (0,1,'right')]
OPPOSITE = {'up':'down', 'down':'up', 'left':'right', 'right':'left'}
PERPENDICULAR = {
    'up': ['left', 'right'],
    'down': ['left', 'right'],
    'left': ['up', 'down'],
    'right': ['up', 'down']
}
DIR_DELTA = {'up': (-1,0), 'down':(1,0), 'left':(0,-1), 'right':(0,1)}

def parse_observation(obs):
    data = obs['data']
    N = len(data) - 1
    clues = []
    for r in range(N+1):
        for c in range(N+1):
            val = data[r][c]
            if val is not None:
                t = val[0]
                k = int(val[1:])
                clues.append((r,c,t,k))
    return N, clues

def initialize_state(N):
    h_edges = [[None for _ in range(N)] for _ in range(N+1)]
    v_edges = [[None for _ in range(N+1)] for _ in range(N)]
    dot_degree = [[0 for _ in range(N+1)] for _ in range(N+1)]
    return h_edges, v_edges, dot_degree

def get_edge_set_from_clue_config(r, c, dir1, len1, dir2, len2, N):
    edges = set()
    dr1, dc1 = DIR_DELTA[dir1]
    for i in range(1, len1+1):
        nr = r + dr1 * (i-1)
        nc = c + dc1 * (i-1)
        if dir1 in ('left', 'right'):
            c1 = min(nc, nc + dc1)
            edges.add(('h', nr, c1))
        else:
            r1 = min(nr, nr + dr1)
            edges.add(('v', r1, nc))
    dr2, dc2 = DIR_DELTA[dir2]
    for i in range(1, len2+1):
        nr = r + dr2 * (i-1)
        nc = c + dc2 * (i-1)
        if dir2 in ('left', 'right'):
            c1 = min(nc, nc + dc2)
            edges.add(('h', nr, c1))
        else:
            r1 = min(nr, nr + dr2)
            edges.add(('v', r1, nc))
    return edges

def get_clue_possible_edges(clue, N):
    r,c,t,k = clue
    possible = []
    if t == 'W':
        for dir1 in ['up', 'left']:
            dir2 = OPPOSITE[dir1]
            dr1, dc1 = DIR_DELTA[dir1]
            dr2, dc2 = DIR_DELTA[dir2]
            for len1 in range(1, k):
                len2 = k - len1
                if len2 < 1:
                    continue
                nr1 = r + dr1 * len1
                nc1 = c + dc1 * len1
                nr2 = r + dr2 * len2
                nc2 = c + dc2 * len2
                if 0 <= nr1 <= N and 0 <= nc1 <= N and 0 <= nr2 <= N and 0 <= nc2 <= N:
                    edges = get_edge_set_from_clue_config(r,c,dir1,len1,dir2,len2,N)
                    possible.append(edges)
    else:
        for dir1 in ['up', 'down', 'left', 'right']:
            for dir2 in PERPENDICULAR[dir1]:
                dr1, dc1 = DIR_DELTA[dir1]
                dr2, dc2 = DIR_DELTA[dir2]
                for len1 in range(1, k):
                    len2 = k - len1
                    if len2 <1:
                        continue
                    nr1 = r + dr1 * len1
                    nc1 = c + dc1 * len1
                    nr2 = r + dr2 * len2
                    nc2 = c + dc2 * len2
                    if 0 <= nr1 <= N and 0 <= nc1 <= N and 0 <= nr2 <= N and 0 <= nc2 <= N:
                        edges = get_edge_set_from_clue_config(r,c,dir1,len1,dir2,len2,N)
                        possible.append(edges)
    return possible

def mark_edge(h_edges, v_edges, dot_degree, edge, val, N):
    t, r, c = edge
    if t == 'h':
        if h_edges[r][c] == val:
            return True
        if h_edges[r][c] is not None and h_edges[r][c] != val:
            return False
        h_edges[r][c] = val
        if val:
            dot_degree[r][c] += 1
            dot_degree[r][c+1] += 1
            if dot_degree[r][c] > 2 or dot_degree[r][c+1] >2:
                return False
    else:
        if v_edges[r][c] == val:
            return True
        if v_edges[r][c] is not None and v_edges[r][c] != val:
            return False
        v_edges[r][c] = val
        if val:
            dot_degree[r][c] +=1
            dot_degree[r+1][c] +=1
            if dot_degree[r][c] >2 or dot_degree[r+1][c] >2:
                return False
    return True

def propagate_constraints(h_edges, v_edges, dot_degree, N, clues):
    changed = True
    while changed:
        changed = False
        for clue in clues:
            r,c,t,k = clue
            possible = get_clue_possible_edges(clue, N)
            valid_possible = []
            for edge_set in possible:
                valid = True
                for e in edge_set:
                    et, er, ec = e
                    if et == 'h' and h_edges[er][ec] is False:
                        valid = False
                        break
                    if et == 'v' and v_edges[er][ec] is False:
                        valid = False
                        break
                if valid:
                    valid_possible.append(edge_set)
            if not valid_possible:
                return False, h_edges, v_edges, dot_degree
            common_edges = set.intersection(*valid_possible)
            impossible_edges = set()
            all_edges = set()
            for s in valid_possible:
                all_edges.update(s)
            for e in common_edges:
                if not mark_edge(h_edges, v_edges, dot_degree, e, True, N):
                    return False, h_edges, v_edges, dot_degree
                changed = True
            for e in all_edges:
                present_in_all = True
                for s in valid_possible:
                    if e not in s:
                        present_in_all = False
                        break
                if not present_in_all:
                    continue
            for r_d in range(N+1):
                for c_d in range(N+1):
                    deg = dot_degree[r_d][c_d]
                    adj_edges = []
                    if c_d < N:
                        adj_edges.append(('h', r_d, c_d))
                    if c_d > 0:
                        adj_edges.append(('h', r_d, c_d -1))
                    if r_d < N:
                        adj_edges.append(('v', r_d, c_d))
                    if r_d >0:
                        adj_edges.append(('v', r_d -1, c_d))
                    if deg == 2:
                        for e in adj_edges:
                            et, er, ec = e
                            current = h_edges[er][ec] if et == 'h' else v_edges[er][ec]
                            if current is None:
                                if not mark_edge(h_edges, v_edges, dot_degree, e, False, N):
                                    return False, h_edges, v_edges, dot_degree
                                changed = True
                    elif deg == 1:
                        possible_edges = []
                        for e in adj_edges:
                            et, er, ec = e
                            current = h_edges[er][ec] if et == 'h' else v_edges[er][ec]
                            if current is None:
                                possible_edges.append(e)
                            elif current is True:
                                pass
                        if len(possible_edges) == 0:
                            return False, h_edges, v_edges, dot_degree
