def is_complete(h_edges, v_edges, N, clues):
    for r in range(N+1):
        for c in range(N):
            if h_edges[r][c] is None:
                return False
    for r in range(N):
        for c in range(N+1):
            if v_edges[r][c] is None:
                return False
    visited = [[False for _ in range(N+1)] for _ in range(N+1)]
    start = None
    for r in range(N+1):
        for c in range(N+1):
            deg = 0
            if c < N and h_edges[r][c]:
                deg +=1
            if c>0 and h_edges[r][c-1]:
                deg +=1
            if r < N and v_edges[r][c]:
                deg +=1
            if r>0 and v_edges[r-1][c]:
                deg +=1
            if deg == 2:
                start = (r,c)
                break
        if start:
            break
    if not start:
        return False
    path = []
    current = start
    prev = None
    while True:
        path.append(current)
        visited[current[0]][current[1]] = True
        r,c = current
        next_nodes = []
        if c < N and h_edges[r][c] and (r, c+1) != prev:
            next_nodes.append((r, c+1))
        if c>0 and h_edges[r][c-1] and (r, c-1) != prev:
            next_nodes.append((r, c-1))
        if r < N and v_edges[r][c] and (r+1, c) != prev:
            next_nodes.append((r+1, c))
        if r>0 and v_edges[r-1][c] and (r-1, c) != prev:
            next_nodes.append((r-1, c))
        if len(next_nodes) != 1:
            return False
        prev = current
        current = next_nodes[0]
        if current == start:
            break
    path.append(start)
    for (r,c,t,k) in clues:
        if not visited[r][c]:
            return False
    for r in range(N+1):
        for c in range(N+1):
            deg = 0
            if c < N and h_edges[r][c]:
                deg +=1
            if c>0 and h_edges[r][c-1]:
                deg +=1
            if r < N and v_edges[r][c]:
                deg +=1
            if r>0 and v_edges[r-1][c]:
                deg +=1
            if deg not in (0,2):
                return False
    return True

def build_path(h_edges, v_edges, N):
    start = None
    for r in range(N+1):
        for c in range(N+1):
            deg = 0
            if c < N and h_edges[r][c]:
                deg +=1
            if c>0 and h_edges[r][c-1]:
                deg +=1
            if r < N and v_edges[r][c]:
                deg +=1
            if r>0 and v_edges[r-1][c]:
                deg +=1
            if deg == 2:
                start = (r,c)
                break
        if start:
            break
    path = []
    current = start
    prev = None
    while True:
        path.append(current)
        r,c = current
        next_nodes = []
        if c < N and h_edges[r][c] and (r, c+1) != prev:
            next_nodes.append((r, c+1))
        if c>0 and h_edges[r][c-1] and (r, c-1) != prev:
            next_nodes.append((r, c-1))
        if r < N and v_edges[r][c] and (r+1, c) != prev:
            next_nodes.append((r+1, c))
        if r>0 and v_edges[r-1][c] and (r-1, c) != prev:
            next_nodes.append((r-1, c))
        prev = current
        current = next_nodes[0]
        if current == start:
            break
    path.append(start)
    return path

def select_next_edge(h_edges, v_edges, N):
    candidates = []
    for r in range(N+1):
        for c in range(N):
            if h_edges[r][c] is None:
                candidates.append(('h', r, c))
    for r in range(N):
        for c in range(N+1):
            if v_edges[r][c] is None:
                candidates.append(('v', r, c))
    if not candidates:
        return None
    return candidates[0]

def backtrack(h_edges, v_edges, dot_degree, N, clues):
    valid, h, v, d = propagate_constraints(deepcopy(h_edges), deepcopy(v_edges), deepcopy(dot_degree), N, clues)
    if not valid:
        return None
    if is_complete(h, v, N, clues):
        return build_path(h, v, N)
    edge = select_next_edge(h, v, N)
    if not edge:
        return None
    new_h1, new_v1, new_d1 = deepcopy(h), deepcopy(v), deepcopy(d)
    if mark_edge(new_h1, new_v1, new_d1, edge, True, N):
        res = backtrack(new_h1, new_v1, new_d1, N, clues)
        if res is not None:
            return res
    new_h2, new_v2, new_d2 = deepcopy(h), deepcopy(v), deepcopy(d)
    if mark_edge(new_h2, new_v2, new_d2, edge, False, N):
        res = backtrack(new_h2, new_v2, new_d2, N, clues)
        if res is not None:
            return res
    return None

def solve(observation):
    N, clues = parse_observation(observation)
    h_edges, v_edges, dot_degree = initialize_state(N)
    valid, h, v, d = propagate_constraints(h_edges, v_edges, dot_degree, N, clues)
    if not valid:
        return "No Solution"
    solution = backtrack(h, v, d, N, clues)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
