from collections import defaultdict

def solve(observation):
    grid = observation['data']
    N = len(grid)
    if N == 0:
        return "No Solution"

    # Precompute cells per region
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            region_cells[rid].append((r, c))
    all_regions = list(region_cells.keys())

    # Helper: get orthogonal adjacent cells
    def get_adjacent(r, c):
        adj = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                adj.append((nr, nc))
        return adj

    # Helper: verify complete solution meets all rules
    def verify(state):
        # Check domino validity and no adjacent dominoes
        visited = [[False]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if state[r][c] == 'S' and not visited[r][c]:
                    # BFS to get domino cells
                    q = [(r,c)]
                    visited[r][c] = True
                    domino = []
                    while q:
                        cr, cc = q.pop(0)
                        domino.append((cr, cc))
                        for nr, nc in get_adjacent(cr, cc):
                            if state[nr][nc] == 'S' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
                    if len(domino) != 2:
                        return False
                    # Check no adjacent S outside domino
                    for cr, cc in domino:
                        for nr, nc in get_adjacent(cr, cc):
                            if state[nr][nc] == 'S' and (nr, nc) not in domino:
                                return False
        # Check each region has exactly 2 shaded cells
        region_counts = defaultdict(int)
        for r in range(N):
            for c in range(N):
                if state[r][c] == 'S':
                    region_counts[grid[r][c]] += 1
        for rid in all_regions:
            if region_counts.get(rid, 0) != 2:
                return False
        return True

    # Backtracking with constraint propagation
    def backtrack(state, region_counts):
        # Constraint propagation loop
        changed = True
        while changed:
            changed = False
            # Rule 1: Regions with 2 shaded cells, all remaining cells are unshaded
            for rid in all_regions:
                if region_counts[rid] == 2:
                    for (r,c) in region_cells[rid]:
                        if state[r][c] is None:
                            state[r][c] = None
                            changed = True
            # Rule 2: Regions with exactly enough unassigned cells to hit 2, set all to S
            for rid in all_regions:
                needed = 2 - region_counts[rid]
                if needed <= 0:
                    continue
                unassigned = [(r,c) for (r,c) in region_cells[rid] if state[r][c] is None]
                if len(unassigned) == needed:
                    for (r,c) in unassigned:
                        if state[r][c] is not None:
                            continue
                        # Check if placing S here is possible (has potential partner)
                        has_partner = False
                        for nr, nc in get_adjacent(r,c):
                            nrid = grid[nr][nc]
                            if region_counts[nrid] < 2:
                                has_partner = True
                                break
                        if not has_partner:
                            return None
                        state[r][c] = 'S'
                        region_counts[rid] += 1
                        changed = True
                        # If only one possible partner, set partner to S
                        possible_partners = []
                        for nr, nc in get_adjacent(r,c):
                            if state[nr][nc] == 'S' or (state[nr][nc] is None and region_counts[grid[nr][nc]] < 2):
                                possible_partners.append((nr, nc))
                        if len(possible_partners) == 1:
                            pr, pc = possible_partners[0]
                            prid = grid[pr][pc]
                            if state[pr][pc] is None:
                                if region_counts[prid] >= 2:
                                    return None
                                state[pr][pc] = 'S'
                                region_counts[prid] += 1
                                changed = True
                                # Mark all cells adjacent to this domino as unshaded
                                for (cr, cc) in [(r,c), (pr, pc)]:
                                    for nr, nc in get_adjacent(cr, cc):
                                        if (nr, nc) not in [(r,c), (pr, pc)]:
                                            if state[nr][nc] == 'S':
                                                return None
                                            if state[nr][nc] is None:
                                                state[nr][nc] = None
                                                changed = True
            # Early invalid state checks
            for rid in all_regions:
                if region_counts[rid] > 2:
                    return None
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 'S':
                        adj_s = sum(1 for nr, nc in get_adjacent(r,c) if state[nr][nc] == 'S')
                        if adj_s > 1:
                            return None

        # Check if complete
        all_assigned = all(state[r][c] is not None for r in range(N) for c in range(N))
        if all_assigned:
            return state if verify(state) else None

        # Select MRV cell (minimum remaining values) to branch
        min_options = float('inf')
        best_cell = None
        for r in range(N):
            for c in range(N):
                if state[r][c] is None:
                    rid = grid[r][c]
                    if region_counts[rid] >= 2:
                        options = 1
                    else:
                        can_be_s = False
                        for nr, nc in get_adjacent(r,c):
                            if region_counts[grid[nr][nc]] < 2:
                                can_be_s = True
                                break
                        options = 2 if can_be_s else 1
                    if options < min_options:
                        min_options = options
                        best_cell = (r, c)
                        if min_options == 1:
                            break
            if best_cell and min_options == 1:
                break
        if best_cell is None:
            return state if verify(state) else None

        r, c = best_cell
        rid = grid[r][c]

        # Try option 1: mark as unshaded
        if region_counts[rid] + sum(1 for (x,y) in region_cells[rid] if state[x][y] == 'S') <= 2:
            new_state = [row.copy() for row in state]
            new_counts = region_counts.copy()
            new_state[r][c] = None
            res = backtrack(new_state, new_counts)
            if res is not None:
                return res

        # Try option 2: mark as shaded
        if region_counts[rid] < 2:
            can_place_s = False
            for nr, nc in get_adjacent(r,c):
                if region_counts[grid[nr][nc]] < 2:
                    can_place_s = True
                    break
            if can_place_s:
                new_state = [row.copy() for row in state]
                new_counts = region_counts.copy()
                new_state[r][c] = 'S'
                new_counts[rid] += 1
                res = backtrack(new_state, new_counts)
                if res is not None:
                    return res

        return None

    initial_state = [[None]*N for _ in range(N)]
    initial_counts = {rid:0 for rid in all_regions}
    result = backtrack(initial_state, initial_counts)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
