        # Try each candidate
        for val in sorted(candidates[r][c]):
            # Create copies for recursion
            new_grid = [row.copy() for row in current_grid]
            new_candidates = [[s.copy() for s in row] for row in candidates]
            new_grid[r][c] = val
            new_candidates[r][c] = {val}
            solution = backtrack(new_grid, new_candidates)
            if solution is not None:
                return solution
        return None

    initial_candidates = build_candidates(grid)
    final_solution = backtrack(grid, initial_candidates)
    return final_solution if final_solution is not None else "No Solution"

