from typing import List, Tuple, Dict, Optional

# Direction constants: (dr, dc)
DIRS = [(-1,0), (0,1), (1,0), (0,-1)]
OPPOSITE_DIR = {0:2, 1:3, 2:0, 3:1}

def get_edge_key(p1: Tuple[int, int], p2: Tuple[int, int]) -> Tuple[int, int, int, int]:
    """Return canonical edge key (smaller coordinate first)"""
    r1, c1 = p1
    r2, c2 = p2
    if (r1, c1) < (r2, c2):
        return (r1, c1, r2, c2)
    return (r2, c2, r1, c1)

def parse_observation(obs: Dict) -> Tuple[int, List[Tuple[int, int, str, int]]]:
    """Parse observation to get grid size N and list of clues (r,c,type,k)"""
    data = obs['data']
    N = len(data) - 1
    clues = []
    for r in range(N+1):
        for c in range(N+1):
            val = data[r][c]
            if val is not None:
                t = val[0]
                k = int(val[1:])
                clues.append((r, c, t, k))
    return N, clues

def initialize_state(N: int) -> Tuple[Dict, Dict]:
    """Initialize edge state (None=unknown, True=present, False=absent) and dot degree"""
    edge_state = {}
    # Add all horizontal edges
    for r in range(N+1):
        for c in range(N):
            edge_state[(r, c, r, c+1)] = None
    # Add all vertical edges
    for r in range(N):
        for c in range(N+1):
            edge_state[(r, c, r+1, c)] = None
    dot_degree = {(r,c):0 for r in range(N+1) for c in range(N+1)}
    return edge_state, dot_degree

def get_neighbors(p: Tuple[int, int], N: int) -> List[Tuple[int, int]]:
    """Get valid adjacent dots"""
    r, c = p
    res = []
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr <= N and 0 <= nc <= N:
            res.append((nr, nc))
    return res

def propagate_constraints(edge_state: Dict, dot_degree: Dict, N: int, clues: List) -> bool:
    """Propagate all constraints, return False if contradiction found"""
    changed = True
    while changed:
        changed = False
        # Rule 1: Dot degree constraint (max 2 edges per dot)
        for (r,c), deg in dot_degree.items():
            if deg > 2:
                return False
            neighbors = get_neighbors((r,c), N)
            if deg == 2:
                # All other edges must be absent
                for (nr, nc) in neighbors:
                    e = get_edge_key((r,c), (nr, nc))
                    if edge_state[e] is None:
                        edge_state[e] = False
                        changed = True
            elif deg == 1:
                # Count unknown edges
                unknown_edges = []
                present_edges = 0
                for (nr, nc) in neighbors:
                    e = get_edge_key((r,c), (nr, nc))
                    if edge_state[e] == True:
                        present_edges += 1
                    elif edge_state[e] is None:
                        unknown_edges.append(e)
                if present_edges > 1:
                    return False
                if len(unknown_edges) == 0 and present_edges != 2:
                    return False
                if len(unknown_edges) == 1 and present_edges == 1:
                    # Must add this edge
                    e = unknown_edges[0]
                    edge_state[e] = True
                    changed = True
                    # Update degrees
                    r1,c1,r2,c2 = e
                    dot_degree[(r1,c1)] +=1
                    dot_degree[(r2,c2)] +=1
                    if dot_degree[(r1,c1)] >2 or dot_degree[(r2,c2)]>2:
                        return False
        # Rule 2: Clue constraints (simplified initial propagation, extended in backtracking)
        for (r,c,t,k) in clues:
            if dot_degree[(r,c)] not in (0,1,2):
                return False
        # Rule 3: No partial loops (check if any closed loop exists that doesn't cover all clues)
        # Simplified check for small partial loops
        visited = set()
        for (r,c) in dot_degree:
            if dot_degree[(r,c)] == 2 and (r,c) not in visited:
                # Traverse path
                path = []
                curr = (r,c)
                prev = None
                while True:
                    if curr in visited:
                        if curr == (r,c) and len(path) > 0:
                            # Found loop, check if all clues are in path
                            clue_set = set((cr,cc) for cr,cc,_,_ in clues)
                            path_set = set(path)
                            if not clue_set.issubset(path_set):
                                return False
                        break
                    visited.add(curr)
                    path.append(curr)
                    # Find next node
                    next_nodes = []
                    for (nr, nc) in get_neighbors(curr, N):
                        e = get_edge_key(curr, (nr, nc))
                        if edge_state[e] == True and (nr, nc) != prev:
                            next_nodes.append((nr, nc))
                    if len(next_nodes) != 1:
                        break
                    prev = curr
                    curr = next_nodes[0]
    return True

def is_complete(edge_state: Dict) -> bool:
    """Check if all edges are assigned"""
    return all(v is not None for v in edge_state.values())

def get_mrv_edge(edge_state: Dict) -> Optional[Tuple]:
    """Pick next unknown edge to assign (simple heuristic, extendable)"""
    for e, v in edge_state.items():
        if v is None:
            return e
    return None

def build_final_path(edge_state: Dict, N: int) -> List[Tuple[int, int]]:
    """Build ordered closed loop path from edge state"""
    # Find start point (any dot with degree 2)
    start = None
    for (r,c) in [(r,c) for r in range(N+1) for c in range(N+1)]:
        cnt = 0
        for (nr, nc) in get_neighbors((r,c), N):
            e = get_edge_key((r,c), (nr, nc))
            if edge_state[e] == True:
                cnt +=1
        if cnt == 2:
            start = (r,c)
            break
    if not start:
        return []
    path = [start]
    prev = None
    curr = start
    while True:
        # Find next node
        next_node = None
        for (nr, nc) in get_neighbors(curr, N):
            if (nr, nc) == prev:
                continue
            e = get_edge_key(curr, (nr, nc))
            if edge_state[e] == True:
                next_node = (nr, nc)
                break
        if not next_node:
            return []
        if next_node == start:
            path.append(start)
            break
        path.append(next_node)
        prev = curr
        curr = next_node
    # Verify path covers all clues
    return path

def backtrack(edge_state: Dict, dot_degree: Dict, N: int, clues: List) -> Optional[List[Tuple]]:
    """Backtracking search with constraint propagation"""
    # Propagate constraints first
    if not propagate_constraints(edge_state, dot_degree, N, clues):
        return None
    # Check if complete
    if is_complete(edge_state):
        path = build_final_path(edge_state, N)
        if path:
            return path
        return None
    # Pick next edge to assign
    e = get_mrv_edge(edge_state)
    if not e:
        return None
    r1,c1,r2,c2 = e
    # Try assigning edge to True first
    for val in [True, False]:
        # Make copies of state
        new_edge = edge_state.copy()
        new_deg = dot_degree.copy()
        new_edge[e] = val
        if val:
            new_deg[(r1,c1)] += 1
            new_deg[(r2,c2)] += 1
            if new_deg[(r1,c1)] > 2 or new_deg[(r2,c2)] > 2:
                continue
        # Recurse
        res = backtrack(new_edge, new_deg, N, clues)
        if res is not None:
            return res
    return None

def solve(observation: Dict) -> List[Tuple[int, int]] | str:
    N, clues = parse_observation(observation)
    edge_state, dot_degree = initialize_state(N)
    # Initial propagation
    if not propagate_constraints(edge_state, dot_degree, N, clues):
        return "No Solution"
    # Run backtracking search
    solution = backtrack(edge_state, dot_degree, N, clues)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
