def get_canonical(shape):
    """Convert set of (r,c) cells to canonical offset form"""
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    offset = tuple(sorted(((r - min_r, c - min_c) for r, c in shape)))
    return offset

def get_tetromino_type(shape):
    """Return type of tetromino if allowed, else None"""
    canon = get_canonical(shape)
    return CANONICAL_TO_TYPE.get(canon, None)

def generate_region_placements(region_cells):
    """Generate all valid tetromino placements for a region"""
    placements = []
    cells = list(region_cells)
    n = len(cells)
    # Generate all 4-cell combinations
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    shape = {cells[i], cells[j], cells[k], cells[l]}
                    # Check if shape is connected orthogonally
                    visited = set()
                    q = deque([next(iter(shape))])
                    visited.add(q[0])
                    while q:
                        r, c = q.popleft()
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = r+dr, c+dc
                            if (nr, nc) in shape and (nr, nc) not in visited:
