def check_2x2(shaded_set):
    """Check if any 2x2 block is fully shaded"""
    max_r = max(r for r, c in shaded_set)
    max_c = max(c for r, c in shaded_set)
    for r in range(max_r):
        for c in range(max_c):
            if (r,c) in shaded_set and (r,c+1) in shaded_set and (r+1,c) in shaded_set and (r+1,c+1) in shaded_set:
                return False
    return True

def check_adjacent_types(assignments, adj_regions):
