    grid = observation['data']
    N = len(grid)
    # Step 1: Preprocess regions
    region_cells = defaultdict(set)
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            region_cells[rid].add((r,c))
    region_ids = list(region_cells.keys())
    # Step 2: Find adjacent regions
    adj_regions = defaultdict(set)
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    nrid = grid[nr][nc]
                    if nrid != rid:
                        adj_regions[rid].add(nrid)
                        adj_regions[nrid].add(rid)
    # Step 3: Generate all possible placements per region
    region_placements = {}
    for rid in region_ids:
        placements = generate_region_placements(region_cells[rid])
        if not placements:
            return "No Solution"
        region_placements[rid] = placements
    # Step 4: Constraint propagation - fix regions with only one placement first
    fixed = {}
    queue = deque()
    for rid in region_ids:
        if len(region_placements[rid]) == 1:
            fixed_t, fixed_shape = region_placements[rid][0]
            fixed[rid] = (fixed_t, fixed_shape)
            queue.append(rid)
    # Propagate constraints
    while queue:
        rid = queue.popleft()
        t1, _ = fixed[rid]
        for neighbor in adj_regions[rid]:
            if neighbor in fixed:
                continue
            # Remove placements from neighbor with same type
            new_placements = [p for p in region_placements[neighbor] if p[0] != t1]
            if not new_placements:
                return "No Solution"
            if len(new_placements) == 1 and neighbor not in fixed:
                fixed[neighbor] = new_placements[0]
                queue.append(neighbor)
            region_placements[neighbor] = new_placements
    # Step 5: Backtracking search with most constrained first heuristic
    unassigned = [rid for rid in region_ids if rid not in fixed]
    if not unassigned:
        # All fixed, check final constraints
        all_shaded = set()
        for rid in fixed:
            all_shaded.update(fixed[rid][1])
        # Check 2x2
        if not check_2x2(all_shaded):
            return "No Solution"
        # Check connectivity
        visited = set()
        q = deque([next(iter(all_shaded))])
        visited.add(q[0])
        while q:
            r,c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if (nr, nc) in all_shaded and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        if len(visited) != len(all_shaded):
            return "No Solution"
        # Build result grid
        res = [[None]*N for _ in range(N)]
        for rid in fixed:
            t, shape = fixed[rid]
            for r,c in shape:
