                    if (nr, nc) in shaded_set and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) != len(shaded_set):
                return None
            # Check 2x2
            if not check_2x2(shaded_set):
                return None
            # Build result
            res = [[None]*N for _ in range(N)]
            for rid in assignments:
                t, shape = assignments[rid]
                for r,c in shape:
