        [None, None, None, 7, 2, None, None, 9, None],
        [None, None, 8, None, None, None, None, 2, 1]
    ],
    'unit': '3x3'
}

def solve(observation):
    data = observation['data']
    unit = observation['unit']
    r_unit, c_unit = map(int, unit.split('x'))
    N = r_unit * c_unit

    # Initialize possible values grid
    possible = []
    for i in range(N):
        row = []
        for j in range(N):
            val = data[i][j]
            if val is not None:
                row.append({val})
            else:
                row.append(set(range(1, N + 1)))
        possible.append(row)

    # Get all unique peer cells for (i,j): same row, column, subgrid
    def get_peers(i, j):
        peers = set()
        # Same row
        for y in range(N):
            if y != j:
                peers.add((i, y))
        # Same column
        for x in range(N):
            if x != i:
                peers.add((x, j))
        # Same subgrid
        sg_r_start = (i // r_unit) * r_unit
        sg_c_start = (j // c_unit) * c_unit
        for x in range(sg_r_start, sg_r_start + r_unit):
            for y in range(sg_c_start, sg_c_start + c_unit):
                if (x, y) != (i, j):
                    peers.add((x, y))
        return peers

    # Constraint propagation: naked singles + hidden singles
    def propagate(poss):
        changed = True
        while changed:
            changed = False
            # Step 1: Naked singles (cell has only 1 possible value)
            for i in range(N):
                for j in range(N):
                    vals = poss[i][j]
                    if len(vals) == 1:
                        val = next(iter(vals))
                        for (x, y) in get_peers(i, j):
                            if val in poss[x][y]:
                                poss[x][y].remove(val)
                                changed = True
                                if len(poss[x][y]) == 0:
                                    return False  # Contradiction
            # Step 2: Hidden singles in rows (value only possible in one cell of row)
            for i in range(N):
                for val in range(1, N + 1):
                    positions = [j for j in range(N) if val in poss[i][j]]
                    if len(positions) == 1:
                        j = positions[0]
                        if len(poss[i][j]) != 1:
                            poss[i][j] = {val}
                            changed = True
            # Step 3: Hidden singles in columns
            for j in range(N):
                for val in range(1, N + 1):
                    positions = [i for i in range(N) if val in poss[i][j]]
                    if len(positions) == 1:
                        i = positions[0]
                        if len(poss[i][j]) != 1:
                            poss[i][j] = {val}
                            changed = True
            # Step 4: Hidden singles in subgrids
            for sg_r in range(0, N, r_unit):
                for sg_c in range(0, N, c_unit):
                    for val in range(1, N + 1):
                        positions = []
                        for i in range(sg_r, sg_r + r_unit):
                            for j in range(sg_c, sg_c + c_unit):
                                if val in poss[i][j]:
                                    positions.append((i, j))
                        if len(positions) == 1:
                            i, j = positions[0]
                            if len(poss[i][j]) != 1:
                                poss[i][j] = {val}
                                changed = True
        return True

    # Check if grid is fully solved
    def is_solved(poss):
        for i in range(N):
            for j in range(N):
                if len(poss[i][j]) != 1:
                    return False
        return True

    # Convert possible grid to final answer format
    def to_answer(poss):
        ans = []
        for i in range(N):
            row = []
            for j in range(N):
                row.append(next(iter(poss[i][j])))
            ans.append(row)
        return ans

    # Backtracking with Minimum Remaining Values (MRV) heuristic
    def backtrack(poss):
        if not propagate(poss):
            return None
        if is_solved(poss):
            return to_answer(poss)
        # Find cell with smallest number of possible values (most constrained first)
        min_len = N + 1
        min_cell = None
        for i in range(N):
            for j in range(N):
                l = len(poss[i][j])
                if 1 < l < min_len:
                    min_len = l
                    min_cell = (i, j)
                    if min_len == 2:  # Early exit, can't get smaller than 2
                        break
            if min_len == 2:
                break
        i, j = min_cell
        # Try each candidate value
        for val in sorted(poss[i][j]):
            new_poss = [[set(s) for s in row] for row in poss]
            new_poss[i][j] = {val}
            res = backtrack(new_poss)
            if res is not None:
                return res
        return None

    result = backtrack(possible)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
