OBSERVATION = {'data': [[3, 2, None, 2, None], [None, None, 2, None, None], [1, 2, 1, 3, 2], [2, 3, None, None, None], [None, 2, 3, 3, None]]}

def solve(observation):
    data = observation['data']
    N = len(data)
    # Edge representation: 0 = off, 1 = on, 2 = undecided
    h_edges = [[2]*N for _ in range(N+1)]  # Horizontal edges: (r,c) connects (r,c)-(r,c+1)
    v_edges = [[2]*(N+1) for _ in range(N)]  # Vertical edges: (r,c) connects (r,c)-(r+1,c)
    final_path = None

    def propagate():
        changed = True
        while changed:
            changed = False
            # Process cell clue constraints
            for i in range(N):
                for j in range(N):
                    clue = data[i][j]
                    if clue is None:
                        continue
                    t, b, l, r = h_edges[i][j], h_edges[i+1][j], v_edges[i][j], v_edges[i][j+1]
                    cnt_on = sum(1 for x in (t,b,l,r) if x == 1)
                    cnt_und = sum(1 for x in (t,b,l,r) if x == 2)
                    req = clue - cnt_on
                    if req < 0 or req > cnt_und:
                        return False
                    if req == cnt_und and req > 0:
                        if h_edges[i][j] == 2: h_edges[i][j] = 1; changed = True
                        if h_edges[i+1][j] == 2: h_edges[i+1][j] = 1; changed = True
                        if v_edges[i][j] == 2: v_edges[i][j] = 1; changed = True
                        if v_edges[i][j+1] == 2: v_edges[i][j+1] = 1; changed = True
                    if req == 0 and cnt_und > 0:
                        if h_edges[i][j] == 2: h_edges[i][j] = 0; changed = True
                        if h_edges[i+1][j] == 2: h_edges[i+1][j] = 0; changed = True
                        if v_edges[i][j] == 2: v_edges[i][j] = 0; changed = True
                        if v_edges[i][j+1] == 2: v_edges[i][j+1] = 0; changed = True
            # Process node degree constraints (each node has exactly 0 or 2 edges)
            for r in range(N+1):
                for c in range(N+1):
                    deg_on = 0
                    deg_und = 0
                    edges = []
                    if r > 0: edges.append(v_edges[r-1][c])
                    if r < N: edges.append(v_edges[r][c])
                    if c > 0: edges.append(h_edges[r][c-1])
                    if c < N: edges.append(h_edges[r][c])
                    deg_on = sum(1 for x in edges if x == 1)
                    deg_und = sum(1 for x in edges if x == 2)
                    if deg_on > 2:
                        return False
                    if deg_on == 2 and deg_und > 0:
                        if r>0 and v_edges[r-1][c] == 2: v_edges[r-1][c] = 0; changed = True
                        if r<N and v_edges[r][c] == 2: v_edges[r][c] = 0; changed = True
                        if c>0 and h_edges[r][c-1] == 2: h_edges[r][c-1] = 0; changed = True
                        if c<N and h_edges[r][c] == 2: h_edges[r][c] = 0; changed = True
                    if deg_on + deg_und < 2:
                        return False
                    if deg_on + deg_und == 2 and deg_und > 0:
                        if r>0 and v_edges[r-1][c] == 2: v_edges[r-1][c] = 1; changed = True
                        if r<N and v_edges[r][c] == 2: v_edges[r][c] = 1; changed = True
                        if c>0 and h_edges[r][c-1] == 2: h_edges[r][c-1] = 1; changed = True
                        if c<N and h_edges[r][c] == 2: h_edges[r][c] = 1; changed = True
        return True

    def is_valid_loop():
        nonlocal final_path
        # Find starting node with degree 2
        start = None
        for r in range(N+1):
            for c in range(N+1):
                deg = 0
                if r>0 and v_edges[r-1][c] == 1: deg += 1
                if r<N and v_edges[r][c] ==1: deg +=1
                if c>0 and h_edges[r][c-1] ==1: deg +=1
                if c<N and h_edges[r][c] ==1: deg +=1
                if deg == 2:
                    start = (r,c)
                    break
            if start:
                break
        if not start:
            return False
        # Trace loop
        path = []
        curr = start
        prev = None
        while True:
            path.append(curr)
            r,c = curr
            next_node = None
            if r>0 and v_edges[r-1][c] == 1 and (r-1,c) != prev:
                next_node = (r-1,c)
            elif r<N and v_edges[r][c] == 1 and (r+1,c) != prev:
                next_node = (r+1,c)
            elif c>0 and h_edges[r][c-1] == 1 and (r,c-1) != prev:
                next_node = (r,c-1)
            elif c<N and h_edges[r][c] == 1 and (r,c+1) != prev:
                next_node = (r,c+1)
            if not next_node:
                return False
            if next_node == start:
                path.append(start)
                break
            prev = curr
            curr = next_node
        # Verify all edges are included (no isolated loops)
        total_on = sum(sum(x==1 for x in row) for row in h_edges) + sum(sum(x==1 for x in row) for row in v_edges)
        if len(path)-1 != total_on:
            return False
        final_path = path
        return True

    def backtrack():
        if not propagate():
            return False
        # Find first undecided edge
        for r in range(N+1):
            for c in range(N):
                if h_edges[r][c] == 2:
                    h_edges[r][c] = 1
                    if backtrack():
                        return True
                    h_edges[r][c] = 0
                    if backtrack():
                        return True
                    h_edges[r][c] = 2
                    return False
        for r in range(N):
            for c in range(N+1):
                if v_edges[r][c] == 2:
                    v_edges[r][c] = 1
                    if backtrack():
                        return True
                    v_edges[r][c] = 0
                    if backtrack():
                        return True
                    v_edges[r][c] = 2
                    return False
        # All edges decided, validate loop
        return is_valid_loop()

    if backtrack():
        return final_path
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
