def normalize_shape(shape):
    min_r = min(p[0] for p in shape)
    min_c = min(p[1] for p in shape)
    normalized = tuple(sorted((r - min_r, c - min_c) for r, c in shape))
    return normalized

CANONICAL = {}
for tname, shapes in TETROMINOES.items():
    for s in shapes:
        CANONICAL[normalize_shape(s)] = tname

def get_region_cells(region_grid):
    regions = defaultdict(list)
    for r in range(len(region_grid)):
        for c in range(len(region_grid[0])):
            regions[region_grid[r][c]].append((r,c))
    return regions

def get_adjacent_regions(region_grid, regions):
    adj = defaultdict(set)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for rid, cells in regions.items():
        for (r,c) in cells:
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<len(region_grid) and 0<=nc<len(region_grid[0]):
                    nrid = region_grid[nr][nc]
                    if nrid != rid:
                        adj[rid].add(nrid)
    return adj

def generate_possible_placements(region_cells):
    placements = []
    cell_set = set(region_cells)
    min_r = min(r for r,c in region_cells)
    max_r = max(r for r,c in region_cells)
    min_c = min(c for r,c in region_cells)
    max_c = max(c for r,c in region_cells)

    for tname, shapes in TETROMINOES.items():
        for shape in shapes:
            for (r0,c0) in region_cells:
                placed = [(r0 + dr, c0 + dc) for (dr, dc) in shape]
                if all((r,c) in cell_set for r,c in placed):
                    placements.append((tname, set(placed)))
    unique_placements = {}
    for t, s in placements:
        key = frozenset(s)
        if key not in unique_placements:
            unique_placements[key] = t
    return [(t, set(k)) for k,t in unique_placements.items()]

def has_2x2(shaded):
    cells = set(shaded)
    for (r,c) in cells:
        if (r+1,c) in cells and (r,c+1) in cells and (r+1,c+1) in cells:
            return True
    return False

def is_connected(shaded):
    if not shaded:
        return True
    shaded_set = set(shaded)
    start = next(iter(shaded_set))
    visited = set([start])
    q = deque([start])
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        r,c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if (nr, nc) in shaded_set and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(shaded_set)

def solve(observation):
    region_grid = observation['data']
    N = len(region_grid)
    regions = get_region_cells(region_grid)
    adj_regions = get_adjacent_regions(region_grid, regions)
    region_ids = list(regions.keys())

    possible = {}
    for rid in region_ids:
        possible[rid] = generate_possible_placements(regions[rid])
        if not possible[rid]:
            return "No Solution"

    assigned_type = {}
    assigned_shaded = {}
    all_shaded = set()

    def backtrack():
        unassigned = [rid for rid in region_ids if rid not in assigned_type]
        if not unassigned:
            if is_connected(all_shaded) and not has_2x2(all_shaded):
                res = [[None for _ in range(N)] for _ in range(N)]
                for rid in assigned_shaded:
                    t = assigned_type[rid]
                    for (r,c) in assigned_shaded[rid]:
                        res[r][c] = t
                return res
            return None

        rid = min(unassigned, key=lambda x: len(possible[x]))
        for (t, shape) in possible[rid]:
            conflict = False
            for adj_rid in adj_regions[rid]:
                if adj_rid in assigned_type and assigned_type[adj_rid] == t:
                    conflict = True
                    break
            if conflict:
                continue
            test_shaded = all_shaded.union(shape)
            if has_2x2(test_shaded):
                continue
            if len(all_shaded) > 0 and not is_connected(test_shaded):
                continue

            assigned_type[rid] = t
            assigned_shaded[rid] = shape
            prev_len = len(all_shaded)
            all_shaded.update(shape)

            res = backtrack()
            if res is not None:
                return res

            del assigned_type[rid]
            del assigned_shaded[rid]
            while len(all_shaded) > prev_len:
                all_shaded.pop()
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

