import copy

def solve(observation):
    data = observation['data']
    unit = observation['unit']

    # Parse subgrid dimensions
    if 'x' in unit:
        sub_h, sub_w = map(int, unit.split('x'))
    else:
        sub_h = sub_w = int(unit)
    N = sub_h * sub_w

    # Validate input grid size
    if len(data) != N or any(len(row) != N for row in data):
        return "No Solution"

    grid = [row.copy() for row in data]
    candidates = [[set() for _ in range(N)] for __ in range(N)]

    # Helper: Get all cells in the same subgrid as (r,c)
    def get_subgrid_cells(r, c):
        sr_start = (r // sub_h) * sub_h
        sc_start = (c // sub_w) * sub_w
        cells = []
        for i in range(sr_start, sr_start + sub_h):
            for j in range(sc_start, sc_start + sub_w):
                cells.append((i, j))
        return cells

    # Helper: Compute valid candidates for cell (r,c)
    def compute_cell_candidates(r, c):
        if grid[r][c] is not None:
            return set()
        used = set()
        # Add row values
        used.update(v for v in grid[r] if v is not None)
        # Add column values
        used.update(grid[i][c] for i in range(N) if grid[i][c] is not None)
        # Add subgrid values
        for (i, j) in get_subgrid_cells(r, c):
            v = grid[i][j]
            if v is not None:
                used.add(v)
        return set(range(1, N+1)) - used

    # Initialize candidates matrix
    for r in range(N):
        for c in range(N):
            candidates[r][c] = compute_cell_candidates(r, c)

    # Helper: Assign value to cell and propagate constraints to related cells
    def assign_value(r, c, val):
        grid[r][c] = val
        candidates[r][c] = set()
        # Update row
        for j in range(N):
            if grid[r][j] is None:
                candidates[r][j].discard(val)
        # Update column
        for i in range(N):
            if grid[i][c] is None:
                candidates[i][c].discard(val)
        # Update subgrid
        for (i, j) in get_subgrid_cells(r, c):
            if grid[i][j] is None:
                candidates[i][j].discard(val)

    # Constraint propagation loop: naked singles + hidden singles
    changed = True
    while changed:
        changed = False

        # Step 1: Find naked singles (cell with exactly 1 candidate)
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and len(candidates[r][c]) == 1:
                    val = next(iter(candidates[r][c]))
                    assign_value(r, c, val)
                    changed = True
        if changed:
            continue

        # Step 2: Find hidden singles in rows (value appears only once in row candidates)
        for r in range(N):
            val_pos = {}
            for c in range(N):
                if grid[r][c] is None:
                    for v in candidates[r][c]:
                        val_pos.setdefault(v, []).append(c)
            for v, positions in val_pos.items():
                if len(positions) == 1:
                    c = positions[0]
                    assign_value(r, c, v)
                    changed = True
                    break
            if changed:
                break
        if changed:
            continue

        # Step 3: Find hidden singles in columns
        for c in range(N):
            val_pos = {}
            for r in range(N):
                if grid[r][c] is None:
                    for v in candidates[r][c]:
                        val_pos.setdefault(v, []).append(r)
            for v, positions in val_pos.items():
                if len(positions) == 1:
                    r = positions[0]
                    assign_value(r, c, v)
                    changed = True
                    break
            if changed:
                break
        if changed:
            continue

        # Step 4: Find hidden singles in subgrids
        for sr_start in range(0, N, sub_h):
            for sc_start in range(0, N, sub_w):
                val_pos = {}
                cells = []
                for i in range(sr_start, sr_start + sub_h):
                    for j in range(sc_start, sc_start + sub_w):
                        cells.append((i,j))
                for (r,c) in cells:
                    if grid[r][c] is None:
                        for v in candidates[r][c]:
                            val_pos.setdefault(v, []).append((r,c))
                for v, positions in val_pos.items():
                    if len(positions) == 1:
                        r,c = positions[0]
                        assign_value(r,c,v)
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break

    # Check for invalid state (cell with no candidates)
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None and len(candidates[r][c]) == 0:
                return "No Solution"

    # Check if grid is fully solved
    is_complete = all(all(v is not None for v in row) for row in grid)
    if is_complete:
        # Final validation
        def is_valid():
            # Check rows
            for row in grid:
                if set(row) != set(range(1, N+1)):
                    return False
            # Check columns
            for c in range(N):
                col = [grid[r][c] for r in range(N)]
                if set(col) != set(range(1, N+1)):
                    return False
            # Check subgrids
            for sr_start in range(0, N, sub_h):
                for sc_start in range(0, N, sub_w):
                    vals = []
                    for i in range(sr_start, sr_start + sub_h):
                        for j in range(sc_start, sc_start + sub_w):
                            vals.append(grid[i][j])
                    if set(vals) != set(range(1, N+1)):
                        return False
            return True
        return grid if is_valid() else "No Solution"

    # MRV heuristic: pick cell with smallest number of candidates to minimize branching
    min_candidate_count = float('inf')
    target_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None and len(candidates[r][c]) < min_candidate_count:
                min_candidate_count = len(candidates[r][c])
                target_cell = (r, c)
                if min_candidate_count == 2:
                    break
        if min_candidate_count == 2:
            break
    tr, tc = target_cell

    # Try each candidate value recursively
    for val in sorted(candidates[tr][tc]):
        new_grid = copy.deepcopy(grid)
        new_grid[tr][tc] = val
        res = solve({'data': new_grid, 'unit': unit})
        if res != "No Solution":
            return res

    # No valid solution found
    return "No Solution"

