        for c in range(N):
            rid = reg[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))
    # Precompute all possible domino positions (horizontal + vertical)
    dominoes = []
    for r in range(N):
        for c in range(N - 1):
            dominoes.append(((r, c), (r, c + 1)))
    for r in range(N - 1):
        for c in range(N):
            dominoes.append(((r, c), (r + 1, c)))
    # Grid state: None = unassigned, 'S' = shaded, 'X' = cannot be shaded (internal marker)
    grid = [[None for _ in range(N)] for _ in range(N)]
    region_placed = {rid: 0 for rid in regions}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    def backtrack():
        # Check if all regions have exactly 2 shaded cells (solution found)
        all_complete = True
        for cnt in region_placed.values():
            if cnt != 2:
                all_complete = False
                break
        if all_complete:
            return True
        # Collect all valid dominoes that can be placed currently
        valid_dominoes = []
        for dom in dominoes:
            (r1, c1), (r2, c2) = dom
            if grid[r1][c1] is not None or grid[r2][c2] is not None:
                continue
            rid1 = reg[r1][c1]
            rid2 = reg[r2][c2]
            if region_placed[rid1] >= 2 or region_placed[rid2] >= 2:
