            valid_dominoes.append(dom)
        # Sort dominoes to prioritize those in regions with more placed shaded cells (prune early)
        valid_dominoes.sort(key=lambda d: -(region_placed[reg[d[0][0]][d[0][1]]] + region_placed[reg[d[1][0]][d[1][1]]]))
        if not valid_dominoes:
            return False
        for dom in valid_dominoes:
            (r1, c1), (r2, c2) = dom
            changes = []
            # Mark domino cells as shaded
            grid[r1][c1] = 'S'
            changes.append(('set', r1, c1, None))
            grid[r2][c2] = 'S'
            changes.append(('set', r2, c2, None))
            # Update region shaded counts
            rid1 = reg[r1][c1]
            rid2 = reg[r2][c2]
            old_rid1 = region_placed[rid1]
            region_placed[rid1] += 1
            changes.append(('reg', rid1, old_rid1))
            old_rid2 = region_placed[rid2]
            region_placed[rid2] += 1
            changes.append(('reg', rid2, old_rid2))
            # Mark all adjacent cells of the domino as blocked (no other domino can touch)
            for (r, c), partner in [((r1, c1), (r2, c2)), ((r2, c2), (r1, c1))]:
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if (nr, nc) == partner:
