                available = 0
                for (r, c) in regions[rid]:
                    if grid[r][c] is None:
                        available += 1
                if needed > available:
                    valid_state = False
                    break
            if valid_state:
                if backtrack():
                    return True
            # Undo all changes for backtracking
            for change in reversed(changes):
                if change[0] == 'set':
                    _, r, c, old_val = change
                    grid[r][c] = old_val
                else:
                    _, rid, old_val = change
                    region_placed[rid] = old_val
        return False
    solution_found = backtrack()
    if not solution_found:
        return "No Solution"
    # Convert internal X marker to None for final output
    output = []
    for row in grid:
        output_row = []
        for cell in row:
            output_row.append('S' if cell == 'S' else None)
        output.append(output_row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
