def deep_copy_edges(h, v):
    return [r[:] for r in h], [r[:] for r in v]

def propagate(h_edges, v_edges, N, clues):
    h, v = deep_copy_edges(h_edges, v_edges)
    changed = True
    while changed:
        changed = False
        # Process cell clue constraints
        for r in range(N):
            for c in range(N):
                clue = clues[r][c]
                if clue is None:
                    continue
                edges = []
                # Top edge (h[r][c])
                edges.append((0, r, c))
                # Bottom edge (h[r+1][c])
                edges.append((0, r+1, c))
                # Left edge (v[r][c])
                edges.append((1, r, c))
                # Right edge (v[r][c+1])
                edges.append((1, r, c+1))
                true_cnt = 0
                false_cnt = 0
                unknown = []
                for typ, er, ec in edges:
                    if typ == 0:
                        val = h[er][ec]
                    else:
                        val = v[er][ec]
                    if val is True:
                        true_cnt +=1
                    elif val is False:
                        false_cnt +=1
                    else:
                        unknown.append((typ, er, ec))
                # Check validity
                if true_cnt > clue:
                    return (False, h, v)
                if (4 - false_cnt) < clue:
                    return (False, h, v)
                # Assign remaining edges
                if true_cnt == clue:
                    for typ, er, ec in unknown:
                        if typ == 0 and h[er][ec] is None:
                            h[er][ec] = False
                            changed = True
                        elif typ == 1 and v[er][ec] is None:
                            v[er][ec] = False
                            changed = True
                if (true_cnt + len(unknown)) == clue:
                    for typ, er, ec in unknown:
                        if typ == 0 and h[er][ec] is None:
                            h[er][ec] = True
                            changed = True
                        elif typ == 1 and v[er][ec] is None:
                            v[er][ec] = True
                            changed = True
        # Process vertex degree constraints (each vertex has 0 or 2 edges)
        for r in range(N+1):
            for c in range(N+1):
                edges = []
                # Top edge (v[r-1][c] if r>0)
                if r > 0:
                    edges.append((1, r-1, c))
                # Bottom edge (v[r][c] if r < N)
                if r < N:
                    edges.append((1, r, c))
                # Left edge (h[r][c-1] if c>0)
                if c > 0:
                    edges.append((0, r, c-1))
                # Right edge (h[r][c] if c < N)
                if c < N:
                    edges.append((0, r, c))
                true_cnt = 0
                false_cnt = 0
                unknown = []
                for typ, er, ec in edges:
                    if typ == 0:
                        val = h[er][ec]
                    else:
                        val = v[er][ec]
                    if val is True:
                        true_cnt += 1
                    elif val is False:
                        false_cnt +=1
                    else:
                        unknown.append((typ, er, ec))
                if true_cnt > 2:
