                            h[er][ec] = True
                            changed = True
                        elif typ == 1 and v[er][ec] is None:
                            v[er][ec] = True
                            changed = True
    return (True, h, v)

def is_complete(h, v, N):
    for r in range(N+1):
        if None in h[r]:
            return False
    for r in range(N):
        if None in v[r]:
            return False
    return True

def extract_loop(h, v, N):
    # Find starting vertex
    start = None
    for r in range(N+1):
        for c in range(N+1):
            cnt = 0
            if r > 0 and v[r-1][c]: cnt +=1
            if r < N and v[r][c]: cnt +=1
            if c >0 and h[r][c-1]: cnt +=1
            if c < N and h[r][c]: cnt +=1
            if cnt == 2:
                start = (r, c)
                break
        if start:
            break
    if not start:
        return None
    path = [start]
    prev = None
    current = start
    while True:
        r, c = current
        neighbors = []
        # Check up
        if r > 0 and v[r-1][c] and (r-1, c) != prev:
            neighbors.append((r-1, c))
        # Check down
        if r < N and v[r][c] and (r+1, c) != prev:
            neighbors.append((r+1, c))
        # Check left
        if c >0 and h[r][c-1] and (r, c-1) != prev:
            neighbors.append((r, c-1))
        # Check right
        if c < N and h[r][c] and (r, c+1) != prev:
            neighbors.append((r, c+1))
        if len(neighbors) != 1:
            return None
        next_node = neighbors[0]
        if next_node == start:
            path.append(next_node)
            break
        path.append(next_node)
        prev = current
        current = next_node
    # Verify all edges are covered
    edge_count = 0
    for r in range(N+1):
        edge_count += sum(1 for x in h[r] if x)
    for r in range(N):
        edge_count += sum(1 for x in v[r] if x)
    if len(path)-1 != edge_count:
        return None
    return path

def select_next_edge(h, v, N):
    best_score = -1
    best = None
    # Check horizontal edges first
    for r in range(N+1):
        for c in range(N):
            if h[r][c] is not None:
                continue
            score = 0
            # Count adjacent clues
            if r > 0:
                if c < N and isinstance(hints[r-1][c], int): score +=1
            if r < N:
                if c < N and isinstance(hints[r][c], int): score +=1
            # Count adjacent vertex degrees
            for (vr, vc) in [(r,c), (r, c+1)]:
                cnt = 0
                if vr >0 and v[vr-1][vc] is not None: cnt +=1
                if vr < N and v[vr][vc] is not None: cnt +=1
                if vc >0 and h[vr][vc-1] is not None: cnt +=1
                if vc < N and h[vr][vc] is not None: cnt +=1
                score += cnt
            if score > best_score:
                best_score = score
                best = (0, r, c)
    # Check vertical edges
    for r in range(N):
        for c in range(N+1):
            if v[r][c] is not None:
                continue
            score =0
            if c>0:
                if r < N and isinstance(hints[r][c-1], int): score +=1
            if c < N:
                if r < N and isinstance(hints[r][c], int): score +=1
            for (vr, vc) in [(r,c), (r+1, c)]:
                cnt =0
                if vr>0 and v[vr-1][vc] is not None: cnt +=1
                if vr < N and v[vr][vc] is not None: cnt +=1
                if vc>0 and h[vr][vc-1] is not None: cnt +=1
                if vc < N and h[vr][vc] is not None: cnt +=1
                score += cnt
            if score > best_score:
                best_score = score
                best = (1, r, c)
    return best

hints = None
def backtrack(h, v, N):
    valid, h_new, v_new = propagate(h, v, N, hints)
    if not valid:
        return None
    if is_complete(h_new, v_new, N):
        return extract_loop(h_new, v_new, N)
    edge = select_next_edge(h_new, v_new, N)
    if not edge:
        return None
    typ, er, ec = edge
    # Try True first
    h_try, v_try = deep_copy_edges(h_new, v_new)
    if typ == 0:
        h_try[er][ec] = True
    else:
        v_try[er][ec] = True
    res = backtrack(h_try, v_try, N)
    if res is not None:
        return res
    # Try False
    h_try, v_try = deep_copy_edges(h_new, v_new)
    if typ ==0:
        h_try[er][ec] = False
    else:
        v_try[er][ec] = False
    return backtrack(h_try, v_try, N)

def solve(observation):
    global hints
    hints = observation['data']
    N = len(hints)
    # Initialize edges: h_edges[r][c] = horizontal edge between (r,c) and (r,c+1)
    h_edges = [[None for _ in range(N)] for _ in range(N+1)]
    # v_edges[r][c] = vertical edge between (r,c) and (r+1,c)
    v_edges = [[None for _ in range(N+1)] for _ in range(N)]
    result = backtrack(h_edges, v_edges, N)
    return result if result else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
