DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
OPPOSITE = {0:1, 1:0, 2:3, 3:2}
PERPENDICULAR = {0: [2,3], 1:[2,3], 2:[0,1], 3:[0,1]}

def count_edges(r, c, h_edges, v_edges, N):
    cnt = 0
    edges = []
    if c > 0 and h_edges[r][c-1] is True:
        cnt +=1
        edges.append(2)
    if c < N-1 and h_edges[r][c] is True:
        cnt +=1
        edges.append(3)
    if r > 0 and v_edges[r-1][c] is True:
        cnt +=1
        edges.append(0)
    if r < N-1 and v_edges[r][c] is True:
        cnt +=1
        edges.append(1)
    return cnt, edges

def propagate(h_edges, v_edges, N, required, data):
    h = [row.copy() for row in h_edges]
    v = [row.copy() for row in v_edges]
    changed = True
    while changed:
        changed = False
        for r in range(N):
            for c in range(N):
                cnt, edges = count_edges(r,c,h,v,N)
                if required[r][c]:
                    if cnt > 2:
                        return (False, None, None)
                    if cnt == 2:
                        for d in range(4):
                            if d not in edges:
                                dr, dc = DIRS[d]
                                nr, nc = r + dr, c + dc
                                if 0<=nr<N and 0<=nc<N:
                                    if d in (2,3):
                                        h_col = min(c, nc)
                                        if h[r][h_col] is None:
                                            h[r][h_col] = False
                                            changed = True
                                    else:
                                        v_row = min(r, nr)
                                        if v[v_row][c] is None:
                                            v[v_row][c] = False
                                            changed = True
                    elif cnt == 1:
                        used_d = edges[0]
                        cell_type = data[r][c]
                        possible = []
                        if cell_type == 'W':
                            possible.append(OPPOSITE[used_d])
                        elif cell_type == 'B':
                            possible = PERPENDICULAR[used_d]
                        else:
                            possible = [d for d in range(4) if d != used_d]
                        valid = []
                        for d in possible:
                            dr, dc = DIRS[d]
                            nr, nc = r + dr, c + dc
                            if 0<=nr<N and 0<=nc<N:
                                if d in (2,3):
                                    h_col = min(c, nc)
                                    if h[r][h_col] is not False:
                                        valid.append(d)
                                else:
                                    v_row = min(r, nr)
                                    if v[v_row][c] is not False:
                                        valid.append(d)
                        if len(valid) == 0:
                            return (False, None, None)
                        if len(valid) == 1:
                            d = valid[0]
                            dr, dc = DIRS[d]
                            nr, nc = r + dr, c + dc
                            if d in (2,3):
                                h_col = min(c, nc)
                                if h[r][h_col] is None:
                                    h[r][h_col] = True
                                    changed = True
                            else:
                                v_row = min(r, nr)
                                if v[v_row][c] is None:
                                    v[v_row][c] = True
                                    changed = True
                else:
                    if cnt > 2:
