        if not check_clues(h, v, N, data):
            return (False, None, None)
        if has_small_cycle(h, v, N, required):
            return (False, None, None)
    return (True, h, v)

def check_clues(h_edges, v_edges, N, data):
    for r in range(N):
        for c in range(N):
            t = data[r][c]
            if t is None:
                continue
            cnt, edges = count_edges(r,c,h_edges,v_edges,N)
            if cnt < 2:
                continue
            d1, d2 = edges
            if t == 'W':
                if d2 != OPPOSITE[d1]:
                    return False
                straight_len = 1
                cr, cc = r + DIRS[d1][0], c + DIRS[d1][1]
                pd = d1
                while 0<=cr<N and 0<=cc<N:
                    cnt_e, edg_e = count_edges(cr, cc, h_edges, v_edges, N)
                    if cnt_e != 2:
                        break
                    od = OPPOSITE[pd]
                    nd = edg_e[0] if edg_e[1] == od else edg_e[1]
                    if nd == OPPOSITE[pd]:
                        straight_len +=1
                        pd = nd
                        cr += DIRS[nd][0]
                        cc += DIRS[nd][1]
                    else:
                        break
                other_straight = 1
                cr, cc = r + DIRS[d2][0], c + DIRS[d2][1]
                pd = d2
                while 0<=cr<N and 0<=cc<N:
                    cnt_e, edg_e = count_edges(cr, cc, h_edges, v_edges, N)
                    if cnt_e != 2:
                        break
                    od = OPPOSITE[pd]
                    nd = edg_e[0] if edg_e[1] == od else edg_e[1]
                    if nd == OPPOSITE[pd]:
                        other_straight +=1
                        pd = nd
                        cr += DIRS[nd][0]
                        cc += DIRS[nd][1]
                    else:
                        break
                if straight_len >=2 and other_straight >=2:
                    return False
            elif t == 'B':
                if d2 not in PERPENDICULAR[d1]:
                    return False
                for d in edges:
                    straight_len = 1
                    cr, cc = r + DIRS[d][0], c + DIRS[d][1]
                    pd = d
                    while 0<=cr<N and 0<=cc<N:
                        cnt_e, edg_e = count_edges(cr, cc, h_edges, v_edges, N)
                        if cnt_e != 2:
                            break
                        od = OPPOSITE[pd]
                        nd = edg_e[0] if edg_e[1] == od else edg_e[1]
                        if nd == OPPOSITE[pd]:
                            straight_len +=1
                            pd = nd
                            cr += DIRS[nd][0]
                            cc += DIRS[nd][1]
                        else:
                            break
                    if straight_len < 2:
                        return False
    return True

def has_small_cycle(h_edges, v_edges, N, required):
    visited = [[False for _ in range(N)] for __ in range(N)]
    total_required = sum(sum(1 for c in row if c) for row in required)
    for r in range(N):
        for c in range(N):
            if not visited[r][c]:
                cnt, edges = count_edges(r,c,h_edges,v_edges,N)
                if cnt != 2:
                    continue
                path = []
                cr, cc = r, c
                pd = None
                while True:
                    if visited[cr][cc]:
                        if (cr, cc) == (r,c) and len(path) > 0:
                            req_in_cycle = sum(1 for (x,y) in path if required[x][y])
                            if req_in_cycle < total_required:
                                return True
                        break
                    visited[cr][cc] = True
                    path.append((cr, cc))
                    cnt_e, edges_e = count_edges(cr, cc, h_edges, v_edges, N)
                    if cnt_e != 2:
                        break
                    if pd is None:
                        nd = edges_e[0]
                    else:
                        od = OPPOSITE[pd]
                        nd = edges_e[0] if edges_e[1] == od else edges_e[1]
                    pd = nd
                    cr += DIRS[nd][0]
                    cc += DIRS[nd][1]
    return False

def is_complete(h_edges, v_edges, N, required):
    for r in range(N):
        for c in range(N-1):
            if h_edges[r][c] is None:
                return False
    for r in range(N-1):
        for c in range(N):
            if v_edges[r][c] is None:
                return False
    for r in range(N):
        for c in range(N):
            if required[r][c]:
                cnt, _ = count_edges(r,c,h_edges,v_edges,N)
                if cnt != 2:
                    return False
            else:
                cnt, _ = count_edges(r,c,h_edges,v_edges,N)
                if cnt not in (0,2):
                    return False
    if has_small_cycle(h_edges, v_edges, N, required):
        return False
    return True

def traverse_loop(h_edges, v_edges, N):
    start = None
    for r in range(N):
        for c in range(N):
            cnt, _ = count_edges(r,c,h_edges,v_edges,N)
            if cnt == 2:
                start = (r,c)
                break
        if start:
            break
    path = [start]
    cr, cc = start
    pd = None
    while True:
        cnt_e, edges_e = count_edges(cr, cc, h_edges, v_edges, N)
        if pd is None:
            nd = edges_e[0]
        else:
            od = OPPOSITE[pd]
            nd = edges_e[0] if edges_e[1] == od else edges_e[1]
        pd = nd
        cr += DIRS[nd][0]
        cc += DIRS[nd][1]
        if (cr, cc) == start:
            path.append((cr, cc))
            break
        path.append((cr, cc))
    return path

def select_next_edge(h_edges, v_edges, N):
    min_options = float('inf')
    best = None
    for r in range(N):
        for c in range(N-1):
            if h_edges[r][c] is None:
                cnt_r, _ = count_edges(r,c,h_edges,v_edges,N)
                cnt_r1, _ = count_edges(r,c+1,h_edges,v_edges,N)
                score = cnt_r + cnt_r1
                if score < min_options:
                    min_options = score
                    best = ('h', r, c)
    for r in range(N-1):
        for c in range(N):
            if v_edges[r][c] is None:
                cnt_r, _ = count_edges(r,c,h_edges,v_edges,N)
                cnt_r1, _ = count_edges(r+1,c,h_edges,v_edges,N)
                score = cnt_r + cnt_r1
                if score < min_options:
                    min_options = score
                    best = ('v', r, c)
    return best

def backtrack(h_edges, v_edges, N, required, data):
    valid, h, v = propagate(h_edges, v_edges, N, required, data)
    if not valid:
        return None
    if is_complete(h, v, N, required):
        return traverse_loop(h, v, N)
    edge = select_next_edge(h, v, N)
    if edge is None:
        return None
    typ, r, c = edge
    for val in [True, False]:
        new_h = [row.copy() for row in h]
        new_v = [row.copy() for row in v]
        if typ == 'h':
            new_h[r][c] = val
        else:
            new_v[r][c] = val
        res = backtrack(new_h, new_v, N, required, data)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    required = [[data[r][c] is not None for c in range(N)] for r in range(N)]
    h_edges = [[None for _ in range(N-1)] for __ in range(N)]
    v_edges = [[None for _ in range(N)] for __ in range(N-1)]
    res = backtrack(h_edges, v_edges, N, required, data)
    return res if res else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
