                possible = []
                for e in adj:
                    if e not in edges and e not in forbidden_edges:
                        possible.append(e)
                if not possible:
                    return None
                if len(possible) == 1:
                    e = possible[0]
                    edges.add(e)
                    changed = True
    return (edges, forbidden_edges)

def is_option_compatible(option, edges, forbidden_edges):
    for e in option['edges']:
        if e in forbidden_edges:
            return False
    dot_cnt = {}
    for e in edges:
        a, b = e
        dot_cnt[a] = dot_cnt.get(a, 0) + 1
        dot_cnt[b] = dot_cnt.get(b, 0) + 1
    for e in option['edges']:
        a, b = e
        dot_cnt[a] = dot_cnt.get(a, 0) + 1
        dot_cnt[b] = dot_cnt.get(b, 0) + 1
        if dot_cnt[a] > 2 or dot_cnt[b] > 2:
            return False
    for e in option['forbidden']:
        if e in edges:
            return False
    return True

def get_valid_options(clue, n, edges, forbidden_edges):
    r, c, t, k = clue
    UP, DOWN, LEFT, RIGHT = (-1,0), (1,0), (0,-1), (0,1)
    opposite = {UP:DOWN, DOWN:UP, LEFT:RIGHT, RIGHT:LEFT}
    perpendicular = {UP: [LEFT, RIGHT], DOWN: [LEFT, RIGHT], LEFT: [UP, DOWN], RIGHT: [UP, DOWN]}
    options = []

    if t == 'W':
        d1, d2 = UP, DOWN
        for l1 in range(1, k):
            l2 = k - l1
            if l2 < 1: continue
            if r - l1 < 0 or r + l2 >= n: continue
            opt_edges = set()
            cr, cc = r, c
            for _ in range(l1):
                nr, nc = cr + d1[0], cc + d1[1]
                opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                cr, cc = nr, nc
            cr, cc = r, c
            for _ in range(l2):
                nr, nc = cr + d2[0], cc + d2[1]
                opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                cr, cc = nr, nc
            opt_forbidden = set()
            if c > 0: opt_forbidden.add(frozenset({(r,c), (r,c-1)}))
            if c < n-1: opt_forbidden.add(frozenset({(r,c), (r,c+1)}))
            options.append({'edges': opt_edges, 'forbidden': opt_forbidden})

        d1, d2 = LEFT, RIGHT
        for l1 in range(1, k):
            l2 = k - l1
            if l2 < 1: continue
            if c - l1 < 0 or c + l2 >= n: continue
            opt_edges = set()
            cr, cc = r, c
            for _ in range(l1):
                nr, nc = cr + d1[0], cc + d1[1]
                opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                cr, cc = nr, nc
            cr, cc = r, c
            for _ in range(l2):
                nr, nc = cr + d2[0], cc + d2[1]
                opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                cr, cc = nr, nc
            opt_forbidden = set()
            if r > 0: opt_forbidden.add(frozenset({(r,c), (r-1,c)}))
            if r < n-1: opt_forbidden.add(frozenset({(r,c), (r+1,c)}))
            options.append({'edges': opt_edges, 'forbidden': opt_forbidden})
    else:
        dirs = [UP, DOWN, LEFT, RIGHT]
        for d1 in dirs:
            for d2 in perpendicular[d1]:
                for l1 in range(1, k):
                    l2 = k - l1
                    if l2 < 1: continue
                    e1r, e1c = r + l1*d1[0], c + l1*d1[1]
                    e2r, e2c = r + l2*d2[0], c + l2*d2[1]
                    if e1r <0 or e1r >=n or e1c <0 or e1c >=n: continue
                    if e2r <0 or e2r >=n or e2c <0 or e2c >=n: continue
                    opt_edges = set()
                    cr, cc = r, c
                    for _ in range(l1):
                        nr, nc = cr + d1[0], cc + d1[1]
                        opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                        cr, cc = nr, nc
                    cr, cc = r, c
                    for _ in range(l2):
                        nr, nc = cr + d2[0], cc + d2[1]
                        opt_edges.add(frozenset({(cr, cc), (nr, nc)}))
                        cr, cc = nr, nc
                    opt_forbidden = set()
                    od1, od2 = opposite[d1], opposite[d2]
                    od1r, od1c = r + od1[0], c + od1[1]
                    if 0<=od1r <n and 0<=od1c <n: opt_forbidden.add(frozenset({(r,c), (od1r, od1c)}))
                    od2r, od2c = r + od2[0], c + od2[1]
                    if 0<=od2r <n and 0<=od2c <n: opt_forbidden.add(frozenset({(r,c), (od2r, od2c)}))
                    options.append({'edges': opt_edges, 'forbidden': opt_forbidden})

    unique_opts = []
    seen = set()
    for opt in options:
        key = frozenset(opt['edges']) | frozenset(opt['forbidden'])
        if key not in seen:
            seen.add(key)
            unique_opts.append(opt)
    valid_opts = [o for o in unique_opts if is_option_compatible(o, edges, forbidden_edges)]
    return valid_opts

def is_valid_loop(edges, n):
    if not edges:
        return False
    dot_cnt = {}
    for e in edges:
        a,b = e
        dot_cnt[a] = dot_cnt.get(a,0)+1
        dot_cnt[b] = dot_cnt.get(b,0)+1
    for cnt in dot_cnt.values():
        if cnt != 2:
            return False
    start = next(iter(dot_cnt.keys()))
    visited = set()
    current, prev = start, None
    while current not in visited:
        visited.add(current)
        for e in edges:
            if current in e:
                a,b = e
                other = a if b == current else b
                if other != prev:
                    prev, current = current, other
                    break
    return len(visited) == len(dot_cnt) and current == start

def get_loop_path(edges):
    start = next(iter(next(iter(edges))))
    path = [start]
    current, prev = start, None
    while True:
        for e in edges:
            if current in e:
                a,b = e
                other = a if b == current else b
                if other != prev:
                    prev, current = current, other
                    path.append(current)
                    break
        if current == start:
            break
    return path

def connect_open_ends(edges, forbidden_edges, n):
    dot_cnt = {}
    for e in edges:
        a,b = e
        dot_cnt[a] = dot_cnt.get(a,0)+1
        dot_cnt[b] = dot_cnt.get(b,0)+1
    open_ends = [d for d,c in dot_cnt.items() if c == 1]
    if len(open_ends) == 0:
        return get_loop_path(edges) if is_valid_loop(edges, n) else None
    if len(open_ends) != 2:
        return None
    start, end = open_ends

    def dfs(current, prev, path_edges):
        if current == end:
            total = edges.union(path_edges)
            return total if is_valid_loop(total, n) else None
        r,c = current
        adj = []
        if r>0: adj.append((r-1,c))
        if r <n-1: adj.append((r+1,c))
        if c>0: adj.append((r,c-1))
        if c <n-1: adj.append((r,c+1))
        for neighbor in adj:
            e = frozenset({current, neighbor})
            if e in edges or e in forbidden_edges or neighbor == prev:
                continue
            if dot_cnt.get(neighbor, 0) + (0 if neighbor in (start, end) else 1) > 2:
                continue
            path_edges.add(e)
            res = dfs(neighbor, current, path_edges)
            if res:
                return res
            path_edges.remove(e)
        return None

    res_edges = dfs(start, None, set())
    return get_loop_path(res_edges) if res_edges else None

def backtrack(remaining_clues, edges, forbidden_edges, n):
    prop = propagate(edges.copy(), forbidden_edges.copy(), n)
    if not prop:
        return None
    edges, forbidden_edges = prop
    if not remaining_clues:
        return connect_open_ends(edges, forbidden_edges, n)
    clue_opts = []
    for clue in remaining_clues:
        opts = get_valid_options(clue, n, edges, forbidden_edges)
        if not opts:
            return None
        clue_opts.append((len(opts), clue, opts))
    clue_opts.sort()
    min_len, selected, opts = clue_opts[0]
    new_remaining = [c for c in remaining_clues if c != selected]
    for opt in opts:
        new_e = edges.union(opt['edges'])
        new_f = forbidden_edges.union(opt['forbidden'])
        res = backtrack(new_remaining, new_e, new_f, n)
        if res:
            return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    clues = get_clues(data)
    res = backtrack(clues, set(), set(), n)
    return res if res else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
