def solve(observation):
    data = observation['data']
    N = len(data)
    # Edge representation: h_edges[r][c] = edge between (r,c) and (r,c+1), 0=no, 1=yes, 2=unknown
    h_edges = [[2]*(N) for _ in range(N+1)]
    # v_edges[r][c] = edge between (r,c) and (r+1,c)
    v_edges = [[2]*(N+1) for _ in range(N)]

    def copy_state():
        return [row[:] for row in h_edges], [row[:] for row in v_edges]

    def propagate():
        changed = True
        while changed:
            changed = False
            # Process cell constraints
            for i in range(N):
                for j in range(N):
                    clue = data[i][j]
                    if clue is None:
                        continue
                    edges = [
                        ('h', i, j),
                        ('h', i+1, j),
                        ('v', i, j),
                        ('v', i, j+1)
                    ]
                    cnt1 = 0
                    cnt2 = 0
                    unknowns = []
                    for typ, r, c in edges:
                        val = h_edges[r][c] if typ == 'h' else v_edges[r][c]
                        if val == 1:
                            cnt1 += 1
                        elif val == 2:
                            cnt2 +=1
                            unknowns.append((typ, r, c))
                    req = clue - cnt1
                    if req < 0 or req > cnt2:
                        return False
                    if req == 0:
                        for typ, r, c in unknowns:
                            if typ == 'h':
                                if h_edges[r][c] == 2:
                                    h_edges[r][c] = 0
                                    changed = True
                            else:
                                if v_edges[r][c] == 2:
                                    v_edges[r][c] = 0
                                    changed = True
                    if req == cnt2:
                        for typ, r, c in unknowns:
                            if typ == 'h':
                                if h_edges[r][c] == 2:
                                    h_edges[r][c] = 1
                                    changed = True
                            else:
                                if v_edges[r][c] == 2:
                                    v_edges[r][c] = 1
                                    changed = True
            # Process dot degree constraints
            for r in range(N+1):
                for c in range(N+1):
                    deg1 = 0
                    deg2 = 0
                    unknowns = []
                    # up edge
                    if r > 0:
                        val = v_edges[r-1][c]
                        if val == 1:
                            deg1 +=1
                        elif val == 2:
                            deg2 +=1
                            unknowns.append(('v', r-1, c))
                    # down edge
                    if r < N:
                        val = v_edges[r][c]
                        if val ==1:
                            deg1 +=1
                        elif val ==2:
                            deg2 +=1
                            unknowns.append(('v', r, c))
                    # left edge
                    if c > 0:
                        val = h_edges[r][c-1]
                        if val ==1:
                            deg1 +=1
                        elif val ==2:
                            deg2 +=1
                            unknowns.append(('h', r, c-1))
                    # right edge
                    if c < N:
                        val = h_edges[r][c]
                        if val ==1:
                            deg1 +=1
                        elif val ==2:
                            deg2 +=1
                            unknowns.append(('h', r, c))
                    if deg1 > 2:
                        return False
                    if deg1 + deg2 < 2:
                        return False
                    if deg1 == 2:
                        for typ, rr, cc in unknowns:
                            if typ == 'h':
                                if h_edges[rr][cc] == 2:
                                    h_edges[rr][cc] = 0
                                    changed = True
                            else:
                                if v_edges[rr][cc] == 2:
                                    v_edges[rr][cc] = 0
                                    changed = True
                    if deg1 == 1 and deg2 == 1:
                        typ, rr, cc = unknowns[0]
                        if typ == 'h':
                            if h_edges[rr][cc] == 2:
                                h_edges[rr][cc] = 1
                                changed = True
                        else:
                            if v_edges[rr][cc] == 2:
                                v_edges[rr][cc] = 1
                                changed = True
        return True

    def is_complete():
        for row in h_edges:
            if 2 in row:
                return False
        for row in v_edges:
            if 2 in row:
                return False
        return True

    def is_valid_loop():
        # Find start point
        start = None
        for r in range(N+1):
            for c in range(N+1):
                deg = 0
                if r>0 and v_edges[r-1][c] ==1: deg +=1
                if r<N and v_edges[r][c] ==1: deg +=1
                if c>0 and h_edges[r][c-1] ==1: deg +=1
                if c<N and h_edges[r][c] ==1: deg +=1
                if deg == 2:
                    start = (r,c)
                    break
            if start:
                break
        if not start:
            return False
        path = []
        visited = set()
        current = start
        prev = None
        while True:
            path.append(current)
            visited.add(current)
            r,c = current
            neighbors = []
            if r>0 and v_edges[r-1][c] ==1:
                neighbors.append((r-1,c))
            if r<N and v_edges[r][c] ==1:
                neighbors.append((r+1,c))
            if c>0 and h_edges[r][c-1] ==1:
                neighbors.append((r,c-1))
            if c<N and h_edges[r][c] ==1:
                neighbors.append((r,c+1))
            if len(neighbors) != 2:
                return False
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            if next_node == start:
                path.append(start)
                break
            prev = current
            current = next_node
        # Check all edges are visited
        edge_count = 0
        for row in h_edges:
            edge_count += sum(1 for x in row if x ==1)
        for row in v_edges:
            edge_count += sum(1 for x in row if x ==1)
        if len(path)-1 != edge_count:
            return False
        return path

    def backtrack():
        nonlocal h_edges, v_edges
        if not propagate():
            return None
        if is_complete():
            path = is_valid_loop()
            if path:
                return path
            return None
        # Pick next edge to branch
        min_unknown = 999
        candidate = None
        for i in range(N):
            for j in range(N):
                clue = data[i][j]
                if clue is None:
                    continue
                edges = [('h',i,j), ('h',i+1,j), ('v',i,j), ('v',i,j+1)]
                cnt2 = 0
                unk = None
                for typ, r, c in edges:
                    val = h_edges[r][c] if typ == 'h' else v_edges[r][c]
                    if val == 2:
                        cnt2 +=1
                        unk = (typ, r, c)
                if cnt2 > 0 and cnt2 < min_unknown:
                    min_unknown = cnt2
                    candidate = unk
                    if min_unknown == 1:
                        break
            if min_unknown == 1:
                break
        if not candidate:
            # If no clue based candidate, pick any unknown edge
            for r in range(N+1):
                for c in range(N):
                    if h_edges[r][c] == 2:
                        candidate = ('h', r, c)
                        break
                if candidate:
                    break
            if not candidate:
                for r in range(N):
                    for c in range(N+1):
                        if v_edges[r][c] == 2:
                            candidate = ('v', r, c)
                            break
                    if candidate:
                        break
        typ, r, c = candidate
        # Try set to 1 first
        old_h, old_v = copy_state()
        if typ == 'h':
            h_edges[r][c] = 1
        else:
            v_edges[r][c] = 1
        res = backtrack()
        if res:
            return res
        # Revert
        h_edges, v_edges = old_h, old_v
        # Try set to 0
        if typ == 'h':
            h_edges[r][c] = 0
        else:
            v_edges[r][c] = 0
        res = backtrack()
        if res:
            return res
        # Revert
        h_edges, v_edges = old_h, old_v
        return None

    result = backtrack()
    return result if result else "No Solution"

