def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Step 1: Map regions to their cells and compute adjacency list
    region_cells = dict()
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            if rid not in region_cells:
                region_cells[rid] = set()
            region_cells[rid].add((r, c))

    adj = {rid: set() for rid in region_cells}
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    nrid = grid[nr][nc]
                    if nrid != rid:
                        adj[rid].add(nrid)

    # Step 2: Generate all valid candidates for each region
    candidates = {rid: [] for rid in region_cells}
    for rid in region_cells:
        cells = region_cells[rid]
        seen = set()
        for (r, c) in cells:
            for t, shape in TETROMINOES:
                points = []
                valid = True
                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) not in cells:
                        valid = False
                        break
                    points.append((nr, nc))
                if valid:
                    fp = frozenset(points)
                    if fp not in seen:
                        seen.add(fp)
                        candidates[rid].append((t, set(points)))

    # Step 3: Backtracking search with most constrained first heuristic
    def backtrack(assigned, shaded):
        if len(assigned) == len(region_cells):
            # Build result grid
            res = [[None]*N for _ in range(N)]
            for rid in assigned:
                t, cells = assigned[rid]
                for (r, c) in cells:
                    res[r][c] = t
            return res

        # Pick unassigned region with smallest candidate count
        unassigned = []
        for rid in region_cells:
            if rid not in assigned:
                # Filter valid candidates for this rid
                valid_cands = []
                for t, cells in candidates[rid]:
                    # Check no adjacent same type
                    ok = True
                    for nrid in adj[rid]:
                        if nrid in assigned and assigned[nrid][0] == t:
                            ok = False
                            break
                    if ok:
                        valid_cands.append((t, cells))
                if not valid_cands:
                    return None
                unassigned.append((len(valid_cands), rid, valid_cands))
        unassigned.sort()
        _, rid, valid_cands = unassigned[0]

        # Try each candidate
        for t, cells in valid_cands:
            # Check 2x2 block rule
            has_2x2 = False
            for (r, c) in cells:
                for dr in (-1, 0):
                    for dc in (-1, 0):
                        r1, r2 = r + dr, r + dr + 1
                        c1, c2 = c + dc, c + dc + 1
                        if 0 <= r1 < N and 0 <= r2 < N and 0 <= c1 < N and 0 <= c2 < N:
                            if all((p in shaded or p in cells) for p in [(r1,c1), (r1,c2), (r2,c1), (r2,c2)]):
                                has_2x2 = True
                                break
                    if has_2x2:
                        break
                if has_2x2:
                    break
            if has_2x2:
                continue

            # Check connectivity
            if shaded:
                connected = False
                for (r, c) in cells:
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if (nr, nc) in shaded:
                            connected = True
                            break
                    if connected:
                        break
                if not connected:
                    continue

            # Proceed recursion
            new_assigned = assigned.copy()
            new_assigned[rid] = (t, cells)
            new_shaded = shaded.union(cells)
            res = backtrack(new_assigned, new_shaded)
            if res is not None:
                return res

        return None

    result = backtrack(dict(), set())
    return result if result else "No Solution"

