    # Edge representations: h_edges[r][c] = between (r,c) and (r,c+1), size (N+1)xN
    h_edges = [[None for _ in range(N)] for _ in range(N+1)]
    # v_edges[r][c] = between (r,c) and (r+1,c), size Nx(N+1)
    v_edges = [[None for _ in range(N+1)] for _ in range(N)]

    def get_cell_edges(r, c):
        # Return 4 edges of cell (r,c): top, right, bottom, left
        return [
            ('h', r, c),
            ('v', r, c+1),
            ('h', r+1, c),
            ('v', r, c)
        ]

    def get_dot_edges(r, c):
        # Return all edges connected to dot (r,c)
        edges = []
        if c > 0:
            edges.append(('h', r, c-1))
        if c < N:
            edges.append(('h', r, c))
        if r > 0:
            edges.append(('v', r-1, c))
        if r < N:
            edges.append(('v', r, c))
        return edges

    def set_edge(edge_type, r, c, val):
        if edge_type == 'h':
            if h_edges[r][c] == val:
                return True
            if h_edges[r][c] is not None:
                return False
            h_edges[r][c] = val
        else:
            if v_edges[r][c] == val:
                return True
            if v_edges[r][c] is not None:
                return False
            v_edges[r][c] = val
        return True

    def get_edge(edge_type, r, c):
        if edge_type == 'h':
            return h_edges[r][c]
        else:
            return v_edges[r][c]

    def propagate():
        changed = True
        while changed:
            changed = False
            # Process cell clues first
            for r in range(N):
                for c in range(N):
                    clue = data[r][c]
                    if clue is None:
                        continue
                    edges = get_cell_edges(r, c)
                    present = 0
                    absent = 0
                    unknown = []
                    for et, er, ec in edges:
                        val = get_edge(et, er, ec)
                        if val is True:
                            present += 1
                        elif val is False:
                            absent +=1
                        else:
                            unknown.append((et, er, ec))
                    if present > clue:
                        return False
                    if (clue - present) > len(unknown):
                        return False
                    if present == clue:
                        for et, er, ec in unknown:
                            if not set_edge(et, er, ec, False):
                                return False
                            changed = True
                    if (clue - present) == len(unknown):
                        for et, er, ec in unknown:
                            if not set_edge(et, er, ec, True):
                                return False
                            changed = True
            # Process dot degree constraints
            for r in range(N+1):
                for c in range(N+1):
                    edges = get_dot_edges(r, c)
                    present = 0
                    absent =0
                    unknown = []
                    for et, er, ec in edges:
                        val = get_edge(et, er, ec)
                        if val is True:
                            present +=1
                        elif val is False:
                            absent +=1
                        else:
                            unknown.append((et, er, ec))
                    if present > 2:
                        return False
                    if (2 - present) > len(unknown):
                        return False
                    if present == 2:
                        for et, er, ec in unknown:
                            if not set_edge(et, er, ec, False):
                                return False
                            changed = True
                    if (2 - present) == len(unknown):
                        for et, er, ec in unknown:
                            if not set_edge(et, er, ec, True):
                                return False
                            changed = True
        return True

    def count_unknowns():
        cnt =0
        for r in range(N+1):
            for c in range(N):
                if h_edges[r][c] is None:
                    cnt +=1
        for r in range(N):
            for c in range(N+1):
                if v_edges[r][c] is None:
                    cnt +=1
        return cnt

    def get_next_edge():
        # Pick unknown edge with most constraints (adjacent to clues/dots with high present count)
        best_score = -1
        best_edge = None
        for r in range(N+1):
            for c in range(N):
                if h_edges[r][c] is None:
                    score = 0
                    # Check adjacent cells
                    if r < N:
                        cl = data[r][c]
                        if cl is not None:
                            score += cl
                    if r > 0:
                        cl = data[r-1][c]
                        if cl is not None:
                            score += cl
                    # Check dots
                    for (dr, dc) in [(0,0), (0,1)]:
                        edges = get_dot_edges(r+dr, c+dc)
                        p = 0
                        for et, er, ec in edges:
                            if get_edge(et, er, ec) is True:
                                p +=1
                        score += p*2
                    if score > best_score:
                        best_score = score
                        best_edge = ('h', r, c)
        for r in range(N):
            for c in range(N+1):
                if v_edges[r][c] is None:
                    score =0
                    if c < N:
                        cl = data[r][c]
                        if cl is not None:
                            score += cl
                    if c > 0:
                        cl = data[r][c-1]
                        if cl is not None:
                            score += cl
                    for (dr, dc) in [(0,0), (1,0)]:
                        edges = get_dot_edges(r+dr, c+dc)
                        p=0
                        for et, er, ec in edges:
                            if get_edge(et, er, ec) is True:
                                p +=1
                        score += p*2
                    if score > best_score:
                        best_score = score
                        best_edge = ('v', r, c)
        return best_edge

    def backtrack():
        if not propagate():
            return None
        if count_unknowns() == 0:
            return build_loop()
        et, er, ec = get_next_edge()
        # Try True first
        set_edge(et, er, ec, True)
        res = backtrack()
        if res is not None:
            return res
        # Backtrack
        set_edge(et, er, ec, None)
        # Try False
        set_edge(et, er, ec, False)
        res = backtrack()
        if res is not None:
            return res
        # Backtrack
        set_edge(et, er, ec, None)
        return None

    def build_loop():
        # Find start dot
        start = None
        for r in range(N+1):
            for c in range(N+1):
                edges = get_dot_edges(r,c)
                p = 0
                for et, er, ec in edges:
                    if get_edge(et, er, ec) is True:
                        p +=1
                if p == 2:
                    start = (r,c)
                    break
            if start is not None:
                break
        if start is None:
            return None
        path = [start]
        prev = None
        current = start
        while True:
            # Find next dot
            edges = get_dot_edges(current[0], current[1])
            next_dot = None
            for et, er, ec in edges:
                if get_edge(et, er, ec) is True:
                    if et == 'h':
                        d1 = (er, ec)
                        d2 = (er, ec+1)
                    else:
                        d1 = (er, ec)
                        d2 = (er+1, ec)
                    if d1 == prev:
                        next_dot = d2
                        break
                    if d2 == prev:
                        next_dot = d1
                        break
            if next_dot is None:
                return None
            if next_dot == start:
                path.append(next_dot)
                break
            path.append(next_dot)
            prev = current
            current = next_dot
        # Verify all edges are included
        edge_count = 0
        for r in range(N+1):
            for c in range(N):
                if h_edges[r][c] is True:
                    edge_count +=1
        for r in range(N):
            for c in range(N+1):
                if v_edges[r][c] is True:
                    edge_count +=1
        if len(path)-1 != edge_count:
            return None
        return path

    res = backtrack()
    return res if res is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
