from collections import defaultdict

def solve(observation):
    data = observation['data']
    N = len(data)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Precompute region cells
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[data[r][c]].append((r,c))
    all_regions = list(region_cells.keys())

    def is_valid(r, c):
        return 0 <= r < N and 0 <= c < N

    def propagate(grid, region_counts):
        changed = True
        while changed:
            changed = False
            # Rule 1: Regions with 2 S, mark rest as X
            for reg in all_regions:
                cnt = region_counts[reg]
                if cnt == 2:
                    for (r,c) in region_cells[reg]:
                        if grid[r][c] is None:
                            grid[r][c] = 'X'
                            changed = True
            # Find all S cells
            s_cells = [(r,c) for r in range(N) for c in range(N) if grid[r][c] == 'S']
            # Check for S with too many neighbors
            for (r,c) in s_cells:
                s_neighbors = []
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if is_valid(nr, nc) and grid[nr][nc] == 'S':
                        s_neighbors.append((nr, nc))
                if len(s_neighbors) > 1:
                    return False
                # If S has no partner yet, find possible partners
                if len(s_neighbors) == 0:
                    possible = []
                    for dr, dc in dirs:
                        nr, nc = r+dr, c+dc
                        if is_valid(nr, nc) and grid[nr][nc] != 'X' and region_counts[data[nr][nc]] < 2:
                            possible.append((nr, nc))
                    if len(possible) == 0:
                        return False
                    if len(possible) == 1:
                        nr, nc = possible[0]
                        grid[nr][nc] = 'S'
                        region_counts[data[nr][nc]] += 1
                        changed = True
                        # Mark all adjacent cells except partner as X
                        for (sr, sc) in [(r,c), (nr, nc)]:
                            for dr2, dc2 in dirs:
                                nnr, nnc = sr + dr2, sc + dc2
                                if is_valid(nnr, nnc) and (nnr, nnc) not in [(r,c), (nr, nc)] and grid[nnr][nnc] != 'S':
                                    if grid[nnr][nnc] is None:
                                        grid[nnr][nnc] = 'X'
                                        changed = True
            # Check regions that need exactly k more S, have exactly k available cells
            for reg in all_regions:
                needed = 2 - region_counts[reg]
                if needed <= 0:
                    continue
                available = []
                for (r,c) in region_cells[reg]:
                    if grid[r][c] is None:
                        available.append((r,c))
                if len(available) < needed:
                    return False
                if len(available) == needed:
                    # Need to place S here, check if they can form valid dominoes
                    for (r,c) in available:
                        if grid[r][c] is None:
                            grid[r][c] = 'S'
                            region_counts[reg] += 1
                            changed = True
            # Check if any domino adjacent to other S
            s_set = set(s_cells)
            for (r,c) in s_cells:
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if is_valid(nr, nc) and grid[nr][nc] == 'S':
                        partner = (nr, nc)
                        break
                else:
                    partner = None
                if partner:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if is_valid(nr, nc) and (nr, nc) != partner and grid[nr][nc] == 'S':
                            return False
                        if is_valid(nr, nc) and (nr, nc) != partner and grid[nr][nc] is None:
                            grid[nr][nc] = 'X'
                            changed = True
                    for dr, dc in dirs:
                        nr, nc = partner[0] + dr, partner[1] + dc
                        if is_valid(nr, nc) and (nr, nc) != (r,c) and grid[nr][nc] == 'S':
                            return False
                        if is_valid(nr, nc) and (nr, nc) != (r,c) and grid[nr][nc] is None:
                            grid[nr][nc] = 'X'
                            changed = True
        # Final validity check
        for reg in all_regions:
            if region_counts[reg] > 2:
                return False
        return True

    def backtrack(grid, region_counts):
        # Propagate constraints first
        valid = propagate(grid, region_counts)
        if not valid:
            return None
        # Check if all regions are filled
        complete = True
        for reg in all_regions:
            if region_counts[reg] != 2:
                complete = False
                break
        if complete:
            # Check all S have exactly one partner
            s_cells = [(r,c) for r in range(N) for c in range(N) if grid[r][c] == 'S']
            visited = set()
            for (r,c) in s_cells:
                if (r,c) in visited:
                    continue
                cnt = 0
                partner = None
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if is_valid(nr, nc) and grid[nr][nc] == 'S':
                        cnt += 1
                        partner = (nr, nc)
                if cnt != 1:
                    return None
                visited.add((r,c))
                visited.add(partner)
            # Convert to output format
            res = []
            for r in range(N):
                row = []
                for c in range(N):
                    row.append('S' if grid[r][c] == 'S' else None)
                res.append(row)
            return res
        # Find MRV cell
        min_options = float('inf')
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    # Count possible options: can we place S here?
                    options = 0
                    # Option 1: place X
                    options +=1
                    # Option 2: place S, check if possible
                    if region_counts[data[r][c]] < 2:
                        has_possible_partner = False
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if is_valid(nr, nc) and grid[nr][nc] != 'X' and region_counts[data[nr][nc]] < 2:
                                has_possible_partner = True
                                break
                        if has_possible_partner:
                            options +=1
                    if options < min_options:
                        min_options = options
                        best_cell = (r,c)
        if best_cell is None:
            return None
        r, c = best_cell
        # Try placing S first
        if region_counts[data[r][c]] < 2:
            new_grid = [row.copy() for row in grid]
            new_counts = region_counts.copy()
            new_grid[r][c] = 'S'
            new_counts[data[r][c]] += 1
            res = backtrack(new_grid, new_counts)
            if res is not None:
                return res
        # Try placing X
        new_grid = [row.copy() for row in grid]
        new_counts = region_counts.copy()
        new_grid[r][c] = 'X'
        res = backtrack(new_grid, new_counts)
        return res

    # Initial state
    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    initial_counts = defaultdict(int)
    solution = backtrack(initial_grid, initial_counts)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
