OBSERVATION = {'row_sum': [15, 15, 7, 12, 14, 12], 'col_sum': [2, 13, 7, 11, 11, 18]}

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    m = len(row_sum)
    n = len(col_sum)
    row_weights = list(range(1, m + 1))
    col_weights = list(range(1, n + 1))

    # Internal grid state: None = unassigned, 'B' = black, 'N' = non-black
    grid = [[None for _ in range(n)] for _ in range(m)]

    def get_remaining_row_sums(current_grid):
        rem = []
        for i in range(m):
            used = sum(col_weights[j] for j in range(n) if current_grid[i][j] == 'B')
            rem.append(row_sum[i] - used)
        return rem

    def get_remaining_col_sums(current_grid):
        rem = []
        for j in range(n):
            used = sum(row_weights[i] for i in range(m) if current_grid[i][j] == 'B')
            rem.append(col_sum[j] - used)
        return rem

    def is_state_valid(current_grid):
        rem_r = get_remaining_row_sums(current_grid)
        rem_c = get_remaining_col_sums(current_grid)

        # Check for negative remaining sums
        if any(r < 0 for r in rem_r) or any(c < 0 for c in rem_c):
            return False

        # Validate row possible sum ranges
        for i in range(m):
            unassigned_w = [col_weights[j] for j in range(n) if current_grid[i][j] is None]
            max_possible = sum(unassigned_w)
            if rem_r[i] > max_possible:
                return False

        # Validate column possible sum ranges
        for j in range(n):
            unassigned_w = [row_weights[i] for i in range(m) if current_grid[i][j] is None]
            max_possible = sum(unassigned_w)
            if rem_c[j] > max_possible:
                return False
        return True

    def apply_forced_assignments(current_grid):
        changed = True
        while changed:
            changed = False
            rem_r = get_remaining_row_sums(current_grid)
            rem_c = get_remaining_col_sums(current_grid)

            # Process rows for forced cells
            for i in range(m):
                unassigned_cols = [j for j in range(n) if current_grid[i][j] is None]
                if not unassigned_cols:
                    continue
                total_unassigned_sum = sum(col_weights[j] for j in unassigned_cols)
                for j in unassigned_cols:
                    # Force to B if we can't reach target without it
                    if total_unassigned_sum - col_weights[j] < rem_r[i]:
                        if current_grid[i][j] == 'N':
                            return False
                        if current_grid[i][j] is None:
                            current_grid[i][j] = 'B'
                            changed = True
                            break
                    # Force to N if selecting it exceeds target
                    if col_weights[j] > rem_r[i]:
                        if current_grid[i][j] == 'B':
                            return False
                        if current_grid[i][j] is None:
                            current_grid[i][j] = 'N'
                            changed = True
                            break
                if changed:
                    break
            if changed:
                if not is_state_valid(current_grid):
                    return False
                continue

            # Process columns for forced cells
            for j in range(n):
                unassigned_rows = [i for i in range(m) if current_grid[i][j] is None]
                if not unassigned_rows:
                    continue
                total_unassigned_sum = sum(row_weights[i] for i in unassigned_rows)
                for i in unassigned_rows:
                    # Force to B if we can't reach target without it
                    if total_unassigned_sum - row_weights[i] < rem_c[j]:
                        if current_grid[i][j] == 'N':
                            return False
                        if current_grid[i][j] is None:
                            current_grid[i][j] = 'B'
                            changed = True
                            break
                    # Force to N if selecting it exceeds target
                    if row_weights[i] > rem_c[j]:
                        if current_grid[i][j] == 'B':
                            return False
                        if current_grid[i][j] is None:
                            current_grid[i][j] = 'N'
                            changed = True
                            break
                if changed:
                    break
            if changed and not is_state_valid(current_grid):
                return False
        return True

    # MRV heuristic: pick most constrained unassigned cell
    def select_next_cell(current_grid):
        min_constraint = float('inf')
        best_cell = None
        for i in range(m):
            for j in range(n):
                if current_grid[i][j] is None:
                    row_unassigned = sum(1 for k in range(n) if current_grid[i][k] is None)
                    col_unassigned = sum(1 for k in range(m) if current_grid[k][j] is None)
                    constraint_score = row_unassigned + col_unassigned
                    if constraint_score < min_constraint:
                        min_constraint = constraint_score
                        best_cell = (i, j)
        return best_cell

    def backtrack(current_grid):
        # Apply all forced assignments first to prune search space
        if not apply_forced_assignments(current_grid):
            return None

        # Check if grid is fully assigned
        all_assigned = all(all(cell is not None for cell in row) for row in current_grid)
        if all_assigned:
            # Verify solution correctness
            rem_r = get_remaining_row_sums(current_grid)
            rem_c = get_remaining_col_sums(current_grid)
            if all(r == 0 for r in rem_r) and all(c == 0 for c in rem_c):
                # Convert to required output format
                return [['B' if cell == 'B' else None for cell in row] for row in current_grid]
            return None

        # Pick next cell to branch
        i, j = select_next_cell(current_grid)

        # Try assigning B first
        grid_b = [row.copy() for row in current_grid]
        grid_b[i][j] = 'B'
        res_b = backtrack(grid_b)
        if res_b:
            return res_b

        # Try assigning N next
        grid_n = [row.copy() for row in current_grid]
        grid_n[i][j] = 'N'
        res_n = backtrack(grid_n)
        if res_n:
            return res_n

        return None

    solution = backtrack(grid)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
