def solve(observation):
    reg_grid = observation['data']
    N = len(reg_grid)

    # Generate all valid domino positions (horizontal then vertical)
    dominoes = []
    for r in range(N):
        for c in range(N-1):
            dominoes.append(((r, c), (r, c+1)))
    for r in range(N-1):
        for c in range(N):
            dominoes.append(((r, c), (r+1, c)))
    M = len(dominoes)

    # Map region IDs to contiguous indices for easier handling
    region_ids = list({cell for row in reg_grid for cell in row})
    reg_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    # Precompute how many shaded cells each domino adds to each region
    domino_reg_delta = [[0]*R for _ in range(M)]
    for d_idx in range(M):
        (r1, c1), (r2, c2) = dominoes[d_idx]
        rid1 = reg_grid[r1][c1]
        rid2 = reg_grid[r2][c2]
        domino_reg_delta[d_idx][reg_to_idx[rid1]] += 1
        if rid1 != rid2:
            domino_reg_delta[d_idx][reg_to_idx[rid2]] += 1

    # Map each cell to dominoes that include it
    cell_to_dominoes = [[[] for _ in range(N)] for _ in range(N)]
    for d_idx in range(M):
        (r1, c1), (r2, c2) = dominoes[d_idx]
        cell_to_dominoes[r1][c1].append(d_idx)
        cell_to_dominoes[r2][c2].append(d_idx)

    # Precompute conflict matrix: dominoes conflict if overlapping or orthogonally adjacent
    conflict = [[False]*M for _ in range(M)]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for d1 in range(M):
        cells = set(dominoes[d1])
        # Mark overlapping dominoes as conflicting
        for (r, c) in cells:
            for d2 in cell_to_dominoes[r][c]:
                if d1 != d2:
                    conflict[d1][d2] = conflict[d2][d1] = True
        # Mark orthogonally adjacent dominoes as conflicting
        for (r, c) in cells:
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    for d2 in cell_to_dominoes[nr][nc]:
                        if d1 != d2 and not conflict[d1][d2]:
                            conflict[d1][d2] = conflict[d2][d1] = True

    # Precompute list of dominoes affecting each region
    reg_dominoes = [[] for _ in range(R)]
    for d_idx in range(M):
        for r_idx in range(R):
            if domino_reg_delta[d_idx][r_idx] > 0:
                reg_dominoes[r_idx].append(d_idx)

    def backtrack(placed, forbidden, reg_counts):
        # Check if we found a valid solution
        if all(c == 2 for c in reg_counts):
            grid = [[None]*N for _ in range(N)]
            for d in placed:
                (r1, c1), (r2, c2) = dominoes[d]
                grid[r1][c1] = 'S'
                grid[r2][c2] = 'S'
            return grid

        # Early exit if any region has too many shaded cells
        if any(c > 2 for c in reg_counts):
            return None

        # Forward checking: ensure all regions can still reach exactly 2 shaded cells
        for r_idx in range(R):
            remaining = 2 - reg_counts[r_idx]
            if remaining < 0:
                return None
            max_possible = 0
            for d in reg_dominoes[r_idx]:
                if d not in placed and d not in forbidden:
                    max_possible += domino_reg_delta[d][r_idx]
            if max_possible < remaining:
                return None

        # MRV heuristic: select most constrained domino to try first
        best_d = None
        min_score = float('inf')
        for d in range(M):
            if d in placed or d in forbidden:
                continue
            # Skip if placing this domino would overfill any region
            valid = True
            for r_idx in range(R):
                if reg_counts[r_idx] + domino_reg_delta[d][r_idx] > 2:
                    valid = False
                    break
            if not valid:
                continue
            # Calculate constraint score (lower = more constrained)
            score = 0
            for r_idx in range(R):
                delta = domino_reg_delta[d][r_idx]
                if delta > 0:
                    rem = 2 - reg_counts[r_idx]
                    avail = len([d2 for d2 in reg_dominoes[r_idx] if d2 not in placed and d2 not in forbidden])
                    score += rem * 100 + avail
            if score < min_score:
                min_score = score
                best_d = d

        if best_d is None:
            return None

        # Try placing the selected domino
        placed.add(best_d)
        added_forbidden = []
        # Add conflicting dominoes to forbidden
        for d in range(M):
            if conflict[best_d][d] and d not in forbidden and d not in placed:
                forbidden.add(d)
                added_forbidden.append(d)
        # Calculate new region counts
        new_reg_counts = reg_counts.copy()
        for r_idx in range(R):
            new_reg_counts[r_idx] += domino_reg_delta[best_d][r_idx]
            # Forbid all other dominoes affecting regions that now have exactly 2 shaded cells
            if new_reg_counts[r_idx] == 2:
                for d in reg_dominoes[r_idx]:
                    if d != best_d and d not in forbidden and d not in placed:
                        forbidden.add(d)
                        added_forbidden.append(d)

        # Recurse with placed domino
        res = backtrack(placed, forbidden, new_reg_counts)
        if res is not None:
            return res

        # Undo placement
        placed.remove(best_d)
        for d in added_forbidden:
            forbidden.remove(d)

        # Try not placing the selected domino
        forbidden.add(best_d)
        res = backtrack(placed, forbidden, reg_counts)
        forbidden.remove(best_d)

        return res

    solution = backtrack(set(), set(), [0]*R)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
