def get_dot_edges(r, c, N):
    edges = []
    if c < N:
        edges.append(('H', r, c))
    if c > 0:
        edges.append(('H', r, c-1))
    if r < N:
        edges.append(('V', r, c))
    if r > 0:
        edges.append(('V', r-1, c))
    return edges

def get_other_end(edge, r, c):
    typ, er, ec = edge
    if typ == 'H':
        if er == r and ec == c:
            return (r, c+1)
        elif er == r and ec == c-1:
            return (r, c-1)
    else:
        if er == r and ec == c:
            return (r+1, c)
        elif er == r-1 and ec == c:
            return (r-1, c)
    raise ValueError("Edge not connected to dot")

def get_segment_length(r, c, dir, edge_state, N):
    length = 0
    cr, cc = r, c
    while True:
        nr, nc = cr + dir[0], cc + dir[1]
        if nr < 0 or nr > N or nc < 0 or nc > N:
            break
        if dir == (0, 1):
            edge = ('H', cr, cc)
        elif dir == (0, -1):
            edge = ('H', cr, cc-1)
        elif dir == (1, 0):
            edge = ('V', cr, cc)
        elif dir == (-1, 0):
            edge = ('V', cr-1, cc)
        else:
            break
        if edge_state.get(edge, None) is not True:
            break
        length += 1
        cr, cc = nr, nc
    return length

def check_clues(edge_state, clues, N):
    for (r, c, typ, k) in clues:
        edges = [e for e in get_dot_edges(r, c, N) if edge_state.get(e, None) is True]
        if len(edges) < 2:
            continue
        if len(edges) > 2:
            return False
        dirs = []
        for e in edges:
            other = get_other_end(e, r, c)
            dr = other[0] - r
            dc = other[1] - c
            dirs.append((dr, dc))
        if typ == 'W':
            if (dirs[0][0] + dirs[1][0] != 0) or (dirs[0][1] + dirs[1][1] != 0):
                return False
            l1 = get_segment_length(r, c, dirs[0], edge_state, N)
            l2 = get_segment_length(r, c, dirs[1], edge_state, N)
            if l1 + l2 > k:
                return False
            nr1 = r + dirs[0][0] * (l1 + 1)
            nc1 = c + dirs[0][1] * (l1 + 1)
            nr2 = r + dirs[1][0] * (l2 + 1)
            nc2 = c + dirs[1][1] * (l2 + 1)
            end1 = (nr1 < 0 or nr1 > N or nc1 <0 or nc1 > N) or (edge_state.get(('H', r, c) if dirs[0][1] != 0 else ('V', r, c), None) is False)
            end2 = (nr2 < 0 or nr2 > N or nc2 <0 or nc2 > N) or (edge_state.get(('H', r, c) if dirs[1][1] != 0 else ('V', r, c), None) is False)
            if end1 and end2 and (l1 + l2 != k):
                return False
        else:
            if dirs[0][0] * dirs[1][0] + dirs[0][1] * dirs[1][1] != 0:
                return False
            l1 = get_segment_length(r, c, dirs[0], edge_state, N)
            l2 = get_segment_length(r, c, dirs[1], edge_state, N)
            if l1 + l2 > k:
                return False
            nr1 = r + dirs[0][0] * (l1 + 1)
            nc1 = c + dirs[0][1] * (l1 + 1)
            nr2 = r + dirs[1][0] * (l2 + 1)
            nc2 = c + dirs[1][1] * (l2 + 1)
            end1 = (nr1 < 0 or nr1 > N or nc1 <0 or nc1 > N) or (edge_state.get(('H', r, c) if dirs[0][1] != 0 else ('V', r, c), None) is False)
            end2 = (nr2 < 0 or nr2 > N or nc2 <0 or nc2 > N) or (edge_state.get(('H', r, c) if dirs[1][1] != 0 else ('V', r, c), None) is False)
            if end1 and end2 and (l1 + l2 != k):
                return False
    return True

def propagate(edge_state, clues, N):
    changed = True
    while changed:
        changed = False
        for r in range(N+1):
            for c in range(N+1):
                edges = get_dot_edges(r, c, N)
                present = 0
                unknown = []
                for e in edges:
                    s = edge_state.get(e, None)
                    if s is True:
                        present += 1
                    elif s is None:
                        unknown.append(e)
                if present > 2:
                    return (False, edge_state)
                is_clue = any(cr == r and cc == c for (cr, cc, _, _) in clues)
                if is_clue:
                    if present + len(unknown) < 2:
                        return (False, edge_state)
                    if present == 2:
                        for e in unknown:
                            if edge_state.get(e, None) is None:
                                edge_state[e] = False
                                changed = True
                    if present == 1 and len(unknown) == 1:
                        e = unknown[0]
                        edge_state[e] = True
                        changed = True
                else:
                    if present == 2:
                        for e in unknown:
                            if edge_state.get(e, None) is None:
                                edge_state[e] = False
                                changed = True
                    if present == 1 and len(unknown) == 0:
                        return (False, edge_state)
                    if present == 0 and len(unknown) < 2:
                        for e in unknown:
                            if edge_state.get(e, None) is None:
                                edge_state[e] = False
                                changed = True
        if not check_clues(edge_state, clues, N):
            return (False, edge_state)
        present_edges = [e for e in edge_state if edge_state[e] is True]
        if len(present_edges) > 0:
            e0 = present_edges[0]
            typ, er, ec = e0
            if typ == 'H':
                start = (er, ec)
                current = (er, ec+1)
            else:
                start = (er, ec)
                current = (er+1, ec)
            prev = start
            loop_closed = False
            while True:
                edges = [e for e in get_dot_edges(current[0], current[1], N) if edge_state.get(e, None) is True]
                if len(edges) != 2:
                    break
                next_nodes = []
                for e in edges:
                    other = get_other_end(e, current[0], current[1])
                    if other != prev:
                        next_nodes.append(other)
                if len(next_nodes) != 1:
                    break
                next_node = next_nodes[0]
                if next_node == start:
                    loop_closed = True
                    break
                prev = current
                current = next_node
            if loop_closed:
                for (cr, cc, _, _) in clues:
                    if (cr, cc) not in [start, current, prev]:
                        found = False
                        test_e0 = present_edges[0]
                        t_typ, t_er, t_ec = test_e0
                        if t_typ == 'H':
                            t_start = (t_er, t_ec)
                            t_current = (t_er, t_ec+1)
                        else:
                            t_start = (t_er, t_ec)
                            t_current = (t_er+1, t_ec)
                        t_path = [t_start, t_current]
                        t_prev = t_start
                        while t_current != t_start:
                            t_edges = [e for e in get_dot_edges(t_current[0], t_current[1], N) if edge_state.get(e, None) is True]
                            t_next_nodes = []
                            for e in t_edges:
                                t_other = get_other_end(e, t_current[0], t_current[1])
                                if t_other != t_prev:
                                    t_next_nodes.append(t_other)
                            if len(t_next_nodes) != 1:
                                break
                            t_next_node = t_next_nodes[0]
                            t_path.append(t_next_node)
                            t_prev = t_current
                            t_current = t_next_node
                        if (cr, cc) not in t_path:
                            return (False, edge_state)
                        break
    return (True, edge_state)

def build_path(edge_state, N):
    present_edges = [e for e in edge_state if edge_state[e] is True]
    if len(present_edges) == 0:
        return None
    e0 = present_edges[0]
    typ, er, ec = e0
    if typ == 'H':
        start = (er, ec)
        current = (er, ec+1)
    else:
        start = (er, ec)
        current = (er+1, ec)
    path = [start, current]
    prev = start
    while current != start:
        edges = [e for e in get_dot_edges(current[0], current[1], N) if edge_state.get(e, None) is True]
        if len(edges) != 2:
            return None
        next_nodes = []
        for e in edges:
            other = get_other_end(e, current[0], current[1])
            if other != prev:
                next_nodes.append(other)
        if len(next_nodes) != 1:
            return None
        next_node = next_nodes[0]
        path.append(next_node)
        prev = current
        current = next_node
    path_edges = set()
    for i in range(len(path)-1):
        a, b = path[i], path[i+1]
        if a[0] == b[0]:
            r = a[0]
            c = min(a[1], b[1])
            path_edges.add(('H', r, c))
        else:
            c = a[1]
            r = min(a[0], b[0])
            path_edges.add(('V', r, c))
    if len(path_edges) != len(present_edges):
        return None
    return path

def backtrack(edge_state, clues, N):
    valid, new_state = propagate(edge_state.copy(), clues, N)
    if not valid:
        return None
    all_edges = []
    for r in range(N+1):
        for c in range(N):
            all_edges.append(('H', r, c))
        for c in range(N+1):
            if r < N:
                all_edges.append(('V', r, c))
    unknown = [e for e in all_edges if new_state.get(e, None) is None]
    if len(unknown) == 0:
        path = build_path(new_state, N)
        if path is None:
            return None
        for (cr, cc, _, _) in clues:
            if (cr, cc) not in path:
                return None
        if check_clues(new_state, clues, N):
            return path
        return None
    unknown.sort(key=lambda e: len([c for c in clues if (c[0] == e[1] and (e[0] == 'H' and (c[1] == e[2] or c[1] == e[2]+1)) or (e[0] == 'V' and (c[1] == e[2] and (c[0] == e[1] or c[0] == e[1]+1))))], reverse=True)
    e = unknown[0]
    new_state[e] = True
    res = backtrack(new_state, clues, N)
    if res is not None:
        return res
    new_state[e] = False
    res = backtrack(new_state, clues, N)
    if res is not None:
        return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    clues = []
    for r in range(N+1):
        for c in range(N+1):
            val = data[r][c]
            if val is not None:
                typ = val[0]
                k = int(val[1:])
                clues.append((r, c, typ, k))
    if not clues:
        return "No Solution"
    edge_state = {}
    path = backtrack(edge_state, clues, N)
    return path if path is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
