def solve(observation):
    grid = observation['data']
    rows = len(grid)
    if not rows:
        return "No Solution"
    cols = len(grid[0])

    def get_neighbors(r, c):
        res = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    res.append((nr, nc))
        return res

    def is_valid(board):
        for r in range(rows):
            for c in range(cols):
                val = board[r][c]
                if not isinstance(val, int):
                    continue
                cnt = sum(1 for (nr, nc) in get_neighbors(r, c) if board[nr][nc] == 'F')
                if cnt != val:
                    return False
        return True

    def backtrack(board):
        # Deduction loop first
        changed = True
        while changed:
            changed = False
            valid = True
            for r in range(rows):
                for c in range(cols):
                    val = board[r][c]
                    if not isinstance(val, int):
                        continue
                    neighbors = get_neighbors(r, c)
                    flag_cnt = 0
                    unknown_cnt = 0
                    unknowns = []
                    for (nr, nc) in neighbors:
                        v = board[nr][nc]
                        if v == 'F':
                            flag_cnt += 1
                        elif v == '?':
                            unknown_cnt += 1
                            unknowns.append((nr, nc))
                    remaining = val - flag_cnt
                    if remaining < 0 or remaining > unknown_cnt:
                        return None
                    if remaining == unknown_cnt and unknown_cnt > 0:
                        for (nr, nc) in unknowns:
                            board[nr][nc] = 'F'
                        changed = True
                    elif remaining == 0 and unknown_cnt > 0:
                        for (nr, nc) in unknowns:
                            board[nr][nc] = None
                        changed = True
            if not valid:
                return None
        # Check if solved
        unknowns = []
        for r in range(rows):
            for c in range(cols):
                if board[r][c] == '?':
                    unknowns.append((r, c))
        if not unknowns:
            if is_valid(board):
                res = []
                for r in range(rows):
                    row = []
                    for c in range(cols):
                        v = board[r][c]
                        row.append('F' if v == 'F' else None)
                    res.append(row)
                return res
            return None
        # Pick best unknown to guess (most adjacent clues)
        best = None
        max_clues = -1
        for (r, c) in unknowns:
            cnt = 0
            for (nr, nc) in get_neighbors(r, c):
                if isinstance(board[nr][nc], int):
                    cnt += 1
            if cnt > max_clues:
                max_clues = cnt
                best = (r, c)
        r, c = best
        # Try flag first
        new_board = [row.copy() for row in board]
        new_board[r][c] = 'F'
        sol = backtrack(new_board)
        if sol is not None:
            return sol
        # Try safe
        new_board = [row.copy() for row in board]
        new_board[r][c] = None
        sol = backtrack(new_board)
        return sol

    # Initialize board
    initial_board = []
    for r in range(rows):
        row = []
        for c in range(cols):
            val = grid[r][c]
            if val is not None:
                row.append(val)
            else:
                row.append('?')
        initial_board.append(row)

    solution = backtrack(initial_board)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
