from typing import List, Tuple, Dict, Optional

# Direction constants: up, right, down, left (bitmask values)
DIR_UP = 1 << 0
DIR_RIGHT = 1 << 1
DIR_DOWN = 1 << 2
DIR_LEFT = 1 << 3

# Opposite directions
OPPOSITE = {DIR_UP: DIR_DOWN, DIR_RIGHT: DIR_LEFT, DIR_DOWN: DIR_UP, DIR_LEFT: DIR_RIGHT}
# Direction deltas (dr, dc)
DELTA = {DIR_UP: (-1, 0), DIR_RIGHT: (0, 1), DIR_DOWN: (1, 0), DIR_LEFT: (0, -1)}

def get_allowed_masks(r: int, c: int, cell_type: Optional[str], N: int) -> List[int]:
    """Return all valid edge masks for a cell based on its type and grid position"""
    masks = []
    if cell_type is None:
        # Normal cell: either 0 edges, or any 2 valid edges within grid
        all_dirs = [d for d in DELTA if 0 <= r + DELTA[d][0] < N and 0 <= c + DELTA[d][1] < N]
        # 0 edges mask
        masks.append(0)
        # All pairs of 2 directions
        for i in range(len(all_dirs)):
            for j in range(i+1, len(all_dirs)):
                masks.append(all_dirs[i] | all_dirs[j])
    elif cell_type == 'W':
        # White cell: only opposite direction pairs, both edges valid
        valid_pairs = []
        # Up-down pair
        if r - 1 >= 0 and r + 1 < N:
            valid_pairs.append(DIR_UP | DIR_DOWN)
        # Left-right pair
        if c - 1 >= 0 and c + 1 < N:
            valid_pairs.append(DIR_LEFT | DIR_RIGHT)
        masks = valid_pairs
    elif cell_type == 'B':
        # Black cell: only perpendicular pairs, each direction can extend 2 steps
        valid_pairs = []
        dirs = []
        # Check which directions are valid for B (can extend 2 steps)
        if r >= 2: dirs.append(DIR_UP)
        if c <= N - 3: dirs.append(DIR_RIGHT)
        if r <= N - 3: dirs.append(DIR_DOWN)
        if c >= 2: dirs.append(DIR_LEFT)
        # Find all perpendicular pairs
        perp_pairs = [(DIR_UP, DIR_RIGHT), (DIR_UP, DIR_LEFT), (DIR_DOWN, DIR_RIGHT), (DIR_DOWN, DIR_LEFT)]
        for d1, d2 in perp_pairs:
            if d1 in dirs and d2 in dirs:
                valid_pairs.append(d1 | d2)
        masks = valid_pairs
    return masks

def propagate_constraints(possible_masks: List[List[List[int]]], N: int, data: List[List[Optional[str]]]) -> bool:
    """Apply constraint propagation, modify possible_masks in place, return False if invalid"""
    changed = True
    while changed:
        changed = False
        # Step 1: Mutual edge constraint: if cell A can't have edge to B, B can't have edge to A
        for r in range(N):
            for c in range(N):
                cur_masks = possible_masks[r][c]
                if not cur_masks:
                    return False
                # For each direction, check if any mask has this direction set
                allowed_dirs = set()
                for m in cur_masks:
                    for d in DELTA:
                        if m & d:
                            allowed_dirs.add(d)
                # For each allowed direction, check neighbor's allowed opposite direction
                for d in allowed_dirs:
                    dr, dc = DELTA[d]
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        opp_d = OPPOSITE[d]
                        # Filter neighbor's masks to those that have opp_d set
                        new_neighbor_masks = [m for m in possible_masks[nr][nc] if m & opp_d]
                        if not new_neighbor_masks:
                            return False
                        if len(new_neighbor_masks) != len(possible_masks[nr][nc]):
                            possible_masks[nr][nc] = new_neighbor_masks
                            changed = True
                # Filter current cell's masks to only those with directions allowed by neighbors
                new_cur_masks = []
                for m in cur_masks:
                    valid = True
                    for d in DELTA:
                        if m & d:
                            dr, dc = DELTA[d]
                            nr, nc = r + dr, c + dc
                            opp_d = OPPOSITE[d]
                            # Check if neighbor has at least one mask with opp_d
                            has = any(m2 & opp_d for m2 in possible_masks[nr][nc])
                            if not has:
                                valid = False
                                break
                    if valid:
                        new_cur_masks.append(m)
                if not new_cur_masks:
                    return False
                if len(new_cur_masks) != len(cur_masks):
                    possible_masks[r][c] = new_cur_masks
                    changed = True

        # Step 2: Apply W cell specific constraints
        for r in range(N):
            for c in range(N):
                if data[r][c] != 'W':
                    continue
                cur_masks = possible_masks[r][c]
                new_masks = []
                for m in cur_masks:
                    valid = True
                    if m == (DIR_UP | DIR_DOWN):
                        # Vertical W: cannot have both up 2 steps and down 2 steps straight
                        up_ok = any(not (m2 & DIR_UP) for m2 in possible_masks[r-1][c])
                        down_ok = any(not (m2 & DIR_DOWN) for m2 in possible_masks[r+1][c])
                        if not (up_ok or down_ok):
                            valid = False
                    elif m == (DIR_LEFT | DIR_RIGHT):
                        # Horizontal W: cannot have both left 2 steps and right 2 steps straight
                        left_ok = any(not (m2 & DIR_LEFT) for m2 in possible_masks[r][c-1])
                        right_ok = any(not (m2 & DIR_RIGHT) for m2 in possible_masks[r][c+1])
                        if not (left_ok or right_ok):
                            valid = False
                    if valid:
                        new_masks.append(m)
                if not new_masks:
                    return False
                if len(new_masks) != len(cur_masks):
                    possible_masks[r][c] = new_masks
                    changed = True

        # Step 3: Apply B cell specific constraints
        for r in range(N):
            for c in range(N):
                if data[r][c] != 'B':
                    continue
                cur_masks = possible_masks[r][c]
                new_masks = []
                for m in cur_masks:
                    valid = True
                    dirs = [d for d in DELTA if m & d]
                    for d in dirs:
                        dr, dc = DELTA[d]
                        nr, nc = r + dr, c + dc
                        opp_d = OPPOSITE[d]
                        # Neighbor cell must be straight in this direction
                        req_mask = d | opp_d
                        if req_mask not in possible_masks[nr][nc]:
                            valid = False
                            break
                    if valid:
                        new_masks.append(m)
                if not new_masks:
                    return False
                if len(new_masks) != len(cur_masks):
                    possible_masks[r][c] = new_masks
                    changed = True
    return True

def is_valid_solution(mask_grid: List[List[int]], N: int, data: List[List[Optional[str]]]) -> Tuple[bool, Optional[List[Tuple[int, int]]]]:
    """Check if mask grid is valid solution, return path if yes"""
    # Collect all edges
    edges: Dict[Tuple[int, int], List[Tuple[int, int]]] = {}
    clue_positions = set((r,c) for r in range(N) for c in range(N) if data[r][c] is not None)
    for r in range(N):
        for c in range(N):
            m = mask_grid[r][c]
            if m == 0:
                continue
            edges[(r,c)] = []
            for d in DELTA:
                if m & d:
                    dr, dc = DELTA[d]
                    nr, nc = r + dr, c + dc
                    edges[(r,c)].append((nr, nc))
            if len(edges[(r,c)]) != 2:
                return False, None
    # Check all clues are in edges
    for pos in clue_positions:
        if pos not in edges:
            return False, None
    # Traverse loop
    start = next(iter(edges.keys()))
    path = [start]
    prev = None
    cur = start
    while True:
        next_nodes = [n for n in edges[cur] if n != prev]
        if len(next_nodes) != 1:
            return False, None
        nxt = next_nodes[0]
        if nxt == start:
            path.append(nxt)
            break
        path.append(nxt)
        prev = cur
        cur = nxt
    # Check loop includes all edge nodes
    if len(path) - 1 != len(edges):
        return False, None
    return True, path

def backtrack(possible_masks: List[List[List[int]]], N: int, data: List[List[Optional[str]]]) -> Optional[List[Tuple[int, int]]]:
    """Backtracking search with MRV heuristic"""
    # Propagate constraints first
    if not propagate_constraints(possible_masks, N, data):
        return None
    # Find cell with minimum remaining options
    min_len = float('inf')
    target = None
    for r in range(N):
        for c in range(N):
            l = len(possible_masks[r][c])
            if l > 1 and l < min_len:
                min_len = l
                target = (r,c)
    # If all cells have only one option, check solution
    if target is None:
        mask_grid = [[possible_masks[r][c][0] for c in range(N)] for r in range(N)]
        valid, path = is_valid_solution(mask_grid, N, data)
        return path if valid else None
    # Try each possible mask for target cell
    r, c = target
    for mask in possible_masks[r][c]:
        # Create copy of possible masks
        new_possible = [[row[c].copy() for c in range(N)] for row in possible_masks]
        new_possible[r][c] = [mask]
        # Recurse
        res = backtrack(new_possible, N, data)
        if res is not None:
            return res
    return None

def solve(observation: Dict) -> List[Tuple[int, int]] | str:
    data = observation['data']
    N = len(data)
    # Initialize possible masks for each cell
    possible_masks = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            possible_masks[r][c] = get_allowed_masks(r, c, data[r][c], N)
            if not possible_masks[r][c]:
                return "No Solution"
    # Run backtracking search
    solution = backtrack(possible_masks, N, data)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
