OBSERVATION = {
    'tree': [
        [None, 'T', None, None, None, None],
        [None, None, 'T', None, None, None],
        [None, None, None, None, None, 'T'],
        [None, 'T', None, None, None, None],
        [None, None, None, 'T', None, None],
        [None, 'T', None, None, None, 'T']
    ],
    'row_tent_counts': [1, 1, 1, 0, 1, 2],
    'col_tent_counts': [2, 1, 1, 1, 1, 1]
}

def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts'].copy()
    col_counts = observation['col_tent_counts'].copy()
    n_rows = len(tree_grid)
    n_cols = len(tree_grid[0]) if n_rows else 0

    # Initialize state: None = empty, 'T' = tree, 't' = tent, 'x' = blocked
    state = []
    trees = []
    for r in range(n_rows):
        row = []
        for c in range(n_cols):
            val = tree_grid[r][c]
            if val == 'T':
                row.append('T')
                trees.append((r, c))
            else:
                row.append(None)
        state.append(row)
    paired_trees = set()

    # Block rows/columns with 0 required tents first
    for r in range(n_rows):
        if row_counts[r] == 0:
            for c in range(n_cols):
                if state[r][c] is None:
                    state[r][c] = 'x'
    for c in range(n_cols):
        if col_counts[c] == 0:
            for r in range(n_rows):
                if state[r][c] is None:
                    state[r][c] = 'x'

    def is_valid(r, c):
        return 0 <= r < n_rows and 0 <= c < n_cols

    def get_tree_candidates(tr, tc, s):
        candidates = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = tr + dr, tc + dc
            if is_valid(nr, nc) and s[nr][nc] is None:
                candidates.append((nr, nc))
        return candidates

    def place_tent(tr, tc, tent_r, tent_c, s, rc, cc, pt):
        if rc[tent_r] <= 0 or cc[tent_c] <= 0 or s[tent_r][tent_c] is not None:
            return False
        s[tent_r][tent_c] = 't'
        rc[tent_r] -= 1
        cc[tent_c] -= 1
        pt.add((tr, tc))
        # Block all 8 adjacent cells
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = tent_r + dr, tent_c + dc
                if is_valid(nr, nc) and s[nr][nc] is None:
                    s[nr][nc] = 'x'
        return True

    def propagate(s, rc, cc, pt):
        changed = True
        while changed:
            changed = False
            # Rule 1: Tree with only 1 possible tent spot
            for (tr, tc) in trees:
                if (tr, tc) in pt:
                    continue
                cand = get_tree_candidates(tr, tc, s)
                if len(cand) == 0:
                    return False
                if len(cand) == 1:
                    if not place_tent(tr, tc, cand[0][0], cand[0][1], s, rc, cc, pt):
                        return False
                    changed = True
            # Rule 2: Row needs exactly as many tents as available spots
            for r in range(n_rows):
                if rc[r] < 0:
                    return False
                avail = [c for c in range(n_cols) if s[r][c] is None]
                if len(avail) < rc[r]:
                    return False
                if len(avail) == rc[r] and rc[r] > 0:
                    for c in avail:
                        found = False
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            tr, tc = r + dr, c + dc
                            if is_valid(tr, tc) and s[tr][tc] == 'T' and (tr, tc) not in pt:
                                if place_tent(tr, tc, r, c, s, rc, cc, pt):
                                    found = True
                                    changed = True
                                    break
                        if not found:
                            return False
            # Rule 3: Column needs exactly as many tents as available spots
            for c in range(n_cols):
                if cc[c] < 0:
                    return False
                avail = [r for r in range(n_rows) if s[r][c] is None]
                if len(avail) < cc[c]:
                    return False
                if len(avail) == cc[c] and cc[c] > 0:
                    for r in avail:
                        found = False
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            tr, tc = r + dr, c + dc
                            if is_valid(tr, tc) and s[tr][tc] == 'T' and (tr, tc) not in pt:
                                if place_tent(tr, tc, r, c, s, rc, cc, pt):
                                    found = True
                                    changed = True
                                    break
                        if not found:
                            return False
        return True

    def is_complete(s, rc, cc, pt):
        if sum(rc) != 0 or sum(cc) != 0 or len(pt) != len(trees):
            return False
        # Verify no adjacent tents
        tents = [(r,c) for r in range(n_rows) for c in range(n_cols) if s[r][c] == 't']
        for (r,c) in tents:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if is_valid(nr, nc) and s[nr][nc] == 't':
                        return False
        return True

    # Initial propagation
    if not propagate(state, row_counts, col_counts, paired_trees):
        return "No Solution"
    if is_complete(state, row_counts, col_counts, paired_trees):
        return [['t' if cell == 't' else None for cell in row] for row in state]

    # Backtracking search
    def backtrack(s, rc, cc, pt):
        if not propagate(s, rc, cc, pt):
            return None
        if is_complete(s, rc, cc, pt):
            return [['t' if cell == 't' else None for cell in row] for row in s]
        # Pick tree with smallest candidate count to minimize branching
        unpaired = [t for t in trees if t not in pt]
        unpaired.sort(key=lambda x: len(get_tree_candidates(x[0], x[1], s)))
        tr, tc = unpaired[0]
        candidates = get_tree_candidates(tr, tc, s)
        for (tent_r, tent_c) in candidates:
            # Create copies of state for recursion
            new_s = [r.copy() for r in s]
            new_rc = rc.copy()
            new_cc = cc.copy()
            new_pt = pt.copy()
            if place_tent(tr, tc, tent_r, tent_c, new_s, new_rc, new_cc, new_pt):
                res = backtrack(new_s, new_rc, new_cc, new_pt)
                if res is not None:
                    return res
        return None

    result = backtrack(state, row_counts, col_counts, paired_trees)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
