        ['B6', None, None, 'B7', None, None, None, None, 'B2', 'B2', None],
        [None, None, None, None, None, None, None, None, None, None, 'W2'],
        [None, None, None, None, 'W4', None, 'W3', None, 'B7', None, None],
        ['W5', 'W2', None, None, None, None, None, None, None, 'W2', None],
        [None, None, None, None, None, None, None, None, None, None, None],
        [None, None, None, None, None, None, None, None, None, 'B2', None],
        [None, 'B2', None, None, 'B3', 'B4', None, 'B5', None, None, None],
        [None, None, None, None, None, None, None, None, None, None, None],
        [None, 'B2', 'B4', None, None, None, 'B3', None, 'B7', None, None],
        ['W2', None, None, 'B3', None, None, None, None, None, 'B2', 'W2'],
        [None, None, 'B2', None, None, None, 'B2', 'B2', None, None, None]
    ]
}

from copy import deepcopy

DIRS = [(-1,0), (0,1), (1,0), (0,-1)] # up, right, down, left
OPPOSITE = [2, 3, 0, 1]
PERPENDICULAR = [[1,3], [0,2], [1,3], [0,2]]

def get_clues(grid):
    clues = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val is not None:
                typ = val[0]
                k = int(val[1:])
                clues.append((r, c, typ, k))
    return clues

def is_valid(r, c, size):
    return 0 <= r < size and 0 <= c < size

def add_edge(h_edges, v_edges, deg, r1, c1, r2, c2, size):
    if r1 == r2:
        c = min(c1, c2)
        if h_edges[r1][c]:
            return False
        h_edges[r1][c] = True
    else:
        r = min(r1, r2)
        if v_edges[r][c1]:
            return False
        v_edges[r][c1] = True
    deg[r1][c1] += 1
    deg[r2][c2] += 1
    if deg[r1][c1] > 2 or deg[r2][c2] > 2:
        return False
    return True

def generate_clue_options(r, c, typ, k, size, h_edges, v_edges, deg):
    options = []
    if typ == 'W':
        for dir1, dir2 in [(1,3), (0,2):
            dr1, dc1 = DIRS[dir1]
            dr2, dc2 = DIRS[dir2]
            for l1 in range(1, k):
                l2 = k - l1
                end1_r, end1_c = r + dr1 * l1, c + dc1 * l1
                end2_r, end2_c = r + dr2 * l2, c + dc2 * l2
                if not is_valid(end1_r, end1_c, size) or not is_valid(end2_r, end2_c, size):
                    continue
                valid = True
                temp_h, temp_v, temp_d = deepcopy(h_edges), deepcopy(v_edges), deepcopy(deg)
                for i in range(1, l1+1):
                    cr, cc = r + dr1*i, c + dc1*i
                    pr, pc = r + dr1*(i-1), c + dc1*(i-1)
                    if not add_edge(temp_h, temp_v, temp_d, pr, pc, cr, cc, size):
                        valid = False
                        break
                if not valid:
                    continue
                for i in range(1, l2+1):
                    cr, cc = r + dr2*i, c + dc2*i
                    pr, pc = r + dr2*(i-1), c + dc2*(i-1)
                    if not add_edge(temp_h, temp_v, temp_d, pr, pc, cr, cc, size):
                        valid = False
                        break
                if valid:
                    options.append( (temp_h, temp_v, temp_d) )
    else:
        for dir1 in range(4):
            for dir2 in PERPENDICULAR[dir1]:
                dr1, dc1 = DIRS[dir1]
                dr2, dc2 = DIRS[dir2]
                for l1 in range(1, k):
                    l2 = k - l1
                    end1_r, end1_c = r + dr1 * l1, c + dc1 * l1
                    end2_r, end2_c = r + dr2 * l2, c + dc2 * l2
                    if not is_valid(end1_r, end1_c, size) or not is_valid(end2_r, end2_c, size):
                        continue
                    valid = True
                    temp_h, temp_v, temp_d = deepcopy(h_edges), deepcopy(v_edges), deepcopy(deg)
                    for i in range(1, l1+1):
                        cr, cc = r + dr1*i, c + dc1*i
                        pr, pc = r + dr1*(i-1), c + dc1*(i-1)
                        if not add_edge(temp_h, temp_v, temp_d, pr, pc, cr, cc, size):
                            valid = False
                            break
                    if not valid:
                        continue
                    for i in range(1, l2+1):
                        cr, cc = r + dr2*i, c + dc2*i
                        pr, pc = r + dr2*(i-1), c + dc2*(i-1)
                        if not add_edge(temp_h, temp_v, temp_d, pr, pc, cr, cc, size):
                            valid = False
                            break
                    if valid:
                        options.append( (temp_h, temp_v, temp_d) )
    return options

def has_partial_loop(h_edges, v_edges, deg, size):
    visited = set()
    for r in range(size):
        for c in range(size):
            if deg[r][c] == 2 and (r,c) not in visited:
                path = []
                curr_r, curr_c = r, c
                prev_dir = None
                while True:
                    if (curr_r, curr_c) in visited:
                        if (curr_r, curr_c) == (r,c) and len(path) > 0:
                            for d in deg:
                                for v in d:
                                    if v == 2:
                                        return True
                        break
                    visited.add( (curr_r, curr_c) )
                    path.append( (curr_r, curr_c) )
                    found = False
                    for d in range(4):
                        if d == prev_dir:
                            continue
                        dr, dc = DIRS[d]
                        nr, nc = curr_r + dr, curr_c + dc
                        if not is_valid(nr, nc, size):
                            continue
                        if d == 0 and v_edges[nr][nc]:
                            prev_dir = OPPOSITE[d]
                            curr_r, curr_c = nr, nc
                            found = True
                            break
                        if d == 1 and h_edges[curr_r][curr_c]:
                            prev_dir = OPPOSITE[d]
                            curr_r, curr_c = nr, nc
                            found = True
                            break
                        if d == 2 and v_edges[curr_r][curr_c]:
                            prev_dir = OPPOSITE[d]
                            curr_r, curr_c = nr, nc
                            found = True
                            break
                        if d == 3 and h_edges[curr_r][nc]:
                            prev_dir = OPPOSITE[d]
                            curr_r, curr_c = nr, nc
                            found = True
                            break
                    if not found:
                        break
    return False

def complete_loop(h_edges, v_edges, deg, size):
    open_ends = []
    for r in range(size):
        for c in range(size):
            if deg[r][c] == 1:
                open_ends.append( (r,c) )
    if len(open_ends) != 0 and len(open_ends) != 2:
        return None
    if len(open_ends) == 0:
        for d in deg:
            for v in d:
                if v not in (0,2):
                    return None
        if has_partial_loop(h_edges, v_edges, deg, size):
            return extract_path(h_edges, v_edges, size)
        else:
            return None
    start_r, start_c = open_ends[0]
    end_r, end_c = open_ends[1]
    def dfs(curr_r, curr_c, prev_dir, temp_h, temp_v, temp_d):
        if curr_r == end_r and curr_c == end_c:
            for r in range(size):
                for c in range(size):
                    if temp_d[r][c] not in (0,2):
                        return None
            if not has_partial_loop(temp_h, temp_v, temp_d, size):
                return extract_path(temp_h, temp_v, size)
            return None
        for d in range(4):
            if d == prev_dir:
                continue
            dr, dc = DIRS[d]
            nr, nc = curr_r + dr, curr_c + dc
            if not is_valid(nr, nc, size):
                continue
            if temp_d[nr][nc] >= 2:
                continue
            edge_exists = False
            if d == 0 and temp_v[nr][nc]: edge_exists = True
            if d == 1 and temp_h[curr_r][curr_c]: edge_exists = True
            if d == 2 and temp_v[curr_r][curr_c]: edge_exists = True
            if d == 3 and temp_h[curr_r][nc]: edge_exists = True
            if edge_exists:
                continue
            new_h, new_v, new_d = deepcopy(temp_h), deepcopy(temp_v), deepcopy(temp_d)
            if not add_edge(new_h, new_v, new_d, curr_r, curr_c, nr, nc, size):
                continue
            res = dfs(nr, nc, OPPOSITE[d], new_h, new_v, new_d)
            if res is not None:
                return res
        return None
    return dfs(start_r, start_c, None, h_edges, v_edges, deg)

def extract_path(h_edges, v_edges, size):
    start = None
    for r in range(size):
        for c in range(size):
            if h_edges[r][c] or v_edges[r][c]:
                start = (r,c)
                break
        if start is not None:
            break
    path = []
    curr_r, curr_c = start
    prev_dir = None
    while True:
        path.append( (curr_r, curr_c) )
        found = False
        for d in range(4):
            if d == prev_dir:
                continue
            dr, dc = DIRS[d]
            nr, nc = curr_r + dr, curr_c + dc
            if not is_valid(nr, nc, size):
                continue
            exists = False
            if d == 0 and v_edges[nr][nc]: exists = True
            if d == 1 and h_edges[curr_r][curr_c]: exists = True
            if d == 2 and v_edges[curr_r][curr_c]: exists = True
            if d == 3 and h_edges[curr_r][nc]: exists = True
            if exists:
                prev_dir = OPPOSITE[d]
                curr_r, curr_c = nr, nc
                found = True
                break
        if not found or (curr_r, curr_c) == start:
            break
    if (curr_r, curr_c) == start:
        path.append(start)
        return path
    return None

def backtrack(clues, idx, h_edges, v_edges, deg, size):
    if idx == len(clues):
        return complete_loop(h_edges, v_edges, deg, size)
    r,c,typ,k = clues[idx]
    options = generate_clue_options(r,c,typ,k,size,h_edges,v_edges,deg)
    options.sort(key=lambda x: sum(sum(row) for row in x[2]))
    for opt in options:
        nh, nv, nd = opt
        if has_partial_loop(nh, nv, nd, size):
            continue
        res = backtrack(clues, idx+1, nh, nv, nd, size)
        if res is not None:
            return res
    return None

def solve(observation):
    grid = observation['data']
    size = len(grid)
    clues = get_clues(grid)
    clues.sort(key=lambda x: x[3])
    h_edges = [ [False]*(size-1) for _ in range(size) ]
    v_edges = [ [False]*size for _ in range(size-1) ]
    deg = [ [0]*size for _ in range(size) ]
    res = backtrack(clues, 0, h_edges, v_edges, deg, size)
    return res if res is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
