from typing import List, Tuple, Optional, Dict

# Direction constants
DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # up, right, down, left
OPPOSITE = [2, 3, 0, 1]  # opposite direction index
PERPENDICULAR = [[1,3], [0,2], [1,3], [0,2]]  # perpendicular directions for each dir

def get_neighbor(r: int, c: int, dir_idx: int, N: int) -> Optional[Tuple[int, int]]:
    dr, dc = DIRS[dir_idx]
    nr, nc = r + dr, c + dc
    if 0 <= nr < N and 0 <= nc < N:
        return (nr, nc)
    return None

def count_edges(r: int, c: int, h_edges: List[List[int]], v_edges: List[List[int]], N: int) -> Tuple[int, List[bool]]:
    edges = [False]*4
    # up: v_edges[r-1][c] if r>0
    if r > 0:
        edges[0] = (v_edges[r-1][c] == 1)
    # right: h_edges[r][c] if c < N-1
    if c < N-1:
        edges[1] = (h_edges[r][c] == 1)
    # down: v_edges[r][c] if r < N-1
    if r < N-1:
        edges[2] = (v_edges[r][c] == 1)
    # left: h_edges[r][c-1] if c>0
    if c > 0:
        edges[3] = (h_edges[r][c-1] == 1)
    return sum(edges), edges

def propagate_constraints(observation: Dict, h_edges: List[List[int]], v_edges: List[List[int]]) -> Tuple[bool, List[List[int]], List[List[int]]]:
    N = len(observation['data'])
    changed = True
    while changed:
        changed = False
        # 1. Check all nodes edge count constraints
        for r in range(N):
            for c in range(N):
                cnt, edges = count_edges(r, c, h_edges, v_edges, N)
                cell_type = observation['data'][r][c]
                # Clue cells must have exactly 2 edges
                if cell_type is not None:
                    if cnt > 2:
                        return False, h_edges, v_edges
                    # If we have 2 edges, all others must be 0
                    if cnt == 2:
                        for d in range(4):
                            if not edges[d]:
                                nr, nc = get_neighbor(r, c, d, N)
                                if nr is None:
                                    continue
                                if d in [0, 2]:  # vertical edge
                                    er = min(r, nr)
                                    ec = c
                                    if v_edges[er][ec] == 2:
                                        v_edges[er][ec] = 0
                                        changed = True
                                else:  # horizontal edge
                                    er = r
                                    ec = min(c, nc)
                                    if h_edges[er][ec] == 2:
                                        h_edges[er][ec] = 0
                                        changed = True
                else:
                    # Non-clue cells can have 0 or 2 edges
                    if cnt > 2:
                        return False, h_edges, v_edges
                    if cnt == 1:
                        # Must have exactly one more edge possible
                        possible = []
                        for d in range(4):
                            if not edges[d]:
                                nr, nc = get_neighbor(r, c, d, N)
                                if nr is None:
                                    continue
                                if d in [0,2]:
                                    er = min(r, nr)
                                    ec = c
                                    if v_edges[er][ec] == 2:
                                        possible.append((d, nr, nc))
                                else:
                                    er = r
                                    ec = min(c, nc)
                                    if h_edges[er][ec] == 2:
                                        possible.append((d, nr, nc))
                        if len(possible) == 0:
                            return False, h_edges, v_edges
                        if len(possible) == 1:
                            d, nr, nc = possible[0]
                            if d in [0,2]:
                                er = min(r, nr)
                                ec = c
                                v_edges[er][ec] = 1
                            else:
                                er = r
                                ec = min(c, nc)
                                h_edges[er][ec] = 1
                            changed = True
                    if cnt == 2:
                        # All other edges must be 0
                        for d in range(4):
                            if not edges[d]:
                                nr, nc = get_neighbor(r, c, d, N)
                                if nr is None:
                                    continue
                                if d in [0,2]:
                                    er = min(r, nr)
                                    ec = c
                                    if v_edges[er][ec] == 2:
                                        v_edges[er][ec] = 0
                                        changed = True
                                else:
                                    er = r
                                    ec = min(c, nc)
                                    if h_edges[er][ec] == 2:
                                        h_edges[er][ec] = 0
                                        changed = True
        # 2. Apply W cell constraints
        for r in range(N):
            for c in range(N):
                if observation['data'][r][c] != 'W':
                    continue
                cnt, edges = count_edges(r, c, h_edges, v_edges, N)
                # W must be straight: either horizontal (left+right) or vertical (up+down)
                if cnt >= 1:
                    has_up = edges[0]
                    has_down = edges[2]
                    has_left = edges[3]
                    has_right = edges[1]
                    if has_up or has_down:
                        # Must be vertical, so left and right must be 0
                        if c > 0 and h_edges[r][c-1] == 2:
                            h_edges[r][c-1] = 0
                            changed = True
                        if c < N-1 and h_edges[r][c] == 2:
                            h_edges[r][c] = 0
                            changed = True
                        # Need both up and down
                        if has_up and r < N-1 and v_edges[r][c] == 2:
                            v_edges[r][c] = 1
                            changed = True
                        if has_down and r > 0 and v_edges[r-1][c] == 2:
                            v_edges[r-1][c] = 1
                            changed = True
                    if has_left or has_right:
                        # Must be horizontal, up and down 0
                        if r > 0 and v_edges[r-1][c] == 2:
                            v_edges[r-1][c] = 0
                            changed = True
                        if r < N-1 and v_edges[r][c] == 2:
                            v_edges[r][c] = 0
                            changed = True
                        # Need both left and right
                        if has_left and c < N-1 and h_edges[r][c] == 2:
                            h_edges[r][c] = 1
                            changed = True
                        if has_right and c > 0 and h_edges[r][c-1] == 2:
                            h_edges[r][c-1] = 1
                            changed = True
        # 3. Apply B cell constraints
        for r in range(N):
            for c in range(N):
                if observation['data'][r][c] != 'B':
                    continue
                cnt, edges = count_edges(r, c, h_edges, v_edges, N)
                # B must turn, so no opposite directions
                if edges[0] and edges[2]:
                    return False, h_edges, v_edges
                if edges[1] and edges[3]:
                    return False, h_edges, v_edges
                # If have one direction, the other must be perpendicular
                if cnt == 1:
                    dir_in = None
                    for d in range(4):
                        if edges[d]:
                            dir_in = d
                            break
                    # Other direction must be one of perpendicular
                    allowed = PERPENDICULAR[dir_in]
