                            if d in [0,2]:
                                er = min(r, nr)
                                ec = c
                                if v_edges[er][ec] == 2:
                                    v_edges[er][ec] = 0
                                    changed = True
                            else:
                                er = r
                                ec = min(c, nc)
                                if h_edges[er][ec] == 2:
                                    h_edges[er][ec] = 0
                                    changed = True
                    # Also, straight in direction for at least 2 steps
                    dr, dc = DIRS[dir_in]
                    prev_r, prev_c = r + dr, c + dc
                    if prev_r <0 or prev_r >=N or prev_c <0 or prev_c >=N:
                        return False, h_edges, v_edges
                    prev2_r, prev2_c = prev_r + dr, prev_c + dc
                    if prev2_r <0 or prev2_r >=N or prev2_c <0 or prev2_c >=N:
                        return False, h_edges, v_edges
                    # Edge between prev and prev2 must exist
                    if dir_in in [0, 2]:
                        er = min(prev_r, prev2_r)
                        ec = prev_c
                        if v_edges[er][ec] == 2:
                            v_edges[er][ec] = 1
                            changed = True
                        elif v_edges[er][ec] == 0:
                            return False, h_edges, v_edges
                    else:
                        er = prev_r
                        ec = min(prev_c, prev2_c)
                        if h_edges[er][ec] == 2:
                            h_edges[er][ec] = 1
                            changed = True
                        elif h_edges[er][ec] == 0:
                            return False, h_edges, v_edges
    return True, h_edges, v_edges

def build_path(h_edges: List[List[int]], v_edges: List[List[int]], N: int) -> Optional[List[Tuple[int, int]]]:
    # Find start point (any edge)
    start = None
    for r in range(N):
        for c in range(N-1):
            if h_edges[r][c] == 1:
                start = (r, c)
                break
        if start:
            break
    if not start:
        return None
    path = [start]
    prev = None
    current = start
    while True:
        r, c = current
        next_points = []
        # Check right
        if c < N-1 and h_edges[r][c] == 1:
            p = (r, c+1)
            if p != prev:
                next_points.append(p)
        # Check left
        if c > 0 and h_edges[r][c-1] == 1:
            p = (r, c-1)
            if p != prev:
                next_points.append(p)
        # Check down
        if r < N-1 and v_edges[r][c] == 1:
            p = (r+1, c)
            if p != prev:
                next_points.append(p)
        # Check up
        if r > 0 and v_edges[r-1][c] == 1:
            p = (r-1, c)
            if p != prev:
                next_points.append(p)
        if len(next_points) != 1:
            return None
        next_p = next_points[0]
        if next_p == start:
            path.append(next_p)
            break
        path.append(next_p)
        prev = current
        current = next_p
    # Check path is closed and covers all clues? We will do that later
    return path

def check_all_clues_included(observation: Dict, path: List[Tuple[int, int]]) -> bool:
    N = len(observation['data'])
    clues = set()
    for r in range(N):
        for c in range(N):
            if observation['data'][r][c] is not None:
                clues.add((r,c))
    path_set = set(path)
    return clues.issubset(path_set)

def check_clue_rules(observation: Dict, path: List[Tuple[int, int]]) -> bool:
    N = len(observation['data'])
    # Create position to index map
    pos_idx = {pos:i for i, pos in enumerate(path)}
    for r in range(N):
        for c in range(N):
            t = observation['data'][r][c]
            if t is None:
                continue
            if (r,c) not in pos_idx:
                return False
            i = pos_idx[(r,c)]
            prev = path[i-1]
            curr = path[i]
            next_p = path[i+1]
            # Get directions
            dir_in = (curr[0] - prev[0], curr[1] - prev[1])
            dir_out = (next_p[0] - curr[0], next_p[1] - curr[1])
            if t == 'W':
                # Must be straight
                if dir_in != (-dir_out[0], -dir_out[1]):
                    return False
                # Must turn in previous or next step
                prev_prev = path[i-2]
                dir_prev = (prev[0] - prev_prev[0], prev[1] - prev_prev[1])
                next_next = path[(i+2) % len(path)]
                dir_next = (next_next[0] - next_p[0], next_next[1] - next_p[1])
                if dir_prev == dir_in and dir_out == dir_next:
                    return False
            elif t == 'B':
                # Must turn, so directions not opposite, not same
                if dir_in == (-dir_out[0], -dir_out[1]) or dir_in == dir_out:
                    return False
                # Must be straight in both previous and next steps
                prev_prev = path[i-2]
                dir_prev = (prev[0] - prev_prev[0], prev[1] - prev_prev[1])
                if dir_prev != dir_in:
                    return False
                next_next = path[(i+2) % len(path)]
                dir_next = (next_next[0] - next_p[0], next_next[1] - next_p[1])
                if dir_next != dir_out:
                    return False
    return True

def backtrack(observation: Dict, h_edges: List[List[int]], v_edges: List[List[int]]) -> Optional[List[Tuple[int, int]]]:
    N = len(observation['data'])
    # Propagate constraints first
    valid, h, v = propagate_constraints(observation, [row[:] for row in h_edges], [row[:] for row in v_edges])
    if not valid:
        return None
    # Check if all edges are determined
    all_known = True
    guess_candidate = None
    min_unknown = float('inf')
    # Find best edge to guess: edge adjacent to most clues, or least options
    for r in range(N):
        for c in range(N-1):
            if h[r][c] == 2:
                all_known = False
                # Count adjacent clues
                cnt = 0
                if observation['data'][r][c] is not None:
                    cnt +=1
                if observation['data'][r][c+1] is not None:
                    cnt +=1
                if cnt > 0 or (guess_candidate is None):
                    guess_candidate = ('h', r, c)
                    if cnt > 0:
                        break
        if guess_candidate and 'cnt' in locals() and cnt>0:
            break
    if all_known:
        for r in range(N-1):
            for c in range(N):
                if v[r][c] == 2:
                    all_known = False
                    cnt = 0
                    if observation['data'][r][c] is not None:
                        cnt +=1
                    if observation['data'][r+1][c] is not None:
                        cnt +=1
                    if cnt>0 or guess_candidate is None:
                        guess_candidate = ('v', r, c)
                        if cnt>0:
                            break
            if guess_candidate and 'cnt' in locals() and cnt>0:
                break
    if all_known:
        # Build path and check
        path = build_path(h, v, N)
        if path is None:
            return None
        if not check_all_clues_included(observation, path):
            return None
        if not check_clue_rules(observation, path):
            return None
        return path
    # If no candidate found, pick any unknown edge
    if guess_candidate is None:
        for r in range(N):
            for c in range(N-1):
                if h[r][c] == 2:
                    guess_candidate = ('h', r, c)
                    break
            if guess_candidate:
                break
        if guess_candidate is None:
            for r in range(N-1):
                for c in range(N):
                    if v[r][c] == 2:
                        guess_candidate = ('v', r, c)
                        break
                if guess_candidate:
                    break
    # Try setting to 1 first
    typ, r, c = guess_candidate
    new_h = [row[:] for row in h]
    new_v = [row[:] for row in v]
    if typ == 'h':
        new_h[r][c] = 1
    else:
        new_v[r][c] = 1
    res = backtrack(observation, new_h, new_v)
    if res is not None:
        return res
    # Try setting to 0
    new_h = [row[:] for row in h]
    new_v = [row[:] for row in v]
    if typ == 'h':
        new_h[r][c] = 0
    else:
        new_v[r][c] = 0
    return backtrack(observation, new_h, new_v)

def solve(observation: Dict) -> List[Tuple[int, int]] | str:
    N = len(observation['data'])
    # Initialize edges: 2 = unknown, 0 = no, 1 = yes
    h_edges = [[2]*(N-1) for _ in range(N)]
    v_edges = [[2]*N for _ in range(N-1)]
    result = backtrack(observation, h_edges, v_edges)
    if result is None:
        return "No Solution"
    return result

