from copy import deepcopy

def solve(observation):
    rows = len(observation['tree'])
    cols = len(observation['tree'][0]) if rows else 0
    trees = [(r, c) for r in range(rows) for c in range(cols) if observation['tree'][r][c] == 'T']
    total_tents = sum(observation['row_tent_counts'])

    # Quick validity check: 1:1 tree to tent ratio
    if len(trees) != total_tents or sum(observation['col_tent_counts']) != total_tents:
        return "No Solution"

    # Initialize grid: None = unknown, 'T' = tree, 'X' = blocked, 't' = tent
    grid = deepcopy(observation['tree'])
    row_remaining = deepcopy(observation['row_tent_counts'])
    col_remaining = deepcopy(observation['col_tent_counts'])

    # Step 1: Mark rows/columns with 0 required tents as fully blocked
    for r in range(rows):
        if row_remaining[r] == 0:
            for c in range(cols):
                if grid[r][c] is None:
                    grid[r][c] = 'X'
    for c in range(cols):
        if col_remaining[c] == 0:
            for r in range(rows):
                if grid[r][c] is None:
                    grid[r][c] = 'X'

    # Helper to get valid adjacent tent candidates for a tree
    def get_tree_candidates(tr, tc):
        candidates = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = tr + dr, tc + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] is None:
                candidates.append((nr, nc))
        return candidates

    # Deduction loop: apply deterministic rules until no more changes
    def apply_deductions():
        changed = True
        while changed:
            changed = False
            # Update candidate lists for all trees
            tree_candidates = {t: get_tree_candidates(*t) for t in trees if grid[t[0]][t[1]] == 'T'}
            # Rule 1: Tree with exactly 1 candidate must have tent there
            for (tr, tc), candidates in tree_candidates.items():
                if len(candidates) == 1:
                    r, c = candidates[0]
                    if not place_tent(r, c):
                        return False
                    changed = True
                    break
            if changed:
                continue
            # Rule 2: Row has exactly N remaining spots for N remaining tents
            for r in range(rows):
                if row_remaining[r] <= 0:
                    continue
                possible = [c for c in range(cols) if grid[r][c] is None]
                if len(possible) == row_remaining[r]:
                    for c in possible:
                        if not place_tent(r, c):
                            return False
                    changed = True
                    break
            if changed:
                continue
            # Rule 3: Column has exactly N remaining spots for N remaining tents
            for c in range(cols):
                if col_remaining[c] <= 0:
                    continue
                possible = [r for r in range(rows) if grid[r][c] is None]
                if len(possible) == col_remaining[c]:
                    for r in possible:
                        if not place_tent(r, c):
                            return False
                    changed = True
                    break
        return True

    # Helper to place a tent and apply constraints
    def place_tent(r, c):
        if grid[r][c] is not None or row_remaining[r] <= 0 or col_remaining[c] <= 0:
            return False
        # Check no adjacent tents
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 't':
                    return False
        # Place tent
        grid[r][c] = 't'
        row_remaining[r] -= 1
        col_remaining[c] -= 1
        # Block all 8 adjacent cells
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] is None:
                    grid[nr][nc] = 'X'
        # Block entire row/column if no more tents needed
        if row_remaining[r] == 0:
            for cc in range(cols):
                if grid[r][cc] is None:
                    grid[r][cc] = 'X'
        if col_remaining[c] == 0:
            for rr in range(rows):
                if grid[rr][c] is None:
                    grid[rr][c] = 'X'
        return True

    # Run initial deductions
    if not apply_deductions():
        return "No Solution"

    # Check if already solved
    if all(cnt == 0 for cnt in row_remaining) and all(cnt == 0 for cnt in col_remaining):
        return [[cell if cell == 't' else None for cell in row] for row in grid]

    # Backtracking search for remaining positions
    def backtrack():
        # Update candidate lists
        unpaired = []
        for t in trees:
            tr, tc = t
            cand = get_tree_candidates(tr, tc)
            if cand:
                unpaired.append((len(cand), t, cand))
        if not unpaired:
            # All trees paired, check if all counts are 0
            if all(cnt == 0 for cnt in row_remaining) and all(cnt == 0 for cnt in col_remaining):
                return [[cell if cell == 't' else None for cell in row] for row in grid]
            return None
        # Pick tree with least candidates to minimize branching
        unpaired.sort()
        _, (tr, tc), candidates = unpaired[0]
        for (r, c) in candidates:
            # Save state
            old_grid = deepcopy(grid)
            old_row = deepcopy(row_remaining)
            old_col = deepcopy(col_remaining)
            if place_tent(r, c):
                if apply_deductions():
                    res = backtrack()
                    if res is not None:
                        return res
            # Restore state
            grid[:] = old_grid
            row_remaining[:] = old_row
            col_remaining[:] = old_col
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

