def generate_subsets(target, max_idx):
    subsets = []
    def backtrack(start, current_sum, path):
        if current_sum == target:
            subsets.append(set(path))
            return
        if current_sum > target or start > max_idx:
            return
        backtrack(start + 1, current_sum + start, path + [start])
        backtrack(start + 1, current_sum, path)
    backtrack(0, 0, [])
    return subsets

def solve(observation):
