            # Step 1: Deduce mandatory cells from row possible subsets
            for r in range(n_rows):
                if not row_p[r]:
                    return None
                common_b = set.intersection(*row_p[r])
                common_non_b = set(range(n_cols)) - set.union(*row_p[r])
                for c in common_b:
                    if grid[r][c] is None:
                        return None
                    if grid[r][c] == '?':
                        grid[r][c] = 'B'
                        changed = True
                for c in common_non_b:
                    if grid[r][c] == 'B':
                        return None
                    if grid[r][c] == '?':
                        grid[r][c] = None
                        changed = True
            # Step 2: Deduce mandatory cells from column possible subsets
            for c in range(n_cols):
                if not col_p[c]:
                    return None
                common_b = set.intersection(*col_p[c])
                common_non_b = set(range(n_rows)) - set.union(*col_p[c])
                for r in common_b:
                    if grid[r][c] is None:
                        return None
                    if grid[r][c] == '?':
                        grid[r][c] = 'B'
                        changed = True
                for r in common_non_b:
                    if grid[r][c] == 'B':
                        return None
                    if grid[r][c] == '?':
                        grid[r][c] = None
                        changed = True
            # Step 3: Prune invalid row subsets
            for r in range(n_rows):
                new_subsets = []
                for s in row_p[r]:
                    valid = True
                    for c in range(n_cols):
                        if grid[r][c] == 'B' and c not in s:
