                if not new_subsets:
                    return None
                if len(new_subsets) != len(row_p[r]):
                    changed = True
                    row_p[r] = new_subsets
            # Step 4: Prune invalid column subsets
            for c in range(n_cols):
                new_subsets = []
                for s in col_p[c]:
