                is_row = True
                idx = r
        for c in range(n_cols):
            if 1 < len(col_p[c]) < min_opt:
                min_opt = len(col_p[c])
                is_row = False
                idx = c
        # Branch on selected variable
        if is_row:
            r = idx
            for subset in row_p[r]:
                new_grid = [row.copy() for row in grid]
                new_rp = [s.copy() for s in row_p]
                new_cp = [s.copy() for s in col_p]
