                res = backtrack(new_grid, new_rp, new_cp)
                if res is not None:
                    return res
        else:
            c = idx
            for subset in col_p[c]:
                new_grid = [row.copy() for row in grid]
                new_rp = [s.copy() for s in row_p]
                new_cp = [s.copy() for s in col_p]
                for r in range(n_rows):
                    new_grid[r][c] = 'B' if r in subset else None
                res = backtrack(new_grid, new_rp, new_cp)
                if res is not None:
                    return res
        return None

    result = backtrack(grid, row_possible, col_possible)
    return result if result is not None else "No Solution"

