OBSERVATION = {'data': [[3, None, None, 3, None], [None, None, 1, None, None], [None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None]]}

from copy import deepcopy

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def is_valid(r, c, rows, cols):
    return 0 <= r < rows and 0 <= c < cols

def flood_fill(grid, r, c, target, rows, cols):
    visited = set()
    stack = [(r, c)]
    visited.add((r, c))
    while stack:
        cr, cc = stack.pop()
        for dr, dc in DIRS:
            nr, nc = cr + dr, cc + dc
            if is_valid(nr, nc, rows, cols) and (nr, nc) not in visited and grid[nr][nc] == target:
                visited.add((nr, nc))
                stack.append((nr, nc))
    return visited

def check_2x2(grid, rows, cols):
    for r in range(rows - 1):
        for c in range(cols - 1):
            cells = [grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]]
            if cells.count('B') == 4:
                return False
    return True

def check_black_connectivity(grid, rows, cols):
    black_cells = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 'B']
    if not black_cells:
        return True
    connected = flood_fill(grid, black_cells[0][0], black_cells[0][1], 'B', rows, cols)
    return len(connected) == len(black_cells)

def check_islands(grid, num_pos, rows, cols):
    assigned = set()
    for (r, c, s) in num_pos:
        if grid[r][c] != 'W':
            return False
        island = flood_fill(grid, r, c, 'W', rows, cols)
        if len(island) != s:
            return False
        for cell in island:
            if cell in assigned:
                return False
            assigned.add(cell)
    all_white = {(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 'W'}
    return assigned == all_white

def propagate_constraints(grid, num_pos, rows, cols):
    changed = True
    num_map = {(r,c): s for r,c,s in num_pos}
    while changed:
        changed = False
        if not check_2x2(grid, rows, cols):
            return False
        if not check_black_connectivity(grid, rows, cols):
            return False

        for r in range(rows - 1):
            for c in range(cols - 1):
                cells = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
                b_count = sum(1 for (cr,cc) in cells if grid[cr][cc] == 'B')
                none_cells = [(cr,cc) for (cr,cc) in cells if grid[cr][cc] is None]
                if b_count == 3 and len(none_cells) == 1:
                    nr, nc = none_cells[0]
                    if (nr, nc) in num_map:
                        pass
                    else:
                        grid[nr][nc] = 'W'
                        changed = True

        for (r,c,s) in num_pos:
            island = flood_fill(grid, r, c, 'W', rows, cols)
            current_size = len(island)
            if current_size > s:
                return False
            if current_size == s:
                for (cr, cc) in island:
                    for dr, dc in DIRS:
                        nr, nc = cr + dr, cc + dc
                        if is_valid(nr, nc, rows, cols) and grid[nr][nc] is None and (nr, nc) not in num_map:
                            grid[nr][nc] = 'B'
                            changed = True

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is None and (r,c) not in num_map:
                    reachable = []
                    for (nr, nc, s) in num_pos:
                        visited = set()
                        stack = [(r,c)]
                        found = False
                        while stack:
                            cr, cc = stack.pop()
                            if (cr, cc) == (nr, nc):
                                found = True
                                break
                            if (cr, cc) in visited:
                                continue
                            visited.add((cr, cc))
                            for dr, dc in DIRS:
                                ncr, ncc = cr + dr, cc + dc
                                if is_valid(ncr, ncc, rows, cols) and grid[ncr][ncc] != 'B' and (ncr, ncc) not in visited:
                                    stack.append((ncr, ncc))
                        if found:
                            reachable.append((nr, nc, s))
                    if not reachable:
                        grid[r][c] = 'B'
                        changed = True
                    elif len(reachable) == 1:
                        nr, nc, s = reachable[0]
                        island_size = len(flood_fill(grid, nr, nc, 'W', rows, cols))
                        if island_size < s:
                            grid[r][c] = 'W'
                            changed = True

        if not check_2x2(grid, rows, cols) or not check_black_connectivity(grid, rows, cols):
            return False
    return True

def backtrack(grid, num_pos, rows, cols):
    if not propagate_constraints(grid, num_pos, rows, cols):
        return None

    complete = all(cell is not None for row in grid for cell in row)
    if complete:
        if check_islands(grid, num_pos, rows, cols) and check_2x2(grid, rows, cols) and check_black_connectivity(grid, rows, cols):
            return [[cell if cell == 'B' else None for cell in row] for row in grid]
        return None

    min_options = 3
    best_cell = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None and (r,c) not in {(nr,nc) for nr,nc,_ in num_pos}:
                options = 0
                temp_grid = deepcopy(grid)
                temp_grid[r][c] = 'B'
                if propagate_constraints(temp_grid, num_pos, rows, cols):
                    options += 1
                temp_grid = deepcopy(grid)
                temp_grid[r][c] = 'W'
                if propagate_constraints(temp_grid, num_pos, rows, cols):
                    options += 1
                if options < min_options:
                    min_options = options
                    best_cell = (r,c)
                    if min_options == 0:
                        return None
                    if min_options == 1:
                        break
        if best_cell and min_options == 1:
            break

    if not best_cell:
        return None

    r, c = best_cell
    for val in ['B', 'W']:
        new_grid = deepcopy(grid)
        new_grid[r][c] = val
        res = backtrack(new_grid, num_pos, rows, cols)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    num_pos = []
    grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                num_pos.append((r, c, data[r][c]))
                grid[r][c] = 'W'

    for (r,c,s) in num_pos:
        if s == 1:
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc, rows, cols):
                    grid[nr][nc] = 'B'

    return backtrack(grid, num_pos, rows, cols)

if __name__ == "__main__":
    print(solve(OBSERVATION))
