    N = len(data)
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Precompute region cells
    region_cells = {}
    for r in range(N):
        for c in range(N):
            rid = data[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    def propagate(grid):
        # Make mutable copy to modify
        grid = [row[:] for row in grid]
        region_s = {rid: 0 for rid in region_cells}
        for rid in region_cells:
            cnt = 0
            for (r, c) in region_cells[rid]:
                if grid[r][c] == 'S':
                    cnt += 1
            region_s[rid] = cnt

        changed = True
        while changed:
            changed = False

            # Process region constraints first
            for rid in region_cells:
                s_cnt = region_s[rid]
                if s_cnt > 2:
                    return (False, None)
                # Count available cells (non-X)
                available = []
                for (r, c) in region_cells[rid]:
                    if grid[r][c] != 'X':
                        available.append((r, c))
                if len(available) < (2 - s_cnt):
                    return (False, None)
                # Rule 1: All required cells must be S
                if len(available) == (2 - s_cnt) and (2 - s_cnt) > 0:
                    for (r, c) in available:
                        if grid[r][c] is None:
                            grid[r][c] = 'S'
                            region_s[rid] += 1
                            changed = True
                # Rule 2: Region full, mark rest X
                if s_cnt == 2:
                    for (r, c) in region_cells[rid]:
                        if grid[r][c] is None:
                            grid[r][c] = 'X'
                            changed = True

            # Process S cell constraints
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'S':
                        s_neighbors = []
                        possible_neighbors = []
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if grid[nr][nc] == 'S':
                                    s_neighbors.append((nr, nc))
                                elif grid[nr][nc] is None:
                                    possible_neighbors.append((nr, nc))
                        # Too many S neighbors
                        if len(s_neighbors) > 1:
                            return (False, None)
                        # Has domino partner, mark all other adjacent cells X
                        if len(s_neighbors) == 1:
                            pr, pc = s_neighbors[0]
                            for dr, dc in dirs:
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < N and 0 <= nc < N:
                                    if (nr, nc) != (pr, pc) and grid[nr][nc] is None:
                                        grid[nr][nc] = 'X'
                                        changed = True
                        # No partner yet, only one possible, mark it S
                        if len(s_neighbors) == 0:
                            if not possible_neighbors:
                                return (False, None)
                            if len(possible_neighbors) == 1:
                                nr, nc = possible_neighbors[0]
                                grid[nr][nc] = 'S'
                                region_s[data[nr][nc]] += 1
                                changed = True

        # Check if solved
        solved = True
        for rid in region_cells:
            if region_s[rid] != 2:
                solved = False
                break
        if solved:
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'S':
                        cnt = 0
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] == 'S':
                                cnt += 1
                        if cnt != 1:
                            solved = False
                            break
                if not solved:
                    break
        if solved:
            # Convert to output format
            res = []
            for r in range(N):
                row = []
                for c in range(N):
                    row.append('S' if grid[r][c] == 'S' else None)
                res.append(row)
            return (True, res)
        return (True, grid)

    def backtrack(grid):
        valid, res = propagate(grid)
        if not valid:
            return None
        if isinstance(res[0][0], str) or res[0][0] is None and all(isinstance(x, (str, type(None))) for x in res[0]):
            # Check if it's the solution
            if all(('S' in row for row in res)):
                return res
        current_grid = res

        # Collect all possible domino candidates
        candidates = []
        seen = set()
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None and (r, c) not in seen:
                    # Check right neighbor
                    if c + 1 < N and current_grid[r][c+1] is None:
                        # Check if placing domino here is allowed
                        rid1 = data[r][c]
                        rid2 = data[r][c+1]
                        s1 = sum(1 for (x,y) in region_cells[rid1] if current_grid[x][y] == 'S')
                        s2 = sum(1 for (x,y) in region_cells[rid2] if current_grid[x][y] == 'S')
                        if s1 < 2 and s2 < 2:
                            candidates.append(((r,c), (r, c+1)))
                            seen.add((r,c))
                            seen.add((r,c+1))
                    # Check down neighbor
                    if r + 1 < N and current_grid[r+1][c] is None:
                        rid1 = data[r][c]
                        rid2 = data[r+1][c]
                        s1 = sum(1 for (x,y) in region_cells[rid1] if current_grid[x][y] == 'S')
                        s2 = sum(1 for (x,y) in region_cells[rid2] if current_grid[x][y] == 'S')
                        if s1 < 2 and s2 < 2:
                            candidates.append(((r,c), (r+1, c)))
                            seen.add((r,c))
                            seen.add((r+1,c))

        # Sort candidates by MRV heuristic (least options first)
        candidates.sort(key=lambda x: len(x))

        for (a, b) in candidates:
            r1, c1 = a
            r2, c2 = b
            new_grid = [row[:] for row in current_grid]
            new_grid[r1][c1] = 'S'
            new_grid[r2][c2] = 'S'
            solution = backtrack(new_grid)
            if solution is not None:
                return solution
        return None

    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    solution = backtrack(initial_grid)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
