from copy import deepcopy

def generate_subsets(items, target, weight_func):
    subsets = []
    n = len(items)
    def backtrack(idx, current_sum, current_subset):
        if current_sum == target:
            subsets.append(frozenset(current_subset))
            return
        if idx >= n or current_sum > target:
            return
        w = weight_func(items[idx])
        if current_sum + w <= target:
            current_subset.append(items[idx])
            backtrack(idx + 1, current_sum + w, current_subset)
            current_subset.pop()
        backtrack(idx + 1, current_sum, current_subset)
    backtrack(0, 0, [])
    return subsets

def propagate(row_possible, col_possible, rows, cols):
    changed = True
    while changed:
        changed = False
        possible = [[False]*cols for _ in range(rows)]
        for r in range(rows):
            allowed_cols = set()
            for s in row_possible[r]:
                allowed_cols.update(s)
            for c in allowed_cols:
                possible[r][c] = True
        for c in range(cols):
            new_subsets = []
            for s in col_possible[c]:
                valid = True
                for r in s:
                    if not possible[r][c]:
                        valid = False
                        break
                if valid:
                    new_subsets.append(s)
            if len(new_subsets) != len(col_possible[c]):
                changed = True
                col_possible[c] = new_subsets
                if not col_possible[c]:
                    return False, row_possible, col_possible
        possible = [[False]*cols for _ in range(rows)]
        for c in range(cols):
            allowed_rows = set()
            for s in col_possible[c]:
                allowed_rows.update(s)
            for r in allowed_rows:
                possible[r][c] = True
        for r in range(rows):
            new_subsets = []
            for s in row_possible[r]:
                valid = True
                for c in s:
                    if not possible[r][c]:
                        valid = False
                        break
                if valid:
                    new_subsets.append(s)
            if len(new_subsets) != len(row_possible[r]):
                changed = True
                row_possible[r] = new_subsets
                if not row_possible[r]:
                    return False, row_possible, col_possible
    return True, row_possible, col_possible

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    rows = len(row_sum)
    cols = len(col_sum)
    row_weights = [r+1 for r in range(rows)]
    col_weights = [c+1 for c in range(cols)]

    row_possible = []
    for r in range(rows):
        subsets = generate_subsets(list(range(cols)), row_sum[r], lambda c: col_weights[c])
        if not subsets:
            return "No Solution"
        row_possible.append(subsets)

    col_possible = []
    for c in range(cols):
        subsets = generate_subsets(list(range(rows)), col_sum[c], lambda r: row_weights[r])
        if not subsets:
            return "No Solution"
        col_possible.append(subsets)

    valid, row_possible, col_possible = propagate(row_possible, col_possible, rows, cols)
    if not valid:
        return "No Solution"

    def backtrack(assigned_rows, col_current_sum, col_used_rows, current_row_possible):
        if len(assigned_rows) == rows:
            for c in range(cols):
                if col_current_sum[c] != col_sum[c]:
                    return None
            grid = [[None]*cols for _ in range(rows)]
            for r in range(rows):
                for s in current_row_possible[r]:
                    if len(current_row_possible[r]) == 1:
                        for c in s:
                            grid[r][c] = 'B'
            return grid

        unassigned = [r for r in range(rows) if r not in assigned_rows]
        r = min(unassigned, key=lambda x: len(current_row_possible[x]))

        for subset in current_row_possible[r]:
            valid_subset = True
            for c in subset:
                if col_current_sum[c] + row_weights[r] > col_sum[c]:
                    valid_subset = False
                    break
            if not valid_subset:
                continue

            temp_col_sum = deepcopy(col_current_sum)
            temp_col_used = deepcopy(col_used_rows)
            for c in subset:
                temp_col_sum[c] += row_weights[r]
                temp_col_used[c].add(r)

            temp_row_possible = deepcopy(current_row_possible)
            for c in range(cols):
                if temp_col_sum[c] == col_sum[c]:
                    for other_r in range(rows):
                        if other_r == r or other_r in assigned_rows:
                            continue
                        temp_row_possible[other_r] = [s for s in temp_row_possible[other_r] if c not in s]
                        if not temp_row_possible[other_r]:
                            valid_subset = False
                            break
                if temp_col_sum[c] > col_sum[c]:
                    valid_subset = False
                    break
            if not valid_subset:
                continue

            ok, _, _ = propagate(temp_row_possible, deepcopy(col_possible), rows, cols)
            if not ok:
                continue

            temp_row_possible[r] = [subset]
            res = backtrack(assigned_rows.union({r}), temp_col_sum, temp_col_used, temp_row_possible)
            if res is not None:
                return res
        return None

    initial_col_sum = [0]*cols
    initial_col_used = [set() for _ in range(cols)]
    result = backtrack(set(), initial_col_sum, initial_col_used, deepcopy(row_possible))
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
