from collections import deque
import copy

def get_ortho_neighbors(r, c, rows, cols):
    res = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            res.append((nr, nc))
    return res

def count_b(grid, rows, cols):
    cnt = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'B':
                cnt += 1
    return cnt

def is_b_connected(grid, rows, cols):
    total_b = count_b(grid, rows, cols)
    if total_b == 0:
        return True
    start = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'B':
                start = (r, c)
                break
        if start:
            break
    visited = set()
    q = deque([start])
    visited.add(start)
    while q:
        r, c = q.popleft()
        for nr, nc in get_ortho_neighbors(r, c, rows, cols):
            if grid[nr][nc] == 'B' and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == total_b

def has_2x2_all_b(grid, rows, cols):
    for r in range(rows - 1):
        for c in range(cols - 1):
            if grid[r][c] == 'B' and grid[r][c+1] == 'B' and grid[r+1][c] == 'B' and grid[r+1][c+1] == 'B':
                return True
    return False

def propagate(grid, assignment, islands, rows, cols, data):
    modified = True
    while modified:
        modified = False
        if has_2x2_all_b(grid, rows, cols):
            return (False, modified)
        if count_b(grid, rows, cols) > 0 and not is_b_connected(grid, rows, cols):
            return (False, modified)

        for (nr, nc), (target_size, cells) in islands.items():
            if len(cells) == target_size:
                for (r, c) in cells:
                    for (nr_n, nc_n) in get_ortho_neighbors(r, c, rows, cols):
                        if grid[nr_n][nc_n] is None:
                            grid[nr_n][nc_n] = 'B'
                            modified = True
                        elif grid[nr_n][nc_n] == 'W' and assignment[nr_n][nc_n] != (nr, nc):
                            return (False, modified)

        for r in range(rows - 1):
            for c in range(cols - 1):
                b_count = 0
                unknown = None
                valid = True
                for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                    cell = grid[r+dr][c+dc]
                    if cell == 'B':
                        b_count +=1
                    elif cell is None:
                        if unknown is None:
                            unknown = (r+dr, c+dc)
                        else:
                            valid = False
                            break
                if valid and b_count == 3 and unknown is not None:
                    ur, uc = unknown
                    if grid[ur][uc] is None:
                        grid[ur][uc] = 'W'
                        modified = True

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != 'W' or assignment[r][c] is not None:
                    continue
                adjacent_islands = set()
                for (nr, nc) in get_ortho_neighbors(r, c, rows, cols):
                    if grid[nr][nc] == 'W' and assignment[nr][nc] is not None:
                        adjacent_islands.add(assignment[nr][nc])
                if len(adjacent_islands) == 0:
                    return (False, modified)
                if len(adjacent_islands) > 1:
                    return (False, modified)
                isl = adjacent_islands.pop()
                target_size, isl_cells = islands[isl]
                if len(isl_cells) + 1 > target_size:
                    return (False, modified)
                assignment[r][c] = isl
                isl_cells.add((r,c))
                modified = True

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is not None:
                    continue
                adjacent_islands = set()
                for (nr, nc) in get_ortho_neighbors(r, c, rows, cols):
                    if grid[nr][nc] == 'W' and assignment[nr][nc] is not None:
                        adjacent_islands.add(assignment[nr][nc])
                if len(adjacent_islands) != 1:
                    continue
                isl = adjacent_islands.pop()
                target_size, isl_cells = islands[isl]
                if len(isl_cells) >= target_size:
                    grid[r][c] = 'B'
                    modified = True
                else:
                    grid[r][c] = 'W'
                    assignment[r][c] = isl
                    isl_cells.add((r,c))
                    modified = True

        for (nr, nc), (target_size, cells) in islands.items():
            if len(cells) > target_size:
                return (False, modified)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'W' and assignment[r][c] is None:
