                    for (nr, nc) in get_ortho_neighbors(r, c, rows, cols):
                        if grid[nr][nc] == 'W' and assignment[nr][nc] is not None:
                            adjacent_islands.add(assignment[nr][nc])
                    if len(adjacent_islands) == 0:
                        return (False, modified)
    return (True, modified)

def is_complete(grid, rows, cols):
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                return False
    return True

def check_final(grid, assignment, islands, rows, cols, data):
    if has_2x2_all_b(grid, rows, cols):
        return False
    if not is_b_connected(grid, rows, cols):
        return False
    for (nr, nc), (target_size, cells) in islands.items():
        if len(cells) != target_size:
            return False
    all_white_cells = set()
    for (nr, nc), (target_size, cells) in islands.items():
        for cell in cells:
            if cell in all_white_cells:
                return False
            all_white_cells.add(cell)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'W' and (r,c) not in all_white_cells:
                return False
    return True

def backtrack(grid, assignment, islands, rows, cols, data):
    valid, _ = propagate(grid, assignment, islands, rows, cols, data)
    if not valid:
        return None
    if is_complete(grid, rows, cols):
        if check_final(grid, assignment, islands, rows, cols, data):
            res = []
            for r in range(rows):
                row = []
                for c in range(cols):
                    row.append('B' if grid[r][c] == 'B' else None)
                res.append(row)
            return res
        return None

    min_options = 3
    best_cell = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                options = 0
                temp_grid = copy.deepcopy(grid)
                temp_grid[r][c] = 'B'
                if not has_2x2_all_b(temp_grid, rows, cols):
                    if count_b(temp_grid, rows, cols) == 0 or is_b_connected(temp_grid, rows, cols):
                        options +=1
                temp_grid[r][c] = 'W'
                adj_islands = set()
                for (nr, nc) in get_ortho_neighbors(r, c, rows, cols):
                    if temp_grid[nr][nc] == 'W' and assignment[nr][nc] is not None:
                        adj_islands.add(assignment[nr][nc])
                if len(adj_islands) <= 1:
                    if len(adj_islands) == 1:
                        isl = adj_islands.pop()
                        if len(islands[isl][1]) < islands[isl][0]:
                            options +=1
                if options < min_options:
                    min_options = options
                    best_cell = (r,c)
                    if min_options == 0:
                        return None
    if best_cell is None:
        return None
    r, c = best_cell

    for val in ['B', 'W']:
        new_grid = copy.deepcopy(grid)
        new_assignment = copy.deepcopy(assignment)
        new_islands = copy.deepcopy(islands)
        new_grid[r][c] = val
        if val == 'W':
            adj_islands = set()
            for (nr, nc) in get_ortho_neighbors(r, c, rows, cols):
                if new_grid[nr][nc] == 'W' and new_assignment[nr][nc] is not None:
                    adj_islands.add(new_assignment[nr][nc])
            if len(adj_islands) > 1:
                continue
            if len(adj_islands) == 1:
                isl = adj_islands.pop()
                target_size, cells = new_islands[isl]
                if len(cells) +1 > target_size:
                    continue
                new_assignment[r][c] = isl
                cells.add((r,c))
            else:
                continue
        res = backtrack(new_grid, new_assignment, new_islands, rows, cols, data)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    grid = [[None for _ in range(cols)] for _ in range(rows)]
    assignment = [[None for _ in range(cols)] for _ in range(rows)]
    islands = {}
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                grid[r][c] = 'W'
                assignment[r][c] = (r,c)
                islands[(r,c)] = (data[r][c], set([(r,c)]))

    for (nr, nc), (target_size, cells) in islands.items():
        if target_size == 1:
            for (r, c) in get_ortho_neighbors(nr, nc, rows, cols):
                if grid[r][c] is None:
                    grid[r][c] = 'B'

    return backtrack(grid, assignment, islands, rows, cols, data) or "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
