        return False

    def has_crossing(path, new_edge):
        for i in range(len(path) - 2):
            edge = (path[i], path[i+1])
            if edges_cross(edge, new_edge):
                return True
        return False

    start = None
    for (r, c), val in clues.items():
        if val == 'B':
            start = (r, c)
            break
    if start is None:
        start = next(iter(clues.keys()))

    def backtrack(path, visited, clues_visited):
        current = path[-1]
        if len(path) > 1 and current == start:
            if len(path) < 4 or clues_visited != clue_count:
                return None
            L = len(path)
            for idx in range(L):
                p = path[idx]
                if p not in clues:
                    continue
                val = clues[p]
                prev = path[idx-1]
                next_p = path[(idx+1) % L]
                if val == 'W':
                    if not is_straight(prev, p, next_p):
                        return None
                    prev_prev = path[idx-2]
                    next_next = path[(idx+2) % L]
                    if not (is_turn(prev_prev, prev, p) or is_turn(p, next_p, next_next)):
                        return None
                elif val == 'B':
                    if not is_turn(prev, p, next_p):
                        return None
                    prev_prev = path[idx-2]
                    next_next = path[(idx+2) % L]
                    if not (is_straight(prev_prev, prev, p) and is_straight(p, next_p, next_next)):
                        return None
            return path

        possible_dirs = []
        if len(path) == 1:
            for d in dirs:
                nr, nc = current[0] + d[0], current[1] + d[1]
                if 0 <= nr < N and 0 <= nc < N:
                    possible_dirs.append(d)
        else:
            prev = path[-2]
            in_dir = get_dir(prev, current)
            rev_dir = (-in_dir[0], -in_dir[1])
            current_val = clues.get(current, None)
            if current_val == 'W':
                d = in_dir
                nr, nc = current[0] + d[0], current[1] + d[1]
                if 0 <= nr < N and 0 <= nc < N:
                    possible_dirs.append(d)
            elif current_val == 'B':
                for d in dirs:
                    if d == in_dir or d == rev_dir:
                        continue
                    nr, nc = current[0] + d[0], current[1] + d[1]
                    if 0 <= nr < N and 0 <= nc < N:
                        possible_dirs.append(d)
            else:
                for d in dirs:
                    if d == rev_dir:
                        continue
                    nr, nc = current[0] + d[0], current[1] + d[1]
                    if 0 <= nr < N and 0 <= nc < N:
                        possible_dirs.append(d)

        for d in possible_dirs:
            nr, nc = current[0] + d[0], current[1] + d[1]
            next_p = (nr, nc)
            if next_p in visited and next_p != start:
                continue
            new_edge = (current, next_p)
            if has_crossing(path, new_edge):
                continue
            new_path = path.copy()
            new_path.append(next_p)
            new_visited = visited.copy()
            new_visited.add(next_p)
            new_clues_visited = clues_visited + (1 if next_p in clues else 0)
            res = backtrack(new_path, new_visited, new_clues_visited)
            if res is not None:
                return res
        return None

    result = backtrack([start], set([start]), 1 if start in clues else 0)
    return result if result else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
