    dirs4 = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_valid(pos):
        r, c = pos
        return 0 <= r < R and 0 <= c < C

    def backtrack(sol, row_counts, col_counts, used_trees, possible):
        # Check win condition
        if all(c == 0 for c in row_counts) and all(c ==0 for c in col_counts) and len(used_trees) == len(trees):
            return sol

        # Propagate constraints as much as possible first
        changed = True
        while changed:
            changed = False

            # Check contradictions first
            for r in range(R):
                possible_in_row = sum(1 for c in range(C) if possible[r][c])
                if row_counts[r] > possible_in_row:
