            res = backtrack(new_sol, new_row, new_col, new_used, new_possible)
            if res is not None:
                return res

        return None

    # Initialize state
    initial_sol = [[None for _ in range(C)] for _ in range(R)]
    initial_row = deepcopy(original_row_counts)
    initial_col = deepcopy(original_col_counts)
    initial_used = set()
    initial_possible = [[True for _ in range(C)] for _ in range(R)]

    # Mark impossible cells initially
    for r in range(R):
        if initial_row[r] == 0:
            for c in range(C):
                initial_possible[r][c] = False
    for c in range(C):
        if initial_col[c] == 0:
            for r in range(R):
                initial_possible[r][c] = False
    for r in range(R):
