def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']
    rows = len(row_counts)
    cols = len(col_counts) if cols else 0
    if rows == 0 or cols == 0:
        return "No Solution"

    # Initialize state
    grid = [[cell for cell in row] for row in tree_grid]
    row_rem = row_counts.copy()
    col_rem = col_counts.copy()

    # Collect all trees
    trees = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 'T']
    total_tents_needed = sum(row_counts)
    if total_tents_needed != len(trees) or sum(col_counts) != len(trees):
        return "No Solution"

    # Track possible tent positions per tree
    tree_possible = {}
    def get_ortho_adj(r, c):
        res = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                res.append((nr, nc))
        return res

    for (r, c) in trees:
        poss = []
        for (nr, nc) in get_ortho_adj(r, c):
            if grid[nr][nc] is None:
                poss.append((nr, nc))
        if not poss:
            return "No Solution"
        tree_possible[(r, c)] = poss

    def get_8_adj(r, c):
        res = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    res.append((nr, nc))
        return res

    def undo_action(action):
        if action[0] == 'set_cell':
            _, ar, ac, val = action
            grid[ar][ac] = val
        elif action[0] == 'set_row_rem':
            _, ar, val = action
            row_rem[ar] = val
        elif action[0] == 'set_col_rem':
            _, ac, val = action
            col_rem[ac] = val
        elif action[0] == 'add_tree':
            _, t, poss = action
            tree_possible[t] = poss.copy()
        elif action[0] == 'add_poss':
            _, t, cell = action
            tree_possible[t].append(cell)

    def place_tent(r, c, assign_tree=None):
        if grid[r][c] is not None:
            return None
        if row_rem[r] <= 0 or col_rem[c] <= 0:
            return None
        for (nr, nc) in get_8_adj(r, c):
            if grid[nr][nc] == 't':
                return None

        if assign_tree is None:
            possible_trees = []
            for (nr, nc) in get_ortho_adj(r, c):
                if grid[nr][nc] == 'T' and (nr, nc) in tree_possible and (r,c) in tree_possible[(nr, nc)]:
                    possible_trees.append((nr, nc))
            if len(possible_trees) != 1:
                return None
            assign_tree = possible_trees[0]

        if assign_tree not in tree_possible or (r,c) not in tree_possible[assign_tree]:
            return None

        undo = []
        grid[r][c] = 't'
        undo.append(('set_cell', r, c, None))

        old_rr = row_rem[r]
        row_rem[r] -= 1
        undo.append(('set_row_rem', r, old_rr))

        old_cr = col_rem[c]
        col_rem[c] -= 1
        undo.append(('set_col_rem', c, old_cr))

        tree_poss_val = tree_possible.pop(assign_tree)
        undo.append(('add_tree', assign_tree, tree_poss_val))

        for (nr, nc) in get_8_adj(r, c):
            if grid[nr][nc] is None:
                old_val = grid[nr][nc]
                grid[nr][nc] = 'X'
                undo.append(('set_cell', nr, nc, old_val))
                for t in list(tree_possible.keys()):
                    if (nr, nc) in tree_possible[t]:
                        tree_possible[t].remove((nr, nc))
                        undo.append(('add_poss', t, (nr, nc)))
                        if not tree_possible[t]:
                            for act in reversed(undo):
                                undo_action(act)
                            return None
        return undo

    def apply_forced_pass():
        undo = []
        changed = False

        for r in range(rows):
            if row_rem[r] == 0:
                for c in range(cols):
                    if grid[r][c] is None:
                        old_val = grid[r][c]
                        grid[r][c] = 'X'
                        undo.append(('set_cell', r, c, old_val))
                        changed = True
                        for t in list(tree_possible.keys()):
                            if (r,c) in tree_possible[t]:
                                tree_possible[t].remove((r,c))
                                undo.append(('add_poss', t, (r,c)))
                                if not tree_possible[t]:
                                    for act in reversed(undo):
                                        undo_action(act)
                                    return False, []

        for c in range(cols):
            if col_rem[c] == 0:
                for r in range(rows):
                    if grid[r][c] is None:
                        old_val = grid[r][c]
                        grid[r][c] = 'X'
                        undo.append(('set_cell', r, c, old_val))
                        changed = True
                        for t in list(tree_possible.keys()):
                            if (r,c) in tree_possible[t]:
                                tree_possible[t].remove((r,c))
                                undo.append(('add_poss', t, (r,c)))
                                if not tree_possible[t]:
                                    for act in reversed(undo):
                                        undo_action(act)
                                    return False, []

        for r in range(rows):
            if row_rem[r] <= 0:
                continue
            avail = [c for c in range(cols) if grid[r][c] is None]
            if len(avail) < row_rem[r]:
                for act in reversed(undo):
                    undo_action(act)
                return False, []
            if len(avail) == row_rem[r]:
                for c in avail:
                    place_undo = place_tent(r, c)
                    if place_undo is None:
                        for act in reversed(undo):
                            undo_action(act)
                        return False, []
                    undo.extend(place_undo)
                    changed = True

        for c in range(cols):
            if col_rem[c] <= 0:
                continue
            avail = [r for r in range(rows) if grid[r][c] is None]
            if len(avail) < col_rem[c]:
                for act in reversed(undo):
                    undo_action(act)
                return False, []
            if len(avail) == col_rem[c]:
                for r in avail:
                    place_undo = place_tent(r, c)
                    if place_undo is None:
                        for act in reversed(undo):
                            undo_action(act)
                        return False, []
                    undo.extend(place_undo)
                    changed = True

        for t in list(tree_possible.keys()):
            poss = tree_possible[t]
            if len(poss) == 1:
                (r,c) = poss[0]
                if grid[r][c] == 'X':
                    for act in reversed(undo):
                        undo_action(act)
                    return False, []
                if grid[r][c] == 't':
                    continue
                place_undo = place_tent(r, c, t)
                if place_undo is None:
                    for act in reversed(undo):
                        undo_action(act)
                    return False, []
                undo.extend(place_undo)
                changed = True

        return True, undo if changed else []

    def backtrack():
        forced_undo = []
        while True:
            ok, undo = apply_forced_pass()
            if not ok:
                for act in reversed(forced_undo):
                    undo_action(act)
                return None
            if not undo:
                break
            forced_undo.extend(undo)

        if all(r == 0 for r in row_rem) and all(c == 0 for c in col_rem) and not tree_possible:
            sol = []
            for r in range(rows):
                sol_row = []
                for c in range(cols):
                    sol_row.append('t' if grid[r][c] == 't' else None)
                sol.append(sol_row)
            for act in reversed(forced_undo):
                undo_action(act)
            return sol

        min_opt = float('inf')
        best_cell = None
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is not None:
                    continue
                cnt = 0
                for t in tree_possible:
                    if (r,c) in tree_possible[t]:
                        cnt += 1
                if cnt == 0:
                    continue
                if cnt < min_opt:
                    min_opt = cnt
                    best_cell = (r,c)

        if best_cell is None:
            for act in reversed(forced_undo):
                undo_action(act)
            return None

        r,c = best_cell
        place_undo = place_tent(r,c)
        if place_undo is not None:
            res = backtrack()
            if res is not None:
                for act in reversed(place_undo):
                    undo_action(act)
                for act in reversed(forced_undo):
                    undo_action(act)
                return res
            for act in reversed(place_undo):
                undo_action(act)

        old_val = grid[r][c]
        grid[r][c] = 'X'
        block_undo = [('set_cell', r, c, old_val)]
        valid = True
        for t in list(tree_possible.keys()):
            if (r,c) in tree_possible[t]:
                tree_possible[t].remove((r,c))
                block_undo.append(('add_poss', t, (r,c)))
                if not tree_possible[t]:
                    valid = False
                    break
        if valid:
            res = backtrack()
            if res is not None:
                for act in reversed(block_undo):
                    undo_action(act)
                for act in reversed(forced_undo):
                    undo_action(act)
                return res

        for act in reversed(block_undo):
            undo_action(act)

        for act in reversed(forced_undo):
            undo_action(act)
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
