from collections import deque

def solve(observation):
    data = observation['data']
    N = len(data)
    if N == 0:
        return "No Solution"

    # Edge representations: 1=present, 0=absent, None=unknown
    h_edges = [[None for _ in range(N-1)] for _ in range(N)]  # (r,c) <-> (r,c+1)
    v_edges = [[None for _ in range(N)] for _ in range(N-1)]  # (r,c) <-> (r+1,c)

    # Collect all clues
    clues = []
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                clues.append((r, c))
    if not clues:
        return "No Solution"

    # Queue for constraint propagation: stores (type, r, c) where type is 'h' or 'v'
    q = deque()

    # Step 1: Apply initial clue constraints
    for r, c in clues:
        typ = data[r][c]
        if typ == 'W':
            # W must be straight through, opposite edges
            # Check border constraints
            if r == 0 or r == N-1:
                # Must be horizontal, can't be vertical
                if c == 0 or c == N-1:
                    return "No Solution"
                # Set horizontal edges to 1
                if h_edges[r][c-1] == 0 or h_edges[r][c] == 0:
                    return "No Solution"
                if h_edges[r][c-1] is None:
                    h_edges[r][c-1] = 1
                    q.append(('h', r, c-1))
                if h_edges[r][c] is None:
                    h_edges[r][c] = 1
                    q.append(('h', r, c))
                # Vertical edges must be 0
                if r > 0:
                    if v_edges[r-1][c] == 1:
                        return "No Solution"
                    if v_edges[r-1][c] is None:
                        v_edges[r-1][c] = 0
                        q.append(('v', r-1, c))
                if r < N-1:
                    if v_edges[r][c] == 1:
                        return "No Solution"
                    if v_edges[r][c] is None:
                        v_edges[r][c] = 0
                        q.append(('v', r, c))
            elif c == 0 or c == N-1:
                # Must be vertical
                if r == 0 or r == N-1:
                    return "No Solution"
                # Set vertical edges to 1
                if v_edges[r-1][c] == 0 or v_edges[r][c] == 0:
                    return "No Solution"
                if v_edges[r-1][c] is None:
                    v_edges[r-1][c] = 1
                    q.append(('v', r-1, c))
                if v_edges[r][c] is None:
                    v_edges[r][c] = 1
                    q.append(('v', r, c))
                # Horizontal edges must be 0
                if c > 0:
                    if h_edges[r][c-1] == 1:
                        return "No Solution"
                    if h_edges[r][c-1] is None:
                        h_edges[r][c-1] = 0
                        q.append(('h', r, c-1))
                if c < N-1:
                    if h_edges[r][c] == 1:
                        return "No Solution"
                    if h_edges[r][c] is None:
                        h_edges[r][c] = 0
                        q.append(('h', r, c))
        elif typ == 'B':
            # B must turn, one horizontal one vertical edge, both sides straight at least 1 step
            # Border constraints
            possible_dirs = []
            if r > 0: possible_dirs.append('U')
            if r < N-1: possible_dirs.append('D')
            if c > 0: possible_dirs.append('L')
            if c < N-1: possible_dirs.append('R')
            if len(possible_dirs) < 2:
                return "No Solution"
            # Prune invalid pairs: e.g., U and D are opposite, invalid for B, same L and R
            # So eliminate opposite pairs
            if 'U' in possible_dirs and 'D' in possible_dirs:
                # Can't have both, so if one is set to 1 the other must be 0
                pass  # Handled later in propagation

    # Step 2: Constraint propagation function
    def propagate():
        while q:
            etype, r, c = q.popleft()
            val = h_edges[r][c] if etype == 'h' else v_edges[r][c]
            # Get dots connected by this edge
            if etype == 'h':
                d1, d2 = (r, c), (r, c+1)
            else:
                d1, d2 = (r, c), (r+1, c)

            # Process both dots for degree constraints
            for (dr, dc) in [d1, d2]:
                # Count present edges and possible edges
                present = 0
                possible = 0
                edges = []
                # Up
                if dr > 0:
                    ev = v_edges[dr-1][dc]
                    if ev == 1: present +=1
                    elif ev is None: possible +=1
                    edges.append(('v', dr-1, dc, ev))
                # Down
                if dr < N-1:
                    ev = v_edges[dr][dc]
                    if ev == 1: present +=1
                    elif ev is None: possible +=1
                    edges.append(('v', dr, dc, ev))
                # Left
                if dc > 0:
                    eh = h_edges[dr][dc-1]
                    if eh == 1: present +=1
                    elif eh is None: possible +=1
                    edges.append(('h', dr, dc-1, eh))
                # Right
                if dc < N-1:
                    eh = h_edges[dr][dc]
                    if eh == 1: present +=1
                    elif eh is None: possible +=1
                    edges.append(('h', dr, dc, eh))

                if present > 2:
                    return False  # Invalid, degree > 2
                if present + possible < 2:
                    # If dot is clue, must have degree 2, so invalid
                    if data[dr][dc] is not None:
                        return False
                    # Else, can have degree 0, set all possible to 0
                    for et, er, ec, ev in edges:
                        if ev is None:
                            if et == 'h':
                                h_edges[er][ec] = 0
                            else:
                                v_edges[er][ec] = 0
                            q.append((et, er, ec))
                if present == 2:
                    # All other edges must be 0
                    for et, er, ec, ev in edges:
                        if ev is None:
                            if et == 'h':
                                h_edges[er][ec] = 0
                            else:
                                v_edges[er][ec] = 0
                            q.append((et, er, ec))
                if present + possible == 2 and data[dr][dc] is not None:
                    # Must have degree 2, set all possible to 1
                    for et, er, ec, ev in edges:
                        if ev is None:
                            if et == 'h':
                                if h_edges[er][ec] == 0:
                                    return False
                                h_edges[er][ec] = 1
                            else:
                                if v_edges[er][ec] == 0:
                                    return False
                                v_edges[er][ec] = 1
                            q.append((et, er, ec))
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Step 3: Check if all edges are determined
    def is_complete():
        for r in range(N):
            for c in range(N-1):
                if h_edges[r][c] is None:
                    return False
        for r in range(N-1):
            for c in range(N):
                if v_edges[r][c] is None:
                    return False
        return True

    # Step 4: Get next edge to guess (MRV heuristic)
    def get_next_edge():
        min_opt = 3
        res = None
        for r in range(N):
            for c in range(N-1):
                if h_edges[r][c] is None:
                    return ('h', r, c)
        for r in range(N-1):
            for c in range(N):
                if v_edges[r][c] is None:
                    return ('v', r, c)
        return None

    # Step 5: Validate solution
    def validate_and_get_path():
        # Build adjacency list
        adj = [[[] for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N-1):
                if h_edges[r][c] == 1:
                    adj[r][c].append((r, c+1))
                    adj[r][c+1].append((r, c))
        for r in range(N-1):
            for c in range(N):
                if v_edges[r][c] == 1:
                    adj[r][c].append((r+1, c))
                    adj[r+1][c].append((r, c))
        # Check all clues have degree 2
        for r,c in clues:
            if len(adj[r][c]) != 2:
                return None
        # Check all dots have degree 0 or 2
        for r in range(N):
            for c in range(N):
                if len(adj[r][c]) not in (0,2):
                    return None
        # Traverse loop
        start = clues[0]
        path = [start]
        prev = None
        curr = start
        while True:
            nexts = [n for n in adj[curr[0]][curr[1]] if n != prev]
            if not nexts:
                return None
            nxt = nexts[0]
            path.append(nxt)
            if nxt == start:
                break
            prev = curr
            curr = nxt
        # Check all clues are in path
        clue_set = set(clues)
        path_set = set(path)
        if not clue_set.issubset(path_set):
            return None
        # Check loop length is correct
        return path

    # Step 6: Backtracking search
    def backtrack():
        if is_complete():
            return validate_and_get_path()
        etype, r, c = get_next_edge()
        # Try 1 first
        save_h = [row[:] for row in h_edges]
        save_v = [row[:] for row in v_edges]
        if etype == 'h':
            h_edges[r][c] = 1
        else:
            v_edges[r][c] = 1
        q.append((etype, r, c))
        if propagate():
            res = backtrack()
            if res is not None:
                return res
        # Revert
        for i in range(N):
            h_edges[i] = save_h[i]
        for i in range(N-1):
            v_edges[i] = save_v[i]
        q.clear()
        # Try 0
        if etype == 'h':
            h_edges[r][c] = 0
        else:
            v_edges[r][c] = 0
        q.append((etype, r, c))
        if propagate():
            res = backtrack()
            if res is not None:
                return res
        # Revert
        for i in range(N):
            h_edges[i] = save_h[i]
        for i in range(N-1):
            v_edges[i] = save_v[i]
        q.clear()
        return None

    solution = backtrack()
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
