def generate_possible_masks(weights, target):
    n = len(weights)
    masks = []
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += weights[i]
                if total > target:
                    break
        if total == target:
            masks.append(mask)
    return masks

def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    n_rows = len(row_sum)
    n_cols = len(col_sum)

    row_weights = [i + 1 for i in range(n_rows)]
    col_weights = [j + 1 for j in range(n_cols)]

    # Generate initial possible masks for rows and columns
    row_possible = []
    for r in range(n_rows):
        masks = generate_possible_masks(col_weights, row_sum[r])
        if not masks:
            return "No Solution"
        row_possible.append(masks)

    col_possible = []
    for c in range(n_cols):
        masks = generate_possible_masks(row_weights, col_sum[c])
        if not masks:
            return "No Solution"
        col_possible.append(masks)

    # Grid state: None=unknown, True=Black, False=Non-black
    grid = [[None for _ in range(n_cols)] for _ in range(n_rows)]

    def backtrack(grid, row_possible, col_possible):
        # Constraint propagation loop
        changed = True
        while changed:
            changed = False

            # Process all rows
            for r in range(n_rows):
                # Filter invalid masks for current row
                valid_masks = []
                for mask in row_possible[r]:
                    valid = True
                    for j in range(n_cols):
                        if grid[r][j] is True and not (mask & (1 << j)):
                            valid = False
                            break
                        if grid[r][j] is False and (mask & (1 << j)):
                            valid = False
                            break
                    if valid:
                        valid_masks.append(mask)
                if not valid_masks:
                    return None
                if len(valid_masks) != len(row_possible[r]):
                    row_possible[r] = valid_masks
                    changed = True

                # Deduce fixed cells from row masks
                for j in range(n_cols):
                    if grid[r][j] is not None:
                        continue
                    all_set = all((m & (1 << j)) for m in row_possible[r])
                    all_unset = all(not (m & (1 << j)) for m in row_possible[r])
                    if all_set:
                        grid[r][j] = True
                        changed = True
                    elif all_unset:
                        grid[r][j] = False
                        changed = True

            # Process all columns
            for c in range(n_cols):
                # Filter invalid masks for current column
                valid_masks = []
                for mask in col_possible[c]:
                    valid = True
                    for i in range(n_rows):
                        if grid[i][c] is True and not (mask & (1 << i)):
                            valid = False
                            break
                        if grid[i][c] is False and (mask & (1 << i)):
                            valid = False
                            break
                    if valid:
                        valid_masks.append(mask)
                if not valid_masks:
                    return None
                if len(valid_masks) != len(col_possible[c]):
                    col_possible[c] = valid_masks
                    changed = True

                # Deduce fixed cells from column masks
                for i in range(n_rows):
                    if grid[i][c] is not None:
                        continue
                    all_set = all((m & (1 << i)) for m in col_possible[c])
                    all_unset = all(not (m & (1 << i)) for m in col_possible[c])
                    if all_set:
                        grid[i][c] = True
                        changed = True
                    elif all_unset:
                        grid[i][c] = False
                        changed = True

        # Check if grid is fully solved
        complete = True
        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] is None:
                    complete = False
                    break
            if not complete:
                break
        if complete:
            return [['B' if cell else None for cell in row] for row in grid]

        # Select row with smallest number of possible masks for branching
        min_options = float('inf')
        pivot_row = -1
        for r in range(n_rows):
            cnt = len(row_possible[r])
            if cnt > 1 and cnt < min_options:
                min_options = cnt
                pivot_row = r

        # Try each possible mask for pivot row
        for mask in row_possible[pivot_row]:
            # Create copies of state for recursion
            new_grid = [r.copy() for r in grid]
            new_row_possible = [m.copy() for m in row_possible]
            new_col_possible = [m.copy() for m in col_possible]

            # Fix pivot row cells according to current mask
            for j in range(n_cols):
                new_grid[pivot_row][j] = bool(mask & (1 << j))

            solution = backtrack(new_grid, new_row_possible, new_col_possible)
            if solution is not None:
                return solution

        return None

    result = backtrack(grid, row_possible, col_possible)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
