        [2, 2, 6, 6, 7, 1]
    ]
}

def solve(observation):
    grid = observation['data']
    N = len(grid)
    if N == 0:
        return "No Solution"

    # Precompute region to cells mapping for quick reference
    region_cells = {}
    for r in range(N):
        for c in range(N):
            reg = grid[r][c]
            if reg not in region_cells:
                region_cells[reg] = []
            region_cells[reg].append((r, c))

    used_rows = set()
    used_cols = set()
    used_regions = set()
    placed_stars = []

    # Validate if placing a star at (r,c) follows all constraints
    def is_valid(r, c):
        if r in used_rows or c in used_cols or grid[r][c] in used_regions:
            return False
        # Check all 8 adjacent cells for existing stars
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) in placed_stars:
                        return False
        return True

    # MRV heuristic: select row with fewest valid remaining positions to minimize branching
    def get_next_row():
        min_candidate_count = float('inf')
        selected_row = None
        for r in range(N):
            if r in used_rows:
                continue
            count = 0
            for c in range(N):
                if is_valid(r, c):
                    count += 1
            if count == 0:
                return None  # No valid options for this row, prune branch
            if count < min_candidate_count:
                min_candidate_count = count
                selected_row = r
        return selected_row

    def backtrack():
        if len(placed_stars) == N:
            # Build result grid
            result = [[None for _ in range(N)] for _ in range(N)]
            for r, c in placed_stars:
                result[r][c] = 'S'
            return result

        current_row = get_next_row()
        if current_row is None:
            return None

        # Get all valid columns for current row
        valid_cols = [c for c in range(N) if is_valid(current_row, c)]
        for col in valid_cols:
            region_id = grid[current_row][col]
            # Place star
            used_rows.add(current_row)
            used_cols.add(col)
            used_regions.add(region_id)
            placed_stars.append((current_row, col))

            solution = backtrack()
            if solution is not None:
                return solution

            # Undo placement
            used_rows.remove(current_row)
            used_cols.remove(col)
            used_regions.remove(region_id)
            placed_stars.pop()

        return None

    final_result = backtrack()
    return final_result if final_result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
