from copy import deepcopy

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def get_neighbors(r, c, R, C):
    res = []
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < R and 0 <= nc < C:
            res.append((nr, nc))
    return res

def is_valid_state(grid, number_cells, R, C):
    # Check no 2x2 all black
    for r in range(R - 1):
        for c in range(C - 1):
            cnt = 0
            for dr in (0,1):
                for dc in (0,1):
                    if grid[r+dr][c+dc] == 'B':
                        cnt +=1
            if cnt ==4:
                return False

    # Check all white regions are valid
    visited = [[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'W' and not visited[r][c]:
                # BFS to get region
                q = [(r,c)]
                visited[r][c] = True
                region = []
                num_count = 0
                while q:
                    cr, cc = q.pop(0)
                    region.append((cr, cc))
                    if (cr, cc) in number_cells:
                        num_count +=1
                    for nr, nc in get_neighbors(cr, cc, R, C):
                        if not visited[nr][nc] and grid[nr][nc] == 'W':
                            visited[nr][nc] = True
                            q.append((nr, nc))
                if num_count ==0:
                    return False
                if num_count >1:
                    return False
                # Get the number value
                num_pos = next((p for p in region if p in number_cells), None)
                num_val = number_cells[num_pos]
                if len(region) > num_val:
                    return False
                # Check max possible size
                max_size = len(region)
                adj_unknown = set()
                for (cr, cc) in region:
                    for nr, nc in get_neighbors(cr, cc, R, C):
                        if grid[nr][nc] is None:
                            adj_unknown.add((nr, nc))
                max_size += len(adj_unknown)
                if max_size < num_val:
                    return False

    # Check black cells are connected if any exist
    b_cells = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == 'B']
    if len(b_cells) > 0:
        visited_b = set()
        q = [b_cells[0]]
        visited_b.add(b_cells[0])
        while q:
            cr, cc = q.pop(0)
            for nr, nc in get_neighbors(cr, cc, R, C):
                if grid[nr][nc] == 'B' and (nr, nc) not in visited_b:
                    visited_b.add((nr, nc))
                    q.append((nr, nc))
        if len(visited_b) != len(b_cells):
            return False

    return True

def apply_inferences(grid, number_cells, R, C):
    changed = True
    while changed:
        changed = False
        # Rule 1: N=1 cells, all neighbors are B
        for (r,c), val in number_cells.items():
            if val == 1:
                for nr, nc in get_neighbors(r, c, R, C):
                    if grid[nr][nc] is None:
                        grid[nr][nc] = 'B'
                        changed = True

        # Rule 2: White island is full size, all adjacent unknown are B
        visited = [[False]*C for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 'W' and not visited[r][c] and (r,c) in number_cells:
                    num_val = number_cells[(r,c)]
                    q = [(r,c)]
                    visited[r][c] = True
                    region = []
                    while q:
                        cr, cc = q.pop(0)
                        region.append((cr, cc))
                        for nr, nc in get_neighbors(cr, cc, R, C):
                            if not visited[nr][nc] and grid[nr][nc] == 'W':
                                visited[nr][nc] = True
                                q.append((nr, nc))
                    if len(region) == num_val:
                        for (cr, cc) in region:
                            for nr, nc in get_neighbors(cr, cc, R, C):
                                if grid[nr][nc] is None:
                                    grid[nr][nc] = 'B'
                                    changed = True

        # Rule3: 3 B in 2x2, remaining is W
        for r in range(R-1):
            for c in range(C-1):
                b_count = 0
                unknown_pos = None
                for dr in (0,1):
                    for dc in (0,1):
                        cell = grid[r+dr][c+dc]
                        if cell == 'B':
                            b_count +=1
                        elif cell is None:
                            unknown_pos = (r+dr, c+dc)
                if b_count == 3 and unknown_pos is not None:
                    ur, uc = unknown_pos
                    grid[ur][uc] = 'W'
                    changed = True

        # Check if state is still valid after changes
        if not is_valid_state(grid, number_cells, R, C):
            return False, grid

    return is_valid_state(grid, number_cells, R, C), grid

def is_solved(grid, number_cells, R, C):
    # Check no unknown cells left
    for r in range(R):
        for c in range(C):
            if grid[r][c] is None:
                return False
    # Must already be valid
    return is_valid_state(grid, number_cells, R, C)

def backtrack(grid, number_cells, R, C):
    # Apply all inferences first
    valid, grid = apply_inferences(grid, number_cells, R, C)
    if not valid:
        return None
    if is_solved(grid, number_cells, R, C):
        return grid
    # Pick MRV cell (least possible options)
    min_options = 3
    best_cell = None
    for r in range(R):
        for c in range(C):
            if grid[r][c] is None:
                # Count possible options
                opts = 0
                # Try B
                temp = deepcopy(grid)
                temp[r][c] = 'B'
                if is_valid_state(temp, number_cells, R, C):
                    opts +=1
                # Try W
                temp = deepcopy(grid)
                temp[r][c] = 'W'
                if is_valid_state(temp, number_cells, R, C):
                    opts +=1
                if opts == 0:
                    return None
                if opts < min_options:
                    min_options = opts
                    best_cell = (r,c)
                    if min_options == 1:
                        break
        if best_cell and min_options == 1:
            break
    if not best_cell:
        return None
    r, c = best_cell
    # Try both options
    for val in ['B', 'W']:
        new_grid = deepcopy(grid)
        new_grid[r][c] = val
        res = backtrack(new_grid, number_cells, R, C)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0]) if R else 0
    number_cells = {(r,c): val for r, row in enumerate(data) for c, val in enumerate(row) if val is not None}
    # Initialize grid
    grid = [[None]*C for _ in range(R)]
    for (r,c) in number_cells:
        grid[r][c] = 'W'
    # Solve
    solution = backtrack(grid, number_cells, R, C)
    if not solution:
        return "No Solution"
    # Convert to required output: W -> None, B -> B
    output = []
    for row in solution:
        output_row = []
        for cell in row:
            output_row.append('B' if cell == 'B' else None)
        output.append(output_row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
