def solve(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']
    R = len(row_target)
    C = len(col_target)

    # Quick sum consistency check
    if sum(row_target) != sum(col_target):
        return "No Solution"

    # Preprocess region metadata: cells sorted bottom to top, delta maps for all possible levels
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    for rid in regions:
        # Sort cells by descending row index (bottom cells first)
        regions[rid].sort(reverse=True, key=lambda x: x[0])
        max_l = len(regions[rid])
        delta_info = []
        for l in range(max_l + 1):
            dr = [0] * R
            dc = [0] * C
            for i in range(l):
                r, c = regions[rid][i]
                dr[r] += 1
                dc[c] += 1
            delta_info.append((dr, dc))
        regions[rid] = {
            'cells': regions[rid],
            'max_l': max_l,
            'delta': delta_info
        }

    # State tracking
    remaining_row = row_target.copy()
    remaining_col = col_target.copy()
    assigned = {rid: None for rid in regions}
    grid = [[None for _ in range(C)] for _ in range(R)]

    def is_level_possible(rid, l):
        dr, dc = regions[rid]['delta'][l]
        for r in range(R):
            if dr[r] > remaining_row[r]:
                return False
        for c in range(C):
            if dc[c] > remaining_col[c]:
                return False
        return True

    def assign_level(rid, l):
        dr, dc = regions[rid]['delta'][l]
        for r in range(R):
            remaining_row[r] -= dr[r]
        for c in range(C):
            remaining_col[c] -= dc[c]
        assigned[rid] = l
        cells = regions[rid]['cells']
        for i in range(l):
            r, c = cells[i]
            grid[r][c] = 'W'

    def unassign_level(rid, l):
        dr, dc = regions[rid]['delta'][l]
        for r in range(R):
            remaining_row[r] += dr[r]
        for c in range(C):
            remaining_col[c] += dc[c]
        assigned[rid] = None
        cells = regions[rid]['cells']
        for i in range(l):
            r, c = cells[i]
            grid[r][c] = None

    def deduce():
        changed = True
        while changed:
            changed = False
            # Find regions with only one possible level
            for rid in regions:
                if assigned[rid] is not None:
                    continue
                possible = []
                for l in range(regions[rid]['max_l'] + 1):
                    if is_level_possible(rid, l):
                        possible.append(l)
                if not possible:
                    return False
                if len(possible) == 1:
                    assign_level(rid, possible[0])
                    changed = True
            # Rows with 0 remaining: all contributing regions must be level 0
            for r in range(R):
                if remaining_row[r] == 0:
                    for rid in regions:
                        if assigned[rid] is not None:
                            continue
                        contributes = any(regions[rid]['delta'][l][0][r] > 0 for l in range(1, regions[rid]['max_l'] + 1))
                        if contributes:
                            if is_level_possible(rid, 0):
                                assign_level(rid, 0)
                                changed = True
                            else:
                                return False
            # Columns with 0 remaining: all contributing regions must be level 0
            for c in range(C):
                if remaining_col[c] == 0:
                    for rid in regions:
                        if assigned[rid] is not None:
                            continue
                        contributes = any(regions[rid]['delta'][l][1][c] > 0 for l in range(1, regions[rid]['max_l'] + 1))
                        if contributes:
                            if is_level_possible(rid, 0):
                                assign_level(rid, 0)
                                changed = True
                            else:
                                return False
        return True

    def backtrack():
        if not deduce():
            return None
        # Check if all regions are assigned
        all_done = True
        for rid in assigned:
            if assigned[rid] is None:
                all_done = False
                break
        if all_done:
            if all(x == 0 for x in remaining_row) and all(x == 0 for x in remaining_col):
                return [row.copy() for row in grid]
            return None
        # Select region with minimal possible levels for branching
        best_rid = None
        min_options = float('inf')
        possible_map = {}
        for rid in regions:
            if assigned[rid] is not None:
                continue
            pl = [l for l in range(regions[rid]['max_l'] + 1) if is_level_possible(rid, l)]
            if not pl:
                return None
            possible_map[rid] = pl
            if len(pl) < min_options:
                min_options = len(pl)
                best_rid = rid
        # Try each possible level
        for l in possible_map[best_rid]:
            assign_level(best_rid, l)
            res = backtrack()
            if res is not None:
                return res
            unassign_level(best_rid, l)
        return None

    solution = backtrack()
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
