def solve(observation):
    data = observation['data']
    N = len(data)
    # Precompute map of region ID to all cells in that region for heuristic calculation
    region_to_cells = {}
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            if reg not in region_to_cells:
                region_to_cells[reg] = []
            region_to_cells[reg].append((r, c))
    total_unique_regions = len(region_to_cells)

    def backtrack(placed_stars, used_columns, used_regions):
        current_row = len(placed_stars)
        # Base case: all rows processed, validate solution
        if current_row == N:
            if len(used_regions) == total_unique_regions:
                output_grid = [[None for _ in range(N)] for _ in range(N)]
                for (r, c) in placed_stars:
                    output_grid[r][c] = 'S'
                return output_grid
            return None

        # Collect all valid columns for current row
        valid_candidates = []
        for col in range(N):
            # Skip used columns
            if col in used_columns:
                continue
            current_region = data[current_row][col]
            # Skip used regions
            if current_region in used_regions:
                continue
            # Check no adjacency (including diagonal) to existing stars
            adjacent = False
            for (sr, sc) in placed_stars:
                if abs(current_row - sr) <= 1 and abs(col - sc) <= 1:
                    adjacent = True
                    break
            if not adjacent:
                valid_candidates.append(col)

        # Apply Minimum Remaining Value (MRV) heuristic: try columns from regions with fewer options first
        def count_remaining_possible(c):
            reg = data[current_row][c]
            count = 0
            for (r, rc) in region_to_cells[reg]:
                if r >= current_row and rc not in used_columns:
                    count += 1
            return count
        valid_candidates.sort(key=count_remaining_possible)

        # Explore each valid candidate
        for col in valid_candidates:
            reg = data[current_row][col]
            # Place star
            placed_stars.append((current_row, col))
            used_columns.add(col)
            used_regions.add(reg)
            # Recurse
            solution = backtrack(placed_stars, used_columns, used_regions)
            if solution is not None:
                return solution
            # Backtrack
            placed_stars.pop()
            used_columns.remove(col)
            used_regions.remove(reg)

        # No valid candidates for this path
        return None

    final_result = backtrack([], set(), set())
    return final_result if final_result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
