OBSERVATION = {'data': [
    [None, 'W', None, None, 'W', 'W', None, None, None, 'B'],
    [None, None, None, None, None, None, None, None, None, None],
    ['B', None, None, 'W', None, None, None, 'W', None, None],
    [None, 'W', None, None, 'W', 'W', None, None, None, 'W'],
    [None, None, None, 'W', None, None, None, None, None, None],
    [None, None, None, None, 'W', None, 'W', None, None, None],
    [None, 'W', None, None, None, None, 'W', None, 'W', None],
    [None, 'W', None, None, 'B', None, None, None, None, None],
    ['W', None, None, None, None, 'B', None, None, None, None],
    [None, None, None, None, None, None, None, 'B', None, 'B']
]}

from typing import List, Tuple, Optional, Dict

# Direction definitions: (dr, dc)
DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]
OPPOSITE = {0: 1, 1: 0, 2: 3, 3: 2}
PERPENDICULAR = {0: [2,3], 1: [2,3], 2: [0,1], 3: [0,1]}

def solve(observation: Dict) -> Optional[List[Tuple[int, int]]]:
    grid = observation['data']
    N = len(grid)
    if N == 0:
        return "No Solution"

    # Collect all clue positions
    clues = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                clues[(r,c)] = grid[r][c]

    # Edge representations: h_edges[r][c] = edge between (r,c) and (r,c+1)
    # v_edges[r][c] = edge between (r,c) and (r+1,c)
    h_edges = [[None for _ in range(N-1)] for _ in range(N)]
    v_edges = [[None for _ in range(N)] for _ in range(N-1)]

    def get_adjacent_edges(r: int, c: int) -> List[Tuple[str, int, int]]:
        edges = []
        if c > 0:
            edges.append(('h', r, c-1))
        if c < N-1:
            edges.append(('h', r, c))
        if r > 0:
            edges.append(('v', r-1, c))
        if r < N-1:
            edges.append(('v', r, c))
        return edges

    def count_connected_edges(r: int, c: int) -> Tuple[int, int]:
        cnt_true = 0
        cnt_unknown = 0
        for et, er, ec in get_adjacent_edges(r,c):
            e = h_edges[er][ec] if et == 'h' else v_edges[er][ec]
            if e is True:
                cnt_true +=1
            elif e is None:
                cnt_unknown +=1
        return cnt_true, cnt_unknown

    def propagate_constraints() -> bool:
        changed = True
        while changed:
            changed = False
            # Check dot degree constraints first
            for r in range(N):
                for c in range(N):
                    t, u = count_connected_edges(r,c)
                    if t > 2:
                        return False
                    if t == 2:
                        # All unknown edges must be False
                        for et, er, ec in get_adjacent_edges(r,c):
                            e = h_edges[er][ec] if et == 'h' else v_edges[er][ec]
                            if e is None:
                                if et == 'h':
                                    h_edges[er][ec] = False
                                else:
                                    v_edges[er][ec] = False
                                changed = True
                    if t + u < 2:
                        # Can't reach 2 edges, invalid
                        return False

            # Check B/W constraints
            for (r,c), typ in clues.items():
                t, u = count_connected_edges(r,c)
                if typ == 'B':
                    # Must turn here, exactly one horizontal and one vertical edge connected
                    h_conn = 0
                    v_conn = 0
                    if c>0 and h_edges[r][c-1] is True:
                        h_conn +=1
                    if c < N-1 and h_edges[r][c] is True:
                        h_conn +=1
                    if r>0 and v_edges[r-1][c] is True:
                        v_conn +=1
                    if r < N-1 and v_edges[r][c] is True:
                        v_conn +=1
                    if h_conn > 1 or v_conn > 1:
                        return False
                    if h_conn == 1 and v_conn == 1:
                        # Valid turn, check straight steps before/after
                        pass # More constraint checks can be added here

                elif typ == 'W':
                    # Must go straight, both horizontal or both vertical edges connected
                    h_left = h_edges[r][c-1] if c>0 else False
                    h_right = h_edges[r][c] if c < N-1 else False
                    v_up = v_edges[r-1][c] if r>0 else False
                    v_down = v_edges[r][c] if r < N-1 else False
                    if (h_left is True and h_right is False) or (h_left is False and h_right is True):
                        return False
                    if (v_up is True and v_down is False) or (v_up is False and v_down is True):
                        return False
        return True

    # Initial constraint propagation
    if not propagate_constraints():
        return "No Solution"

    def select_next_edge() -> Optional[Tuple[str, int, int]]:
        # MRV heuristic: select edge with fewest possible options
        min_options = 3
        best_edge = None
        for r in range(N):
            for c in range(N-1):
                if h_edges[r][c] is None:
                    # Calculate number of constraints on this edge
                    t1, u1 = count_connected_edges(r,c)
                    t2, u2 = count_connected_edges(r,c+1)
                    options = 2
                    if t1 >= 2 or t2 >= 2:
                        options = 1
                    if options < min_options:
                        min_options = options
                        best_edge = ('h', r, c)
        for r in range(N-1):
            for c in range(N):
                if v_edges[r][c] is None:
                    t1, u1 = count_connected_edges(r,c)
                    t2, u2 = count_connected_edges(r+1,c)
                    options = 2
                    if t1 >= 2 or t2 >= 2:
                        options = 1
                    if options < min_options:
                        min_options = options
                        best_edge = ('v', r, c)
        return best_edge

    def is_solution() -> bool:
        # Check all edges are assigned
        for r in range(N):
            for c in range(N-1):
                if h_edges[r][c] is None:
                    return False
        for r in range(N-1):
            for c in range(N):
                if v_edges[r][c] is None:
                    return False
        # Check all clues are on loop
        for (r,c) in clues:
            t, _ = count_connected_edges(r,c)
            if t != 2:
                return False
        # Check single closed loop
        start = None
        for r in range(N):
            for c in range(N):
                t, _ = count_connected_edges(r,c)
                if t == 2:
                    start = (r,c)
                    break
            if start is not None:
                break
        if start is None:
            return False
        path = []
        curr = start
        prev = None
        while True:
            path.append(curr)
            cr, cc = curr
            next_pos = None
            for dr, dc in DIRS:
                nr = cr + dr
                nc = cc + dc
                if nr < 0 or nr >= N or nc <0 or nc >= N:
                    continue
                if (nr, nc) == prev:
                    continue
                if dr == 0:
                    # Horizontal edge
                    if dc == 1:
                        e = h_edges[cr][cc]
                    else:
                        e = h_edges[cr][nc]
                else:
                    # Vertical edge
                    if dr == 1:
                        e = v_edges[cr][cc]
                    else:
                        e = v_edges[nr][cc]
                if e is True:
                    next_pos = (nr, nc)
                    break
            if next_pos is None:
                return False
            if next_pos == start:
                path.append(start)
                break
            prev = curr
            curr = next_pos
        # Check all loop nodes have degree 2, others 0
        for r in range(N):
            for c in range(N):
                t, _ = count_connected_edges(r,c)
                if (r,c) in path and t != 2:
                    return False
                if (r,c) not in path and t != 0:
                    return False
        return True

    def backtrack() -> bool:
        if is_solution():
            return True
        edge = select_next_edge()
        if edge is None:
            return False
        et, er, ec = edge
        # Try True first
        if et == 'h':
            h_edges[er][ec] = True
        else:
            v_edges[er][ec] = True
        if propagate_constraints() and backtrack():
            return True
        # Backtrack
        if et == 'h':
            h_edges[er][ec] = None
        else:
            v_edges[er][ec] = None
        propagate_constraints()
        # Try False
        if et == 'h':
            h_edges[er][ec] = False
        else:
            v_edges[er][ec] = False
        if propagate_constraints() and backtrack():
            return True
        # Backtrack
        if et == 'h':
            h_edges[er][ec] = None
        else:
            v_edges[er][ec] = None
        propagate_constraints()
        return False

    if not backtrack():
        return "No Solution"

    # Trace the final path
    start = None
    for r in range(N):
        for c in range(N):
            t, _ = count_connected_edges(r,c)
            if t == 2:
                start = (r,c)
                break
        if start is not None:
            break
    path = []
    curr = start
    prev = None
    while True:
        path.append(curr)
        cr, cc = curr
        next_pos = None
        for dr, dc in DIRS:
            nr = cr + dr
            nc = cc + dc
            if nr <0 or nr >= N or nc <0 or nc >= N:
                continue
            if (nr, nc) == prev:
                continue
            if dr == 0:
                e = h_edges[cr][cc if dc == 1 else nc]
            else:
                e = v_edges[cr if dr == 1 else nr][cc]
            if e is True:
                next_pos = (nr, nc)
                break
        if next_pos == start:
            path.append(start)
            break
        prev = curr
        curr = next_pos
    return path

if __name__ == "__main__":
    print(solve(OBSERVATION))
