from copy import deepcopy

DIRS = [(-1,0), (1,0), (0,-1), (0,1)]

def solve(observation):
    data = observation['data']
    N = len(data)
    # Preprocess region cells
    reg_cells = {}
    for r in range(N):
        for c in range(N):
            rid = data[r][c]
            if rid not in reg_cells:
                reg_cells[rid] = []
            reg_cells[rid].append((r,c))
    all_rids = list(reg_cells.keys())

    # Initialize grid: None=unknown, 'S'=shaded, 'U'=unshaded
    grid = [[None for _ in range(N)] for _ in range(N)]
    reg_count = {rid:0 for rid in all_rids}

    # First forced deductions: regions with exactly 2 cells must have both S
    for rid in all_rids:
        if len(reg_cells[rid]) == 2:
            for (r,c) in reg_cells[rid]:
                if grid[r][c] is None:
                    grid[r][c] = 'S'
                    reg_count[rid] += 1

    def propagate(g, rc):
        changed = True
        while changed:
            changed = False
            # Check regions with count == 2: mark all others U
            for rid in all_rids:
                if rc[rid] == 2:
                    for (r,c) in reg_cells[rid]:
                        if g[r][c] is None:
                            g[r][c] = 'U'
                            changed = True
                # Check if region can't reach 2 S
                unknowns = sum(1 for (r,c) in reg_cells[rid] if g[r][c] is None)
                if rc[rid] + unknowns < 2:
                    return False
                if rc[rid] > 2:
                    return False
                # If remaining needed == unknowns: mark all as S
                needed = 2 - rc[rid]
                if needed > 0 and needed == unknowns:
                    for (r,c) in reg_cells[rid]:
                        if g[r][c] is None:
                            g[r][c] = 'S'
                            rc[rid] += 1
                            changed = True
            # Process all S cells
            for r in range(N):
                for c in range(N):
                    if g[r][c] != 'S':
                        continue
                    # Count adjacent S
                    adj_s = []
                    adj_unknown = []
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N:
                            if g[nr][nc] == 'S':
                                adj_s.append((nr, nc))
                            elif g[nr][nc] is None:
                                adj_unknown.append((nr, nc))
                    # Invalid if more than 1 adjacent S
                    if len(adj_s) > 1:
                        return False
                    # If no adjacent S: exactly one unknown must be S
                    if len(adj_s) == 0:
                        if len(adj_unknown) == 0:
                            return False
                        if len(adj_unknown) == 1:
                            nr, nc = adj_unknown[0]
                            g[nr][nc] = 'S'
                            rc[data[nr][nc]] += 1
                            changed = True
                            adj_s.append((nr, nc))
                    # If we have exactly one partner: mark all other adjacent cells U, and partner's adjacent except this cell U
                    if len(adj_s) == 1:
                        pr, pc = adj_s[0]
                        # Mark all adjacent to (r,c) except partner as U
                        for dr, dc in DIRS:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if (nr, nc) != (pr, pc) and g[nr][nc] is None:
                                    g[nr][nc] = 'U'
                                    changed = True
                        # Mark all adjacent to partner except (r,c) as U
                        for dr, dc in DIRS:
                            nr, nc = pr + dr, pc + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if (nr, nc) != (r,c) and g[nr][nc] is None:
                                    g[nr][nc] = 'U'
                                    changed = True
        return True

    # Initial propagation
    if not propagate(grid, reg_count):
        return "No Solution"

    # Check if done
    def is_complete(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return False
        # Verify all constraints
        # Check region counts
        temp_rc = {rid:0 for rid in all_rids}
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'S':
                    temp_rc[data[r][c]] += 1
        for rid in all_rids:
            if temp_rc[rid] != 2:
                return False
        # Check all S have exactly one adjacent S
        for r in range(N):
            for c in range(N):
                if g[r][c] == 'S':
                    cnt = 0
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if 0<=nr<N and 0<=nc<N and g[nr][nc] == 'S':
                            cnt +=1
                    if cnt != 1:
                        return False
        return True

    if is_complete(grid):
        # Convert U to None
        res = []
        for row in grid:
            res_row = []
            for cell in row:
                res_row.append('S' if cell == 'S' else None)
            res.append(res_row)
        return res

    # Backtracking search with MRV heuristic
    def backtrack(g, rc):
        if is_complete(g):
            return g
        # Find cell with minimum remaining values
        min_options = float('inf')
        best_cell = None
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    # Count possible options
                    opts = 2
                    # Check if can be S
                    rid = data[r][c]
                    if rc[rid] >= 2:
                        opts -= 1
                    # Check adjacent S
                    has_adj_s = False
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if 0<=nr<N and 0<=nc<N and g[nr][nc] == 'S':
                            # Check if that S already has a partner
                            cnt_s = 0
                            for dr2, dc2 in DIRS:
                                nr2, nc2 = nr + dr2, nc + dc2
                                if 0<=nr2<N and 0<=nc2<N and g[nr2][nc2] == 'S':
                                    cnt_s +=1
                            if cnt_s >= 1:
                                opts -=1
                                break
                    if opts < min_options:
                        min_options = opts
                        best_cell = (r,c)
        if best_cell is None:
            return None
        r,c = best_cell
        # Try setting to S first
        new_g = deepcopy(g)
        new_rc = deepcopy(rc)
        new_g[r][c] = 'S'
        new_rc[data[r][c]] += 1
        if propagate(new_g, new_rc):
            res = backtrack(new_g, new_rc)
            if res is not None:
                return res
        # Try setting to U
        new_g = deepcopy(g)
        new_rc = deepcopy(rc)
        new_g[r][c] = 'U'
        if propagate(new_g, new_rc):
            res = backtrack(new_g, new_rc)
            if res is not None:
                return res
        return None

    solution = backtrack(grid, reg_count)
    if solution is None:
        return "No Solution"
    # Convert to required format
    res = []
    for row in solution:
        res_row = []
        for cell in row:
            res_row.append('S' if cell == 'S' else None)
        res.append(res_row)
    return res

