from collections import deque

DIRS = [(-1,0), (1,0), (0,-1), (0,1)]

def get_adjacent(r, c, rows, cols):
    res = []
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            res.append((nr, nc))
    return res

def check_2x2(state, rows, cols):
    for r in range(rows - 1):
        for c in range(cols - 1):
            cells = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
            b_count = 0
            unknown = None
            valid = True
            for (cr, cc) in cells:
                v = state[cr][cc]
                if v == 'B':
                    b_count +=1
                elif v is None:
                    if unknown is None:
                        unknown = (cr, cc)
                    else:
                        valid = False
                        break
            if not valid:
                continue
            if b_count ==4:
                return False, None
            if b_count ==3 and unknown is not None:
                return False, unknown
    return True, None

def check_b_connectivity(state, rows, cols):
    b_cells = []
    for r in range(rows):
        for c in range(cols):
            if state[r][c] == 'B':
                b_cells.append((r,c))
    if not b_cells:
        return True
    visited = set()
    q = deque([b_cells[0]])
    visited.add(b_cells[0])
    while q:
        r,c = q.popleft()
        for nr, nc in get_adjacent(r,c, rows, cols):
            if state[nr][nc] == 'B' and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    for (r,c) in b_cells:
        if (r,c) not in visited:
            return False
    return True

def propagate(state, islands, cell_to_island, rows, cols):
    changed = True
    while changed:
        changed = False
        valid, forced_w = check_2x2(state, rows, cols)
        if not valid and forced_w is None:
            return False
        if forced_w is not None:
            fr, fc = forced_w
            if state[fr][fc] == 'B':
                return False
            if state[fr][fc] is None:
                possible_islands = set()
                for nr, nc in get_adjacent(fr, fc, rows, cols):
                    if state[nr][nc] == 'W' and cell_to_island[nr][nc] != -1:
                        possible_islands.add(cell_to_island[nr][nc])
                if len(possible_islands) != 1:
                    return False
                is_idx = possible_islands.pop()
                isl = islands[is_idx]
                if len(isl['cells']) >= isl['target']:
                    return False
                state[fr][fc] = 'W'
                isl['cells'].add((fr, fc))
                cell_to_island[fr][fc] = is_idx
                changed = True
                continue
        for is_idx, isl in enumerate(islands):
            curr_size = len(isl['cells'])
            target = isl['target']
            if curr_size > target:
                return False
            adjacent_unknown = []
            for (r,c) in isl['cells']:
                for nr, nc in get_adjacent(r,c, rows, cols):
                    if state[nr][nc] is None:
                        adjacent_unknown.append((nr, nc))
                    elif state[nr][nc] == 'W' and cell_to_island[nr][nc] != is_idx:
                        return False
            adjacent_unknown = list(set(adjacent_unknown))
            if curr_size + len(adjacent_unknown) < target:
                return False
            if curr_size == target:
                for (nr, nc) in adjacent_unknown:
                    if state[nr][nc] == 'W':
                        return False
                    if state[nr][nc] is None:
                        state[nr][nc] = 'B'
                        changed = True
            elif curr_size + len(adjacent_unknown) == target:
                for (nr, nc) in adjacent_unknown:
                    if state[nr][nc] == 'B':
                        return False
                    if state[nr][nc] is None:
                        state[nr][nc] = 'W'
                        isl['cells'].add((nr, nc))
                        cell_to_island[nr][nc] = is_idx
                        changed = True
        if not check_b_connectivity(state, rows, cols):
            return False
    return True

def is_complete(state, rows, cols):
    for r in range(rows):
        for c in range(cols):
            if state[r][c] is None:
                return False
    return True

def final_check(state, islands, rows, cols):
    if not check_b_connectivity(state, rows, cols):
        return False
    for r in range(rows-1):
        for c in range(cols-1):
            if state[r][c] == 'B' and state[r][c+1] == 'B' and state[r+1][c] == 'B' and state[r+1][c+1] == 'B':
                return False
    all_w = set()
    for isl in islands:
        if len(isl['cells']) != isl['target']:
            return False
        for cell in isl['cells']:
            if cell in all_w:
                return False
            all_w.add(cell)
    for r in range(rows):
        for c in range(cols):
            if state[r][c] == 'W' and (r,c) not in all_w:
                return False
    return True

def select_unknown(state, islands, cell_to_island, rows, cols):
    candidates = []
    for r in range(rows):
        for c in range(cols):
            if state[r][c] is None:
                score = 0
                for nr, nc in get_adjacent(r,c, rows, cols):
                    if state[nr][nc] is not None:
                        score +=1
                b_2x2 = 0
                for dr in [0, -1]:
                    for dc in [0, -1]:
                        tr, tc = r + dr, c + dc
                        if 0 <= tr < rows-1 and 0 <= tc < cols-1:
                            cnt = 0
                            for ar in [0, 1]:
                                for ac in [0,1]:
                                    if state[tr+ar][tc+ac] == 'B':
                                        cnt +=1
                            if cnt >=2:
                                score += cnt
                candidates.append((-score, r, c))
    candidates.sort()
    return (candidates[0][1], candidates[0][2])

def backtrack(state, islands, cell_to_island, rows, cols):
    if not propagate(state, islands, cell_to_island, rows, cols):
        return None
    if is_complete(state, rows, cols):
        if final_check(state, islands, rows, cols):
            return state
        return None
    r, c = select_unknown(state, islands, cell_to_island, rows, cols)
    for val in ['B', 'W']:
        new_state = [row.copy() for row in state]
        new_islands = [{'root': isl['root'], 'target': isl['target'], 'cells': set(isl['cells'])} for isl in islands]
        new_cell_to_island = [row.copy() for row in cell_to_island]
        new_state[r][c] = val
        valid = True
        if val == 'W':
            possible_islands = []
            for nr, nc in get_adjacent(r,c, rows, cols):
                if new_state[nr][nc] == 'W' and new_cell_to_island[nr][nc] != -1:
                    is_idx = new_cell_to_island[nr][nc]
                    if is_idx not in possible_islands:
                        possible_islands.append(is_idx)
            if len(possible_islands) != 1:
                continue
            is_idx = possible_islands[0]
            isl = new_islands[is_idx]
            if len(isl['cells']) >= isl['target']:
                continue
            isl['cells'].add((r,c))
            new_cell_to_island[r][c] = is_idx
        res = backtrack(new_state, new_islands, new_cell_to_island, rows, cols)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    state = [[None for _ in range(cols)] for _ in range(rows)]
    islands = []
    cell_to_island = [[-1 for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            num = data[r][c]
            if num is not None:
                state[r][c] = 'W'
                islands.append({'root': (r,c), 'target': num, 'cells': {(r,c)}})
                cell_to_island[r][c] = len(islands)-1
                if num == 1:
                    for nr, nc in get_adjacent(r,c, rows, cols):
                        state[nr][nc] = 'B'
    solution = backtrack(state, islands, cell_to_island, rows, cols)
    if not solution:
        return "No Solution"
    output = []
    for row in solution:
        out_row = []
        for v in row:
            out_row.append('B' if v == 'B' else None)
        output.append(out_row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
