def propagate_constraints(grid):
    N = len(grid)
    changed = True
    while changed:
        changed = False
        for i in range(N - 1):
            for j in range(N - 1):
                cells = [(i, j), (i, j+1), (i+1, j), (i+1, j+1)]
                values = [grid[x][y] for x, y in cells]
                count_b = values.count('B')
                count_w = values.count('W')
                if count_b == 4 or count_w == 4:
                    return (grid, False)
                if count_b == 3:
                    for idx in range(4):
                        if values[idx] is None:
                            x, y = cells[idx]
                            if grid[x][y] is None:
                                grid[x][y] = 'W'
                                changed = True
                            elif grid[x][y] != 'W':
                                return (grid, False)
                elif count_w == 3:
                    for idx in range(4):
                        if values[idx] is None:
                            x, y = cells[idx]
                            if grid[x][y] is None:
                                grid[x][y] = 'B'
                                changed = True
                            elif grid[x][y] != 'B':
                                return (grid, False)
    for i in range(N - 1):
        for j in range(N - 1):
            vals = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if len(vals) == 1 and None not in vals:
                return (grid, False)
    return (grid, True)

def is_connected(grid, color):
    N = len(grid)
    cells = []
    for i in range(N):
        for j in range(N):
            if grid[i][j] == color:
                cells.append((i, j))
    if not cells:
        return True
    visited = set()
    q = [cells[0]]
    visited.add(cells[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.pop(0)
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and grid[nx][ny] == color and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny))
    return len(visited) == len(cells)

def solve(observation):
    data = observation['data']
    N = len(data)
    initial = [row.copy() for row in data]
    initial, valid = propagate_constraints(initial)
    if not valid:
        return "No Solution"

    def backtrack(grid):
        empty = []
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    empty.append((i, j))
        if not empty:
            if is_connected(grid, 'B') and is_connected(grid, 'W'):
                return grid
            return None

        best_cell = None
        min_options = 3
        best_options = []
        for (i, j) in empty:
            options = []
            temp_b = [r.copy() for r in grid]
            temp_b[i][j] = 'B'
            _, ok_b = propagate_constraints([r.copy() for r in temp_b])
            if ok_b:
                options.append('B')
            temp_w = [r.copy() for r in grid]
            temp_w[i][j] = 'W'
            _, ok_w = propagate_constraints([r.copy() for r in temp_w])
            if ok_w:
                options.append('W')
            if len(options) < min_options:
                min_options = len(options)
                best_cell = (i, j)
                best_options = options
                if min_options == 0:
                    return None

        i, j = best_cell
        for color in best_options:
            new_grid = [r.copy() for r in grid]
            new_grid[i][j] = color
            new_grid, valid = propagate_constraints(new_grid)
            if not valid:
                continue
            res = backtrack(new_grid)
            if res is not None:
                return res
        return None

    result = backtrack(initial)
    return result if result is not None else "No Solution"

