# Direction definitions
UP = (-1, 0)
DOWN = (1, 0)
LEFT = (0, -1)
RIGHT = (0, 1)
DIRS = [UP, DOWN, LEFT, RIGHT]
OPPOSITE = {UP: DOWN, DOWN: UP, LEFT: RIGHT, RIGHT: LEFT}
PERPENDICULAR = {
    UP: [LEFT, RIGHT],
    DOWN: [LEFT, RIGHT],
    LEFT: [UP, DOWN],
    RIGHT: [UP, DOWN]
}

def is_valid_pos(r, c, N):
    return 0 <= r < N and 0 <= c < N

def set_edge(edges, r, c, d, val):
    nr, nc = r + d[0], c + d[1]
    if not is_valid_pos(nr, nc, len(edges)):
        return False
    if edges[r][c][d] is not None and edges[r][c][d] != val:
        return False
    edges[r][c][d] = val
    edges[nr][nc][OPPOSITE[d]] = val
    return True

def propagate(edges, N, clues):
    changed = True
    while changed:
        changed = False
        # General node degree constraints
        for r in range(N):
            for c in range(N):
                present = [d for d in DIRS if edges[r][c][d] is True]
                absent = [d for d in DIRS if edges[r][c][d] is False]
                unknown = [d for d in DIRS if edges[r][c][d] is None]
                cnt_present = len(present)
                cnt_unknown = len(unknown)
                if cnt_present > 2:
                    return False, edges
                # If exactly 2 present, set rest to absent
                if cnt_present == 2:
                    for d in unknown:
                        if not set_edge(edges, r, c, d, False):
                            return False, edges
                        changed = True
                # If need more edges than unknown, invalid
                if cnt_present + cnt_unknown < 2:
                    return False, edges
                # If remaining unknown must all be present
                if cnt_present + cnt_unknown == 2 and cnt_unknown > 0:
                    for d in unknown:
                        if not set_edge(edges, r, c, d, True):
                            return False, edges
                        changed = True
        # Clue specific constraints
        for (r, c, typ) in clues:
            present = [d for d in DIRS if edges[r][c][d] is True]
            absent = [d for d in DIRS if edges[r][c][d] is False]
            unknown = [d for d in DIRS if edges[r][c][d] is None]
            if typ == 'B':
                # B must have perpendicular edges, no opposite
                # Check if present edges are opposite
                if len(present) == 2:
                    if OPPOSITE[present[0]] == present[1]:
                        return False, edges
                    # B requires both edges extend straight 1 more
                    for d in present:
                        nr1, nc1 = r + d[0], c + d[1]
                        nr2, nc2 = r + 2*d[0], c + 2*d[1]
                        if not is_valid_pos(nr2, nc2, N):
                            return False, edges
                        if not set_edge(edges, nr1, nc1, d, True):
                            return False, edges
                        changed = True
                elif len(present) == 1:
                    d1 = present[0]
                    # Second edge must be perpendicular
                    invalid = [OPPOSITE[d1]] + [d for d in PERPENDICULAR[d1] if d in absent]
                    possible = [d for d in PERPENDICULAR[d1] if d not in absent]
                    if len(possible) == 0:
                        return False, edges
                    if len(possible) == 1:
                        d2 = possible[0]
                        if not set_edge(edges, r, c, d2, True):
                            return False, edges
                        changed = True
                    # Extend first edge straight
                    nr1, nc1 = r + d1[0], c + d1[1]
                    nr2, nc2 = r + 2*d1[0], c + 2*d1[1]
                    if not is_valid_pos(nr2, nc2, N):
                        return False, edges
                    if not set_edge(edges, nr1, nc1, d1, True):
                        return False, edges
                    changed = True
                # Eliminate opposite pairs for unknown
                if len(present) == 0:
                    # Check if any opposite pair is possible, eliminate impossible
                    if (UP in absent or DOWN in absent) and (LEFT in absent or RIGHT in absent):
                        return False, edges
            elif typ == 'W':
                # W must have opposite edges, straight
                if len(present) == 2:
                    if OPPOSITE[present[0]] != present[1]:
                        return False, edges
                    # Check at least one turn in prev/next step
                    d = present[0]
                    nr1, nc1 = r + d[0], c + d[1]
                    nr2, nc2 = r + 2*d[0], c + 2*d[1]
                    od = OPPOSITE[d]
                    onr1, onc1 = r + od[0], c + od[1]
                    onr2, onc2 = r + 2*od[0], c + 2*od[1]
                    straight_before = False
                    if is_valid_pos(onr2, onc2, N) and edges[onr1][onc1][od] is True:
                        straight_before = True
                    straight_after = False
                    if is_valid_pos(nr2, nc2, N) and edges[nr1][nc1][d] is True:
                        straight_after = True
                    if straight_before and straight_after:
                        return False, edges
                elif len(present) == 1:
                    d1 = present[0]
                    d2 = OPPOSITE[d1]
                    if d2 in absent:
                        return False, edges
                    if not set_edge(edges, r, c, d2, True):
                        return False, edges
                    changed = True
                # Eliminate perpendicular pairs
                if len(present) == 0:
                    has_vertical = (UP not in absent and DOWN not in absent)
                    has_horizontal = (LEFT not in absent and RIGHT not in absent)
                    if not has_vertical and not has_horizontal:
                        return False, edges
    return True, edges

def build_path(edges, N, start):
    path = [start]
    prev_dir = None
    current = start
    while True:
        r, c = current
        next_dir = None
        for d in DIRS:
            if edges[r][c][d] is True and (prev_dir is None or d != OPPOSITE[prev_dir]):
                next_dir = d
                break
        if next_dir is None:
            return None
        nr, nc = r + next_dir[0], c + next_dir[1]
        current = (nr, nc)
        path.append(current)
        prev_dir = next_dir
        if current == start:
            break
    return path

def is_valid_solution(edges, N, clues, path):
    # Check all clues are on path
    clue_pos = set((r,c) for (r,c,_) in clues)
    path_set = set(path)
    if not clue_pos.issubset(path_set):
        return False
    # Check path length is correct for loop
    if len(path) < 4:
        return False
    # Check no branches: all nodes in path have exactly 2 edges
    for (r,c) in path_set:
        cnt = sum(1 for d in DIRS if edges[r][c][d] is True)
        if cnt != 2:
            return False
    return True

def backtrack(edges, N, clues):
    # Propagate first
    valid, edges = propagate(edges, N, clues)
    if not valid:
        return None
    # Check if all edges are determined
    all_determined = True
    candidate = None
    min_unknown = 100
    for r in range(N):
        for c in range(N):
            unknown = [d for d in DIRS if edges[r][c][d] is None and is_valid_pos(r+d[0], c+d[1], N)]
            if len(unknown) > 0:
                all_determined = False
                if len(unknown) < min_unknown:
                    min_unknown = len(unknown)
                    candidate = (r, c, unknown[0])
    if all_determined:
        # Build path and validate
        start = next((r,c) for (r,c,_) in clues)
        path = build_path(edges, N, start)
        if path and is_valid_solution(edges, N, clues, path):
            return path
        return None
    # Branch on candidate edge
    r, c, d = candidate
    # Try True first
    new_edges = [[{d2: edges[r2][c2][d2] for d2 in DIRS} for c2 in range(N)] for r2 in range(N)]
    if set_edge(new_edges, r, c, d, True):
        res = backtrack(new_edges, N, clues)
        if res is not None:
            return res
    # Try False
    new_edges = [[{d2: edges[r2][c2][d2] for d2 in DIRS} for c2 in range(N)] for r2 in range(N)]
    if set_edge(new_edges, r, c, d, False):
        res = backtrack(new_edges, N, clues)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    clues = [(r,c, data[r][c]) for r in range(N) for c in range(N) if data[r][c] is not None]
    if not clues:
        return "No Solution"
    # Initialize edges
    edges = [[{d: None for d in DIRS} for _ in range(N)] for _ in range(N)]
    # Mark out of bounds edges as False
    for r in range(N):
        for c in range(N):
            for d in DIRS:
                nr, nc = r + d[0], c + d[1]
                if not is_valid_pos(nr, nc, N):
                    edges[r][c][d] = False
    # Backtrack
    solution = backtrack(edges, N, clues)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
