                    row_counts[r] -= 1
                    col_counts[c] -= 1
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            if dr == 0 and dc == 0:
                                continue
                            ar = r + dr
                            ac = c + dc
                            if 0<=ar<rows and 0<=ac<cols and grid[ar][ac] is None:
                                grid[ar][ac] = 'X'
                                changed = True
                    changed = True

        # Rule 3: Column remaining count equals available cells
        for c in range(cols):
            available = [r for r in range(rows) if grid[r][c] is None]
            needed = col_counts[c]
            if needed == 0:
                for r in available:
                    grid[r][c] = 'X'
                    changed = True
            elif len(available) == needed and needed > 0:
                for r in available:
                    grid[r][c] = 't'
                    row_counts[r] -= 1
                    col_counts[c] -= 1
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            if dr ==0 and dc ==0:
                                continue
                            ar = r + dr
                            ac = c + dc
                            if 0<=ar<rows and 0<=ac<cols and grid[ar][ac] is None:
                                grid[ar][ac] = 'X'
                                changed = True
                    changed = True

        # Rule 4: Cell is candidate for exactly one tree
        cell_map = defaultdict(list)
        for (tr, tc) in unpaired_trees:
            candidates = []
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr = tr + dr
                nc = tc + dc
                if 0<=nr<rows and 0<=nc<cols and grid[nr][nc] is None:
                    candidates.append((nr, nc))
            for (nr, nc) in candidates:
                cell_map[(nr, nc)].append((tr, tc))
        for (cell, trees) in cell_map.items():
            if len(trees) == 1:
                nr, nc = cell
                tr, tc = trees[0]
                if grid[nr][nc] is None:
                    grid[nr][nc] = 't'
                    row_counts[nr] -= 1
                    col_counts[nc] -= 1
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            if dr ==0 and dc ==0:
                                continue
                            ar = nr + dr
                            ac = nc + dc
                            if 0<=ar<rows and 0<=ac<cols and grid[ar][ac] is None:
                                grid[ar][ac] = 'X'
                                changed = True
                    if (tr, tc) in unpaired_trees:
                        unpaired_trees.remove((tr, tc))
                    changed = True

    # Check if we have invalid state
    for r in range(rows):
        if row_counts[r] < 0:
            return False
    for c in range(cols):
        if col_counts[c] < 0:
            return False
    return True

def backtrack(grid, row_counts, col_counts, unpaired_trees, rows, cols):
    # Apply deductions first
    valid = apply_deductions(grid, row_counts, col_counts, unpaired_trees, rows, cols)
    if not valid:
        return None

    # Check if done
    if all(rc == 0 for rc in row_counts) and all(cc == 0 for cc in col_counts) and len(unpaired_trees) == 0:
        if is_valid(grid, rows, cols):
            return grid
        return None

    # Pick tree with smallest candidate list
    min_candidates = float('inf')
    chosen_tree = None
    candidates_list = []
    for (tr, tc) in unpaired_trees:
        candidates = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr = tr + dr
            nc = tc + dc
            if 0<=nr<rows and 0<=nc<cols and grid[nr][nc] is None:
                candidates.append((nr, nc))
        if len(candidates) < min_candidates:
            min_candidates = len(candidates)
            chosen_tree = (tr, tc)
            candidates_list = candidates
            if min_candidates == 0:
                return None

    if not candidates_list:
        return None

    # Try each candidate
    for (nr, nc) in candidates_list:
        # Create copies
        new_grid = deepcopy(grid)
        new_row_counts = deepcopy(row_counts)
        new_col_counts = deepcopy(col_counts)
        new_unpaired = deepcopy(unpaired_trees)

        # Place tent
        new_grid[nr][nc] = 't'
        new_row_counts[nr] -= 1
        new_col_counts[nc] -= 1
        # Block adjacent cells
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr ==0 and dc ==0:
                    continue
                ar = nr + dr
                ac = nc + dc
                if 0<=ar<rows and 0<=ac<cols and new_grid[ar][ac] is None:
                    new_grid[ar][ac] = 'X'
        # Remove tree from unpaired
        new_unpaired.remove(chosen_tree)

        # Recurse
        res = backtrack(new_grid, new_row_counts, new_col_counts, new_unpaired, rows, cols)
        if res is not None:
            return res

    return None

def solve(observation):
    tree_grid = observation['tree']
    rows = len(tree_grid)
    cols = len(tree_grid[0]) if rows else 0
    row_counts = deepcopy(observation['row_tent_counts'])
    col_counts = deepcopy(observation['col_tent_counts'])

    # Initialize internal grid
    grid = []
    unpaired_trees = []
    for r in range(rows):
        row = []
        for c in range(cols):
            val = tree_grid[r][c]
            if val == 'T':
                row.append('T')
                unpaired_trees.append((r,c))
            else:
                row.append(None)
        grid.append(row)

    # Mark rows and columns with 0 count as blocked first
    for r in range(rows):
        if row_counts[r] == 0:
            for c in range(cols):
                if grid[r][c] != 'T':
                    grid[r][c] = 'X'
    for c in range(cols):
        if col_counts[c] == 0:
            for r in range(rows):
                if grid[r][c] != 'T':
                    grid[r][c] = 'X'

    solved_grid = backtrack(grid, row_counts, col_counts, unpaired_trees, rows, cols)
    if not solved_grid:
        return "No Solution"

    # Convert to output format: 't' for tents, None otherwise
    output = []
    for r in range(rows):
        out_row = []
        for c in range(cols):
            out_row.append('t' if solved_grid[r][c] == 't' else None)
        output.append(out_row)
    return output

