                b_count = sum(1 for x in cells if x == 'B')
                w_count = sum(1 for x in cells if x == 'W')
                if b_count == 4 or w_count == 4:
                    return False
                if b_count == 3:
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        nr, nc = r + dr, c + dc
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
                            break
                if w_count == 3:
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        nr, nc = r + dr, c + dc
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'B'
                            changed = True
                            break
    return True

def is_complete(grid):
    for row in grid:
        if None in row:
            return False
    return True

def count_connected(grid, color):
    N = len(grid)
    visited = [[False]*N for _ in range(N)]
    count = 0
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for r in range(N):
        for c in range(N):
            if grid[r][c] == color and not visited[r][c]:
                count += 1
                q = [(r, c)]
                visited[r][c] = True
                while q:
                    x, y = q.pop(0)
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny] and grid[nx][ny] == color:
                            visited[nx][ny] = True
                            q.append((nx, ny))
    return count

def is_valid_complete(grid):
    N = len(grid)
    for r in range(N-1):
        for c in range(N-1):
            block = {grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]}
            if len(block) == 1:
                return False
    if count_connected(grid, 'B') != 1 or count_connected(grid, 'W') != 1:
        return False
    return True

def solve(observation):
    grid = [row.copy() for row in observation['data']]
    N = len(grid)

    def backtrack():
        if not propagate_constraints(grid):
            return None
        if is_complete(grid):
            return [row.copy() for row in grid] if is_valid_complete(grid) else None

        min_options = 3
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    options = 0
                    grid[r][c] = 'B'
                    valid_b = True
                    for dr in (-1, 0):
                        for dc in (-1, 0):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N-1 and 0 <= nc < N-1:
                                if len({grid[nr][nc], grid[nr][nc+1], grid[nr+1][nc], grid[nr+1][nc+1]}) == 1:
                                    valid_b = False
                                    break
                        if not valid_b:
                            break
                    if valid_b:
                        options += 1

                    grid[r][c] = 'W'
                    valid_w = True
                    for dr in (-1, 0):
                        for dc in (-1, 0):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N-1 and 0 <= nc < N-1:
                                if len({grid[nr][nc], grid[nr][nc+1], grid[nr+1][nc], grid[nr+1][nc+1]}) == 1:
                                    valid_w = False
                                    break
                        if not valid_w:
                            break
                    if valid_w:
                        options += 1

                    grid[r][c] = None
                    if options < min_options:
                        min_options = options
                        best_cell = (r, c)
                        if min_options == 0:
                            return None
                        if min_options == 1:
                            break
            if min_options == 1:
                break

        if best_cell is None:
            return None
        r, c = best_cell

        for color in ['B', 'W']:
            grid[r][c] = color
            valid = True
            for dr in (-1, 0):
                for dc in (-1, 0):
