                        if len({grid[nr][nc], grid[nr][nc+1], grid[nr+1][nc], grid[nr+1][nc+1]}) == 1:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                res = backtrack()
                if res is not None:
                    return res
            grid[r][c] = None
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

