                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if state[nr][nc] == 'F':
                                flag_count += 1
                            elif state[nr][nc] == 'U':
                                unknown_cells.append((nr, nc))

                # Case 1: All required mines found, remaining unknowns are safe
                if flag_count == clue:
                    for (nr, nc) in unknown_cells:
                        state[nr][nc] = 'S'
                        changed = True
                # Case 2: Remaining unknowns must all be mines
                remaining_mines = clue - flag_count
                if remaining_mines == len(unknown_cells) and remaining_mines > 0:
                    for (nr, nc) in unknown_cells:
                        state[nr][nc] = 'F'
                        changed = True

    # Helper to validate current state for backtracking
    def is_valid(current_state):
        for r in range(rows):
            for c in range(cols):
                clue = data[r][c]
                if clue is None:
                    continue
                flags = 0
                unknowns = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if current_state[nr][nc] == 'F':
                                flags += 1
                            elif current_state[nr][nc] == 'U':
                                unknowns += 1
                if flags > clue:
                    return False
                if (flags + unknowns) < clue:
                    return False
        return True

    # Check if we already solved it
    has_unknown = any('U' in row for row in state)
    if not has_unknown:
        if is_valid(state):
            return [['F' if cell == 'F' else None for cell in row] for row in state]
        else:
            return "No Solution"

    # Backtracking search for remaining unknowns (only runs if deduction is stuck)
    def backtrack(current_state):
        if not is_valid(current_state):
            return None

        # Find most constrained unknown cell (adjacent to most clues to minimize branching)
        best_cell = None
        max_adj_clues = -1
        for r in range(rows):
            for c in range(cols):
                if current_state[r][c] == 'U':
                    adj_clue_count = 0
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols and data[nr][nc] is not None:
                                adj_clue_count += 1
                    if adj_clue_count > max_adj_clues:
                        max_adj_clues = adj_clue_count
                        best_cell = (r, c)

        # No constrained cells left, pick first unknown
        if best_cell is None:
            for r in range(rows):
                for c in range(cols):
                    if current_state[r][c] == 'U':
                        best_cell = (r, c)
                        break
                if best_cell:
                    break

        # No unknowns left, return solution
        if best_cell is None:
            return [row.copy() for row in current_state] if is_valid(current_state) else None

        r, c = best_cell
        # Try placing mine first
        current_state[r][c] = 'F'
        res = backtrack(current_state)
        if res is not None:
            return res
        # Try placing safe
        current_state[r][c] = 'S'
        res = backtrack(current_state)
        if res is not None:
            return res
        # Backtrack
        current_state[r][c] = 'U'
        return None

    final_state = backtrack(state)
    if not final_state:
        return "No Solution"

    # Convert to required output format
    return [['F' if cell == 'F' else None for cell in row] for row in final_state]

if __name__ == "__main__":
    print(solve(OBSERVATION))
