def apply_forced_moves(grid):
    n = len(grid)
    changed = True
    while changed:
        changed = False
        # 2x2 block forced fill rule
        for i in range(n - 1):
            for j in range(n - 1):
                cells = [grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]]
                cnt_b = sum(1 for c in cells if c == 'B')
                cnt_w = sum(1 for c in cells if c == 'W')
                if cnt_b == 3:
