            for dx, dy in DIRS:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    if grid[nx][ny] in ('B', None):
                        visited.add((nx, ny))
                        q.append((nx, ny))
        for (x,y) in b_cells:
            if (x,y) not in visited:
                return False
    # Check W connectivity possibility
    w_cells = [(i,j) for i in range(n) for j in range(n) if grid[i][j] == 'W']
    if w_cells:
