            for dx, dy in DIRS:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    if grid[nx][ny] in ('W', None):
                        visited.add((nx, ny))
                        q.append((nx, ny))
        for (x,y) in w_cells:
            if (x,y) not in visited:
