def is_final_valid(grid):
    n = len(grid)
    # Check 2x2 rule
    for i in range(n-1):
        for j in range(n-1):
            s = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if len(s) == 1:
                return False
    # Check B connected
    b_cells = [(i,j) for i in range(n) for j in range(n) if grid[i][j] == 'B']
    visited = set([b_cells[0]])
    q = [b_cells[0]]
    while q:
        x,y = q.pop()
        for dx, dy in DIRS:
            nx, ny = x+dx, y+dy
            if 0<=nx<n and 0<=ny<n and (nx,ny) not in visited and grid[nx][ny] == 'B':
                visited.add((nx,ny))
                q.append((nx,ny))
    if len(visited) != len(b_cells):
        return False
    # Check W connected
    w_cells = [(i,j) for i in range(n) for j in range(n) if grid[i][j] == 'W']
