        for dx, dy in DIRS:
            nx, ny = x+dx, y+dy
            if 0<=nx<n and 0<=ny<n and (nx,ny) not in visited and grid[nx][ny] == 'W':
                visited.add((nx,ny))
                q.append((nx,ny))
    if len(visited) != len(w_cells):
        return False
    return True

def select_next_cell(grid):
    n = len(grid)
    max_constraint = -1
    best_cell = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] is None:
                cnt = 0
                for dx, dy in DIRS:
