    if not is_partial_valid(grid):
        return None
    next_cell = select_next_cell(grid)
    if next_cell is None:
        if is_final_valid(grid):
            return grid
        return None
    i,j = next_cell
    # Try both values, prioritize less frequent value in neighbors first
    cnt_b = 0
    cnt_w = 0
    for dx, dy in DIRS:
        nx, ny = i+dx, j+dy
        if 0<=nx<len(grid) and 0<=ny<len(grid):
