            elif grid[nx][ny] == 'W': cnt_w +=1
    order = ['W', 'B'] if cnt_b > cnt_w else ['B', 'W']
    for val in order:
        grid[i][j] = val
        res = backtrack(grid)
        if res is not None:
            return res
        grid[i][j] = None
    return None

def solve(observation):
    initial_grid = deepcopy(observation['data'])
    solution = backtrack(initial_grid)
    return solution if solution else "No Solution"

