OBSERVATION = {"row_sum": [1, 22, 12, 12, 27, 11, 34, 16, 27], "col_sum": [43, 27, 35, 10, 10, 26, 14, 39, 9]}

def generate_masks(target, max_idx, weight_func):
    masks = []
    def backtrack(idx, current_sum, current_mask):
        if current_sum == target:
            masks.append(current_mask)
            return
        if idx >= max_idx or current_sum > target:
            return
        w = weight_func(idx)
        if current_sum + w <= target:
            backtrack(idx + 1, current_sum + w, current_mask | (1 << idx))
        backtrack(idx + 1, current_sum, current_mask)
    backtrack(0, 0, 0)
    return masks

def propagate(grid, row_masks, col_masks, num_rows, num_cols):
    changed = True
    while changed:
        changed = False
        # Deduce fixed cells from row possible masks
        for r in range(num_rows):
            masks = row_masks[r]
            if not masks:
                return False
            for c in range(num_cols):
                if grid[r][c] is not None:
                    continue
                all_set = all((mask & (1 << c)) != 0 for mask in masks)
                all_unset = all((mask & (1 << c)) == 0 for mask in masks)
                if all_set:
                    grid[r][c] = 'B'
                    changed = True
                elif all_unset:
                    grid[r][c] = None
                    changed = True
        # Deduce fixed cells from column possible masks
        for c in range(num_cols):
            masks = col_masks[c]
            if not masks:
                return False
            for r in range(num_rows):
                if grid[r][c] is not None:
                    continue
                all_set = all((mask & (1 << r)) != 0 for mask in masks)
                all_unset = all((mask & (1 << r)) == 0 for mask in masks)
                if all_set:
                    grid[r][c] = 'B'
                    changed = True
                elif all_unset:
                    grid[r][c] = None
                    changed = True
        # Filter row masks to match fixed cells
        for r in range(num_rows):
            fixed = [(c, 1 if grid[r][c] == 'B' else 0) for c in range(num_cols) if grid[r][c] is not None]
            new_masks = []
            for mask in row_masks[r]:
                valid = True
                for c, expected in fixed:
                    actual = 1 if (mask & (1 << c)) else 0
                    if actual != expected:
                        valid = False
                        break
                if valid:
                    new_masks.append(mask)
            if not new_masks:
                return False
            if len(new_masks) != len(row_masks[r]):
                changed = True
                row_masks[r] = new_masks
        # Filter column masks to match fixed cells
        for c in range(num_cols):
            fixed = [(r, 1 if grid[r][c] == 'B' else 0) for r in range(num_rows) if grid[r][c] is not None]
            new_masks = []
            for mask in col_masks[c]:
                valid = True
                for r, expected in fixed:
                    actual = 1 if (mask & (1 << r)) else 0
                    if actual != expected:
                        valid = False
                        break
                if valid:
                    new_masks.append(mask)
            if not new_masks:
                return False
            if len(new_masks) != len(col_masks[c]):
                changed = True
                col_masks[c] = new_masks
    return True

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    num_rows = len(row_sum)
    num_cols = len(col_sum)

    # Precompute all possible valid masks for each row and column
    row_masks = []
    for r in range(num_rows):
        masks = generate_masks(row_sum[r], num_cols, lambda c: c + 1)
        if not masks:
            return "No Solution"
        row_masks.append(masks)

    col_masks = []
    for c in range(num_cols):
        masks = generate_masks(col_sum[c], num_rows, lambda r: r + 1)
        if not masks:
            return "No Solution"
        col_masks.append(masks)

    # Initialize empty grid
    grid = [[None for _ in range(num_cols)] for _ in range(num_rows)]

    # Initial constraint propagation
    if not propagate(grid, row_masks, col_masks, num_rows, num_cols):
        return "No Solution"

    # Check if grid is already complete
    def is_complete(g):
        return all(None not in row for row in g)

    if is_complete(grid):
        return grid

    # Backtracking search with MRV heuristic
    def backtrack(current_grid, current_row_masks, current_col_masks):
        # Select cell with minimum branching factor (MRV heuristic)
        min_branch = float('inf')
        best_cell = None
        for r in range(num_rows):
            for c in range(num_cols):
                if current_grid[r][c] is None:
                    set_count = sum(1 for m in current_row_masks[r] if (m & (1 << c)))
                    unset_count = len(current_row_masks[r]) - set_count
                    branch = min(set_count, unset_count)
                    if branch < min_branch:
                        min_branch = branch
                        best_cell = (r, c)
        if best_cell is None:
            return current_grid
        r, c = best_cell

        # Try setting cell to Black
        grid_b = [row.copy() for row in current_grid]
        rm_b = [m.copy() for m in current_row_masks]
        cm_b = [m.copy() for m in current_col_masks]
        grid_b[r][c] = 'B'
        if propagate(grid_b, rm_b, cm_b, num_rows, num_cols):
            res = backtrack(grid_b, rm_b, cm_b)
            if res is not None:
                return res

        # Try setting cell to non-Black
        grid_nb = [row.copy() for row in current_grid]
        rm_nb = [m.copy() for m in current_row_masks]
        cm_nb = [m.copy() for m in current_col_masks]
        grid_nb[r][c] = None
        if propagate(grid_nb, rm_nb, cm_nb, num_rows, num_cols):
            res = backtrack(grid_nb, rm_nb, cm_nb)
            if res is not None:
                return res

        return None

    result = backtrack(grid, row_masks, col_masks)
    return result if result is not None else "No Solution"

