from collections import defaultdict

def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']
    n_rows = len(row_targets)
    n_cols = len(col_targets)

    # Group cells by region, sort each region's cells from bottom to top (descending row order)
    region_cells = defaultdict(list)
    for r in range(n_rows):
        for c in range(n_cols):
            reg_id = region_grid[r][c]
            region_cells[reg_id].append((r, c))
    for reg_id in region_cells:
        region_cells[reg_id].sort(reverse=True, key=lambda x: x[0])
    all_regions = list(region_cells.keys())
    total_regions = len(all_regions)

    # Precompute all possible fill levels (k) for each region, with their row/col count deltas
    region_possible_levels = {}
    for reg_id in all_regions:
        cells = region_cells[reg_id]
        max_possible_k = len(cells)
        levels = []
        for k in range(max_possible_k + 1):
            row_delta = [0] * n_rows
            col_delta = [0] * n_cols
            for i in range(k):
                r, c = cells[i]
                row_delta[r] += 1
                col_delta[c] += 1
            levels.append((k, row_delta, col_delta))
        region_possible_levels[reg_id] = levels

    # Backtracking state tracking
    current_row_counts = [0] * n_rows
    current_col_counts = [0] * n_cols
    assigned_levels = {}

    def backtrack(assigned_count):
        if assigned_count == total_regions:
            # Verify full solution matches all targets
            if current_row_counts == row_targets and current_col_counts == col_targets:
                # Build final result grid
                result = [[None for _ in range(n_cols)] for _ in range(n_rows)]
                for reg_id in assigned_levels:
                    k = assigned_levels[reg_id]
                    cells = region_cells[reg_id]
                    for i in range(k):
                        r, c = cells[i]
                        result[r][c] = 'W'
                return result
            return None

        # Select most constrained region first (minimum valid options) to prune early
        best_region = None
        best_valid_options = None
        for reg_id in all_regions:
            if reg_id in assigned_levels:
                continue
            valid_options = []
            for (k, rd, cd) in region_possible_levels[reg_id]:
                # Skip levels that immediately exceed row/col targets
                valid = True
                for r in range(n_rows):
                    if current_row_counts[r] + rd[r] > row_targets[r]:
                        valid = False
                        break
                if not valid:
                    continue
                for c in range(n_cols):
                    if current_col_counts[c] + cd[c] > col_targets[c]:
                        valid = False
                        break
                if valid:
                    valid_options.append((k, rd, cd))
            if not valid_options:
                return None  # No possible values for this region, prune path
            if best_region is None or len(valid_options) < len(best_valid_options):
                best_region = reg_id
                best_valid_options = valid_options

        reg_id = best_region
        for (k, rd, cd) in best_valid_options:
            # Apply level selection
            for r in range(n_rows):
                current_row_counts[r] += rd[r]
            for c in range(n_cols):
                current_col_counts[c] += cd[c]
            assigned_levels[reg_id] = k

            # Prune: check if even maximum possible remaining fill can meet targets
            prune = False
            unassigned_regions = [r for r in all_regions if r not in assigned_levels]
            remaining_max_row = [0] * n_rows
            remaining_max_col = [0] * n_cols
            for unreg in unassigned_regions:
                _, urd, ucd = region_possible_levels[unreg][-1]
                for r in range(n_rows):
                    remaining_max_row[r] += urd[r]
                for c in range(n_cols):
                    remaining_max_col[c] += ucd[c]
            # Check row feasibility
            for r in range(n_rows):
                if current_row_counts[r] + remaining_max_row[r] < row_targets[r]:
                    prune = True
                    break
            if prune:
                # Undo changes
                for r in range(n_rows):
                    current_row_counts[r] -= rd[r]
                for c in range(n_cols):
                    current_col_counts[c] -= cd[c]
                del assigned_levels[reg_id]
                continue
            # Check column feasibility
            for c in range(n_cols):
                if current_col_counts[c] + remaining_max_col[c] < col_targets[c]:
                    prune = True
                    break
            if prune:
                # Undo changes
                for r in range(n_rows):
                    current_row_counts[r] -= rd[r]
                for c in range(n_cols):
                    current_col_counts[c] -= cd[c]
                del assigned_levels[reg_id]
                continue

            # Recurse to next assignment
            solution = backtrack(assigned_count + 1)
            if solution is not None:
                return solution

            # Undo changes for backtracking
            for r in range(n_rows):
                current_row_counts[r] -= rd[r]
            for c in range(n_cols):
                current_col_counts[c] -= cd[c]
            del assigned_levels[reg_id]

        return None

    final_solution = backtrack(0)
    return final_solution if final_solution is not None else "No Solution"

