def solve(observation):
    data = observation['data']
    N = len(data)
    # Precompute cells per region
    region_cells = {}
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            if reg not in region_cells:
                region_cells[reg] = []
            region_cells[reg].append((r, c))
    regions = list(region_cells.keys())

    # Initialize state
    grid = [[None for _ in range(N)] for _ in range(N)]
    row_counts = [0] * N
    col_counts = [0] * N
    region_counts = {reg: 0 for reg in regions}
    possible = [[True for _ in range(N)] for _ in range(N)]

    def place_star(r, c):
        """Place star at (r,c) and update constraints, return False if invalid"""
        if not possible[r][c] or grid[r][c] == 'S' or row_counts[r] >= 2 or col_counts[c] >=2 or region_counts[data[r][c]] >=2:
            return False
        # Place star
        grid[r][c] = 'S'
        row_counts[r] += 1
        col_counts[c] += 1
        reg = data[r][c]
        region_counts[reg] += 1
        # Mark all 8 adjacent cells as impossible
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    possible[nr][nc] = False
        return True

    def propagate():
        """Deduct forced placements until no more changes, return False if invalid"""
        changed = True
        while changed:
            changed = False
            # Process rows
            for r in range(N):
                needed = 2 - row_counts[r]
                if needed <= 0:
                    # Mark entire row as impossible
                    for c in range(N):
                        if possible[r][c]:
                            possible[r][c] = False
                            changed = True
                    continue
                possible_cells = [c for c in range(N) if possible[r][c]]
                if len(possible_cells) < needed:
                    return False
                if len(possible_cells) == needed:
                    for c in possible_cells:
                        if not place_star(r, c):
                            return False
                        changed = True
            # Process columns
            for c in range(N):
                needed = 2 - col_counts[c]
                if needed <= 0:
                    for r in range(N):
                        if possible[r][c]:
                            possible[r][c] = False
                            changed = True
                    continue
                possible_cells = [r for r in range(N) if possible[r][c]]
                if len(possible_cells) < needed:
                    return False
                if len(possible_cells) == needed:
                    for r in possible_cells:
                        if not place_star(r, c):
                            return False
                        changed = True
            # Process regions
            for reg in regions:
                needed = 2 - region_counts[reg]
                if needed <= 0:
                    for (r, c) in region_cells[reg]:
                        if possible[r][c]:
                            possible[r][c] = False
                            changed = True
                    continue
                possible_cells = [(r,c) for (r,c) in region_cells[reg] if possible[r][c]]
                if len(possible_cells) < needed:
                    return False
                if len(possible_cells) == needed:
                    for (r,c) in possible_cells:
                        if not place_star(r,c):
                            return False
                        changed = True
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    if sum(row_counts) == 2 * N:
        return grid

    def backtrack():
        if sum(row_counts) == 2 * N:
            return [row.copy() for row in grid]
        # MRV heuristic: pick cell from row with least possible options
        min_opt = float('inf')
        best_cell = None
        for r in range(N):
            needed = 2 - row_counts[r]
            if needed <= 0:
                continue
            for c in range(N):
                if possible[r][c]:
                    opt_count = len([c2 for c2 in range(N) if possible[r][c2]])
                    if opt_count < min_opt:
                        min_opt = opt_count
                        best_cell = (r,c)
        if not best_cell:
            return None
        r,c = best_cell

        # Save state for backtracking
        old_grid = [row.copy() for row in grid]
        old_row = row_counts.copy()
        old_col = col_counts.copy()
        old_reg = region_counts.copy()
        old_possible = [row.copy() for row in possible]

        # Try placing star here
        if place_star(r,c):
            if propagate():
                res = backtrack()
                if res:
                    return res
        # Restore state
        grid[:] = old_grid
        row_counts[:] = old_row
        col_counts[:] = old_col
        region_counts.update(old_reg)
        possible[:] = old_possible

        # Try skipping this cell
        possible[r][c] = False
        if propagate():
            res = backtrack()
            if res:
                return res
        # Restore state
        possible[:] = old_possible
        return None

    result = backtrack()
    return result if result else "No Solution"

