def solve(observation):
    data = observation['data']
    rows = len(data)
    if rows == 0:
        return []
    cols = len(data[0])

    # Get all 8-direction adjacent cells in bounds
    def get_adj(r, c):
        adj = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    adj.append((nr, nc))
        return adj

    # Deduce all possible cells using basic minesweeper rules
    def deduce(res_grid):
        changed = True
        while changed:
            changed = False
            for r in range(rows):
                for c in range(cols):
                    clue = data[r][c]
                    if clue is None:
                        continue
                    adj = get_adj(r, c)
                    mine_cnt = 0
                    unknowns = []
                    for (nr, nc) in adj:
                        val = res_grid[nr][nc]
                        if val == 'F':
                            mine_cnt += 1
                        elif val is None:
                            unknowns.append((nr, nc))
                    # Invalid state check
                    if mine_cnt > clue:
                        return None
                    # All remaining unknowns are safe
                    if mine_cnt == clue:
                        for (nr, nc) in unknowns:
                            res_grid[nr][nc] = 'S'
                            changed = True
                    # All remaining unknowns are mines
                    elif mine_cnt + len(unknowns) == clue:
                        for (nr, nc) in unknowns:
                            res_grid[nr][nc] = 'F'
                            changed = True
        return res_grid

    # Check if current grid is fully solved and valid
    def is_solved(res_grid):
        # Check no unknown cells left
        for r in range(rows):
            for c in range(cols):
                if res_grid[r][c] is None:
                    return False
        # Verify all clues are satisfied
        for r in range(rows):
            for c in range(cols):
                clue = data[r][c]
                if clue is None:
                    continue
                mine_cnt = sum(1 for (nr, nc) in get_adj(r, c) if res_grid[nr][nc] == 'F')
                if mine_cnt != clue:
                    return False
        return True

    # Pick unknown cell adjacent to most clues to minimize branching
    def pick_unknown(res_grid):
        best = None
        max_clue_adj = -1
        for r in range(rows):
            for c in range(cols):
                if res_grid[r][c] is None:
                    adj_clue_cnt = sum(1 for (nr, nc) in get_adj(r, c) if data[nr][nc] is not None)
                    if adj_clue_cnt > max_clue_adj:
                        max_clue_adj = adj_clue_cnt
                        best = (r, c)
        return best

    # Backtracking search with early pruning
    def backtrack(res_grid):
        res_grid = deduce(res_grid)
        if res_grid is None:
            return None
        if is_solved(res_grid):
            return res_grid
        (r, c) = pick_unknown(res_grid)
        if not (r, c):
            return None
        # Try placing mine first
        new_res = [row.copy() for row in res_grid]
        new_res[r][c] = 'F'
        sol = backtrack(new_res)
        if sol:
            return sol
        # Try safe cell
        new_res = [row.copy() for row in res_grid]
        new_res[r][c] = 'S'
        return backtrack(new_res)

    # Initialize grid: all clue cells are safe
    res = [[None for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                res[r][c] = 'S'

    final = backtrack(res)
    if not final:
        return "No Solution"
    # Convert to required output format
    return [['F' if cell == 'F' else None for cell in row] for row in final]

