def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n_rows = len(row_sum)
    n_cols = len(col_sum)
    row_weights = [i + 1 for i in range(n_rows)]
    col_weights = [j + 1 for j in range(n_cols)]

    # Precompute all valid masks for each row (bitmask representation of black columns)
    possible_masks = []
    for i in range(n_rows):
        target = row_sum[i]
        masks = []
        for mask in range(1 << n_cols):
            s = 0
            valid = True
            for j in range(n_cols):
                if mask & (1 << j):
                    s += col_weights[j]
                    if s > target:
                        valid = False
                        break
            if valid and s == target:
                masks.append(mask)
        if not masks:
            return "No Solution"
        possible_masks.append(masks)

    # Constraint propagation function: reduces possible masks using logical deductions
    def propagate(pm):
        pm = [list(masks) for masks in pm]
        changed = True
        while changed:
            changed = False
            # Calculate mandatory (set in all masks) and forbidden (unset in all masks) bits per row
            mandatory = []
            forbidden = []
            for masks in pm:
                mand = (1 << n_cols) - 1
                forb = 0
                for m in masks:
                    mand &= m
                    forb |= ~m
                mand &= (1 << n_cols) - 1
                forb &= (1 << n_cols) - 1
                mandatory.append(mand)
                forbidden.append(forb)

            # Process each column to apply constraints
            for j in range(n_cols):
                fixed = 0
                max_possible = 0
                for i in range(n_rows):
                    if mandatory[i] & (1 << j):
                        fixed += row_weights[i]
                        max_possible += row_weights[i]
                    elif not (forbidden[i] & (1 << j)):
                        max_possible += row_weights[i]

                # Check for impossible state
                if fixed > col_sum[j] or max_possible < col_sum[j]:
                    return (False, None)
                remaining = col_sum[j] - fixed

                # If column target already met, forbid all remaining rows in this column
                if fixed == col_sum[j]:
                    for i in range(n_rows):
                        if not (mandatory[i] & (1 << j)) and not (forbidden[i] & (1 << j)):
                            new_masks = [m for m in pm[i] if not (m & (1 << j))]
                            if not new_masks:
                                return (False, None)
                            if len(new_masks) != len(pm[i]):
                                pm[i] = new_masks
                                changed = True

                # Forbid rows with weight larger than remaining column sum
                for i in range(n_rows):
                    if not (forbidden[i] & (1 << j)) and not (mandatory[i] & (1 << j)):
                        if row_weights[i] > remaining:
                            new_masks = [m for m in pm[i] if not (m & (1 << j))]
                            if not new_masks:
                                return (False, None)
                            if len(new_masks) != len(pm[i]):
                                pm[i] = new_masks
                                changed = True

                # If maximum possible sum equals remaining, all allowed rows must be selected
                if max_possible == remaining and remaining > 0:
                    for i in range(n_rows):
                        if not (forbidden[i] & (1 << j)) and not (mandatory[i] & (1 << j)):
                            new_masks = [m for m in pm[i] if (m & (1 << j))]
                            if not new_masks:
                                return (False, None)
                            if len(new_masks) != len(pm[i]):
                                pm[i] = new_masks
                                changed = True

            # Filter row masks that would exceed column targets
            for i in range(n_rows):
                new_masks = []
                for m in pm[i]:
                    valid = True
                    for j in range(n_cols):
                        if m & (1 << j):
                            fixed_j = sum(row_weights[k] for k in range(n_rows) if k != i and (mandatory[k] & (1 << j)))
                            if fixed_j + row_weights[i] > col_sum[j]:
                                valid = False
                                break
                    if valid:
                        new_masks.append(m)
                if not new_masks:
                    return (False, None)
                if len(new_masks) != len(pm[i]):
                    pm[i] = new_masks
                    changed = True

        return (True, pm)

    # Run initial propagation
    valid, pm = propagate(possible_masks)
    if not valid:
        return "No Solution"

    # Backtracking search with minimum branching heuristic
    def backtrack(current_pm):
        # Check if all rows have exactly one valid mask
        if all(len(masks) == 1 for masks in current_pm):
            # Verify column sums are correct
            col_total = [0] * n_cols
            for i in range(n_rows):
                mask = current_pm[i][0]
                for j in range(n_cols):
                    if mask & (1 << j):
                        col_total[j] += row_weights[i]
            if col_total == col_sum:
                # Convert masks to output grid
                grid = []
                for i in range(n_rows):
                    mask = current_pm[i][0]
                    grid.append(['B' if (mask & (1 << j)) else None for j in range(n_cols)])
                return grid
            return None

        # Select row with smallest number of possible masks to minimize branching
        min_len = float('inf')
        row_idx = -1
        for i in range(n_rows):
            l = len(current_pm[i])
            if l > 1 and l < min_len:
                min_len = l
                row_idx = i

        # Try each valid mask for selected row
        for mask in current_pm[row_idx]:
            new_pm = [list(masks) for masks in current_pm]
            new_pm[row_idx] = [mask]
            valid, propagated = propagate(new_pm)
            if not valid:
                continue
            res = backtrack(propagated)
            if res is not None:
                return res

        return None

    solution = backtrack(pm)
    return solution if solution is not None else "No Solution"

