            for r in range(N):
                rem = 2 - row_counts[r]
                if rem < 0:
                    return False
                available = [c for c in range(N) if grid[r][c] is None]
                if rem > len(available):
                    return False
                if rem == len(available) and rem > 0:
                    for c in available:
                        grid[r][c] = 'S'
                        row_counts[r] += 1
                        col_counts[c] += 1
                        reg = cell_to_region[r][c]
