                if rem == len(available) and rem > 0:
                    for r in available:
                        grid[r][c] = 'S'
                        row_counts[r] += 1
                        col_counts[c] += 1
                        reg = cell_to_region[r][c]
                        region_counts[reg] += 1
                        changed = True
                elif rem == 0:
                    for r in available:
                        grid[r][c] = 'X'
                        changed = True

            # Rule4: Process region constraints
            for reg in region_counts:
                rem = 2 - region_counts[reg]
                if rem < 0:
                    return False
                available = [(r,c) for (r,c) in region_to_cells[reg] if grid[r][c] is None]
                if rem > len(available):
