        # Select most constrained undecided cell (minimum available options across row/col/region)
        min_score = float('inf')
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    row_avail = len([x for x in range(N) if grid[r][x] is None])
