        cc1[c] += 1
        regc1[reg] += 1
        res = backtrack(g1, rc1, cc1, regc1)
        if res:
            return res

        # Try not placing star at best cell
        g2 = copy.deepcopy(grid)
        rc2 = copy.deepcopy(row_counts)
        cc2 = copy.deepcopy(col_counts)
        regc2 = copy.deepcopy(region_counts)
        g2[r][c] = 'X'
        res = backtrack(g2, rc2, cc2, regc2)
        return res

    # Initialize state
    initial_grid = [[None]*N for _ in range(N)]
    initial_row_counts = [0]*N
    initial_col_counts = [0]*N
    initial_region_counts = {reg:0 for reg in region_to_cells}

