def propagate_constraints(grid, n):
    changed = True
    while changed:
        changed = False
        for i in range(n - 1):
            for j in range(n - 1):
                cells = [grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]]
                b_count = cells.count('B')
                w_count = cells.count('W')
                none_count = cells.count(None)
                if none_count == 0:
                    if b_count == 4 or w_count == 4:
                        return None
                elif none_count == 1:
                    target_val = None
                    if b_count == 3:
                        target_val = 'W'
                    elif w_count == 3:
                        target_val = 'B'
                    if target_val is not None:
                        idx = cells.index(None)
                        ni, nj = i + (idx // 2), j + (idx % 2)
                        if grid[ni][nj] is None:
                            grid[ni][nj] = target_val
                            changed = True
                        elif grid[ni][nj] != target_val:
                            return None
    return grid

def count_components(grid, n, color):
    visited = [[False]*n for _ in range(n)]
    count = 0
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == color and not visited[i][j]:
                count += 1
                q = [(i,j)]
                visited[i][j] = True
                while q:
                    x,y = q.pop(0)
                    for dx, dy in dirs:
                        nx, ny = x+dx, y+dy
                        if 0<=nx<n and 0<=ny<n and not visited[nx][ny] and grid[nx][ny] == color:
                            visited[nx][ny] = True
                            q.append((nx, ny))
    return count

def is_full(grid, n):
    return all(None not in row for row in grid)

def is_valid_full(grid, n):
    for i in range(n-1):
        for j in range(n-1):
            cells = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if len(cells) == 1:
                return False
    if count_components(grid, n, 'B') != 1 or count_components(grid, n, 'W') != 1:
        return False
    return True

def get_valid_values(grid, n, i, j):
    valid = []
    for val in ['B', 'W']:
        grid[i][j] = val
        ok = True
        for di in (-1, 0):
            for dj in (-1, 0):
                ni, nj = i + di, j + dj
                if 0 <= ni < n-1 and 0 <= nj < n-1:
                    cells = [grid[ni][nj], grid[ni][nj+1], grid[ni+1][nj], grid[ni+1][nj+1]]
                    if cells.count(val) == 4:
                        ok = False
                        break
            if not ok:
                break
        if ok:
            valid.append(val)
    grid[i][j] = None
    return valid

def backtrack(grid, n):
    grid = propagate_constraints([r[:] for r in grid], n)
    if grid is None:
        return None
    if is_full(grid, n):
        return grid if is_valid_full(grid, n) else None
    min_opts = 3
    best_cell = None
    best_opts = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] is None:
                opts = get_valid_values(grid, n, i, j)
                if not opts:
                    return None
                if len(opts) < min_opts:
                    min_opts = len(opts)
                    best_cell = (i,j)
                    best_opts = opts
                    if min_opts == 1:
                        break
        if min_opts == 1:
            break
    i,j = best_cell
    for v in best_opts:
        new_grid = [r[:] for r in grid]
        new_grid[i][j] = v
        res = backtrack(new_grid, n)
        if res is not None:
            return res
    return None

def solve(observation):
    grid = [r[:] for r in observation['data']]
    n = len(grid)
    sol = backtrack(grid, n)
    return sol if sol is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
