            # Rule 1: Process 1-value cells, adjacent must be black
            for r, c, n in numbers:
                if n == 1:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 'U':
                            g[nr][nc] = 'B'
                            changed = True
            # Rule 2: Check island sizes for numbered cells
            for r, c, n in numbers:
                visited = set()
                q = [(r, c)]
                visited.add((r, c))
                valid = True
                while q:
                    cr, cc = q.pop(0)
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if g[nr][nc] == 'W' and (nr, nc) not in visited:
                                if data[nr][nc] is not None:
                                    return (False, changed)
                                visited.add((nr, nc))
                                q.append((nr, nc))
                size = len(visited)
                if size > n:
                    return (False, changed)
                if size == n:
                    for (cr, cc) in visited:
                        for dr, dc in dirs:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if (nr, nc) not in visited and g[nr][nc] == 'U':
                                    g[nr][nc] = 'B'
                                    changed = True
                # Check maximum possible island size
                max_vis = set(visited)
                max_q = list(visited)
                while max_q:
                    cr, cc = max_q.pop(0)
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in max_vis:
                            if data[nr][nc] is not None and (nr, nc) != (r, c):
                                continue
                            if g[nr][nc] in ('U', 'W'):
                                max_vis.add((nr, nc))
                                max_q.append((nr, nc))
                if len(max_vis) < n:
                    return (False, changed)
            # Rule3: No 2x2 all black blocks
            for r in range(rows - 1):
                for c in range(cols - 1):
                    cells = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
                    b = []
                    u = []
                    for (rr, cc) in cells:
                        if g[rr][cc] == 'B':
                            b.append((rr, cc))
                        elif g[rr][cc] == 'U':
                            u.append((rr, cc))
                    if len(b) == 4:
                        return (False, changed)
                    if len(b) == 3 and len(u) == 1:
                        ur, uc = u[0]
                        g[ur][uc] = 'W'
                        changed = True
            # Rule4: All white cells connected to exactly one number
            w_cells = set()
            for r in range(rows):
                for c in range(cols):
                    if g[r][c] == 'W':
                        w_cells.add((r,c))
            covered = set()
            for r,c,_ in numbers:
                q = [(r,c)]
                vis = set([(r,c)])
                while q:
                    cr, cc = q.pop(0)
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 'W' and (nr, nc) not in vis:
                            vis.add((nr, nc))
                            q.append((nr, nc))
                for cell in vis:
                    if cell in covered:
                        return (False, changed)
                    covered.add(cell)
            for cell in w_cells:
                if cell not in covered:
                    return (False, changed)
            # Rule5: Black cells are connected
            b_cells = []
            for r in range(rows):
                for c in range(cols):
                    if g[r][c] == 'B':
                        b_cells.append((r,c))
            if len(b_cells) > 0:
                q = [b_cells[0]]
                vis = set([b_cells[0]])
                while q:
                    cr, cc = q.pop(0)
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 'B' and (nr, nc) not in vis:
                            vis.add((nr, nc))
                            q.append((nr, nc))
                if len(vis) != len(b_cells):
                    return (False, changed)
        return (True, changed)

    valid, _ = apply_constraints(grid)
    if not valid:
        return "No Solution"

    def is_complete(g):
        for r in range(rows):
            for c in range(cols):
                if g[r][c] == 'U':
                    return False
        # Verify island sizes
        for r,c,n in numbers:
            q = [(r,c)]
            vis = set([(r,c)])
            while q:
                cr, cc = q.pop(0)
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 'W' and (nr, nc) not in vis:
                        vis.add((nr, nc))
                        q.append((nr, nc))
            if len(vis) != n:
                return False
        # Verify no 2x2 all black
        for r in range(rows-1):
            for c in range(cols-1):
                if g[r][c] == 'B' and g[r][c+1] == 'B' and g[r+1][c] == 'B' and g[r+1][c+1] == 'B':
                    return False
        # Verify black connectivity
        b_cells = [(r,c) for r in range(rows) for c in range(cols) if g[r][c] == 'B']
        if len(b_cells) > 0:
            q = [b_cells[0]]
            vis = set([b_cells[0]])
            while q:
                cr, cc = q.pop(0)
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 'B' and (nr, nc) not in vis:
                        vis.add((nr, nc))
                        q.append((nr, nc))
            if len(vis) != len(b_cells):
                return False
        return True

    if is_complete(grid):
        res = []
        for r in range(rows):
            row = []
            for c in range(cols):
                row.append('B' if grid[r][c] == 'B' else None)
            res.append(row)
        return res

    def backtrack(g):
        # MRV heuristic: pick most constrained unknown cell
        best = None
        max_constraint = -1
        for r in range(rows):
            for c in range(cols):
                if g[r][c] == 'U':
                    cnt = 0
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] != 'U':
                            cnt += 1
                    if cnt > max_constraint:
                        max_constraint = cnt
                        best = (r,c)
        if best is None:
            return g if is_complete(g) else None
        r, c = best
        for val in ['B', 'W']:
            new_g = [row.copy() for row in g]
            new_g[r][c] = val
            valid, _ = apply_constraints(new_g)
            if not valid:
                continue
            res = backtrack(new_g)
            if res is not None:
                return res
        return None

    sol = backtrack(grid)
    if sol is None:
        return "No Solution"
    res = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('B' if sol[r][c] == 'B' else None)
        res.append(row)
    return res

