def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']
    R = len(row_targets)
    C = len(col_targets)

    # Preprocess all regions to get cell positions and possible fill levels
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_info = {}
    for rid in regions:
        cells = regions[rid]
        rows = [r for r, c in cells]
        min_r = min(rows)
        max_r = max(rows)

        # Count cells per row and column for this region
        row_cnt = {}
        for r, c in cells:
            row_cnt[r] = row_cnt.get(r, 0) + 1
        col_cnt = {}
        for r, c in cells:
            col_cnt[c] = col_cnt.get(c, 0) + 1

        # Precompute all possible fill levels and their deltas
        possible_levels = []
        # Level = max_r + 1 means no water in this region
        for L in range(min_r, max_r + 2):
            delta_r = [0] * R
            delta_c = [0] * C
            if L <= max_r:
                for r in range(L, max_r + 1):
                    delta_r[r] = row_cnt.get(r, 0)
                for r, c in cells:
                    if r >= L:
                        delta_c[c] += 1
            possible_levels.append((L, delta_r, delta_c))

        # Precompute min and max possible contributions for pruning
        min_row = [0] * R
        max_row = [row_cnt.get(r, 0) for r in range(R)]
        min_col = [0] * C
        max_col = [col_cnt.get(c, 0) for c in range(C)]

        region_info[rid] = {
            'cells': cells,
            'possible_levels': possible_levels,
            'min_row': min_row,
            'max_row': max_row,
            'min_col': min_col,
            'max_col': max_col
        }

    region_ids = list(regions.keys())
    total_regions = len(region_ids)

    def backtrack(assigned, row_counts, col_counts):
        if len(assigned) == total_regions:
            # Validate final state
            if row_counts == row_targets and col_counts == col_targets:
                # Build result grid
                grid = [[None]*C for _ in range(R)]
                for rid in assigned:
                    L = assigned[rid]
                    for r, c in region_info[rid]['cells']:
                        if r >= L:
                            grid[r][c] = 'W'
                return grid
            return None

        # MRV heuristic: pick region with fewest valid options first
        best_rid = None
        best_valid = None
        for rid in region_ids:
            if rid in assigned:
                continue
            # Filter valid levels for this region
            valid = []
            for (L, dr, dc) in region_info[rid]['possible_levels']:
                # Check if adding delta doesn't exceed targets
                valid_level = True
                for r in range(R):
                    if row_counts[r] + dr[r] > row_targets[r]:
                        valid_level = False
                        break
                if not valid_level:
                    continue
                for c in range(C):
                    if col_counts[c] + dc[c] > col_targets[c]:
                        valid_level = False
                        break
                if valid_level:
                    valid.append((L, dr, dc))
            if not valid:
                return None  # No valid options for this region, prune
            if best_rid is None or len(valid) < len(best_valid):
                best_rid = rid
                best_valid = valid

        # Try all valid levels for selected region
        for (L, dr, dc) in best_valid:
            # Apply assignment
            assigned[best_rid] = L
            for r in range(R):
                row_counts[r] += dr[r]
            for c in range(C):
                col_counts[c] += dc[c]

            # Prune: check if remaining regions can satisfy remaining targets
            unassigned = [rid for rid in region_ids if rid not in assigned]
            min_possible_r = [0]*R
            max_possible_r = [0]*R
            min_possible_c = [0]*C
            max_possible_c = [0]*C
            for rid in unassigned:
                info = region_info[rid]
                for r in range(R):
                    min_possible_r[r] += info['min_row'][r]
                    max_possible_r[r] += info['max_row'][r]
                for c in range(C):
                    min_possible_c[c] += info['min_col'][c]
                    max_possible_c[c] += info['max_col'][c]

            prune = False
            for r in range(R):
                rem = row_targets[r] - row_counts[r]
                if rem < min_possible_r[r] or rem > max_possible_r[r]:
                    prune = True
                    break
            if not prune:
                for c in range(C):
                    rem = col_targets[c] - col_counts[c]
                    if rem < min_possible_c[c] or rem > max_possible_c[c]:
                        prune = True
                        break

            if not prune:
                res = backtrack(assigned, row_counts, col_counts)
                if res is not None:
                    return res

            # Undo assignment
            del assigned[best_rid]
            for r in range(R):
                row_counts[r] -= dr[r]
            for c in range(C):
                col_counts[c] -= dc[c]

        return None

    result = backtrack({}, [0]*R, [0]*C)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
