        for j in range(N):
            col = [next(iter(grid[i][j])) for i in range(N)]
            if U[j] != 0 and count_visible(col) != U[j]:
                return False
            if D[j] != 0 and count_visible(reversed(col)) != D[j]:
                return False
        return True

    if is_solved():
        return [[next(iter(c)) for c in row] for row in grid]

    def get_mrv_cell():
        min_options = N + 1
        cell = None
        for i in range(N):
            for j in range(N):
                opt_count = len(grid[i][j])
                if 1 < opt_count < min_options:
                    min_options = opt_count
                    cell = (i, j)
        return cell

    def backtrack():
        if is_solved():
            return [[next(iter(c)) for c in row] for row in grid]
        i, j = get_mrv_cell()
        original_grid = copy.deepcopy(grid)
        for val in sorted(grid[i][j]):
            grid[i][j] = {val}
            if propagate_constraints():
                res = backtrack()
                if res is not None:
                    return res
            # Restore state
            grid[:] = copy.deepcopy(original_grid)
        return None

    solution = backtrack()
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
