OBSERVATION = {'U': [0, 5, 0, 0, 3], 'D': [2, 0, 4, 0, 0], 'L': [0, 4, 0, 0, 0], 'R': [3, 0, 0, 0, 3]}

def count_visible(seq):
    max_h, cnt = 0, 0
    for h in seq:
        if h > max_h:
            cnt += 1
            max_h = h
    return cnt

def is_valid_partial(seq, clue, reverse=False):
    if clue == 0:
        return True
    s = seq[::-1] if reverse else seq
    current_max = 0
    visible = 0
    empty = 0
    higher_than_current = 0
    n = len(s)
    for idx, val in enumerate(s):
        if val == 0:
            empty += 1
        else:
            if val > current_max:
                visible += 1
                current_max = val
    if visible > clue:
        return False
    max_possible_add = 0
    remaining_possible = set(range(1, n+1)) - set([x for x in s if x != 0])
    for num in remaining_possible:
        if num > current_max:
            max_possible_add += 1
    if visible + max_possible_add < clue:
        return False
    return True

def get_possible_values(grid, r, c, n):
    used = set(grid[r]) | set(grid[i][c] for i in range(n))
    return [v for v in range(1, n+1) if v not in used]

def check_all_partial(grid, obs, n):
    U, D, L, R = obs['U'], obs['D'], obs['L'], obs['R']
    for r in range(n):
        row = grid[r]
        if not is_valid_partial(row, L[r]) or not is_valid_partial(row, R[r], reverse=True):
            return False
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if not is_valid_partial(col, U[c]) or not is_valid_partial(col, D[c], reverse=True):
            return False
    return True

def is_complete(grid, n):
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                return False
    return True

def check_full(grid, obs, n):
    U, D, L, R = obs['U'], obs['D'], obs['L'], obs['R']
    for r in range(n):
        row = grid[r]
        if L[r] != 0 and count_visible(row) != L[r]:
            return False
        if R[r] != 0 and count_visible(row[::-1]) != R[r]:
            return False
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if U[c] != 0 and count_visible(col) != U[c]:
            return False
        if D[c] != 0 and count_visible(col[::-1]) != D[c]:
            return False
    return True

def backtrack(grid, obs, n):
    if is_complete(grid, n):
        return grid if check_full(grid, obs, n) else None
    min_options = n + 1
    best_cell = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                opts = get_possible_values(grid, r, c, n)
                if len(opts) == 0:
                    return None
                if len(opts) < min_options:
                    min_options = len(opts)
                    best_cell = (r, c, opts)
    r, c, opts = best_cell
    for val in opts:
        grid[r][c] = val
        if check_all_partial(grid, obs, n):
            res = backtrack(grid, obs, n)
            if res is not None:
                return res
        grid[r][c] = 0
    return None

def preprocess(grid, obs, n):
    U, D, L, R = obs['U'], obs['D'], obs['L'], obs['R']
    for c in range(n):
        if U[c] == n:
            for r in range(n):
                grid[r][c] = r + 1
        if U[c] == 1:
            grid[0][c] = n
        if D[c] == n:
            for r in range(n):
                grid[r][c] = n - r
        if D[c] == 1:
            grid[n-1][c] = n
    for r in range(n):
        if L[r] == n:
            for c in range(n):
                grid[r][c] = c + 1
        if L[r] == 1:
            grid[r][0] = n
        if R[r] == n:
            for c in range(n):
                grid[r][c] = n - c
        if R[r] == 1:
            grid[r][n-1] = n
    return grid

def solve(observation):
    n = len(observation['U'])
    grid = [[0]*n for _ in range(n)]
    grid = preprocess(grid, observation, n)
    solution = backtrack(grid, observation, n)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
