# Helper function to apply constraint propagation
def propagate(mask, data):
    n = len(data)
    changed = True
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while changed:
        changed = False

        # Rule 1: Mark unique numbers in rows as white
        for r in range(n):
            freq = {}
            cell_map = {}
            for c in range(n):
                if mask[r][c] != 'B':
                    v = data[r][c]
                    freq[v] = freq.get(v, 0) + 1
                    cell_map.setdefault(v, []).append(c)
            for v, cnt in freq.items():
                if cnt == 1:
                    c = cell_map[v][0]
                    if mask[r][c] == '?':
                        mask[r][c] = None
                        changed = True

        # Rule 2: Mark unique numbers in columns as white
        for c in range(n):
            freq = {}
            cell_map = {}
            for r in range(n):
                if mask[r][c] != 'B':
                    v = data[r][c]
                    freq[v] = freq.get(v, 0) + 1
                    cell_map.setdefault(v, []).append(r)
            for v, cnt in freq.items():
                if cnt == 1:
                    r = cell_map[v][0]
                    if mask[r][c] == '?':
                        mask[r][c] = None
                        changed = True

        # Rule3: For any white cell, mark duplicate values in row/column as black
        for r in range(n):
            for c in range(n):
                if mask[r][c] is None:
                    v = data[r][c]
                    # Check row duplicates
                    for cc in range(n):
                        if cc != c and data[r][cc] == v:
                            if mask[r][cc] == '?':
                                mask[r][cc] = 'B'
                                changed = True
                            elif mask[r][cc] is None:
                                return None, False
                    # Check column duplicates
                    for rr in range(n):
                        if rr != r and data[rr][c] == v:
                            if mask[rr][c] == '?':
                                mask[rr][c] = 'B'
                                changed = True
                            elif mask[rr][c] is None:
                                return None, False

        # Rule4: Black cells cannot be adjacent, mark neighbors as white
        for r in range(n):
            for c in range(n):
                if mask[r][c] == 'B':
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n:
                            if mask[nr][nc] == '?':
                                mask[nr][nc] = None
                                changed = True
                            elif mask[nr][nc] == 'B':
                                return None, False

        # Final validity check for adjacent blacks
        for r in range(n):
            for c in range(n):
                if mask[r][c] == 'B':
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and mask[nr][nc] == 'B':
                            return None, False

    return mask, True

# Helper function to check if all white cells are connected
def is_connected(mask):
    n = len(mask)
    start = None
    total_white = 0
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Count white cells and find start position
    for r in range(n):
        for c in range(n):
            if mask[r][c] is None:
                total_white += 1
                if start is None:
                    start = (r, c)

    if total_white == 0:
        return False

    # BFS to count connected whites
    visited = set([start])
    queue = [start]
    while queue:
        r, c = queue.pop(0)
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and mask[nr][nc] is None and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return len(visited) == total_white

# Backtracking search with pruning
def backtrack(mask, data):
    n = len(data)
    # Apply propagation first to reduce search space
    new_mask, valid = propagate([row[:] for row in mask], data)
    if not valid:
        return None

    # Check if all cells are assigned
    pos = None
    for r in range(n):
        for c in range(n):
            if new_mask[r][c] == '?':
                pos = (r, c)
                break
        if pos:
            break

    if not pos:
        # All cells assigned, check connectivity
        if is_connected(new_mask):
            return new_mask
        return None

    r, c = pos
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Try setting to Black first
    can_black = True
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n and new_mask[nr][nc] == 'B':
            can_black = False
            break
    if can_black:
        trial_mask = [row[:] for row in new_mask]
        trial_mask[r][c] = 'B'
        res = backtrack(trial_mask, data)
        if res:
            return res

    # Try setting to White
    trial_mask = [row[:] for row in new_mask]
    trial_mask[r][c] = None
    res = backtrack(trial_mask, data)
    if res:
        return res

    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    initial_mask = [['?' for _ in range(n)] for _ in range(n)]
    solution = backtrack(initial_mask, data)
    return solution if solution else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
