import itertools

def count_visible(seq):
    max_h = 0
    cnt = 0
    for h in seq:
        if h > max_h:
            cnt += 1
            max_h = h
    return cnt

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    nums = list(range(1, N + 1))

    # Precompute valid row permutations matching left/right clues
    valid_rows = []
    for r in range(N):
        lc, rc = L[r], R[r]
        valid = set()
        for perm in itertools.permutations(nums):
            if count_visible(perm) == lc and count_visible(reversed(perm)) == rc:
                valid.add(perm)
        if not valid:
            return "No Solution"
        valid_rows.append(valid)

    # Precompute valid column permutations matching up/down clues
    valid_cols = []
    for c in range(N):
        uc, dc = U[c], D[c]
        valid = set()
        for perm in itertools.permutations(nums):
            if count_visible(perm) == uc and count_visible(reversed(perm)) == dc:
                valid.add(perm)
        if not valid:
            return "No Solution"
        valid_cols.append(valid)

    # Constraint propagation function: prune impossible permutations iteratively
    def propagate(vr, vc):
        while True:
            changed = False
            # Compute possible values per cell
            possible = [[set() for _ in range(N)] for __ in range(N)]
            for r in range(N):
                for perm in vr[r]:
                    for c in range(N):
                        possible[r][c].add(perm[c])
            # Prune invalid rows
            new_vr = [set() for _ in range(N)]
            for r in range(N):
                for perm in vr[r]:
                    if all(perm[c] in possible[r][c] for c in range(N)):
                        new_vr[r].add(perm)
                if not new_vr[r]:
                    return None
                if len(new_vr[r]) != len(vr[r]):
                    changed = True
            # Prune invalid columns
            new_vc = [set() for _ in range(N)]
            for c in range(N):
                for perm in vc[c]:
                    if all(perm[r] in possible[r][c] for r in range(N)):
                        new_vc[c].add(perm)
                if not new_vc[c]:
                    return None
                if len(new_vc[c]) != len(vc[c]):
                    changed = True
            if not changed:
                # Check for impossible cells
                if any(len(possible[r][c]) == 0 for r in range(N) for c in range(N)):
                    return None
                return (new_vr, new_vc, possible)
            vr, vc = new_vr, new_vc

    # Initial propagation
    init_prop = propagate(valid_rows, valid_cols)
    if not init_prop:
        return "No Solution"
    vr, vc, _ = init_prop

    # Check if already solved
    def get_solution(vr):
        sol = []
        for r in range(N):
            if len(vr[r]) != 1:
                return None
            sol.append(list(next(iter(vr[r]))))
        # Verify columns match valid permutations
        for c in range(N):
            col = tuple(sol[r][c] for r in range(N))
            if col not in vc[c]:
                return None
        return sol

    sol = get_solution(vr)
    if sol:
        return sol

    # Backtracking with MRV heuristic
    def backtrack(vr, vc):
        s = get_solution(vr)
        if s:
            return s
        # Find MRV cell (minimum remaining values)
        possible = [[set() for _ in range(N)] for __ in range(N)]
        for r in range(N):
            for perm in vr[r]:
                for c in range(N):
                    possible[r][c].add(perm[c])
        min_size = N + 1
        mr, mc = -1, -1
        for r in range(N):
            for c in range(N):
                sz = len(possible[r][c])
                if 1 < sz < min_size:
                    min_size = sz
                    mr, mc = r, c
        # Try each possible value for MRV cell
        for val in possible[mr][mc]:
            # Filter rows for selected value
            new_vr = [s.copy() for s in vr]
            new_vr[mr] = set(p for p in vr[mr] if p[mc] == val)
            if not new_vr[mr]:
                continue
            # Filter columns for selected value
            new_vc = [s.copy() for s in vc]
            new_vc[mc] = set(p for p in vc[mc] if p[mr] == val)
            if not new_vc[mc]:
                continue
            # Propagate constraints
            prop_res = propagate(new_vr, new_vc)
            if not prop_res:
                continue
            p_vr, p_vc, _ = prop_res
            res = backtrack(p_vr, p_vc)
            if res:
                return res
        return None

    final_sol = backtrack(vr, vc)
    return final_sol if final_sol else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
