    }
}

def solve(observation):
    N = len(observation['data'])
    # Initialize possible values for each cell
    possible = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = observation['data'][r][c]
            if val is not None:
                possible[r][c] = {val}

    # Parse constraints
    horizontal_constraints = []
    for key, op in observation['horizontal'].items():
        r, c_float = map(float, key.strip('()').split(','))
        r = int(r)
        c_left = int(c_float - 0.5)
        horizontal_constraints.append((r, c_left, op))

    vertical_constraints = []
    for key, op in observation['vertical'].items():
        r_float, c = map(float, key.strip('()').split(','))
        c = int(c)
        r_top = int(r_float - 0.5)
        vertical_constraints.append((r_top, c, op))

    def propagate():
        changed = True
        while changed:
            changed = False
            # Rule 1: Unique values per row and column
            for r in range(N):
                for c in range(N):
                    if len(possible[r][c]) == 1:
                        val = next(iter(possible[r][c]))
                        # Remove from row
                        for col in range(N):
                            if col != c and val in possible[r][col]:
                                possible[r][col].remove(val)
                                changed = True
                        # Remove from column
                        for row in range(N):
                            if row != r and val in possible[row][c]:
                                possible[row][c].remove(val)
                                changed = True

            # Rule 2: Horizontal constraints
            for r, c_left, op in horizontal_constraints:
                c_right = c_left + 1
                left = possible[r][c_left]
                right = possible[r][c_right]
                if op == '<':
                    # left < right
                    max_left = max(left)
                    min_right = min(right)
                    # Remove values from left >= min_right
                    to_remove = [v for v in left if v >= min_right]
                    if to_remove:
                        for v in to_remove:
                            left.remove(v)
                        changed = True
                    # Remove values from right <= max_left
                    to_remove = [v for v in right if v <= max_left]
                    if to_remove:
                        for v in to_remove:
                            right.remove(v)
                        changed = True
                elif op == '>':
                    # left > right
                    min_left = min(left)
                    max_right = max(right)
                    # Remove values from left <= max_right
                    to_remove = [v for v in left if v <= max_right]
                    if to_remove:
                        for v in to_remove:
                            left.remove(v)
                        changed = True
                    # Remove values from right >= min_left
                    to_remove = [v for v in right if v >= min_left]
                    if to_remove:
                        for v in to_remove:
                            right.remove(v)
                        changed = True

            # Rule 3: Vertical constraints
            for r_top, c, op in vertical_constraints:
                r_bottom = r_top + 1
                top = possible[r_top][c]
                bottom = possible[r_bottom][c]
                if op == '^':
                    # top < bottom
                    max_top = max(top)
                    min_bottom = min(bottom)
                    to_remove = [v for v in top if v >= min_bottom]
                    if to_remove:
                        for v in to_remove:
                            top.remove(v)
                        changed = True
                    to_remove = [v for v in bottom if v <= max_top]
                    if to_remove:
                        for v in to_remove:
                            bottom.remove(v)
                        changed = True
                elif op == 'v':
                    # top > bottom
                    min_top = min(top)
                    max_bottom = max(bottom)
                    to_remove = [v for v in top if v <= max_bottom]
                    if to_remove:
                        for v in to_remove:
                            top.remove(v)
                        changed = True
                    to_remove = [v for v in bottom if v >= min_top]
                    if to_remove:
                        for v in to_remove:
                            bottom.remove(v)
                        changed = True

            # Check for contradiction
            for r in range(N):
                for c in range(N):
                    if len(possible[r][c]) == 0:
                        return False
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Check if solved already
    solved = True
    for r in range(N):
        for c in range(N):
            if len(possible[r][c]) != 1:
                solved = False
                break
        if not solved:
            break
    if solved:
        return [[next(iter(cell)) for cell in row] for row in possible]

    # Backtracking with MRV heuristic
    def backtrack():
        # Find cell with smallest number of possible values
        min_len = N + 1
        cell = None
        for r in range(N):
            for c in range(N):
                l = len(possible[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    cell = (r, c)
                    if min_len == 2:
                        break
            if min_len == 2:
                break
        if cell is None:
            # All cells filled
            return [[next(iter(cell)) for cell in row] for row in possible]

        r, c = cell
        # Try each possible value
        for val in list(possible[r][c]):
            # Save state
            saved = [[set(s) for s in row] for row in possible]
            possible[r][c] = {val}
            if propagate():
                res = backtrack()
                if res is not None:
                    return res
            # Restore state
            for i in range(N):
                for j in range(N):
                    possible[i][j] = saved[i][j]
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

