    # Check if solved
    def is_solved(doms):
        for r in range(N):
            for c in range(N):
                if len(doms[r][c]) != 1:
                    return False
        return True

    if is_solved(domains):
        res = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
        return res

    # MRV heuristic select cell
    def select_cell(doms):
        min_size = N + 1
        cell = None
        for r in range(N):
            for c in range(N):
                s = len(doms[r][c])
                if 1 < s < min_size:
                    min_size = s
                    cell = (r, c)
        return cell

    # Backtracking search
    def backtrack(doms):
        if not propagate_constraints(doms):
            return None
        if is_solved(doms):
            return [[next(iter(doms[r][c])) for c in range(N)] for r in range(N)]
        r, c = select_cell(doms)
        # Try values in domain
        for val in sorted(doms[r][c]):
            # Copy domains
            new_doms = [[s.copy() for s in row] for row in doms]
            new_doms[r][c] = {val}
            res = backtrack(new_doms)
            if res is not None:
                return res
        return None

    solution = backtrack(domains)
    return solution if solution else "No Solution"

