    # Initialize grid: None = unknown, 'B' = black, 'W' = white
    grid = [[None for _ in range(N)] for _ in range(N)]
    region_black_count = defaultdict(int)

    def is_valid():
        # Check all region counts
        for rid in region_clue:
            cnt = 0
            for (r,c) in region_cells[rid]:
                if grid[r][c] == 'B': cnt +=1
                elif grid[r][c] is None: break
            else:
                if cnt != region_clue[rid]:
                    return False
        # Check no adjacent blacks
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B':
                    for dr, dc in dirs:
                        nr, nc = r+dr, c+dc
                        if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                            return False
        # Check white segment rule (partial)
        for r in range(N):
            regs = set()
            for c in range(N):
                if grid[r][c] == 'B':
