                    if len(regs) > 2: return False
                    regs.clear()
                else:
                    regs.add(region_grid[r][c])
                    if len(regs) > 2: return False
            if len(regs) > 2: return False
        # Check white connectivity (if all whites known)
        white_cells = []
        has_unknown = False
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'W':
                    white_cells.append((r,c))
                elif grid[r][c] is None:
                    has_unknown = True
        if not has_unknown and white_cells:
            visited = set()
            q = deque([white_cells[0]])
            visited.add(white_cells[0])
            while q:
                r,c = q.popleft()
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'W' and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        q.append((nr,nc))
            if len(visited) != len(white_cells):
