        changed = True
        while changed:
            changed = False
            # Rule 1: Region clue 0: all white
            for rid in region_clue:
                if region_clue[rid] == 0:
                    for (r,c) in region_cells[rid]:
                        if grid[r][c] != 'W':
                            grid[r][c] = 'W'
                            changed = True
            # Rule 2: Region full blacks
            for rid in region_clue:
                required = region_clue[rid]
                cnt = 0
                unknowns = []
                for (r,c) in region_cells[rid]:
                    if grid[r][c] == 'B': cnt +=1
                    elif grid[r][c] is None: unknowns.append((r,c))
                if cnt > required:
                    return False
                if cnt == required:
                    for (r,c) in unknowns:
                        if grid[r][c] != 'W':
                            grid[r][c] = 'W'
                            changed = True
                elif cnt + len(unknowns) == required:
                    for (r,c) in unknowns:
                        if grid[r][c] != 'B':
                            grid[r][c] = 'B'
                            region_black_count[rid] +=1
                            changed = True
            # Rule3: No adjacent blacks
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'B':
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N and grid[nr][nc] != 'W':
                                if grid[nr][nc] == 'B':
                                    return False
                                grid[nr][nc] = 'W'
                                changed = True
            # Check validity
            if not is_valid():
                return False
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    def backtrack():
        # Find first unknown cell
        min_options = float('inf')
        chosen = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    # Count options
                    opts = 0
                    # Try B
                    grid[r][c] = 'B'
                    if is_valid():
                        opts +=1
                    # Try W
                    grid[r][c] = 'W'
                    if is_valid():
                        opts +=1
                    grid[r][c] = None
                    if opts == 0:
                        return None
                    if opts < min_options:
                        min_options = opts
                        chosen = (r,c)
                        if min_options == 1:
                            break
            if chosen and min_options == 1:
                break
        if not chosen:
            # All filled, return solution
            res = []
            for row in grid:
                res_row = []
                for val in row:
                    res_row.append('B' if val == 'B' else None)
                res.append(res_row)
            return res
        r,c = chosen
        # Try B first
        grid[r][c] = 'B'
        if is_valid() and propagate():
            res = backtrack()
            if res:
                return res
        # Undo B
        for rid in region_black_count:
            region_black_count[rid] = 0
        for rr in range(N):
            for cc in range(N):
                if (rr,cc) == (r,c) or grid[rr][cc] == 'W' or grid[rr][cc] == 'B':
                    continue
        grid[r][c] = None
        # Re propagate original state
        propagate()
        # Try W
        grid[r][c] = 'W'
        if is_valid() and propagate():
            res = backtrack()
            if res:
                return res
        # Undo
        grid[r][c] = None
        propagate()
        return None

    solution = backtrack()
    return solution if solution else "No Solution"

