    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                possible[r][c] = {val}

    def propagate():
        changed = True
        while changed:
            changed = False
            # Step 1: Naked singles elimination
            for r in range(N):
                for c in range(N):
                    opts = possible[r][c]
                    if len(opts) != 1:
                        continue
                    val = next(iter(opts))
                    # Remove from row
                    for cc in range(N):
                        if cc == c:
                            continue
                        if val in possible[r][cc]:
                            possible[r][cc].remove(val)
                            changed = True
                    # Remove from column
                    for rr in range(N):
                        if rr == r:
                            continue
                        if val in possible[rr][c]:
                            possible[rr][c].remove(val)
                            changed = True
                    # Remove from region
                    rid = region[r][c]
                    for (rr, cc) in region_cells[rid]:
                        if rr == r and cc == c:
                            continue
                        if val in possible[rr][cc]:
                            possible[rr][cc].remove(val)
                            changed = True
            # Step 2: Hidden singles in rows
            for r in range(N):
                count = {v: [] for v in nums}
                for c in range(N):
                    for v in possible[r][c]:
                        count[v].append(c)
                for v, positions in count.items():
                    if len(positions) == 1:
                        c = positions[0]
                        if possible[r][c] != {v}:
                            possible[r][c] = {v}
                            changed = True
            # Step3: Hidden singles in columns
            for c in range(N):
                count = {v: [] for v in nums}
                for r in range(N):
                    for v in possible[r][c]:
                        count[v].append(r)
                for v, positions in count.items():
                    if len(positions) == 1:
                        r = positions[0]
                        if possible[r][c] != {v}:
                            possible[r][c] = {v}
                            changed = True
            # Step4: Hidden singles in regions
            for rid in region_cells:
                count = {v: [] for v in nums}
                for (r, c) in region_cells[rid]:
