        for r in range(N):
            for c in range(N):
                if len(possible[r][c]) != 1:
                    return False
        return True

    if is_solved():
        return [[next(iter(possible[r][c])) for c in range(N)] for r in range(N)]

    # Find cell with minimum remaining values
    def get_mrv_cell():
        min_len = N+1
        cell = None
        for r in range(N):
            for c in range(N):
                l = len(possible[r][c])
                if 1 < l < min_len:
                    min_len = l
                    cell = (r, c)
        return cell

    # Backtracking search
    def backtrack():
        if is_solved():
            return [[next(iter(possible[r][c])) for c in range(N)] for r in range(N)]
        r, c = get_mrv_cell()
        original_options = list(possible[r][c])
