            saved = [[set(s) for s in row] for row in possible]
            possible[r][c] = {val}
            if propagate():
                res = backtrack()
                if res is not None:
                    return res
            # Restore state
            for rr in range(N):
                for cc in range(N):
                    possible[rr][cc] = saved[rr][cc]
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

