DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def get_visible(r, c, state, N):
    visible = []
    # Up
    for nr in range(r-1, -1, -1):
        if state[nr][c] == 'B':
            break
        visible.append((nr, c))
    # Down
    for nr in range(r+1, N):
        if state[nr][c] == 'B':
            break
        visible.append((nr, c))
    # Left
    for nc in range(c-1, -1, -1):
        if state[r][nc] == 'B':
            break
        visible.append((r, nc))
    # Right
    for nc in range(c+1, N):
        if state[r][nc] == 'B':
            break
        visible.append((r, nc))
    visible.append((r, c))
    return visible

def count_white_visible(r, c, state, N):
    return sum(1 for (nr, nc) in get_visible(r, c, state, N) if state[nr][nc] == 'W')

def is_connected(state, N):
    start = None
    total_white = 0
    for r in range(N):
        for c in range(N):
            if state[r][c] == 'W':
                total_white += 1
                if start is None:
                    start = (r, c)
    if total_white == 0:
        return False
    visited = set([start])
    q = [start]
    while q:
        r, c = q.pop(0)
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and state[nr][nc] == 'W' and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == total_white

def propagate(state, clues, N):
    new_state = [row.copy() for row in state]
    changed = True
    while changed:
        changed = False
        # Process black cells to mark adjacent as white
        for r in range(N):
            for c in range(N):
                if new_state[r][c] == 'B':
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N:
                            if new_state[nr][nc] == 'B':
                                return (False, None)
                            if new_state[nr][nc] == 'U':
                                new_state[nr][nc] = 'W'
                                changed = True
        # Process all clues
        for (r, c), target in clues.items():
            visible = get_visible(r, c, new_state, N)
            white_cnt = 0
            unassigned = []
            for (nr, nc) in visible:
                if new_state[nr][nc] == 'W':
                    white_cnt += 1
                elif new_state[nr][nc] == 'U':
                    unassigned.append((nr, nc))
            # Check contradictions
            if white_cnt > target or (white_cnt + len(unassigned)) < target:
                return (False, None)
            # All unassigned must be white
            if white_cnt + len(unassigned) == target:
                for (nr, nc) in unassigned:
                    if new_state[nr][nc] == 'U':
                        new_state[nr][nc] = 'W'
                        changed = True
            # All unassigned must be black
            if white_cnt == target:
                for (nr, nc) in unassigned:
                    if new_state[nr][nc] == 'U':
                        # Check adjacent no black
                        for dr, dc in DIRS:
                            nnr, nnc = nr + dr, nc + dc
                            if 0 <= nnr < N and 0 <= nnc < N and new_state[nnr][nnc] == 'B':
                                return (False, None)
                        new_state[nr][nc] = 'B'
                        changed = True
    # Final adjacent black check
    for r in range(N):
        for c in range(N):
            if new_state[r][c] == 'B':
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N and new_state[nr][nc] == 'B':
                        return (False, None)
    return (True, new_state)

def backtrack(state, clues, N):
    valid, new_state = propagate(state, clues, N)
    if not valid:
        return None
    # Check if all assigned
    unassigned = []
    all_assigned = True
    for r in range(N):
        for c in range(N):
            if new_state[r][c] == 'U':
                all_assigned = False
                unassigned.append((r, c))
    if all_assigned:
        # Verify all clues
        for (r, c), target in clues.items():
            if count_white_visible(r, c, new_state, N) != target:
                return None
        # Verify connectivity
        if not is_connected(new_state, N):
            return None
        # Convert to output format
        output = []
        for r in range(N):
            row = []
            for c in range(N):
                if (r, c) in clues:
                    row.append(clues[(r, c)])
                elif new_state[r][c] == 'B':
                    row.append('B')
                else:
                    row.append(None)
            output.append(row)
        return output
    # MRV heuristic: pick cell with least options
    min_options = 3
    best_cell = None
    for (r, c) in unassigned:
        options = 0
        # Check if can be black
        can_black = True
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and new_state[nr][nc] == 'B':
                can_black = False
                break
        if can_black:
            options += 1
        # Can always be white (will be checked in propagate)
        options += 1
        if options < min_options:
            min_options = options
            best_cell = (r, c)
            if min_options == 1:
                break
    r, c = best_cell
    # Try black first
    can_black = True
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N and new_state[nr][nc] == 'B':
            can_black = False
            break
    if can_black:
        temp_state = [row.copy() for row in new_state]
        temp_state[r][c] = 'B'
        res = backtrack(temp_state, clues, N)
        if res is not None:
            return res
    # Try white
    temp_state = [row.copy() for row in new_state]
    temp_state[r][c] = 'W'
    res = backtrack(temp_state, clues, N)
    if res is not None:
        return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    state = []
    clues = {}
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            if val is not None:
                clues[(r, c)] = val
                row.append('W')
            else:
                row.append('U')
        state.append(row)
    result = backtrack(state, clues, N)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
