                    comp = []
                    while q:
                        cr, cc = q.pop()
                        comp.append((cr,cc))
                        for dr, dc in dirs:
                            nr, nc = cr+dr, cc+dc
                            if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'W' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr,nc))
                    components.append(comp)
        return components

    def is_valid(grid, partial=True):
        # Rule 2: no adjacent Bs
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B' and not check_adjacent_bs(grid, r, c):
                    return False
        # Rule 1: region counts
        for rid in regions:
            cnt = count_region_bs(grid, rid)
            req = regions[rid]['count']
            if req is not None:
                if cnt > req:
                    return False
                if not partial and cnt != req:
                    return False
        # Rule3: white segments <= 2 regions
        if not check_white_segments(grid):
            return False
        # Rule4: white cells connected (only check if full grid, or partial no separate components)
        comps = get_white_components(grid)
        if len(comps) > 1:
            if not partial:
                return False
            # For partial: check if there's way to connect via unknowns? For simplicity, only block obvious invalid
            has_unknown = any(any(cell is None for cell in row) for row in grid)
            if not has_unknown and len(comps) > 1:
                return False
        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Step 1: handle region constraints
            for rid in regions:
                req = regions[rid]['count']
                if req is None:
                    continue
                cnt = count_region_bs(grid, rid)
                unknowns = []
                for (r,c) in regions[rid]['cells']:
                    if grid[r][c] is None:
                        unknowns.append((r,c))
                if cnt == req:
                    # All unknowns are W
                    for (r,c) in unknowns:
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True
                elif cnt + len(unknowns) == req:
                    # All unknowns are B
                    for (r,c) in unknowns:
                        if grid[r][c] is None:
                            if not check_adjacent_bs(grid, r, c):
                                return False
                            grid[r][c] = 'B'
                            changed = True
                            # Mark adjacent as W
                            for dr, dc in dirs:
                                nr, nc = r+dr, c+dc
                                if 0<=nr<N and 0<=nc<N and grid[nr][nc] is None:
                                    grid[nr][nc] = 'W'
                                    changed = True
            # Step 2: check if any unknown adjacent to 2 Bs? No, can't be B, so W
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None:
                        adjacent_b = 0
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                                adjacent_b +=1
                        if adjacent_b >= 1:
                            # Can't be B, so W
                            grid[r][c] = 'W'
                            changed = True
            # Step 3: recheck validity
            if not is_valid(grid):
                return False
        return True

    def backtrack(grid):
        # Propagate first
        if not propagate(grid):
            return None
        # Check if done
        done = True
        next_cell = None
        min_options = float('inf')
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    done = False
                    # Count options
                    options = 0
                    # Option 1: B
                    if check_adjacent_bs(grid, r, c):
                        rid = region_grid[r][c]
                        cnt = count_region_bs(grid, rid)
                        req = regions[rid]['count']
                        if req is None or cnt < req:
                            options +=1
                    # Option 2: W always possible?
                    options +=1
                    if options < min_options:
                        min_options = options
                        next_cell = (r,c)
        if done:
            if is_valid(grid, partial=False):
                return grid
            return None
        # Try options
        r, c = next_cell
        # Try B first
        if check_adjacent_bs(grid, r, c):
            rid = region_grid[r][c]
            cnt = count_region_bs(grid, rid)
            req = regions[rid]['count']
            if req is None or cnt < req:
                new_grid = [row.copy() for row in grid]
                new_grid[r][c] = 'B'
                res = backtrack(new_grid)
                if res is not None:
                    return res
        # Try W
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = 'W'
        res = backtrack(new_grid)
        if res is not None:
            return res
        return None

    # Initialize grid
    initial_grid = [[None]*N for _ in range(N)]
    # Initial propagation of 0 and full regions
    for rid in regions:
        req = regions[rid]['count']
        if req == 0:
            for (r,c) in regions[rid]['cells']:
                initial_grid[r][c] = 'W'
        elif req == len(regions[rid]['cells']):
            for (r,c) in regions[rid]['cells']:
                if not check_adjacent_bs(initial_grid, r, c):
                    return "No Solution"
                initial_grid[r][c] = 'B'
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<N and 0<=nc<N:
                        initial_grid[nr][nc] = 'W'

    solution = backtrack(initial_grid)
    if solution is None:
        return "No Solution"
    # Convert to output format: W -> None, B -> B
    output = []
    for row in solution:
        out_row = []
        for cell in row:
            if cell == 'B':
                out_row.append('B')
            else:
                out_row.append(None)
        output.append(out_row)
    return output

