from collections import defaultdict

def solve(observation):
    region = observation['region']
    initial_data = observation['data']
    N = len(initial_data)
    grid = [row.copy() for row in initial_data]

    # Precompute cells per region
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[region[r][c]].append((r, c))

    # Initialize used value trackers
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    region_used = defaultdict(set)
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            if val is not None:
                row_used[r].add(val)
                col_used[c].add(val)
                region_used[region[r][c]].add(val)

    def propagate():
        """Fill all naked and hidden singles, return False on contradiction"""
        changed = True
        while changed:
            changed = False

            # Naked singles: cells with only 1 possible value
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is not None:
                        continue
                    used = row_used[r].union(col_used[c]).union(region_used[region[r][c]])
                    possible = [v for v in range(1, N+1) if v not in used]
                    if not possible:
                        return False
                    if len(possible) == 1:
                        val = possible[0]
                        grid[r][c] = val
                        row_used[r].add(val)
                        col_used[c].add(val)
                        region_used[region[r][c]].add(val)
                        changed = True
            if changed:
                continue

            # Hidden singles in rows: value only fits in one cell of row
            for r in range(N):
                for val in range(1, N+1):
                    if val in row_used[r]:
                        continue
                    positions = []
                    for c in range(N):
                        if grid[r][c] is None and val not in col_used[c] and val not in region_used[region[r][c]]:
                            positions.append(c)
                    if not positions:
                        return False
                    if len(positions) == 1:
                        c = positions[0]
                        grid[r][c] = val
                        row_used[r].add(val)
                        col_used[c].add(val)
                        region_used[region[r][c]].add(val)
                        changed = True
            if changed:
                continue

            # Hidden singles in columns
            for c in range(N):
                for val in range(1, N+1):
                    if val in col_used[c]:
                        continue
                    positions = []
                    for r in range(N):
                        if grid[r][c] is None and val not in row_used[r] and val not in region_used[region[r][c]]:
                            positions.append(r)
                    if not positions:
                        return False
                    if len(positions) == 1:
                        r = positions[0]
                        grid[r][c] = val
                        row_used[r].add(val)
                        col_used[c].add(val)
                        region_used[region[r][c]].add(val)
                        changed = True
            if changed:
                continue

            # Hidden singles in regions
            for reg_id, cells in region_cells.items():
                for val in range(1, N+1):
                    if val in region_used[reg_id]:
                        continue
                    positions = []
                    for (r, c) in cells:
                        if grid[r][c] is None and val not in row_used[r] and val not in col_used[c]:
                            positions.append((r, c))
                    if not positions:
                        return False
                    if len(positions) == 1:
                        r, c = positions[0]
                        grid[r][c] = val
                        row_used[r].add(val)
                        col_used[c].add(val)
                        region_used[reg_id].add(val)
                        changed = True
        return True

    def backtrack():
        if not propagate():
            return None

        # Find cell with smallest possible values to branch
        min_options = float('inf')
        best_cell = None
        best_options = None
        solved = True

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    solved = False
                    used = row_used[r].union(col_used[c]).union(region_used[region[r][c]])
                    options = [v for v in range(1, N+1) if v not in used]
                    if len(options) < min_options:
                        min_options = len(options)
                        best_cell = (r, c)
                        best_options = options
                        if min_options == 1:
                            break
            if min_options == 1:
                break

        if solved:
            return [row.copy() for row in grid]

        r, c = best_cell
        for val in best_options:
            # Assign value
            grid[r][c] = val
            row_used[r].add(val)
            col_used[c].add(val)
            region_used[region[r][c]].add(val)

            res = backtrack()
            if res is not None:
                return res

            # Backtrack
            grid[r][c] = None
            row_used[r].remove(val)
            col_used[c].remove(val)
            region_used[region[r][c]].remove(val)

        return None

    result = backtrack()
    return result if result is not None else "No Solution"

