def get_opposite(c):
    return 'W' if c == 'B' else 'B'

def parse_constraint_key(key):
    parts = key.strip('()').split(',')
    return float(parts[0]), float(parts[1])

def propagate_all(grid, horizontal, vertical, n, m):
    target = n // 2
    while True:
        changed = False
        # Process horizontal constraints
        for key, op in horizontal.items():
            row, col_half = parse_constraint_key(key)
            row = int(row)
            c1 = int(col_half - 0.5)
            c2 = c1 + 1
            v1, v2 = grid[row][c1], grid[row][c2]
            if op == '=':
                if v1 is not None and v2 is None:
                    grid[row][c2] = v1
                    changed = True
                elif v2 is not None and v1 is None:
                    grid[row][c1] = v2
                    changed = True
                elif v1 is not None and v2 is not None and v1 != v2:
                    return (False, grid)
            else: # 'x'
                if v1 is not None and v2 is None:
                    grid[row][c2] = get_opposite(v1)
                    changed = True
                elif v2 is not None and v1 is None:
                    grid[row][c1] = get_opposite(v2)
                    changed = True
                elif v1 is not None and v2 is not None and v1 == v2:
                    return (False, grid)
        # Process vertical constraints
        for key, op in vertical.items():
            row_half, col = parse_constraint_key(key)
            col = int(col)
            r1 = int(row_half - 0.5)
            r2 = r1 + 1
            v1, v2 = grid[r1][col], grid[r2][col]
            if op == '=':
                if v1 is not None and v2 is None:
                    grid[r2][col] = v1
                    changed = True
                elif v2 is not None and v1 is None:
                    grid[r1][col] = v2
                    changed = True
                elif v1 is not None and v2 is not None and v1 != v2:
                    return (False, grid)
            else: # 'x'
                if v1 is not None and v2 is None:
                    grid[r2][col] = get_opposite(v1)
                    changed = True
                elif v2 is not None and v1 is None:
                    grid[r1][col] = get_opposite(v2)
                    changed = True
                elif v1 is not None and v2 is not None and v1 == v2:
                    return (False, grid)
        # Check row consecutive triplets
        for r in range(n):
            row = grid[r]
            for i in range(m - 2):
                a, b, c = row[i], row[i+1], row[i+2]
                if a == b and a is not None:
                    exp = get_opposite(a)
                    if c is None:
                        row[i+2] = exp
                        changed = True
                    elif c != exp:
                        return (False, grid)
                if b == c and b is not None:
                    exp = get_opposite(b)
                    if a is None:
                        row[i] = exp
                        changed = True
                    elif a != exp:
                        return (False, grid)
                if a == c and a is not None:
                    exp = get_opposite(a)
                    if b is None:
                        row[i+1] = exp
                        changed = True
                    elif b != exp:
                        return (False, grid)
        # Check column consecutive triplets
        for c in range(m):
            for i in range(n - 2):
                a, b, c_val = grid[i][c], grid[i+1][c], grid[i+2][c]
                if a == b and a is not None:
                    exp = get_opposite(a)
                    if c_val is None:
                        grid[i+2][c] = exp
                        changed = True
                    elif c_val != exp:
