                        changed = True
                    elif b != exp:
                        return (False, grid)
        # Check row counts
        for r in range(n):
            row = grid[r]
            cnt_b = sum(1 for v in row if v == 'B')
            cnt_w = sum(1 for v in row if v == 'W')
            if cnt_b > target or cnt_w > target:
                return (False, grid)
            if cnt_b == target:
                for c in range(m):
                    if row[c] is None:
                        row[c] = 'W'
                        changed = True
            if cnt_w == target:
                for c in range(m):
                    if row[c] is None:
                        row[c] = 'B'
                        changed = True
        # Check column counts
        for c in range(m):
            cnt_b = sum(1 for r in range(n) if grid[r][c] == 'B')
            cnt_w = sum(1 for r in range(n) if grid[r][c] == 'W')
            if cnt_b > target or cnt_w > target:
                return (False, grid)
            if cnt_b == target:
                for r in range(n):
                    if grid[r][c] is None:
                        grid[r][c] = 'W'
                        changed = True
            if cnt_w == target:
                for r in range(n):
                    if grid[r][c] is None:
                        grid[r][c] = 'B'
                        changed = True
        if not changed:
            break
    return (True, grid)

def get_allowed_values(grid, r, c, n, m, target):
    allowed = []
    row = grid[r]
    cnt_b_row = sum(1 for v in row if v == 'B')
    cnt_w_row = sum(1 for v in row if v == 'W')
    cnt_b_col = sum(1 for i in range(n) if grid[i][c] == 'B')
    cnt_w_col = sum(1 for i in range(n) if grid[i][c] == 'W')
    for val in ['B', 'W']:
        # Check count constraints
        if val == 'B' and cnt_b_row + 1 > target:
            continue
        if val == 'W' and cnt_w_row + 1 > target:
            continue
        if val == 'B' and cnt_b_col + 1 > target:
            continue
        if val == 'W' and cnt_w_col + 1 > target:
            continue
        # Check row consecutive
        valid = True
        # Check left two
        if c >= 2 and row[c-1] == val and row[c-2] == val:
            valid = False
        # Check left and right
        if c >=1 and c < m-1 and row[c-1] == val and row[c+1] == val:
            valid = False
        # Check right two
        if c <= m-3 and row[c+1] == val and row[c+2] == val:
            valid = False
        if not valid:
            continue
        # Check column consecutive
        # Check above two
        if r >= 2 and grid[r-1][c] == val and grid[r-2][c] == val:
            valid = False
        # Check above and below
        if r >=1 and r < n-1 and grid[r-1][c] == val and grid[r+1][c] == val:
            valid = False
        # Check below two
        if r <= n-3 and grid[r+1][c] == val and grid[r+2][c] == val:
            valid = False
        if valid:
            allowed.append(val)
    return allowed

def backtrack(grid, horizontal, vertical, n, m):
    # Check if solved
    if all(all(v is not None for v in row) for row in grid):
        return grid
    # MRV heuristic: find cell with minimum allowed values
    min_options = 3
    best_cell = None
    target = n//2
    for r in range(n):
        for c in range(m):
            if grid[r][c] is None:
                opts = get_allowed_values(grid, r, c, n, m, target)
                if len(opts) < min_options:
                    min_options = len(opts)
                    best_cell = (r, c)
                    if min_options == 0:
                        return None
                    if min_options == 1:
                        break
        if min_options == 1:
            break
    if best_cell is None:
        return None
    r, c = best_cell
    for val in get_allowed_values(grid, r, c, n, m, target):
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = val
        valid, propagated = propagate_all(new_grid, horizontal, vertical, n, m)
        if not valid:
            continue
        res = backtrack(propagated, horizontal, vertical, n, m)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']
    n = len(data)
    m = len(data[0])
    initial_grid = [row.copy() for row in data]
    valid, propagated = propagate_all(initial_grid, horizontal, vertical, n, m)
    if not valid:
        return "No Solution"
    solution = backtrack(propagated, horizontal, vertical, n, m)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
