from collections import deque

DIRS = [(-1,0), (1,0), (0,-1), (0,1)]

def propagate(grid, mask, n, m, row_vals, col_vals):
    q = deque()
    for r in range(n):
        for c in range(m):
            if mask[r][c] != 0:
                q.append((r,c))
    while q:
        r, c = q.popleft()
        if mask[r][c] == 2:  # Black cell
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if mask[nr][nc] == 2:
                        return None
                    if mask[nr][nc] == 0:
                        mask[nr][nc] = 1
                        q.append((nr, nc))
        elif mask[r][c] == 1:  # White cell
            v = grid[r][c]
            for cc in row_vals[r][v]:
                if cc == c:
                    continue
                if mask[r][cc] == 1:
                    return None
                if mask[r][cc] == 0:
                    mask[r][cc] = 2
                    q.append((r, cc))
            for rr in col_vals[c][v]:
                if rr == r:
                    continue
                if mask[rr][c] == 1:
                    return None
                if mask[rr][c] == 0:
                    mask[rr][c] = 2
                    q.append((rr, c))
    return mask

def is_connected(mask, n, m):
    start = None
    for r in range(n):
        for c in range(m):
            if mask[r][c] == 1:
                start = (r,c)
                break
        if start:
            break
    if not start:
        return False
    visited = set([start])
    q = deque([start])
    while q:
        r,c = q.popleft()
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and mask[nr][nc] == 1 and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    total_white = sum(1 for r in range(n) for c in range(m) if mask[r][c] == 1)
    return len(visited) == total_white

def backtrack(grid, mask, n, m, row_vals, col_vals):
    temp_mask = [row.copy() for row in mask]
    propagated = propagate(grid, temp_mask, n, m, row_vals, col_vals)
    if propagated is None:
        return None
    mask = propagated
    has_unknown = any(0 in row for row in mask)
    if not has_unknown:
        if is_connected(mask, n, m):
            res = []
            for r in range(n):
                row = []
                for c in range(m):
                    row.append('B' if mask[r][c] == 2 else None)
                res.append(row)
            return res
        return None
    best_cell = None
    min_options = 3
    for r in range(n):
        for c in range(m):
            if mask[r][c] != 0:
                continue
            options = 0
            can_be_black = True
            for dr, dc in DIRS:
                nr, nc = r+dr, c+dc
                if 0<=nr<n and 0<=nc<m and mask[nr][nc] == 2:
                    can_be_black = False
                    break
            if can_be_black:
                options += 1
            options +=1
            if options < min_options:
                min_options = options
                best_cell = (r,c)
                if min_options == 1:
                    break
        if best_cell and min_options == 1:
            break
    r,c = best_cell
    can_be_black = True
    for dr, dc in DIRS:
        nr, nc = r+dr, c+dc
        if 0<=nr<n and 0<=nc<m and mask[nr][nc] == 2:
            can_be_black = False
            break
    if can_be_black:
        mask[r][c] = 2
        res = backtrack(grid, mask, n, m, row_vals, col_vals)
        if res:
            return res
        mask[r][c] = 0
    mask[r][c] = 1
    res = backtrack(grid, mask, n, m, row_vals, col_vals)
    if res:
        return res
    mask[r][c] =0
    return None

def solve(observation):
    grid = observation['data']
    n = len(grid)
