    m = len(grid[0])
    row_vals = [dict() for _ in range(n)]
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v not in row_vals[r]:
                row_vals[r][v] = []
            row_vals[r][v].append(c)
    col_vals = [dict() for _ in range(m)]
    for c in range(m):
        for r in range(n):
            v = grid[r][c]
            if v not in col_vals[c]:
                col_vals[c][v] = []
            col_vals[c][v].append(r)
    mask = [[0]*m for _ in range(n)]
    result = backtrack(grid, mask, n, m, row_vals, col_vals)
    return result if result else "No Solution"

