        else:
            d1, d2 = (cr, cc + 1), (cr + 1, cc)
        for dr, dc in [d1, d2]:
            clue = data[dr][dc]
            if clue is not None and count[dr][dc] + 1 > clue:
                return False
        idx1 = d1[0] * (N + 1) + d1[1]
        idx2 = d2[0] * (N + 1) + d2[1]
        if dsu.find(idx1) == dsu.find(idx2):
            return False
        grid[cr][cc] = val
        for dr, dc in [d1, d2]:
            count[dr][dc] += 1
        dsu.union(idx1, idx2)
        return True

    def apply_forced():
        changed = True
        while changed:
            changed = False
            for dr in range(N + 1):
                for dc in range(N + 1):
                    clue = data[dr][dc]
                    if clue is None:
                        continue
                    current = count[dr][dc]
                    needed = clue - current
                    if needed < 0:
                        return False
                    adjacent = []
                    if dr > 0 and dc > 0:
                        cr, cc = dr - 1, dc - 1
                        if grid[cr][cc] is None:
                            adjacent.append((cr, cc, '\\', '/'))
                    if dr > 0 and dc < N:
