                    if dr < N and dc < N:
                        cr, cc = dr, dc
                        if grid[cr][cc] is None:
                            adjacent.append((cr, cc, '\\', '/'))
                    k = len(adjacent)
                    if needed < 0 or needed > k:
                        return False
                    if needed == k:
                        for cr, cc, add, _ in adjacent:
                            if not set_cell(cr, cc, add):
                                return False
                            changed = True
                    if needed == 0:
                        for cr, cc, _, no_add in adjacent:
                            if not set_cell(cr, cc, no_add):
