            return None
        all_filled = True
        min_opt = 3
        best_cell = None
        for cr in range(N):
            for cc in range(N):
                if grid[cr][cc] is None:
                    all_filled = False
                    opts = 0
                    for val in ['/', '\\']:
                        if val == '\\':
