                    if opts < min_opt:
                        min_opt = opts
                        best_cell = (cr, cc)
                        if min_opt == 1:
                            break
            if min_opt == 1:
                break
        if all_filled:
            return [r.copy() for r in grid]
        cr, cc = best_cell
        for val in ['/', '\\']:
            if val == '\\':
                d1, d2 = (cr, cc), (cr+1, cc+1)
            else:
                d1, d2 = (cr, cc+1), (cr+1, cc)
            valid = True
