            idx1 = d1[0]*(N+1) + d1[1]
            idx2 = d2[0]*(N+1) + d2[1]
            if dsu.find(idx1) == dsu.find(idx2):
                continue
            checkpoint = len(dsu.stack)
            old_val = grid[cr][cc]
            old_counts = [(d1[0], d1[1], count[d1[0]][d1[1]]), (d2[0], d2[1], count[d2[0]][d2[1]])]
            if set_cell(cr, cc, val):
                res = backtrack()
                if res is not None:
                    return res
            dsu.rollback(checkpoint)
            grid[cr][cc] = old_val
            for dr, dc, c in old_counts:
                count[dr][dc] = c
        return None

    res = backtrack()
    return res if res is not None else "No Solution"

