    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if state[nr][nc] == WHITE and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return len(visited) == len(whites)

def apply_deductions(state, data):
    n = len(state)
    changed = True
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while changed:
        changed = False
        # Step 1: Mark unique in row and column as white
        for r in range(n):
            row_counts = {}
            for c in range(n):
                val = data[r][c]
                if val not in row_counts:
                    row_counts[val] = []
                row_counts[val].append(c)
            for c in range(n):
                if state[r][c] != UNKNOWN:
                    continue
                val = data[r][c]
                if len(row_counts[val]) > 1:
                    continue
                # Check column
                col_counts = {}
                for rr in range(n):
                    vv = data[rr][c]
                    if vv not in col_counts:
                        col_counts[vv] = []
                    col_counts[vv].append(rr)
                if len(col_counts[val]) == 1:
                    state[r][c] = WHITE
                    changed = True
        # Step 2: If value already white in row, mark others same value as black
        for r in range(n):
            seen = set()
            for c in range(n):
                if state[r][c] == WHITE:
                    seen.add(data[r][c])
            for c in range(n):
                if state[r][c] == UNKNOWN and data[r][c] in seen:
                    state[r][c] = BLACK
                    changed = True
        # Step 3: Same for columns
        for c in range(n):
            seen = set()
            for r in range(n):
                if state[r][c] == WHITE:
                    seen.add(data[r][c])
            for r in range(n):
                if state[r][c] == UNKNOWN and data[r][c] in seen:
                    state[r][c] = BLACK
                    changed = True
        # Step4: Black cells make neighbors white
        for r in range(n):
            for c in range(n):
                if state[r][c] == BLACK:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and state[nr][nc] == UNKNOWN:
                            state[nr][nc] = WHITE
                            changed = True
    return state

def is_valid(state, data):
    n = len(state)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    # Check adjacent blacks
    for r in range(n):
        for c in range(n):
            if state[r][c] == BLACK:
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and state[nr][nc] == BLACK:
                        return False
    # Check row duplicates
    for r in range(n):
        seen = set()
        for c in range(n):
            if state[r][c] == WHITE:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)
    # Check column duplicates
    for c in range(n):
        seen = set()
        for r in range(n):
            if state[r][c] == WHITE:
                val = data[r][c]
                if val in seen:
                    return False
                seen.add(val)
    return True

def backtrack(state, data, unknowns, idx):
    n = len(state)
    if idx == len(unknowns):
        if is_connected(state):
            return state
        return None
    r, c = unknowns[idx]
    # Try black first
    new_state = [row.copy() for row in state]
    new_state[r][c] = BLACK
    if is_valid(new_state, data):
        new_state = apply_deductions(new_state, data)
        if is_valid(new_state, data):
            res = backtrack(new_state, data, unknowns, idx + 1)
            if res is not None:
                return res
    # Try white
    new_state = [row.copy() for row in state]
    new_state[r][c] = WHITE
    if is_valid(new_state, data):
        new_state = apply_deductions(new_state, data)
        if is_valid(new_state, data):
            res = backtrack(new_state, data, unknowns, idx + 1)
            if res is not None:
                return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    # Initialize state
    state = [[UNKNOWN for _ in range(n)] for _ in range(n)]
    # Apply initial deductions
    state = apply_deductions(state, data)
    if not is_valid(state, data):
        return "No Solution"
    # Collect remaining unknowns, order by most constrained first
    unknowns = []
    for r in range(n):
        for c in range(n):
            if state[r][c] == UNKNOWN:
                # Count constraints: number of duplicates in row + column
                val = data[r][c]
                row_dup = sum(1 for cc in range(n) if data[r][cc] == val) - 1
                col_dup = sum(1 for rr in range(n) if data[rr][c] == val) - 1
                unknowns.append((-(row_dup + col_dup), r, c))
    # Sort by highest constraint first
    unknowns.sort()
    unknowns = [(r,c) for (s, r, c) in unknowns]
    # Backtrack
    solved = backtrack(state, data, unknowns, 0)
    if solved is None:
        return "No Solution"
    # Convert to output format
    res = []
    for r in range(n):
        row = []
        for c in range(n):
            if solved[r][c] == BLACK:
                row.append('B')
            else:
                row.append(None)
        res.append(row)
    return res

