                        count += 1
                    elif val is None:
                        unset.append((r-1, c, '/', '\\'))
                if r < N and c-1 >= 0:
                    val = grid[r][c-1]
                    if val == '/':
                        count += 1
                    elif val is None:
                        unset.append((r, c-1, '/', '\\'))
                if r < N and c < N:
                    val = grid[r][c]
                    if val == '\\':
                        count += 1
                    elif val is None:
                        unset.append((r, c, '\\', '/'))
                if count > clue:
                    return False
                remaining_needed = clue - count
                if remaining_needed < 0 or remaining_needed > len(unset):
                    return False
                if remaining_needed == 0:
                    for (cr, cc, _, not_val) in unset:
                        if grid[cr][cc] is not None:
                            if grid[cr][cc] != not_val:
                                return False
                            continue
                        if not_val == '\\':
                            a = cr * (N+1) + cr
                            b = (cr+1) * (N+1) + (cc+1)
                        else:
                            a = cr * (N+1) + (cc + 1)
                            b = (cr+1) * (N+1) + cc
                        if dsu.find(a) == dsu.find(b):
                            return False
                        dsu.union(a, b)
                        grid[cr][cc] = not_val
                        changed = True
                if remaining_needed == len(unset):
                    for (cr, cc, val, _) in unset:
                        if grid[cr][cc] is not None:
                            if grid[cr][cc] != val:
                                return False
                            continue
                        if val == '\\':
                            a = cr * (N+1) + cc
                            b = (cr+1) * (N+1) + (cc+1)
                        else:
                            a = cr * (N+1) + (cc + 1)
                            b = (cr+1) * (N+1) + cc
                        if dsu.find(a) == dsu.find(b):
                            return False
                        dsu.union(a, b)
                        grid[cr][cc] = val
                        changed = True
    return True

def backtrack(grid, clues, N, dsu):
    if not propagate(grid, clues, N, dsu):
        return None
    all_filled = True
    min_options = 3
    best_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                all_filled = False
                options = []
                a_back = r * (N+1) + c
                b_back = (r+1) * (N+1) + (c+1)
                if dsu.find(a_back) != dsu.find(b_back):
                    options.append('\\')
                a_forward = r * (N+1) + (c+1)
                b_forward = (r+1) * (N+1) + c
                if dsu.find(a_forward) != dsu.find(b_forward):
                    options.append('/')
                if not options:
                    return None
                if len(options) < min_options:
                    min_options = len(options)
                    best_cell = (r, c, options)
    if all_filled:
        return [row.copy() for row in grid]
    r, c, options = best_cell
    for val in options:
        new_grid = [row.copy() for row in grid]
        new_dsu = dsu.copy()
        new_grid[r][c] = val
        if val == '\\':
            a = r * (N+1) + c
            b = (r+1) * (N+1) + (c+1)
        else:
            a = r * (N+1) + (c+1)
            b = (r+1) * (N+1) + c
        if new_dsu.find(a) == new_dsu.find(b):
            continue
        new_dsu.union(a, b)
        res = backtrack(new_grid, clues, N, new_dsu)
        if res is not None:
            return res
    return None

def solve(observation):
    clues = observation['data']
    N = len(clues) - 1
    grid = [[None for _ in range(N)] for _ in range(N)]
    dsu = DSU((N+1)*(N+1))
    solution = backtrack(grid, clues, N, dsu)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
