import ast
import copy

def propagate(domains, inequality_constraints, N):
    changed = True
    while changed:
        changed = False
        # Process row uniqueness constraints
        for r in range(N):
            fixed_vals = set()
            for c in range(N):
                if len(domains[r][c]) == 1:
                    fixed_vals.add(next(iter(domains[r][c])))
            for c in range(N):
                if len(domains[r][c]) > 1:
                    old_len = len(domains[r][c])
                    domains[r][c] -= fixed_vals
                    if len(domains[r][c]) == 0:
                        return False, domains
                    if len(domains[r][c]) != old_len:
                        changed = True
        # Process column uniqueness constraints
        for c in range(N):
            fixed_vals = set()
            for r in range(N):
                if len(domains[r][c]) == 1:
                    fixed_vals.add(next(iter(domains[r][c])))
            for r in range(N):
                if len(domains[r][c]) > 1:
                    old_len = len(domains[r][c])
                    domains[r][c] -= fixed_vals
                    if len(domains[r][c]) == 0:
                        return False, domains
                    if len(domains[r][c]) != old_len:
                        changed = True
        # Process inequality constraints
        for ( (r1, c1), (r2, c2), op ) in inequality_constraints:
            d1 = domains[r1][c1]
            d2 = domains[r2][c2]
            # Prune domain 1
            new_d1 = set()
            for v1 in d1:
                valid = False
                for v2 in d2:
                    if (op == '>' and v1 > v2) or (op == '<' and v1 < v2):
                        valid = True
                        break
                if valid:
                    new_d1.add(v1)
            if len(new_d1) == 0:
                return False, domains
            if new_d1 != d1:
                domains[r1][c1] = new_d1
                changed = True
            # Prune domain 2
            new_d2 = set()
            for v2 in d2:
                valid = False
                for v1 in d1:
                    if (op == '>' and v1 > v2) or (op == '<' and v1 < v2):
                        valid = True
                        break
                if valid:
                    new_d2.add(v2)
            if len(new_d2) == 0:
                return False, domains
            if new_d2 != d2:
                domains[r2][c2] = new_d2
                changed = True
    return True, domains

def backtrack(domains, inequality_constraints, N):
    # Check if solution is found
    solved = True
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) != 1:
                solved = False
                break
        if not solved:
            break
    if solved:
        result = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(next(iter(domains[r][c])))
            result.append(row)
        return result
    # Select Minimum Remaining Value cell
    min_domain_size = N + 1
    selected_cell = None
    for r in range(N):
        for c in range(N):
            s = len(domains[r][c])
            if s > 1 and s < min_domain_size:
                min_domain_size = s
                selected_cell = (r, c)
                if min_domain_size == 2:
                    break
        if min_domain_size == 2:
            break
    r, c = selected_cell
    # Try all possible values for selected cell
    for val in sorted(domains[r][c]):
        new_domains = copy.deepcopy(domains)
        new_domains[r][c] = {val}
        consistent, updated_domains = propagate(new_domains, inequality_constraints, N)
        if consistent:
            solution = backtrack(updated_domains, inequality_constraints, N)
            if solution is not None:
                return solution
    return None

def solve(observation):
    data = observation['data']
    N = len(data)
    # Parse all inequality constraints
    inequality_constraints = []
    # Process horizontal constraints
    for key, op in observation['horizontal'].items():
        r, c_half = ast.literal_eval(key)
        c = int(c_half - 0.5)
        inequality_constraints.append( ((r, c), (r, c+1), op) )
    # Process vertical constraints
    for key, op in observation['vertical'].items():
        r_half, c = ast.literal_eval(key)
        r = int(r_half - 0.5)
        if op == 'v':
            inequality_constraints.append( ((r, c), (r+1, c), '>') )
        elif op == '^':
            inequality_constraints.append( ((r, c), (r+1, c), '<') )
    # Initialize domains
    domains = []
    for r in range(N):
        row_domains = []
        for c in range(N):
            given_val = data[r][c]
            if given_val is not None:
                row_domains.append({given_val})
            else:
                row_domains.append(set(range(1, N+1)))
        domains.append(row_domains)
    # Initial constraint propagation
    consistent, domains = propagate(domains, inequality_constraints, N)
    if not consistent:
        return "No Solution"
    # Start backtracking search
    solution = backtrack(domains, inequality_constraints, N)
    return solution if solution is not None else "No Solution"

