                break
        if solved:
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
        # Select Minimum Remaining Value (MRV) cell for backtracking
        min_size = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                s = len(domains[r][c])
                if s > 1 and s < min_size:
                    min_size = s
                    best_cell = (r, c)
                    if min_size == 2:
                        break
            if min_size == 2:
                break
        r, c = best_cell
        # Try each possible value for selected cell
        for val in sorted(domains[r][c]):
            # Create deep copy of domains
            new_domains = []
            for row in domains:
                new_domains.append([set(cell) for cell in row])
            new_domains[r][c] = {val}
            result = backtrack(new_domains)
            if result is not None:
                return result
        return None

    # Initialize domain sets
    initial_domains = []
    for r in range(N):
        row = []
        for c in range(N):
            if data[r][c] is not None:
                row.append({data[r][c]})
            else:
                row.append(set(range(1, N+1)))
        initial_domains.append(row)
    solution = backtrack(initial_domains)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
