from collections import defaultdict

def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)

    # Precompute cells per region
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[region[r][c]].append((r, c))

    # Initialize possibilities grid
    possibilities = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                possibilities[r][c].add(data[r][c])
            else:
                possibilities[r][c] = set(range(1, N+1))

    def propagate():
        changed = True
        while changed:
            changed = False

            # Process naked singles (only one possible value for cell)
            for r in range(N):
                for c in range(N):
                    if len(possibilities[r][c]) == 1:
                        val = next(iter(possibilities[r][c]))
                        # Remove from same row
                        for col in range(N):
                            if col != c and val in possibilities[r][col]:
                                possibilities[r][col].remove(val)
                                changed = True
                        # Remove from same column
                        for row in range(N):
                            if row != r and val in possibilities[row][c]:
                                possibilities[row][c].remove(val)
                                changed = True
                        # Remove from same region
                        for (rr, cc) in region_cells[region[r][c]]:
                            if (rr, cc) != (r, c) and val in possibilities[rr][cc]:
                                possibilities[rr][cc].remove(val)
                                changed = True

            # Check for contradictions first
            for r in range(N):
                for c in range(N):
                    if len(possibilities[r][c]) == 0:
                        return False

            # Process hidden singles for rows (value only fits one cell in row)
            for r in range(N):
                val_pos = defaultdict(list)
                for c in range(N):
                    for v in possibilities[r][c]:
                        val_pos[v].append(c)
                for v, cols in val_pos.items():
                    if len(cols) == 1:
                        c = cols[0]
                        if len(possibilities[r][c]) > 1:
                            possibilities[r][c] = {v}
                            changed = True

            # Process hidden singles for columns
            for c in range(N):
                val_pos = defaultdict(list)
                for r in range(N):
                    for v in possibilities[r][c]:
                        val_pos[v].append(r)
                for v, rows in val_pos.items():
                    if len(rows) == 1:
                        r = rows[0]
                        if len(possibilities[r][c]) > 1:
                            possibilities[r][c] = {v}
                            changed = True

            # Process hidden singles for regions
            for reg_id, cells in region_cells.items():
                val_pos = defaultdict(list)
                for (r, c) in cells:
                    for v in possibilities[r][c]:
                        val_pos[v].append((r, c))
                for v, cell_list in val_pos.items():
                    if len(cell_list) == 1:
                        r, c = cell_list[0]
                        if len(possibilities[r][c]) > 1:
                            possibilities[r][c] = {v}
                            changed = True

            # Check again for contradictions
            for r in range(N):
                for c in range(N):
                    if len(possibilities[r][c]) == 0:
                        return False
        return True

    def backtrack():
        if not propagate():
            return None

        # Check if solved, find minimum remaining value cell if not
        min_len = N + 1
        min_cell = None
        solved = True
        for r in range(N):
            for c in range(N):
                l = len(possibilities[r][c])
                if l > 1:
                    solved = False
                    if l < min_len:
                        min_len = l
                        min_cell = (r, c)
        if solved:
            res = [[0]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    res[r][c] = next(iter(possibilities[r][c]))
            return res

        r, c = min_cell
        # Try each possible value for min cell
        for val in list(possibilities[r][c]):
            # Save state
            old_poss = [[set(s) for s in row] for row in possibilities]
            possibilities[r][c] = {val}
            result = backtrack()
            if result is not None:
                return result
            # Restore state
            for i in range(N):
                for j in range(N):
                    possibilities[i][j] = old_poss[i][j]
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
