from copy import deepcopy

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        self.parent[yr] = xr
        return True

    def copy(self):
        new_dsu = DSU(0)
        new_dsu.parent = self.parent.copy()
        return new_dsu

def get_dot_idx(r, c, dot_dim):
    return r * dot_dim + c

def get_cell_affected_dots(cell_r, cell_c, val):
    if val == '\\':
        return (cell_r, cell_c), (cell_r + 1, cell_c + 1)
    else: # '/'
        return (cell_r, cell_c + 1), (cell_r + 1, cell_c)

def get_dot_adjacent_cells(dot_r, dot_c, N):
    cells = []
    # cell (dr, dc) -> (val that affects dot, val that doesn't)
    if dot_r > 0 and dot_c > 0:
        cells.append( (dot_r-1, dot_c-1, '\\', '/') )
    if dot_r > 0 and dot_c < N:
        cells.append( (dot_r-1, dot_c, '/', '\\') )
    if dot_r < N and dot_c > 0:
        cells.append( (dot_r, dot_c-1, '/', '\\') )
    if dot_r < N and dot_c < N:
        cells.append( (dot_r, dot_c, '\\', '/') )
    return cells

def propagate(grid, rem, dsu, N, dot_dim):
    changed = True
    while changed:
        changed = False
        for dr in range(dot_dim):
            for dc in range(dot_dim):
                clue = rem[dr][dc]
                if clue < 0:
                    continue
                adj_cells = get_dot_adjacent_cells(dr, dc, N)
                cnt_assigned_pos = 0
                cnt_unassigned = 0
                unassigned_cells = []
                valid = True
                for (cr, cc, pos_val, neg_val) in adj_cells:
                    v = grid[cr][cc]
                    if v == pos_val:
                        cnt_assigned_pos += 1
                    elif v is None:
                        cnt_unassigned += 1
                        unassigned_cells.append( (cr, cc, pos_val, neg_val) )
                # Check for conflict
                if cnt_assigned_pos > clue:
                    return False
                remaining_needed = clue - cnt_assigned_pos
                if remaining_needed < 0 or remaining_needed > cnt_unassigned:
                    return False
                # All remaining must be negative
                if remaining_needed == 0:
                    for (cr, cc, pos_val, neg_val) in unassigned_cells:
                        if grid[cr][cc] is None:
                            grid[cr][cc] = neg_val
                            # Update rem and DSU
                            d1, d2 = get_cell_affected_dots(cr, cc, neg_val)
                            for (r_d, c_d) in [d1, d2]:
                                if rem[r_d][c_d] > 0:
                                    rem[r_d][c_d] -= 1
                                    if rem[r_d][c_d] < 0:
                                        return False
                            # Check cycle
                            idx1 = get_dot_idx(d1[0], d1[1], dot_dim)
                            idx2 = get_dot_idx(d2[0], d2[1], dot_dim)
                            if not dsu.union(idx1, idx2):
                                return False
                            changed = True
                # All remaining must be positive
                if remaining_needed == cnt_unassigned:
                    for (cr, cc, pos_val, neg_val) in unassigned_cells:
                        if grid[cr][cc] is None:
                            grid[cr][cc] = pos_val
                            # Update rem and DSU
                            d1, d2 = get_cell_affected_dots(cr, cc, pos_val)
                            for (r_d, c_d) in [d1, d2]:
                                if rem[r_d][c_d] > 0:
                                    rem[r_d][c_d] -= 1
                                    if rem[r_d][c_d] < 0:
                                        return False
                            # Check cycle
                            idx1 = get_dot_idx(d1[0], d1[1], dot_dim)
                            idx2 = get_dot_idx(d2[0], d2[1], dot_dim)
                            if not dsu.union(idx1, idx2):
                                return False
                            changed = True
    return True

def backtrack(grid, rem, dsu, N, dot_dim):
    # Check if all assigned
    unassigned = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                unassigned.append( (r,c) )
    if not unassigned:
        return deepcopy(grid)
    # MRV heuristic
    min_options = 3
    best_cell = None
    for (r,c) in unassigned:
        options = 0
        # Check both values
        for val in ['\\', '/']:
            d1, d2 = get_cell_affected_dots(r,c,val)
            valid = True
            if rem[d1[0]][d1[1]] == 0 or rem[d2[0]][d2[1]] == 0:
                valid = False
            if valid:
                idx1 = get_dot_idx(d1[0],d1[1], dot_dim)
                idx2 = get_dot_idx(d2[0],d2[1], dot_dim)
                if dsu.find(idx1) == dsu.find(idx2):
                    valid = False
            if valid:
                options +=1
        if options < min_options:
            min_options = options
            best_cell = (r,c)
            if min_options == 0:
                return None
            if min_options == 1:
                break
    cr, cc = best_cell
    # Try both values
    for val in ['\\', '/']:
        d1, d2 = get_cell_affected_dots(cr, cc, val)
        # Check if valid
        if rem[d1[0]][d1[1]] == 0 or rem[d2[0]][d2[1]] ==0:
            continue
        idx1 = get_dot_idx(d1[0],d1[1], dot_dim)
        idx2 = get_dot_idx(d2[0],d2[1], dot_dim)
        if dsu.find(idx1) == dsu.find(idx2):
            continue
        # Make copies
        new_grid = deepcopy(grid)
        new_rem = deepcopy(rem)
        new_dsu = dsu.copy()
        # Assign value
        new_grid[cr][cc] = val
        # Update rem
        if new_rem[d1[0]][d1[1]] > 0:
            new_rem[d1[0]][d1[1]] -= 1
        if new_rem[d2[0]][d2[1]] > 0:
            new_rem[d2[0]][d2[1]] -=1
        # Union
        new_dsu.union(idx1, idx2)
        # Propagate
        if propagate(new_grid, new_rem, new_dsu, N, dot_dim):
            res = backtrack(new_grid, new_rem, new_dsu, N, dot_dim)
            if res is not None:
                return res
    return None

def solve(observation):
    data = observation['data']
    dot_dim = len(data)
    N = dot_dim - 1
    # Initialize grid
    grid = [ [None for _ in range(N)] for _ in range(N) ]
    # Initialize remaining count
    rem = [ [ (data[r][c] if data[r][c] is not None else -1) for c in range(dot_dim) ] for r in range(dot_dim) ]
    # Initialize DSU
    dsu = DSU(dot_dim * dot_dim)
    # First propagation
    if not propagate(grid, rem, dsu, N, dot_dim):
        return "No Solution"
    # Backtrack
    result = backtrack(grid, rem, dsu, N, dot_dim)
    if result is None:
        return "No Solution"
    return result

if __name__ == "__main__":
    solution = solve(OBSERVATION)
    if isinstance(solution, list):
        for row in solution:
            print(''.join(row))
    else:
        print(solution)
