                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                        can_b = False
                        break
                if can_b:
                    options += 1
                # Can be W?
                can_w = True
                if req is not None and (cb + (unk - 1)) < req:
                    can_w = False
                if can_w:
                    options +=1
                if options < min_options:
                    min_options = options
                    unknown = (r,c)
    if all_filled:
        if check_final(grid, obs):
            return grid
        return None
    r,c = unknown
    # Try B first
    new_grid = copy.deepcopy(grid)
    new_regions = copy.deepcopy(regions)
    new_grid[r][c] = 'B'
    rid = obs['region'][r][c]
    new_regions[rid]['current_b'] += 1
    new_regions[rid]['unknowns'] -= 1
    res = backtrack(new_grid, new_regions, obs)
    if res is not None:
        return res
    # Try W
    new_grid = copy.deepcopy(grid)
    new_regions = copy.deepcopy(regions)
    new_grid[r][c] = 'W'
    rid = obs['region'][r][c]
    new_regions[rid]['unknowns'] -= 1
    res = backtrack(new_grid, new_regions, obs)
    return res

def solve(observation):
    N = len(observation['region'])
    # Initialize grid
    grid = [[None for _ in range(N)] for _ in range(N)]
    # Initialize regions
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = observation['region'][r][c]
            if rid not in regions:
                regions[rid] = {
                    'cells': [],
                    'clue': observation['data'][r][c],
                    'required': observation['data'][r][c],
                    'current_b': 0
                }
            regions[rid]['cells'].append((r,c))
    for rid in regions:
        regions[rid]['unknowns'] = len(regions[rid]['cells'])
    # Solve
    result = backtrack(grid, regions, observation)
    if result is None:
        return "No Solution"
    # Convert to required output: 'B' for black, None for white
    output = []
    for row in result:
        out_row = []
        for cell in row:
            out_row.append('B' if cell == 'B' else None)
        output.append(out_row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
