        while changed:
            changed = False
            # Step 1: Row constraint propagation
            for r in range(N):
                fixed = set()
                for c in range(N):
                    if len(dom[r][c]) == 1:
                        fixed.add(next(iter(dom[r][c])))
                for c in range(N):
                    if len(dom[r][c]) > 1:
                        original_len = len(dom[r][c])
                        dom[r][c] -= fixed
                        if len(dom[r][c]) == 0:
                            return (False, None)
                        if len(dom[r][c]) != original_len:
                            changed = True
            # Step 2: Column constraint propagation
            for c in range(N):
                fixed = set()
                for r in range(N):
                    if len(dom[r][c]) == 1:
                        fixed.add(next(iter(dom[r][c])))
                for r in range(N):
                    if len(dom[r][c]) > 1:
                        original_len = len(dom[r][c])
                        dom[r][c] -= fixed
                        if len(dom[r][c]) == 0:
                            return (False, None)
                        if len(dom[r][c]) != original_len:
                            changed = True
            # Step3: Horizontal inequalities
            for key, sym in observation['horizontal'].items():
                r, c_half = eval(key)
                c1 = int(c_half - 0.5)
                c2 = c1 + 1
                d1 = dom[r][c1]
                d2 = dom[r][c2]
                if sym == '<':
                    # d1 elements must be < some d2 element
                    new_d1 = {v for v in d1 if any(u > v for u in d2)}
                    new_d2 = {u for u in d2 if any(v < u for v in d1)}
                else: # '>'
                    new_d1 = {v for v in d1 if any(u < v for u in d2)}
                    new_d2 = {u for u in d2 if any(v > u for v in d1)}
                if len(new_d1) == 0 or len(new_d2) == 0:
                    return (False, None)
                if new_d1 != d1:
                    dom[r][c1] = new_d1
                    changed = True
                if new_d2 != d2:
                    dom[r][c2] = new_d2
                    changed = True
            # Step4: Vertical inequalities
            for key, sym in observation['vertical'].items():
                r_half, c = eval(key)
                r1 = int(r_half - 0.5)
                r2 = r1 + 1
                d1 = dom[r1][c] # upper cell
                d2 = dom[r2][c] # lower cell
                if sym == '^':
                    # upper > lower: d1 > d2
                    new_d1 = {v for v in d1 if any(u < v for u in d2)}
                    new_d2 = {u for u in d2 if any(v > u for v in d1)}
                else: # 'v'
                    # upper < lower: d1 < d2
                    new_d1 = {v for v in d1 if any(u > v for u in d2)}
                    new_d2 = {u for u in d2 if any(v < u for v in d1)}
                if len(new_d1) == 0 or len(new_d2) == 0:
                    return (False, None)
                if new_d1 != d1:
                    dom[r1][c] = new_d1
                    changed = True
                if new_d2 != d2:
                    dom[r2][c] = new_d2
                    changed = True
        # Check if all domains are valid
        for r in range(N):
            for c in range(N):
