        return (True, dom)

    # Initial propagation
    valid, domains = propagate(domains)
    if not valid:
        return "No Solution"

    # Check if solved already
    def is_solved(dom):
        for r in range(N):
            for c in range(N):
                if len(dom[r][c]) != 1:
                    return False
        return True

    if is_solved(domains):
        res = [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]
        return res

    # Backtracking with MRV heuristic
    def backtrack(dom):
        if is_solved(dom):
            return [[next(iter(dom[r][c])) for c in range(N)] for r in range(N)]
        # Find cell with smallest domain size > 1
        min_size = N + 1
        cell = None
        for r in range(N):
            for c in range(N):
                s = len(dom[r][c])
                if 1 < s < min_size:
                    min_size = s
                    cell = (r, c)
                    if min_size == 2: # can't get smaller than 2, break early
                        break
            if min_size == 2:
                break
        r, c = cell
        # Try each value in domain
        for val in sorted(dom[r][c]):
            # Create copy of domains
            new_dom = [[set(s) for s in row] for row in dom]
            new_dom[r][c] = {val}
            # Propagate
            valid, updated_dom = propagate(new_dom)
            if valid:
                res = backtrack(updated_dom)
                if res is not None:
                    return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

