OBSERVATION = {'region': [[0, 1, 1, 2, 3], [0, 1, 1, 2, 3], [0, 4, 1, 2, 3], [0, 4, 4, 2, 3], [0, 4, 4, 2, 3]], 'data': [[None, 5, None, None, None], [None, None, None, None, 3], [None, 4, None, 2, None], [5, None, None, None, None], [None, None, None, 5, None]]}

def solve(observation):
    import copy
    region_map = observation['region']
    initial_grid = observation['data']
    N = len(initial_grid)

    # Precompute cell list per region
    region_cells = {}
    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    def get_possible_values(grid, r, c):
        if grid[r][c] is not None:
            return set()
        used = set()
        # Check row
        used.update(v for v in grid[r] if v is not None)
        # Check column
        used.update(grid[row][c] for row in range(N) if grid[row][c] is not None)
        # Check region
        rid = region_map[r][c]
        used.update(grid[rr][cc] for (rr, cc) in region_cells[rid] if grid[rr][cc] is not None)
        return set(range(1, N+1)) - used

    def propagate_constraints(grid):
        changed = True
        while changed:
            changed = False
            # Fill naked singles (only 1 possible value for cell)
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None:
                        possible = get_possible_values(grid, r, c)
                        if len(possible) == 0:
                            return False
                        if len(possible) == 1:
                            grid[r][c] = possible.pop()
                            changed = True
            if changed:
                continue
            # Fill hidden singles (value only fits in 1 cell of row/col/region)
            # Check rows
            for r in range(N):
                row_vals = set(v for v in grid[r] if v is not None)
                for val in range(1, N+1):
                    if val in row_vals:
                        continue
                    candidates = []
                    for c in range(N):
                        if grid[r][c] is None and val in get_possible_values(grid, r, c):
                            candidates.append(c)
                    if len(candidates) == 0:
                        return False
                    if len(candidates) == 1:
                        grid[r][candidates[0]] = val
                        changed = True
            if changed:
                continue
            # Check columns
            for c in range(N):
                col_vals = set(grid[r][c] for r in range(N) if grid[r][c] is not None)
                for val in range(1, N+1):
                    if val in col_vals:
                        continue
                    candidates = []
                    for r in range(N):
                        if grid[r][c] is None and val in get_possible_values(grid, r, c):
                            candidates.append(r)
                    if len(candidates) == 0:
                        return False
                    if len(candidates) == 1:
                        grid[candidates[0]][c] = val
                        changed = True
            if changed:
                continue
            # Check regions
            for rid in region_cells:
                region_vals = set(grid[r][c] for (r,c) in region_cells[rid] if grid[r][c] is not None)
                for val in range(1, N+1):
                    if val in region_vals:
                        continue
                    candidates = []
                    for (r,c) in region_cells[rid]:
                        if grid[r][c] is None and val in get_possible_values(grid, r, c):
                            candidates.append((r,c))
                    if len(candidates) == 0:
                        return False
                    if len(candidates) == 1:
                        r,c = candidates[0]
                        grid[r][c] = val
                        changed = True
        return True

    def backtrack(grid):
        if not propagate_constraints(grid):
            return None
        # Check if grid is full
        is_full = True
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    is_full = False
                    break
            if not is_full:
                break
        if is_full:
            return grid
        # Select cell with minimum remaining values (MRV heuristic)
        min_len = N + 1
        best_cell = None
        best_possible = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    possible = get_possible_values(grid, r, c)
                    if len(possible) < min_len:
                        min_len = len(possible)
                        best_cell = (r,c)
                        best_possible = possible
                        if min_len == 1:
                            break
            if min_len == 1:
                break
        r,c = best_cell
        for val in sorted(best_possible):
            new_grid = copy.deepcopy(grid)
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res is not None:
                return res
        return None

    working_grid = copy.deepcopy(initial_grid)
    solution = backtrack(working_grid)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
