def get_visible(r, c, grid, n):
    count = 0
    visible = []
    # Up direction
    for nr in range(r, -1, -1):
        if grid[nr][c] == 'B':
            break
        count += 1
        visible.append((nr, c))
    # Down direction
    for nr in range(r + 1, n):
        if grid[nr][c] == 'B':
            break
        count += 1
        visible.append((nr, c))
    # Left direction
    for nc in range(c - 1, -1, -1):
        if grid[r][nc] == 'B':
            break
        count += 1
        visible.append((r, nc))
    # Right direction
    for nc in range(c + 1, n):
        if grid[r][nc] == 'B':
            break
        count += 1
        visible.append((r, nc))
    return count, visible

def is_valid_black(r, c, grid, n):
    if isinstance(grid[r][c], int) or grid[r][c] == 'W':
        return False
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 'B':
            return False
    return True

def is_connected(grid, n):
    whites = []
    for r in range(n):
        for c in range(n):
            if isinstance(grid[r][c], int) or grid[r][c] == 'W':
                whites.append((r, c))
    if not whites:
        return False
    visited = set()
    q = [whites[0]]
    visited.add(whites[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        r, c = q.pop(0)
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                if isinstance(grid[nr][nc], int) or grid[nr][nc] == 'W':
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return len(visited) == len(whites)

def is_valid_state(grid, n, clues):
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 'B':
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 'B':
                        return False
    for (r, c, val) in clues:
        cnt, _ = get_visible(r, c, grid, n)
        if cnt > val:
            return False
    has_unknown = any(cell is None for row in grid for cell in row)
    if not has_unknown:
        if not is_connected(grid, n):
            return False
        for (r, c, val) in clues:
            cnt, _ = get_visible(r, c, grid, n)
            if cnt != val:
                return False
    return True

def propagate(grid, n, clues):
    changed = True
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while changed:
        changed = False
        # Rule 1: Adjacent to black cells are white
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 'B':
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n:
                            if grid[nr][nc] is None:
                                grid[nr][nc] = 'W'
                                changed = True
                            elif grid[nr][nc] == 'B':
                                return (False, False)
        # Rule 2: Process each clue constraints
        for (r, c, val) in clues:
            cnt, visible = get_visible(r, c, grid, n)
            if cnt > val:
                return (False, False)
            remaining = val - cnt
            if remaining < 0:
                return (False, False)
            # Get unknown cells per direction
            up = []
            for nr in range(r - 1, -1, -1):
                if grid[nr][c] == 'B':
                    break
                if grid[nr][c] is None:
                    up.append((nr, c))
            down = []
            for nr in range(r + 1, n):
                if grid[nr][c] == 'B':
                    break
                if grid[nr][c] is None:
                    down.append((nr, c))
            left = []
            for nc in range(c - 1, -1, -1):
                if grid[r][nc] == 'B':
                    break
                if grid[r][nc] is None:
                    left.append((r, nc))
            right = []
            for nc in range(c + 1, n):
                if grid[r][nc] == 'B':
                    break
                if grid[r][nc] is None:
                    right.append((r, nc))
            total_unknown = len(up) + len(down) + len(left) + len(right)
            if cnt + total_unknown < val:
                return (False, False)
            # If remaining is 0, block next cells in all directions
            if remaining == 0:
                # Up block
                col_visible = [x[0] for x in visible if x[1] == c]
                min_up_r = min(col_visible) if col_visible else r
                if min_up_r - 1 >= 0 and grid[min_up_r - 1][c] is None:
                    if is_valid_black(min_up_r - 1, c, grid, n):
                        grid[min_up_r - 1][c] = 'B'
                        changed = True
                    else:
                        return (False, False)
                # Down block
                max_down_r = max(col_visible) if col_visible else r
                if max_down_r + 1 < n and grid[max_down_r + 1][c] is None:
                    if is_valid_black(max_down_r + 1, c, grid, n):
                        grid[max_down_r + 1][c] = 'B'
                        changed = True
                    else:
                        return (False, False)
                # Left block
                row_visible = [x[1] for x in visible if x[0] == r]
                min_left_c = min(row_visible) if row_visible else c
                if min_left_c - 1 >= 0 and grid[r][min_left_c - 1] is None:
                    if is_valid_black(r, min_left_c - 1, grid, n):
                        grid[r][min_left_c - 1] = 'B'
                        changed = True
                    else:
                        return (False, False)
                # Right block
                max_right_c = max(row_visible) if row_visible else c
                if max_right_c + 1 < n and grid[r][max_right_c + 1] is None:
                    if is_valid_black(r, max_right_c + 1, grid, n):
                        grid[r][max_right_c + 1] = 'B'
                        changed = True
                    else:
                        return (False, False)
            # If remaining equals unknown count in one direction, mark all as white
            if remaining > 0:
                if len(up) == remaining:
                    for (nr, nc) in up:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
                if len(down) == remaining:
                    for (nr, nc) in down:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
                if len(left) == remaining:
                    for (nr, nc) in left:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
                if len(right) == remaining:
                    for (nr, nc) in right:
                        if grid[nr][nc] is None:
                            grid[nr][nc] = 'W'
                            changed = True
        if not is_valid_state(grid, n, clues):
            return (False, False)
    return (True, True)

def backtrack(grid, n, clues):
    ok, valid = propagate(grid, n, clues)
    if not valid:
        return None
    has_unknown = any(cell is None for row in grid for cell in row)
    if not has_unknown:
        if is_valid_state(grid, n, clues):
            return grid
        return None
    # Find most constrained cell
    min_options = 3
    best_cell = None
    best_adj = -1
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                options = 1  # W is always allowed
                if is_valid_black(r,c, grid, n):
                    options +=1
                adj_filled = 0
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<n and 0<=nc<n and grid[nr][nc] is not None:
                        adj_filled +=1
                if options < min_options or (options == min_options and adj_filled > best_adj):
                    min_options = options
                    best_cell = (r,c)
                    best_adj = adj_filled
    if best_cell is None:
        return None
    r,c = best_cell
    # Try black first
    if is_valid_black(r,c, grid, n):
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = 'B'
        res = backtrack(new_grid, n, clues)
        if res is not None:
            return res
    # Try white
    new_grid = [row.copy() for row in grid]
    new_grid[r][c] = 'W'
    res = backtrack(new_grid, n, clues)
    if res is not None:
        return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    grid = []
    clues = []
    for r in range(n):
        row = []
        for c in range(n):
            val = data[r][c]
            row.append(val)
            if val is not None:
                clues.append((r,c, val))
        grid.append(row)
    solution = backtrack(grid, n, clues)
    if solution is None:
        return "No Solution"
    # Convert to required output format
    output = []
    for r in range(n):
        out_row = []
        for c in range(n):
            cell = solution[r][c]
            if cell == 'W':
                out_row.append(None)
            else:
                out_row.append(cell)
        output.append(out_row)
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))
