def solve(observation):
    # Helper constraint functions to avoid lambda late binding issues
    def lt(a, b): return a < b
    def gt(a, b): return a > b
    def ne(a, b): return a != b
    def rev_lt(b, a): return lt(a, b)
    def rev_gt(b, a): return gt(a, b)

    from collections import deque
    data = observation['data']
    N = len(data)

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Build adjacency list of constraints
    adj = {cell: [] for cell in domains}

    # Add all-diff row constraints
    for r in range(N):
        for c1 in range(N):
            for c2 in range(N):
                if c1 != c2:
                    adj[(r, c1)].append(((r, c2), ne))

    # Add all-diff column constraints
    for c in range(N):
        for r1 in range(N):
            for r2 in range(N):
                if r1 != r2:
                    adj[(r1, c)].append(((r2, c), ne))

    # Add horizontal inequality constraints
    for key, sym in observation['horizontal'].items():
        parts = key.strip('()').split(',')
        r = int(float(parts[0].strip()))
        c_half = float(parts[1].strip())
        c = int(c_half - 0.5)
        cell_a = (r, c)
        cell_b = (r, c + 1)
        if sym == '<':
            adj[cell_a].append((cell_b, lt))
            adj[cell_b].append((cell_a, rev_lt))
        else:
            adj[cell_a].append((cell_b, gt))
            adj[cell_b].append((cell_a, rev_gt))

    # Add vertical inequality constraints
    for key, sym in observation['vertical'].items():
        parts = key.strip('()').split(',')
        r_half = float(parts[0].strip())
        r = int(r_half - 0.5)
        c = int(float(parts[1].strip()))
        cell_a = (r, c)
        cell_b = (r + 1, c)
        if sym == '^':
            adj[cell_a].append((cell_b, lt))
            adj[cell_b].append((cell_a, rev_lt))
        else:
            adj[cell_a].append((cell_b, gt))
            adj[cell_b].append((cell_a, rev_gt))

    # AC-3 Constraint Propagation
    q = deque()
    for c1 in adj:
        for (c2, func) in adj[c1]:
            q.append((c1, c2, func))

    while q:
        c1, c2, func = q.popleft()
        revised = False
        to_remove = []
        for val1 in domains[c1]:
            valid = any(func(val1, val2) for val2 in domains[c2])
            if not valid:
                to_remove.append(val1)
                revised = True
        for val in to_remove:
            domains[c1].remove(val)
        if not domains[c1]:
            return "No Solution"
        if revised:
            for (nc, nfunc) in adj[c1]:
                if nc != c2:
                    q.append((nc, c1, nfunc))

    # Check if already solved after AC-3
    solved = all(len(vals) == 1 for vals in domains.values())
    if solved:
        res = [[0]*N for _ in range(N)]
        for (r,c), vals in domains.items():
            res[r][c] = next(iter(vals))
        return res

    # Backtracking Search with MRV + LCV + Forward Checking
    def backtrack(assignment, doms):
        if len(assignment) == N * N:
            res = [[0]*N for _ in range(N)]
            for (r,c), val in assignment.items():
                res[r][c] = val
            return res

        # MRV Heuristic: select cell with smallest domain
        unassigned = [cell for cell in doms if cell not in assignment]
        cell = min(unassigned, key=lambda x: len(doms[x]))

        # LCV Heuristic: order values by least conflicts
        def count_conflicts(val):
            cnt = 0
            for (neigh, func) in adj[cell]:
                if neigh not in assignment:
                    cnt += sum(1 for nval in doms[neigh] if not func(val, nval))
            return cnt
        values = sorted(doms[cell], key=count_conflicts)

        for val in values:
            # Check consistency with current assignment
            consistent = True
            for (neigh, func) in adj[cell]:
                if neigh in assignment and not func(val, assignment[neigh]):
                    consistent = False
                    break
            if not consistent:
                continue

            # Create new assignment and domains
            new_assn = assignment.copy()
            new_assn[cell] = val
            new_doms = {k: v.copy() for k, v in doms.items()}
            new_doms[cell] = {val}

            # Forward checking
            valid = True
            fq = deque()
            for (neigh, func) in adj[cell]:
                if neigh not in new_assn:
                    fq.append((neigh, cell, func))

            while fq and valid:
                c1, c2, f = fq.popleft()
                to_rem = []
                for v1 in new_doms[c1]:
                    has_valid = any(f(v1, v2) for v2 in new_doms[c2])
                    if not has_valid:
                        to_rem.append(v1)
                for v in to_rem:
                    new_doms[c1].remove(v)
                if not new_doms[c1]:
                    valid = False
                    break
                if to_rem:
                    for (nc, nf) in adj[c1]:
                        if nc != c2 and nc not in new_assn:
                            fq.append((nc, c1, nf))

            if not valid:
                continue

            # Recurse
            result = backtrack(new_assn, new_doms)
            if result is not None:
                return result
        return None

    initial_assignment = {cell: next(iter(domains[cell])) for cell in domains if len(domains[cell]) == 1}
    solution = backtrack(initial_assignment, domains)
    return solution if solution is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
