from collections import deque

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0]*size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1
        return True

    def copy(self):
        new_dsu = DSU(0)
        new_dsu.parent = self.parent.copy()
        new_dsu.rank = self.rank.copy()
        return new_dsu

def propagate(grid, dsu, data, N):
    q = deque()
    in_queue = set()
    for dr in range(N+1):
        for dc in range(N+1):
            if data[dr][dc] is not None:
                key = (dr, dc)
                if key not in in_queue:
                    q.append(key)
                    in_queue.add(key)

    opp_dir = {'\\': '/', '/': '\\'}

    while q:
        dr, dc = q.popleft()
        in_queue.remove((dr, dc))
        k = data[dr][dc]
        if k is None:
            continue

        current = 0
        possible = []

        if dr > 0 and dc > 0:
            r, c = dr-1, dc-1
            val = grid[r][c]
            if val == '\\':
                current += 1
            elif val is None:
                possible.append((r, c, '\\'))

        if dr > 0 and dc < N:
            r, c = dr-1, dc
            val = grid[r][c]
            if val == '/':
                current += 1
            elif val is None:
                possible.append((r, c, '/'))

        if dr < N and dc > 0:
            r, c = dr, dc-1
            val = grid[r][c]
            if val == '/':
                current += 1
            elif val is None:
                possible.append((r, c, '/'))

        if dr < N and dc < N:
            r, c = dr, dc
            val = grid[r][c]
            if val == '\\':
                current += 1
            elif val is None:
                possible.append((r, c, '\\'))

        if current > k:
            return False
        rem = k - current
        if rem < 0 or rem > len(possible):
            return False

        if rem == len(possible):
            for (r, c, d) in possible:
                if grid[r][c] is not None:
                    if grid[r][c] != d:
                        return False
                    continue
                grid[r][c] = d
                if d == '\\':
                    d1, d2 = (r, c), (r+1, c+1)
                else:
                    d1, d2 = (r, c+1), (r+1, c)
                idx1 = d1[0]*(N+1) + d1[1]
                idx2 = d2[0]*(N+1) + d2[1]
                if dsu.find(idx1) == dsu.find(idx2):
                    return False
                dsu.union(idx1, idx2)
                for dot in [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]:
                    if dot not in in_queue:
                        q.append(dot)
                        in_queue.add(dot)
        elif rem == 0:
            for (r, c, d) in possible:
                req_d = opp_dir[d]
                if grid[r][c] is not None:
                    if grid[r][c] != req_d:
                        return False
                    continue
                grid[r][c] = req_d
                if req_d == '\\':
                    d1, d2 = (r, c), (r+1, c+1)
                else:
                    d1, d2 = (r, c+1), (r+1, c)
                idx1 = d1[0]*(N+1) + d1[1]
                idx2 = d2[0]*(N+1) + d2[1]
                if dsu.find(idx1) == dsu.find(idx2):
                    return False
                dsu.union(idx1, idx2)
                for dot in [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]:
                    if dot not in in_queue:
                        q.append(dot)
                        in_queue.add(dot)
    return True

def backtrack(grid, dsu, data, N):
    all_filled = True
    min_opt = 3
    best_cell = None
    best_opts = []
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                all_filled = False
                opts = []
                for d in ['/', '\\']:
                    if d == '\\':
                        d1, d2 = (r,c), (r+1,c+1)
                    else:
                        d1, d2 = (r,c+1), (r+1,c)
                    idx1 = d1[0]*(N+1) + d1[1]
                    idx2 = d2[0]*(N+1) + d2[1]
                    if dsu.find(idx1) == dsu.find(idx2):
                        continue
                    valid = True
                    for (dr, dc) in [d1, d2]:
                        k = data[dr][dc]
                        if k is None:
                            continue
                        curr = 0
                        if dr > 0 and dc > 0 and grid[dr-1][dc-1] == '\\':
                            curr += 1
                        if dr > 0 and dc < N and grid[dr-1][dc] == '/':
                            curr +=1
                        if dr < N and dc >0 and grid[dr][dc-1] == '/':
                            curr +=1
                        if dr < N and dc < N and grid[dr][dc] == '\\':
                            curr +=1
                        curr +=1
                        if curr > k:
                            valid = False
                            break
                    if valid:
                        opts.append(d)
                if not opts:
                    return None
                if len(opts) < min_opt:
                    min_opt = len(opts)
                    best_cell = (r,c)
                    best_opts = opts
                    if min_opt == 1:
                        break
        if min_opt == 1:
            break
    if all_filled:
        return [row.copy() for row in grid]
    r,c = best_cell
    for d in best_opts:
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = d
        new_dsu = dsu.copy()
        if d == '\\':
            d1, d2 = (r,c), (r+1,c+1)
        else:
            d1, d2 = (r,c+1), (r+1,c)
        idx1 = d1[0]*(N+1) + d1[1]
        idx2 = d2[0]*(N+1) + d2[1]
        if new_dsu.find(idx1) == new_dsu.find(idx2):
            continue
        new_dsu.union(idx1, idx2)
        if not propagate(new_grid, new_dsu, data, N):
            continue
        res = backtrack(new_grid, new_dsu, data, N)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    if N < 1:
        return []
    grid = [[None]*N for _ in range(N)]
    dsu_size = (N+1)*(N+1)
    dsu = DSU(dsu_size)
    if not propagate(grid, dsu, data, N):
        return "No Solution"
    res = backtrack(grid, dsu, data, N)
    return res if res is not None else "No Solution"

