                current_vis += 1
                max_h = num
        if current_vis > clue:
            return False
        if len(filled) == len(seq):
            return current_vis == clue
        remaining = set(range(1, N+1)) - set(filled)
        max_remaining = max(remaining)
        min_add = 1 if max_remaining > max_h else 0
        if current_vis + min_add > clue:
            return False
        add_vis = 0
        temp_max = max_h
        for num in sorted(remaining, reverse=True):
            if num > temp_max:
                add_vis += 1
                temp_max = num
        if current_vis + add_vis < clue:
            return False
        return True

    def propagate(possible):
        changes = True
        while changes:
            changes = False
            for i in range(N):
                for j in range(N):
                    if len(possible[i][j]) == 1:
                        val = next(iter(possible[i][j]))
                        for k in range(N):
                            if k != j and val in possible[i][k]:
                                possible[i][k].remove(val)
                                changes = True
                                if len(possible[i][k]) == 0:
                                    return (False, None)
                        for k in range(N):
                            if k != i and val in possible[k][j]:
                                possible[k][j].remove(val)
                                changes = True
                                if len(possible[k][j]) == 0:
                                    return (False, None)
            for i in range(N):
                l = observation['L'][i]
                r = observation['R'][i]
                row = [next(iter(possible[i][j])) if len(possible[i][j]) == 1 else None for j in range(N)]
                if not is_valid_partial(row, l):
                    return (False, None)
                if not is_valid_partial(row[::-1], r):
                    return (False, None)
            for j in range(N):
                u = observation['U'][j]
                d = observation['D'][j]
                col = [next(iter(possible[i][j])) if len(possible[i][j]) == 1 else None for i in range(N)]
                if not is_valid_partial(col, u):
                    return (False, None)
                if not is_valid_partial(col[::-1], d):
                    return (False, None)
        return (True, possible)

    def is_full_valid(grid):
        for i in range(N):
            row = grid[i]
            l = observation['L'][i]
            r = observation['R'][i]
            if l != 0 and count_visible(row) != l:
                return False
            if r != 0 and count_visible(reversed(row)) != r:
                return False
        for j in range(N):
            col = [grid[i][j] for i in range(N)]
            u = observation['U'][j]
            d = observation['D'][j]
            if u != 0 and count_visible(col) != u:
                return False
            if d != 0 and count_visible(reversed(col)) != d:
                return False
        return True

    def backtrack(possible):
        ok, updated = propagate(possible)
        if not ok:
            return None
        all_assigned = True
        for i in range(N):
            for j in range(N):
                if len(updated[i][j]) != 1:
                    all_assigned = False
                    break
            if not all_assigned:
                break
        if all_assigned:
            grid = [[next(iter(updated[i][j])) for j in range(N)] for i in range(N)]
            if is_full_valid(grid):
                return grid
            return None
        min_len = N + 1
        cell = None
        for i in range(N):
            for j in range(N):
                l = len(updated[i][j])
                if 1 < l < min_len:
                    min_len = l
                    cell = (i, j)
                    if min_len == 2:
                        break
            if min_len == 2:
                break
        i, j = cell
        for val in sorted(updated[i][j]):
            new_possible = [[set(s) for s in row] for row in updated]
            new_possible[i][j] = {val}
            res = backtrack(new_possible)
            if res is not None:
                return res
        return None

    possible = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for i in range(N):
        l = observation['L'][i]
        r = observation['R'][i]
        if l == 1:
            possible[i][0] = {N}
        elif l == N:
            for j in range(N):
                possible[i][j] = {j+1}
        if r == 1:
            possible[i][N-1] = {N}
        elif r == N:
            for j in range(N):
                possible[i][j] = {N - j}
    for j in range(N):
        u = observation['U'][j]
        d = observation['D'][j]
        if u == 1:
            possible[0][j] = {N}
        elif u == N:
            for i in range(N):
                possible[i][j] = {i+1}
        if d == 1:
            possible[N-1][j] = {N}
        elif d == N:
            for i in range(N):
                possible[i][j] = {N - i}
    solution = backtrack(possible)
    return solution if solution is not None else "No Solution"

