            start = r
            valid_run = True
            while r < N and grid[r][c] != 'B':
                if grid[r][c] is None:
                    valid_run = False
                    break
                regions.add(region_grid[r][c])
                r += 1
            if valid_run and len(regions) > 2:
                return False
            if not valid_run:
                r = start + 1
        return True

    def check_connectivity():
        start = None
        total_white = 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'W':
                    total_white += 1
                    if start is None:
                        start = (r,c)
        if total_white == 0:
            return False
        visited = set([start])
        q = [start]
