        can_b = True
        rid = region_grid[r][c]
        clue = region_map[rid]['clue']
        if clue is not None and count_blacks(rid) >= clue:
            can_b = False
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                can_b = False
                break
        if can_b:
            changes = []
