def is_partial_feasible(partial, clue, total_len):
    if clue == 0:
        return True
    filled = [x for x in partial if x != 0]
    if len(filled) == total_len:
        return count_visible(partial) == clue
    current_vis = count_visible(filled)
    current_max = max(filled) if filled else 0
    remaining = set(range(1, total_len + 1)) - set(filled)
    num_larger = sum(1 for x in remaining if x > current_max)
    min_add = 1 if num_larger else 0
    max_add = num_larger
    return current_vis + min_add <= clue <= current_vis + max_add

def check_all_feasible(grid, N, U, D, L, R):
    # Check rows
    for r in range(N):
        row = grid[r]
        if not is_partial_feasible(row, L[r], N):
            return False
        if not is_partial_feasible(row[::-1], R[r], N):
            return False
    # Check columns
    for c in range(N):
        col = [grid[r][c] for r in range(N)]
        if not is_partial_feasible(col, U[c], N):
            return False
        if not is_partial_feasible(col[::-1], D[c], N):
            return False
    return True

def select_mrv_cell(grid, domains, N):
    min_size = float('inf')
    best_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 0:
                size = len(domains[r][c])
                if size < min_size:
                    min_size = size
                    best_cell = (r, c)
                    if min_size == 1:
                        return best_cell
    return best_cell

def backtrack(grid, domains, N, U, D, L, R):
    # Check if all filled
    if all(all(cell != 0 for cell in row) for row in grid):
        return [row.copy() for row in grid]
    # Select MRV cell
    r, c = select_mrv_cell(grid, domains, N)
    # Try each possible value
    for val in sorted(domains[r][c]):
        # Check if val already exists in row or column
        if val in grid[r] or val in [grid[i][c] for i in range(N)]:
            continue
        # Assign value
        grid[r][c] = val
        # Create new domains
        new_domains = [[set(s) for s in row] for row in domains]
        new_domains[r][c] = {val}
        # Remove val from row and column domains
        valid = True
        for i in range(N):
            if i != c and val in new_domains[r][i]:
                new_domains[r][i].remove(val)
                if len(new_domains[r][i]) == 0:
                    valid = False
            if i != r and val in new_domains[i][c]:
                new_domains[i][c].remove(val)
                if len(new_domains[i][c]) == 0:
                    valid = False
        if not valid:
            grid[r][c] = 0
            continue
        # Check feasibility
        if not check_all_feasible(grid, N, U, D, L, R):
            grid[r][c] = 0
            continue
        # Recurse
        res = backtrack(grid, new_domains, N, U, D, L, R)
        if res is not None:
            return res
        # Backtrack
        grid[r][c] = 0
    return None

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    # Initialize grid and domains
    grid = [[0 for _ in range(N)] for _ in range(N)]
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Initial constraint propagation for obvious clues
    for r in range(N):
        if L[r] == N:
            for c in range(N):
                grid[r][c] = c + 1
                domains[r][c] = {c + 1}
        elif L[r] == 1:
            grid[r][0] = N
            domains[r][0] = {N}
        if R[r] == N:
            for c in range(N):
                grid[r][c] = N - c
                domains[r][c] = {N - c}
        elif R[r] == 1:
            grid[r][N-1] = N
            domains[r][N-1] = {N}
    for c in range(N):
        if U[c] == N:
            for r in range(N):
                grid[r][c] = r + 1
                domains[r][c] = {r + 1}
        elif U[c] == 1:
            grid[0][c] = N
            domains[0][c] = {N}
        if D[c] == N:
            for r in range(N):
                grid[r][c] = N - r
                domains[r][c] = {N - r}
        elif D[c] == 1:
            grid[N-1][c] = N
            domains[N-1][c] = {N}

    # Update domains after initial assignments
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            if val != 0:
                for i in range(N):
                    if i != c and val in domains[r][i]:
                        domains[r][i].remove(val)
                    if i != r and val in domains[i][c]:
                        domains[i][c].remove(val)

    # Check initial feasibility
    if not check_all_feasible(grid, N, U, D, L, R):
        return "No Solution"

    solution = backtrack(grid, domains, N, U, D, L, R)
    return solution if solution is not None else "No Solution"

