        if U[c] == 1:
            grid[0][c] = {N}
        elif U[c] == N:
            for r in range(N):
                grid[r][c] = {r+1}
        if D[c] == 1:
            grid[-1][c] = {N}
        elif D[c] == N:
            for r in range(N):
                grid[r][c] = {N - r}

    result = backtrack()
    return result if result else "No Solution"

