    for r in range(N):
        for c in range(N):
            if len(possible[r][c]) != 1:
                return False
    return True

def get_solution(possible, N):
    res = [[0]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            res[r][c] = next(iter(possible[r][c]))
    return res

def backtrack(possible, region, region_cells, N):
    valid, possible = propagate(possible, region, region_cells, N)
    if not valid:
        return None
    if is_solved(possible, N):
        return get_solution(possible, N)

    # Find cell with smallest number of possibilities
    min_len = float('inf')
    cell = None
    for r in range(N):
        for c in range(N):
            l = len(possible[r][c])
            if l >1 and l < min_len:
                min_len = l
                cell = (r,c)
                if min_len == 2: # Can't get smaller than 2
                    break
        if min_len ==2:
            break

    r,c = cell
    for val in possible[r][c]:
        new_possible = copy.deepcopy(possible)
        new_possible[r][c] = {val}
        res = backtrack(new_possible, region, region_cells, N)
        if res is not None:
