                r2 = r1 + 1
                a, b = g[r1][c], g[r2][c]
                if a is not None and b is None:
                    g[r2][c] = a if val == '=' else ('W' if a == 'B' else 'B')
                    changed = True
                elif b is not None and a is None:
                    g[r1][c] = b if val == '=' else ('W' if b == 'B' else 'B')
                    changed = True
                elif a is not None and b is not None:
                    if (val == '=' and a != b) or (val == 'x' and a == b):
                        return False

            for r in range(N):
                row = g[r]
                for i in range(N-2):
                    a, b, c = row[i], row[i+1], row[i+2]
                    if a == b and a is not None and c is None:
                        row[i+2] = 'W' if a == 'B' else 'B'
                        changed = True
                    if b == c and b is not None and a is None:
                        row[i] = 'W' if b == 'B' else 'B'
                        changed = True
                    if a == b == c and a is not None:
                        return False

            for c in range(N):
                for i in range(N-2):
                    a = g[i][c]
                    b = g[i+1][c]
                    c_val = g[i+2][c]
                    if a == b and a is not None and c_val is None:
                        g[i+2][c] = 'W' if a == 'B' else 'B'
                        changed = True
                    if b == c_val and b is not None and a is None:
                        g[i][c] = 'W' if b == 'B' else 'B'
                        changed = True
                    if a == b == c_val and a is not None:
                        return False

            for r in range(N):
                row = g[r]
                b_count = row.count('B')
                w_count = row.count('W')
                if b_count > req_per_color or w_count > req_per_color:
                    return False
                if b_count == req_per_color:
                    for i in range(N):
                        if row[i] is None:
                            row[i] = 'W'
                            changed = True
                if w_count == req_per_color:
                    for i in range(N):
                        if row[i] is None:
                            row[i] = 'B'
                            changed = True

            for c in range(N):
                col = [g[r][c] for r in range(N)]
                b_count = col.count('B')
                w_count = col.count('W')
                if b_count > req_per_color or w_count > req_per_color:
                    return False
                if b_count == req_per_color:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                if w_count == req_per_color:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            if not changed:
                break
        return is_valid(g)

    def backtrack(g):
        if not propagate(g):
            return None
        full = True
        for r in range(N):
            if None in g[r]:
                full = False
                break
        if full:
            return g

        min_options = 3
        best_cell = None
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    opts = 0
                    for v in ['B', 'W']:
                        g[r][c] = v
                        if is_valid(g):
                            opts +=1
                        g[r][c] = None
                    if opts < min_options:
                        min_options = opts
                        best_cell = (r,c)
                        if min_options == 0:
                            return None
                        if min_options == 1:
                            break
            if min_options == 1:
                break

        r,c = best_cell
        for val in ['B', 'W']:
            new_grid = copy.deepcopy(g)
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res is not None:
                return res
        return None

    sol = backtrack(grid)
    return sol if sol is not None else "No Solution"

