                    seen.add(val)

        # Check unique white values per column
        for c in range(n):
            seen = set()
            for r in range(n):
                if state[r][c] is None:
                    val = original[r][c]
                    if val in seen:
                        return False
                    seen.add(val)

        # Check if white cells can be connected (through unknown/white cells)
        white_cells = [(r, c) for r in range(n) for c in range(n) if state[r][c] is None]
        if not white_cells:
            return False

        visited = set()
        q = [white_cells[0]]
        visited.add(white_cells[0])
        while q:
            r, c = q.pop(0)
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                    if state[nr][nc] is None or state[nr][nc] != 'B':
                        visited.add((nr, nc))
                        q.append((nr, nc))

        for cell in white_cells:
            if cell not in visited:
                return False

        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False
            # Rule 1: White cell forces all duplicates in row/column to be black
            for r in range(n):
                for c in range(n):
                    if state[r][c] is None:
                        val = original[r][c]
                        # Process row
                        for cc in range(n):
                            if cc != c and original[r][cc] == val and state[r][cc] not in ('B', None):
                                state[r][cc] = 'B'
                                changed = True
                        # Process column
                        for rr in range(n):
                            if rr != r and original[rr][c] == val and state[rr][c] not in ('B', None):
                                state[rr][c] = 'B'
                                changed = True

            # Rule 2: Black cell forces all adjacent cells to be white
            for r in range(n):
                for c in range(n):
                    if state[r][c] == 'B':
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n and state[nr][nc] not in ('B', None):
                                state[nr][nc] = None
                                changed = True

            # Rule 3: Cell adjacent to black cannot be black, so force white
            for r in range(n):
                for c in range(n):
                    if state[r][c] not in ('B', None):
                        has_black_neighbor = False
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n and state[nr][nc] == 'B':
                                has_black_neighbor = True
                                break
                        if has_black_neighbor:
                            state[r][c] = None
                            changed = True
        return state

    def backtrack(state):
        state = propagate([row.copy() for row in state])
        if not is_valid(state):
            return None

