                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<n and 0<=nc<n and state[nr][nc] is None and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        q.append((nr,nc))
            if len(visited) == len(white):
                return [['B' if cell == 'B' else None for cell in row] for row in state]
            return None

        # Pick most constrained unknown (highest duplicate count in row + column)
        def constraint_count(cell):
            r,c = cell
            val = original[r][c]
            row_cnt = sum(1 for cc in range(n) if original[r][cc] == val)
            col_cnt = sum(1 for rr in range(n) if original[rr][c] == val)
            return row_cnt + col_cnt

        unknowns.sort(key=constraint_count, reverse=True)
        r,c = unknowns[0]

        # Try mark as black first
        new_state = [row.copy() for row in state]
        new_state[r][c] = 'B'
        res = backtrack(new_state)
        if res:
            return res

        # Try mark as white
        new_state = [row.copy() for row in state]
        new_state[r][c] = None
        res = backtrack(new_state)
        if res:
            return res

        return None

    initial_grid = [row.copy() for row in original]
    solution = backtrack(initial_grid)
    return solution if solution else "No Solution"

