from collections import deque

def solve(observation):
    N = len(observation['region'])
    # Preprocess regions
    regions = {}
    rid_to_clue = {}
    for r in range(N):
        for c in range(N):
            rid = observation['region'][r][c]
            if rid not in regions:
                regions[rid] = []
                if observation['data'][r][c] is not None:
                    rid_to_clue[rid] = observation['data'][r][c]
                else:
                    rid_to_clue[rid] = None
            regions[rid].append((r,c))

    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_connected(grid):
        # Check all white cells are orthogonally connected
        white_cells = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    white_cells.append((r,c))
        if not white_cells:
            return True
        visited = set()
        q = deque([white_cells[0]])
        visited.add(white_cells[0])
        while q:
            r,c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<N and 0<=nc<N and grid[nr][nc] is None and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    q.append((nr,nc))
        return len(visited) == len(white_cells)

    def check_rule3(grid):
        # Check rows
        for r in range(N):
            start = 0
            while start < N:
                if grid[r][start] == 'B':
                    start += 1
                    continue
                end = start
                regs = set()
                has_unassigned = False
                while end < N and grid[r][end] != 'B':
                    regs.add(observation['region'][r][end])
                    if grid[r][end] is None:
                        has_unassigned = True
                    end += 1
                if len(regs) > 2 and not has_unassigned:
                    return False
                start = end
        # Check columns
        for c in range(N):
            start = 0
            while start < N:
                if grid[start][c] == 'B':
                    start +=1
                    continue
                end = start
                regs = set()
                has_unassigned = False
                while end < N and grid[end][c] != 'B':
                    regs.add(observation['region'][end][c])
                    if grid[end][c] is None:
                        has_unassigned = True
                    end +=1
                if len(regs) > 2 and not has_unassigned:
                    return False
                start = end
        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Process regions
            for rid in regions:
                clue = rid_to_clue[rid]
                if clue is None:
                    continue
                cells = regions[rid]
                b_count = 0
                unassigned = []
                for (r,c) in cells:
                    if grid[r][c] == 'B':
                        b_count +=1
                    elif grid[r][c] is None:
                        unassigned.append((r,c))
                if b_count > clue:
                    return (False, None)
                if b_count == clue:
                    # All unassigned must be white
                    for (r,c) in unassigned:
                        if grid[r][c] is None:
                            grid[r][c] = None  # redundant but mark change
                            changed = True
                remaining = clue - b_count
                if remaining == len(unassigned) and remaining > 0:
                    # All unassigned must be B
                    for (r,c) in unassigned:
                        # Check adjacent B
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                                return (False, None)
                        grid[r][c] = 'B'
                        changed = True
                        # Set adjacent cells to white
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N and grid[nr][nc] is None:
                                grid[nr][nc] = None
                                changed = True
            # Check adjacent B cells
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'B':
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<N and 0<=nc<N:
                                if grid[nr][nc] == 'B':
                                    return (False, None)
                                if grid[nr][nc] is None:
                                    grid[nr][nc] = None
                                    changed = True
            # Check rule3
            if not check_rule3(grid):
                return (False, None)
        # Final checks
        if not check_rule3(grid):
            return (False, None)
        return (True, grid)

    def backtrack(grid):
        # Propagate first
        valid, grid = propagate([row[:] for row in grid])
        if not valid:
            return None
        # Check if all cells are assigned
        unassigned = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    unassigned.append((r,c))
        if not unassigned:
            if is_connected(grid):
                return grid
            else:
                return None
        # Pick most constrained cell (min possible options)
        min_options = 3
        best_cell = None
        for (r,c) in unassigned:
            options = 0
            # Check if B is possible
            can_b = True
            rid = observation['region'][r][c]
            clue = rid_to_clue[rid]
            if clue is not None:
                b_count = 0
                for (rr,cc) in regions[rid]:
                    if grid[rr][cc] == 'B':
                        b_count +=1
                if b_count >= clue:
                    can_b = False
            if can_b:
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                        can_b = False
                        break
            if can_b:
                options +=1
            # White is always possible unless it breaks rule3, but we can count it
            options +=1
            if options < min_options:
                min_options = options
                best_cell = (r,c)
                if min_options == 1:
                    break
        r,c = best_cell
        # Try B first
        can_b = True
        rid = observation['region'][r][c]
        clue = rid_to_clue[rid]
        if clue is not None:
            b_count = 0
            for (rr,cc) in regions[rid]:
                if grid[rr][cc] == 'B':
                    b_count +=1
            if b_count >= clue:
                can_b = False
        if can_b:
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<N and 0<=nc<N and grid[nr][nc] == 'B':
                    can_b = False
                    break
        if can_b:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = 'B'
            res = backtrack(new_grid)
            if res is not None:
                return res
        # Try white
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = None
        res = backtrack(new_grid)
        if res is not None:
            return res
        return None

    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    # Set 0 clue regions to all white first
    for rid in regions:
        if rid_to_clue[rid] == 0:
            for (r,c) in regions[rid]:
                initial_grid[r][c] = None
    solution = backtrack(initial_grid)
    if solution is None:
        return "No Solution"
    return solution

