OBSERVATION = {'U': [2, 0, 0, 1, 0, 6], 'D': [2, 2, 3, 0, 0, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}

def count_visible(seq):
    max_h = 0
    count = 0
    for h in seq:
        if h > max_h:
            count += 1
            max_h = h
    return count

def is_partial_valid(seq, clue):
    if clue == 0:
        return True
    filled = [x for x in seq if x != 0]
    current_vis = count_visible(filled)
    if current_vis > clue:
        return False
    remaining = len(seq) - len(filled)
    max_possible = current_vis + remaining
    if max_possible < clue:
        return False
    if remaining == 0:
        return current_vis == clue
    return True

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    grid = [[0]*N for _ in range(N)]
    possible = [[set(range(1, N+1)) for _ in range(N)] for __ in range(N)]

    # Initial deductions from edge clues equal to N or 1
    for c in range(N):
        if U[c] == N:
            for r in range(N):
                grid[r][c] = r+1
                possible[r][c] = {r+1}
        elif U[c] == 1:
            grid[0][c] = N
            possible[0][c] = {N}
        if D[c] == N:
            for r in range(N):
                grid[r][c] = N - r
                possible[r][c] = {N - r}
        elif D[c] == 1:
            grid[N-1][c] = N
            possible[N-1][c] = {N}
    for r in range(N):
        if L[r] == N:
            for c in range(N):
                grid[r][c] = c+1
                possible[r][c] = {c+1}
        elif L[r] == 1:
            grid[r][0] = N
            possible[r][0] = {N}
        if R[r] == N:
            for c in range(N):
                grid[r][c] = N - c
                possible[r][c] = {N - c}
        elif R[r] == 1:
            grid[r][N-1] = N
            possible[r][N-1] = {N}

    # Constraint propagation loop
    changed = True
    while changed:
        changed = False
        # Remove values present in assigned cells from same row/column possibilities
        for r in range(N):
            for c in range(N):
                if grid[r][c] != 0:
                    val = grid[r][c]
                    for cc in range(N):
                        if cc != c and val in possible[r][cc]:
                            possible[r][cc].remove(val)
                            changed = True
                    for rr in range(N):
                        if rr != r and val in possible[rr][c]:
                            possible[rr][c].remove(val)
                            changed = True
        # Assign cells with only one remaining possible value
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0 and len(possible[r][c]) == 1:
                    val = next(iter(possible[r][c]))
                    grid[r][c] = val
                    changed = True
        # Find hidden singles in rows
        for r in range(N):
            for val in range(1, N+1):
                pos = []
                for c in range(N):
                    if grid[r][c] == 0 and val in possible[r][c]:
                        pos.append(c)
                if len(pos) == 1:
                    c = pos[0]
                    if grid[r][c] == 0:
                        grid[r][c] = val
                        possible[r][c] = {val}
                        changed = True
        # Find hidden singles in columns
        for c in range(N):
            for val in range(1, N+1):
                pos = []
                for r in range(N):
                    if grid[r][c] == 0 and val in possible[r][c]:
                        pos.append(r)
                if len(pos) == 1:
                    r = pos[0]
                    if grid[r][c] == 0:
                        grid[r][c] = val
                        possible[r][c] = {val}
                        changed = True

    # Check if already fully solved after propagation
    def is_solved():
        for r in range(N):
            if 0 in grid[r]: return False
            if not is_partial_valid(grid[r], L[r]): return False
            if not is_partial_valid(grid[r][::-1], R[r]): return False
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if not is_partial_valid(col, U[c]): return False
            if not is_partial_valid(col[::-1], D[c]): return False
        return True
    if is_solved():
        return grid

    # Backtracking search with MRV heuristic
    def backtrack():
        # Select unassigned cell with smallest number of possible values
        min_len, cell = N+1, None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0 and len(possible[r][c]) < min_len:
                    min_len = len(possible[r][c])
                    cell = (r, c)
        if cell is None:
            return grid if is_solved() else None
        r, c = cell
        # Try each possible value for selected cell
        for val in sorted(possible[r][c]):
            # Skip duplicate values in row/column
            if val in grid[r]: continue
            if val in [grid[rr][c] for rr in range(N)]: continue
            # Assign value and save state for backtracking
            grid[r][c] = val
            saved_possible = [[set(s) for s in row] for row in possible]
            # Update possible values for same row/column
            for cc in range(N):
                if cc != c: possible[r][cc].discard(val)
            for rr in range(N):
                if rr != r: possible[rr][c].discard(val)
            # Check partial validity of affected row and column
            valid = True
            if not is_partial_valid(grid[r], L[r]): valid = False
            if not is_partial_valid(grid[r][::-1], R[r]): valid = False
            col = [grid[rr][c] for rr in range(N)]
            if not is_partial_valid(col, U[c]): valid = False
            if not is_partial_valid(col[::-1], D[c]): valid = False
            if valid:
                res = backtrack()
                if res is not None:
                    return res
            # Undo assignment
            grid[r][c] = 0
            possible = saved_possible
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
