    }
}

def solve(observation):
    n = len(observation['data'])
    m = len(observation['data'][0])
    required_per_row = n // 2

    # Preprocess all constraints into list of ((r1,c1), (r2,c2), op)
    constraints = []
    for key, op in observation['horizontal'].items():
        r, c_half = eval(key)
        c = int(c_half - 0.5)
        constraints.append(((int(r), c), (int(r), c+1), op))
    for key, op in observation['vertical'].items():
        r_half, c = eval(key)
        r = int(r_half - 0.5)
        constraints.append(((r, int(c)), (r+1, int(c)), op))

    # Initialize grid: each cell is set of possible values {'B', 'W'}
    grid = []
    for r in range(n):
        row = []
        for c in range(m):
            val = observation['data'][r][c]
            row.append({val} if val is not None else {'B', 'W'})
        grid.append(row)

    def is_valid():
        # Check no empty possible sets
        for r in range(n):
            for c in range(m):
                if len(grid[r][c]) == 0:
                    return False
        # Check row counts don't exceed limit
        for r in range(n):
            b_count = sum(1 for c in range(m) if grid[r][c] == {'B'})
            w_count = sum(1 for c in range(m) if grid[r][c] == {'W'})
            if b_count > required_per_row or w_count > required_per_row:
                return False
        # Check column counts don't exceed limit
        for c in range(m):
            b_count = sum(1 for r in range(n) if grid[r][c] == {'B'})
            w_count = sum(1 for r in range(n) if grid[r][c] == {'W'})
            if b_count > required_per_row or w_count > required_per_row:
                return False
        # Check no existing three consecutive same values
        for r in range(n):
            for i in range(m-2):
                a, b, c_cell = grid[r][i], grid[r][i+1], grid[r][i+2]
                if len(a) == 1 and len(b) == 1 and len(c_cell) ==1:
                    if a == b == c_cell:
                        return False
        for c in range(m):
            for i in range(n-2):
                a, b, d = grid[i][c], grid[i+1][c], grid[i+2][c]
                if len(a) ==1 and len(b) ==1 and len(d) ==1:
                    if a == b == d:
                        return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False
            # Apply adjacency constraints
            for (r1,c1), (r2,c2), op in constraints:
                s1, s2 = grid[r1][c1], grid[r2][c2]
                if op == '=':
                    common = s1 & s2
                    if common != s1:
                        grid[r1][c1] = common
                        changed = True
                    if common != s2:
                        grid[r2][c2] = common
                        changed = True
                else: # 'x' constraint
                    new_s1 = {v for v in s1 if ('W' if v == 'B' else 'B') in s2}
                    new_s2 = {v for v in s2 if ('W' if v == 'B' else 'B') in s1}
                    if new_s1 != s1:
                        grid[r1][c1] = new_s1
                        changed = True
                    if new_s2 != s2:
                        grid[r2][c2] = new_s2
                        changed = True
            # Apply consecutive three rule for rows
            for r in range(n):
                for i in range(m-2):
                    a, b, c_cell = grid[r][i], grid[r][i+1], grid[r][i+2]
                    if len(a) == 1 and len(b) == 1 and a == b:
                        opp = 'W' if next(iter(a)) == 'B' else 'B'
                        if opp not in c_cell:
                            return False
                        if grid[r][i+2] != {opp}:
                            grid[r][i+2] = {opp}
                            changed = True
                    if len(b) ==1 and len(c_cell) ==1 and b == c_cell:
                        opp = 'W' if next(iter(b)) == 'B' else 'B'
                        if opp not in a:
                            return False
                        if grid[r][i] != {opp}:
                            grid[r][i] = {opp}
                            changed = True
            # Apply consecutive three rule for columns
            for c in range(m):
                for i in range(n-2):
                    a, b, d = grid[i][c], grid[i+1][c], grid[i+2][c]
                    if len(a) ==1 and len(b) ==1 and a == b:
                        opp = 'W' if next(iter(a)) == 'B' else 'B'
                        if opp not in d:
                            return False
                        if grid[i+2][c] != {opp}:
                            grid[i+2][c] = {opp}
                            changed = True
                    if len(b) ==1 and len(d) ==1 and b == d:
                        opp = 'W' if next(iter(b)) == 'B' else 'B'
                        if opp not in a:
                            return False
                        if grid[i][c] != {opp}:
                            grid[i][c] = {opp}
                            changed = True
            # Apply count limit rule for rows
            for r in range(n):
                b_count = sum(1 for c in range(m) if grid[r][c] == {'B'})
                w_count = sum(1 for c in range(m) if grid[r][c] == {'W'})
                if b_count == required_per_row:
                    for c in range(m):
                        if len(grid[r][c]) > 1:
                            if 'W' not in grid[r][c]:
                                return False
                            if grid[r][c] != {'W'}:
                                grid[r][c] = {'W'}
                                changed = True
                if w_count == required_per_row:
                    for c in range(m):
                        if len(grid[r][c]) > 1:
                            if 'B' not in grid[r][c]:
                                return False
                            if grid[r][c] != {'B'}:
                                grid[r][c] = {'B'}
                                changed = True
            # Apply count limit rule for columns
            for c in range(m):
                b_count = sum(1 for r in range(n) if grid[r][c] == {'B'})
                w_count = sum(1 for r in range(n) if grid[r][c] == {'W'})
                if b_count == required_per_row:
                    for r in range(n):
                        if len(grid[r][c]) > 1:
                            if 'W' not in grid[r][c]:
                                return False
                            if grid[r][c] != {'W'}:
                                grid[r][c] = {'W'}
                                changed = True
                if w_count == required_per_row:
                    for r in range(n):
                        if len(grid[r][c]) > 1:
                            if 'B' not in grid[r][c]:
                                return False
                            if grid[r][c] != {'B'}:
                                grid[r][c] = {'B'}
                                changed = True
            # Early validity check
            if not is_valid():
                return False
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    def is_fully_solved():
        # Check all cells are fixed
        for r in range(n):
            for c in range(m):
                if len(grid[r][c]) != 1:
                    return False
        # Verify all rules are satisfied
        for r in range(n):
            row_vals = [next(iter(grid[r][c])) for c in range(m)]
            if row_vals.count('B') != required_per_row:
                return False
            if 'BBB' in ''.join(row_vals) or 'WWW' in ''.join(row_vals):
                return False
        for c in range(m):
            col_vals = [next(iter(grid[r][c])) for r in range(n)]
            if col_vals.count('B') != required_per_row:
                return False
            if 'BBB' in ''.join(col_vals) or 'WWW' in ''.join(col_vals):
                return False
        for (r1,c1), (r2,c2), op in constraints:
            v1 = next(iter(grid[r1][c1]))
            v2 = next(iter(grid[r2][c2]))
            if op == '=' and v1 != v2:
                return False
            if op == 'x' and v1 == v2:
                return False
        return True

    if is_fully_solved():
        return [[next(iter(cell)) for cell in row] for row in grid]

    # Backtracking with MRV heuristic
    def backtrack():
        # Find most constrained cell (smallest possible value count)
        min_len = 3
        best_cell = None
        for r in range(n):
            for c in range(m):
                l = len(grid[r][c])
                if 1 < l < min_len:
                    min_len = l
                    best_cell = (r,c)
                    if min_len == 2:
                        break
            if min_len == 2:
                break
        if best_cell is None:
            return is_fully_solved()
        r,c = best_cell
        # Try each possible value
        for val in list(grid[r][c]):
            # Save current state
            backup = [[set(cell) for cell in row] for row in grid]
            grid[r][c] = {val}
            if propagate() and backtrack():
                return True
            # Restore state
            for i in range(n):
                for j in range(m):
                    grid[i][j] = backup[i][j]
        return False

    if backtrack():
        return [[next(iter(cell)) for cell in row] for row in grid]
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
