            col = [grid[i][j] for i in range(N)]
            if len(set(col)) != N:
                return False
            uc = observation['U'][j]
            if uc !=0 and count_visible(col) != uc:
                return False
            dc = observation['D'][j]
            if dc !=0 and count_visible(reversed(col)) != dc:
                return False
        return True

    def select_cell():
        # Minimum Remaining Value heuristic
        min_opts = N + 1
        best = None
        for i in range(N):
            for j in range(N):
                if grid[i][j] is None:
                    used = set(grid[i]) | set(grid[x][j] for x in range(N))
                    opts = [v for v in range(1, N+1) if v not in used]
                    if len(opts) < min_opts:
                        min_opts = len(opts)
                        best = (i,j)
                        if min_opts == 1:
                            return best
        return best

    def backtrack():
        if is_complete():
            return grid if check_final() else None
        r,c = select_cell()
        used = set(grid[r]) | set(grid[x][c] for x in range(N))
        options = [v for v in range(1, N+1) if v not in used]
        for val in options:
            if is_valid_partial(grid, observation, r, c, val):
                grid[r][c] = val
                res = backtrack()
                if res is not None:
                    return res
                grid[r][c] = None
        return None

    result = backtrack()
    return result if result is not None else "No Solution"

