                break
            count += 1
            visible.append((nr, nc))
            nr += dr
            nc += dc
    return count, visible

def get_max_possible_visible(grid, r, c):
    n = len(grid)
    count = 1
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        while 0 <= nr < n and 0 <= nc < n:
            if grid[nr][nc] == 'B':
                break
            count +=1
            nr += dr
            nc += dc
    return count

def has_adjacent_black(grid, r, c):
    n = len(grid)
    for dr, dc in DIRS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 'B':
            return True
    return False

def propagate_constraints(grid, clues):
