            if has_adjacent_black(grid, r,c):
                continue
            if isinstance(grid[r][c], int):
                continue
        new_grid = deepcopy(grid)
        new_grid[r][c] = val
        res = backtrack(new_grid, clues)
        if res is not None:
            return res
    return None

