class RollbackDSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0]*size
        self.stack = []

    def find(self, x):
        # No path compression for rollback compatibility
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False # No union performed
        # Union by rank
        if self.rank[x_root] < self.rank[y_root]:
            x_root, y_root = y_root, x_root
        # Push old state to stack
        self.stack.append(('union', y_root, self.parent[y_root], x_root, self.rank[x_root]))
        self.parent[y_root] = x_root
        if self.rank[x_root] == self.rank[y_root]:
            self.rank[x_root] += 1
        return True

    def rollback(self, checkpoint):
        while len(self.stack) > checkpoint:
            op, *args = self.stack.pop()
            if op == 'union':
                y_root, old_parent_y, x_root, old_rank_x = args
                self.parent[y_root] = old_parent_y
                self.rank[x_root] = old_rank_x

def solve(observation):
