    for dr in range(DOT_SIZE):
        for dc in range(DOT_SIZE):
            max_cnt[dr][dc] = data[dr][dc] if data[dr][dc] is not None else INF

    # Initialize cell grid, count matrix
    grid = [[None]*N for _ in range(N)]
    cnt = [[0]*DOT_SIZE for _ in range(DOT_SIZE)]

    # Initialize DSU
    dsu = RollbackDSU(DOT_SIZE * DOT_SIZE)
    def dot_id(dr, dc):
