            adjacent = []
            # Cell (dr-1, dc-1) -> '\' affects (dr,dc)
            if dr > 0 and dc > 0:
                cr, cc = dr-1, dc-1
                if grid[cr][cc] is None:
                    adjacent.append((cr, cc, '\\', True)) # True means this value contributes to cnt
                elif grid[cr][cc] == '\\':
                    pass # already counted
            # Cell (dr-1, dc) -> '/' affects (dr,dc)
            if dr > 0 and dc < N:
                cr, cc = dr-1, dc
                if grid[cr][cc] is None:
                    adjacent.append((cr, cc, '/', True))
                elif grid[cr][cc] == '/':
                    pass
            # Cell (dr, dc-1) -> '/' affects (dr,dc)
            if dr < N and dc > 0:
                cr, cc = dr, dc-1
                if grid[cr][cc] is None:
                    adjacent.append((cr, cc, '/', True))
                elif grid[cr][cc] == '/':
                    pass
            # Cell (dr, dc) -> '\' affects (dr,dc)
            if dr < N and dc < N:
                cr, cc = dr, dc
                if grid[cr][cc] is None:
                    adjacent.append((cr, cc, '\\', True))
                elif grid[cr][cc] == '\\':
                    pass

            # Count how many possible contributors left
            possible_contrib = len(adjacent)
            remaining_needed = allowed - current

            if remaining_needed < 0:
                return False

            # Case 1: no more needed, all possible contributors must be set to non-contributing value
            if remaining_needed == 0:
                for (cr, cc, v_contrib, _) in adjacent:
                    # Set to opposite value
                    v_other = '/' if v_contrib == '\\' else '\\'
                    (d1, d2) = get_connected(cr, cc, v_other)
                    # Check if setting this would exceed max counts
                    if cnt[d1[0]][d1[1]] + 1 > max_cnt[d1[0]][d1[1]] or cnt[d2[0]][d2[1]] +1 > max_cnt[d2[0]][d2[1]]:
                        return False
                    # Check loop
                    id1 = dot_id(*d1)
                    id2 = dot_id(*d2)
                    if dsu.find(id1) == dsu.find(id2):
                        return False
                    # Set the cell
                    grid[cr][cc] = v_other
                    # Update counts
                    cnt[d1[0]][d1[1]] += 1
                    cnt[d2[0]][d2[1]] += 1
                    # Union
                    dsu.union(id1, id2)
                    # Add dots to queue
                    for d in [d1, d2]:
                        if not in_queue[d[0]][d[1]]:
                            q.append(d)
                            in_queue[d[0]][d[1]] = True

            # Case 2: exactly as many possible contributors as needed, all must be set to contributing value
            elif remaining_needed == possible_contrib:
                for (cr, cc, v_contrib, _) in adjacent:
                    (d1, d2) = get_connected(cr, cc, v_contrib)
                    # Check counts
                    if cnt[d1[0]][d1[1]] +1 > max_cnt[d1[0]][d1[1]] or cnt[d2[0]][d2[1]] +1 > max_cnt[d2[0]][d2[1]]:
                        return False
                    # Check loop
                    id1 = dot_id(*d1)
                    id2 = dot_id(*d2)
                    if dsu.find(id1) == dsu.find(id2):
                        return False
                    # Set cell
                    grid[cr][cc] = v_contrib
                    # Update counts
                    cnt[d1[0]][d1[1]] += 1
                    cnt[d2[0]][d2[1]] += 1
                    # Union
                    dsu.union(id1, id2)
                    # Add dots to queue
                    for d in [d1, d2]:
                        if not in_queue[d[0]][d[1]]:
                            q.append(d)
                            in_queue[d[0]][d[1]] = True
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Check if already solved
    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return False
        return True

    if is_solved():
        return [row[:] for row in grid]

    # Backtracking with MRV heuristic
    def backtrack():
        if is_solved():
            return [row[:] for row in grid]

        # Select cell with minimum remaining options (MRV)
        min_options = 3
        best_cell = None
        valid_options = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is not None:
                    continue
                options = []
                for v in ['/', '\\']:
                    d1, d2 = get_connected(r,c,v)
                    # Check count limits
                    if cnt[d1[0]][d1[1]] +1 > max_cnt[d1[0]][d1[1]] or cnt[d2[0]][d2[1]] +1 > max_cnt[d2[0]][d2[1]]:
                        continue
                    # Check loop
                    id1 = dot_id(*d1)
                    id2 = dot_id(*d2)
                    if dsu.find(id1) == dsu.find(id2):
                        continue
                    options.append(v)
                if not options:
                    return None
                if len(options) < min_options:
                    min_options = len(options)
                    best_cell = (r,c)
                    valid_options = options
                    if min_options == 1:
                        break
            if min_options == 1:
                break

        r, c = best_cell
        for v in valid_options:
            # Save state
            checkpoint = len(dsu.stack)
            old_val = grid[r][c]
            d1, d2 = get_connected(r,c,v)
            old_cnt1 = cnt[d1[0]][d1[1]]
            old_cnt2 = cnt[d2[0]][d2[1]]

            # Apply move
            grid[r][c] = v
            cnt[d1[0]][d1[1]] += 1
            cnt[d2[0]][d2[1]] += 1
            dsu.union(dot_id(*d1), dot_id(*d2))

            # Propagate
            if propagate():
                res = backtrack()
                if res is not None:
                    return res

            # Rollback
            dsu.rollback(checkpoint)
            grid[r][c] = old_val
            cnt[d1[0]][d1[1]] = old_cnt1
            cnt[d2[0]][d2[1]] = old_cnt2

        return None

    solution = backtrack()
    return solution if solution is not None else "No Solution"

