def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(region)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Preprocess region info
    region_cells = {}
    region_clue = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
                region_clue[rid] = data[r][c]
            region_cells[rid].append((r,c))

    def get_adjacent(r,c):
        res = []
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                res.append((nr, nc))
        return res

    def count_black(rid, grid):
        return sum(1 for (r,c) in region_cells[rid] if grid[r][c] == 'B')

    def count_white(rid, grid):
        return sum(1 for (r,c) in region_cells[rid] if grid[r][c] is None)

    def check_rule2(grid):
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B':
                    for nr, nc in get_adjacent(r,c):
                        if grid[nr][nc] == 'B':
                            return False
        return True

    def check_rule1(grid):
        for rid in region_clue:
            clue = region_clue[rid]
            if clue is None:
                continue
            bc = count_black(rid, grid)
            wc = count_white(rid, grid)
            if bc > clue:
                return False
            if bc + wc < clue:
                return False
        return True

    def check_rule3(grid):
        # Check rows
        for r in range(N):
            seg_regions = set()
            for c in range(N):
                if grid[r][c] == 'B':
                    if len(seg_regions) > 2:
                        return False
                    seg_regions = set()
                else:
                    seg_regions.add(region[r][c])
            if len(seg_regions) > 2:
                return False
        # Check columns
        for c in range(N):
            seg_regions = set()
            for r in range(N):
                if grid[r][c] == 'B':
                    if len(seg_regions) > 2:
                        return False
                    seg_regions = set()
                else:
                    seg_regions.add(region[r][c])
            if len(seg_regions) > 2:
                return False
        return True

    def check_white_connectivity(grid):
        whites = [(r,c) for r in range(N) for c in range(N) if grid[r][c] is None]
        if not whites:
            return True
        visited = set()
        q = [whites[0]]
        visited.add(whites[0])
        while q:
            r,c = q.pop(0)
            for nr, nc in get_adjacent(r,c):
                if grid[nr][nc] is None and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(whites)

    def is_valid(grid):
        if not check_rule2(grid):
            return False
        if not check_rule1(grid):
            return False
        if not check_rule3(grid):
            return False
        if not check_white_connectivity(grid):
            return False
        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Rule 2: black adjacent cells must be white
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'B':
                        for nr, nc in get_adjacent(r,c):
                            if grid[nr][nc] is None:
                                grid[nr][nc] = None  # mark white
                                changed = True
            # Rule 1: region constraints
            for rid in region_clue:
                clue = region_clue[rid]
                if clue is None:
                    continue
                bc = count_black(rid, grid)
                wc = count_white(rid, grid)
                if bc == clue:
                    # All remaining must be white
                    for (r,c) in region_cells[rid]:
                        if grid[r][c] is None:
                            grid[r][c] = None
                            changed = True
                elif bc + wc == clue:
                    # All remaining must be black
                    for (r,c) in region_cells[rid]:
                        if grid[r][c] is None:
                            grid[r][c] = 'B'
                            changed = True
                            # Mark adjacent as white
                            for nr, nc in get_adjacent(r,c):
                                if grid[nr][nc] is None:
                                    grid[nr][nc] = None
                                    changed = True
            # Check validity during propagation
            if not is_valid(grid):
                return False
        return is_valid(grid)

    def backtrack(grid):
        # Propagate first
        if not propagate(grid):
            return None
        # Check if complete
        complete = True
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and region_clue[region[r][c]] is not None:
                    complete = False
                    break
            if not complete:
                break
        if complete:
            if is_valid(grid):
                return grid
            return None
        # Find MRV cell
        min_options = 3
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    options = 0
                    # Try black
                    temp = [row[:] for row in grid]
                    temp[r][c] = 'B'
                    if propagate(temp):
                        options +=1
                    # Try white
                    temp = [row[:] for row in grid]
                    temp[r][c] = None
                    if propagate(temp):
                        options +=1
                    if options < min_options:
                        min_options = options
                        best_cell = (r,c)
                        if min_options == 0:
                            return None
        if best_cell is None:
            return None
        r,c = best_cell
        # Try black first
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = 'B'
        res = backtrack(new_grid)
        if res is not None:
            return res
        # Try white
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = None
        res = backtrack(new_grid)
        if res is not None:
            return res
        return None

    # Initialize grid
    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    # Initial deductions for 0 clues
    for rid in region_clue:
        if region_clue[rid] == 0:
            for (r,c) in region_cells[rid]:
                initial_grid[r][c] = None
    result = backtrack(initial_grid)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
