def get_possible(r, c, grid, regions, N):
    used = set()
    # Check row
    for col in range(N):
        if grid[r][col] is not None:
            used.add(grid[r][col])
    # Check column
    for row in range(N):
        if grid[row][c] is not None:
            used.add(grid[row][c])
    # Check region
    reg_id = regions[r][c]
    for row in range(N):
        for col in range(N):
            if regions[row][col] == reg_id and grid[row][col] is not None:
                used.add(grid[row][col])
    return [v for v in range(1, N+1) if v not in used]

def backtrack(grid, regions, N):
    while True:
        changed = False
        possible_values = {}
        min_possible = N + 1
        min_cell = None

        # Step 1: Find naked singles (cells with only 1 possible value)
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    pv = get_possible(r, c, grid, regions, N)
                    if not pv:
                        return None  # Invalid state
                    possible_values[(r, c)] = pv
                    if len(pv) == 1:
                        grid[r][c] = pv[0]
                        changed = True
                    if len(pv) < min_possible:
                        min_possible = len(pv)
                        min_cell = (r, c)
        if changed:
            continue  # Recheck after assignment

        # Step 2: Find hidden singles in rows
        for r in range(N):
            val_counts = {v: [] for v in range(1, N+1)}
            for c in range(N):
                if grid[r][c] is None:
                    for v in possible_values[(r, c)]:
                        val_counts[v].append(c)
            for v, positions in val_counts.items():
                if len(positions) == 1 and grid[r][positions[0]] is None:
                    grid[r][positions[0]] = v
                    changed = True
        if changed:
            continue

        # Step3: Find hidden singles in columns
        for c in range(N):
            val_counts = {v: [] for v in range(1, N+1)}
            for r in range(N):
                if grid[r][c] is None:
                    for v in possible_values[(r, c)]:
                        val_counts[v].append(r)
            for v, positions in val_counts.items():
                if len(positions) == 1 and grid[positions[0]][c] is None:
                    grid[positions[0]][c] = v
                    changed = True
        if changed:
            continue

        # Step4: Find hidden singles in regions
        reg_ids = set(id for row in regions for id in row)
        for reg_id in reg_ids:
            val_counts = {v: [] for v in range(1, N+1)}
            reg_cells = [(r,c) for r in range(N) for c in range(N) if regions[r][c] == reg_id]
            for (r,c) in reg_cells:
                if grid[r][c] is None:
                    for v in possible_values[(r,c)]:
                        val_counts[v].append((r,c))
            for v, positions in val_counts.items():
                if len(positions) == 1:
                    r,c = positions[0]
                    if grid[r][c] is None:
                        grid[r][c] = v
                        changed = True
        if not changed:
            break

    # Check if solved
    all_filled = all(cell is not None for row in grid for cell in row)
    if all_filled:
        return grid

    # MRV heuristic: try cell with minimum possible values
    r,c = min_cell
    for val in possible_values[(r,c)]:
        new_grid = [row.copy() for row in grid]
        new_grid[r][c] = val
        res = backtrack(new_grid, regions, N)
        if res is not None:
            return res
    return None

def solve(observation):
    regions = observation['region']
    initial_grid = [row.copy() for row in observation['data']]
    N = len(initial_grid)
    result = backtrack(initial_grid, regions, N)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
