    col_w = sum(1 for i in range(N) if grid[i][c] == 'W')
    if val == 'B' and col_b + 1 > target:
        return False
    if val == 'W' and col_w + 1 > target:
        return False
    # Check horizontal constraints
    if c > 0:
        key = f"({r}, {c - 0.5})"
        if key in horizontal:
            neighbor = grid[r][c-1]
            if neighbor is not None:
                if horizontal[key] == '=' and val != neighbor:
                    return False
                if horizontal[key] == 'x' and val == neighbor:
                    return False
    if c < N -1:
