                        if not is_valid(grid, r, c, 'W', target, horizontal, vertical, N):
                            return False
                        grid[r][c] = 'W'
                        changed = True
            if w_cnt == target:
                for c in range(N):
                    if grid[r][c] is None:
                        if not is_valid(grid, r, c, 'B', target, horizontal, vertical, N):
                            return False
                        grid[r][c] = 'B'
                        changed = True
        # Fill columns with full count of one color
        for c in range(N):
            b_cnt = sum(1 for r in range(N) if grid[r][c] == 'B')
            w_cnt = sum(1 for r in range(N) if grid[r][c] == 'W')
            if b_cnt == target:
                for r in range(N):
                    if grid[r][c] is None:
                        if not is_valid(grid, r, c, 'W', target, horizontal, vertical, N):
                            return False
                        grid[r][c] = 'W'
                        changed = True
            if w_cnt == target:
                for r in range(N):
                    if grid[r][c] is None:
                        if not is_valid(grid, r, c, 'B', target, horizontal, vertical, N):
                            return False
                        grid[r][c] = 'B'
                        changed = True
        if not changed:
            break
    return True

def is_complete(grid, N):
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                return False
    return True

def select_mrv_cell(grid, target, horizontal, vertical, N):
    min_options = 3
    best_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                continue
            cnt = 0
            for v in ['B', 'W']:
                if is_valid(grid, r, c, v, target, horizontal, vertical, N):
                    cnt +=1
            if cnt < min_options:
                min_options = cnt
                best_cell = (r,c)
                if min_options == 1:
                    return best_cell
    return best_cell

def backtrack(grid, target, horizontal, vertical, N):
    if not propagate(grid, target, horizontal, vertical, N):
        return None
    if is_complete(grid, N):
        return grid
    r,c = select_mrv_cell(grid, target, horizontal, vertical, N)
    for val in ['B', 'W']:
        if is_valid(grid, r, c, val, target, horizontal, vertical, N):
            new_grid = copy.deepcopy(grid)
            new_grid[r][c] = val
            res = backtrack(new_grid, target, horizontal, vertical, N)
            if res is not None:
                return res
    return None

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']
    N = len(data)
    target = N // 2
    grid = copy.deepcopy(data)
    solution = backtrack(grid, target, horizontal, vertical, N)
    if not solution:
        return "No Solution"
    return '\n'.join(''.join(row) for row in solution)

if __name__ == "__main__":
    print(solve(OBSERVATION))
