                for j in range(N):
                    if len(dom[i][j]) == 1:
                        val = next(iter(dom[i][j]))
                        if val in fixed_vals:
                            return False
                        fixed_vals.add(val)

                # Remove fixed values from other cells in row
                for j in range(N):
                    if len(dom[i][j]) > 1:
                        new_dom = dom[i][j] - fixed_vals
                        if not new_dom:
                            return False
                        if new_dom != dom[i][j]:
                            dom[i][j] = new_dom
                            changed = True

                # Find hidden singles in row
