                        val = next(iter(dom[i][j]))
                        if val in fixed_vals:
                            return False
                        fixed_vals.add(val)

                # Remove fixed values from other cells in column
                for i in range(N):
                    if len(dom[i][j]) > 1:
                        new_dom = dom[i][j] - fixed_vals
                        if not new_dom:
                            return False
                        if new_dom != dom[i][j]:
                            dom[i][j] = new_dom
                            changed = True

                # Find hidden singles in column
                for val in range(1, N+1):
                    if val in fixed_vals:
                        continue
                    candidates = []
                    for i in range(N):
                        if val in dom[i][j]:
                            candidates.append(i)
                    if len(candidates) == 0:
                        return False
                    if len(candidates) == 1:
                        i = candidates[0]
                        if dom[i][j] != {val}:
                            dom[i][j] = {val}
                            changed = True

            # Process horizontal inequalities
            for key, sym in observation['horizontal'].items():
                r, c = map(float, key.strip('()').split(', '))
                i = int(r)
                j_left = int(c - 0.5)
                j_right = j_left + 1
                d_left = dom[i][j_left]
                d_right = dom[i][j_right]

                if sym == '>':
                    new_left = {a for a in d_left if any(b < a for b in d_right)}
                    new_right = {b for b in d_right if any(a > b for a in d_left)}
                else: # '<'
                    new_left = {a for a in d_left if any(b > a for b in d_right)}
                    new_right = {b for b in d_right if any(a < b for a in d_left)}

                if not new_left or not new_right:
                    return False
                if new_left != d_left:
                    dom[i][j_left] = new_left
                    changed = True
                if new_right != d_right:
                    dom[i][j_right] = new_right
                    changed = True

            # Process vertical inequalities
            for key, sym in observation['vertical'].items():
                r, c = map(float, key.strip('()').split(', '))
                j = int(c)
                i_upper = int(r - 0.5)
                i_lower = i_upper + 1
                d_upper = dom[i_upper][j]
                d_lower = dom[i_lower][j]

                if sym == 'v':
                    new_upper = {a for a in d_upper if any(b < a for b in d_lower)}
                    new_lower = {b for b in d_lower if any(a > b for a in d_upper)}
                else: # '^'
                    new_upper = {a for a in d_upper if any(b > a for b in d_lower)}
                    new_lower = {b for b in d_lower if any(a < b for a in d_upper)}

                if not new_upper or not new_lower:
                    return False
                if new_upper != d_upper:
                    dom[i_upper][j] = new_upper
                    changed = True
                if new_lower != d_lower:
