    # Initial constraint propagation
    if not propagate(domains):
        return "No Solution"

    # Check if already solved
    def is_complete(dom):
        for i in range(N):
            for j in range(N):
                if len(dom[i][j]) != 1:
                    return False
        return True

    if is_complete(domains):
        return [[next(iter(domains[i][j])) for j in range(N)] for i in range(N)]

    # Backtracking search with MRV heuristic
    def backtrack(dom):
        # Find cell with smallest domain (MRV)
        min_len = N + 1
        target = None
        for i in range(N):
            for j in range(N):
                l = len(dom[i][j])
                if 1 < l < min_len:
                    min_len = l
                    target = (i, j)
                    if min_len == 2:
                        break
            if target and min_len == 2:
                break

        if not target:
            return [[next(iter(dom[i][j])) for j in range(N)] for i in range(N)]

        i, j = target
        # Try each possible value
        for val in sorted(dom[i][j]):
            # Create copy of domains
            new_dom = []
            for r in range(N):
                new_row = []
                for c in range(N):
                    new_row.append(set(dom[r][c]))
                new_dom.append(new_row)
            new_dom[i][j] = {val}

            if propagate(new_dom):
                res = backtrack(new_dom)
                if res is not None:
                    return res
        return None

    solution = backtrack(domains)
    return solution if solution is not None else "No Solution"

