def get_adjacent(r, c, N):
    adj = []
    if r > 0: adj.append((r-1, c))
    if r < N-1: adj.append((r+1, c))
    if c > 0: adj.append((r, c-1))
    if c < N-1: adj.append((r, c+1))
    return adj

def propagate(grid, region_info, N, region_grid):
    changed = True
