def is_valid_solution(grid, region_info, N, region_grid):
    # Check rule1: region counts
    for rid in region_info:
        cells, req = region_info[rid]
        cnt = sum(1 for r,c in cells if grid[r][c] == 1)
        if cnt != req:
            return False
    # Check rule2: no adjacent B
    for r in range(N):
        for c in range(N):
            if grid[r][c] ==1:
                for nr, nc in get_adjacent(r,c,N):
                    if grid[nr][nc] == 1:
                        return False
    # Check rule3: segments <= 2 regions
    for r in range(N):
        seg = []
        for c in range(N):
            if grid[r][c] == 1:
                if seg:
                    regs = set(region_grid[r][sc] for sc in seg)
                    if len(regs) > 2:
                        return False
                    seg = []
            else:
                seg.append(c)
        if seg:
            regs = set(region_grid[r][sc] for sc in seg)
            if len(regs) > 2:
                return False
    for c in range(N):
        seg = []
        for r in range(N):
            if grid[r][c] == 1:
                if seg:
                    regs = set(region_grid[sr][c] for sr in seg)
                    if len(regs) > 2:
                        return False
                    seg = []
            else:
                seg.append(r)
        if seg:
            regs = set(region_grid[sr][c] for sr in seg)
            if len(regs) > 2:
                return False
    # Check rule4: white connected
    w_cells = [(r,c) for r in range(N) for c in range(N) if grid[r][c] == 2]
    if not w_cells:
        return False
    visited = set()
    q = [w_cells[0]]
    visited.add(w_cells[0])
    while q:
        r,c = q.pop(0)
        for nr, nc in get_adjacent(r,c,N):
            if grid[nr][nc] == 2 and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(w_cells)

def backtrack(grid, region_info, N, region_grid):
    valid, grid = propagate([row[:] for row in grid], region_info, N, region_grid)
    if not valid:
        return None
    all_decided = all(all(cell != 0 for cell in row) for row in grid)
    if all_decided:
        if is_valid_solution(grid, region_info, N, region_grid):
            return grid
        return None
    # MRV heuristic: pick cell with least options
    best_cell = None
    min_options = float('inf')
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 0:
                can_be_b = True
                for nr, nc in get_adjacent(r,c,N):
                    if grid[nr][nc] == 1:
                        can_be_b = False
                        break
                options = (1 if can_be_b else 0) + 1
                if options < min_options:
                    min_options = options
                    best_cell = (r,c)
                    if min_options == 1:
                        break
        if min_options == 1:
            break
    r,c = best_cell
    # Try B first
    can_be_b = True
    for nr, nc in get_adjacent(r,c,N):
        if grid[nr][nc] == 1:
            can_be_b = False
            break
    if can_be_b:
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = 1
        res = backtrack(new_grid, region_info, N, region_grid)
        if res is not None:
            return res
    # Try W
    new_grid = [row[:] for row in grid]
    new_grid[r][c] = 2
    res = backtrack(new_grid, region_info, N, region_grid)
    return res

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)
    # Precompute region info
    reg_cells = {}
    reg_req = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            if rid not in reg_cells:
                reg_cells[rid] = []
            reg_cells[rid].append((r,c))
            if data_grid[r][c] is not None:
                reg_req[rid] = data_grid[r][c]
    region_info = {rid: (reg_cells[rid], reg_req[rid]) for rid in reg_cells}
    # Initialize grid: 0=undecided, 1=B, 2=W
    grid = [[0]*N for _ in range(N)]
    valid, grid = propagate(grid, region_info, N, region_grid)
    if not valid:
        return "No Solution"
    solution = backtrack(grid, region_info, N, region_grid)
    if solution is None:
        return "No Solution"
    # Convert to output format
    output = []
    for row in solution:
        out_row = []
        for cell in row:
            out_row.append('B' if cell == 1 else None)
        output.append(out_row)
    return output

