                                        if 0<=nnr<n and 0<=nnc<n:
                                            if state[nnr][nnc] ==1: return (False, state)
                                            if state[nnr][nnc] ==0:
                                                state[nnr][nnc] = 2
                                                changed = True
        # Process columns
        for c in range(n):
