                    else: undecided.append(r)
                if len(whites) >1: return (False, state)
                if len(whites) == 1:
                    for r in undecided:
                        state[r][c] = 1
                        changed = True
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<n and 0<=nc<n:
                                if state[nr][nc] == 1: return (False, state)
                                if state[nr][nc] == 0:
                                    state[nr][nc] = 2
                                    changed = True
                needed = (len(rows)-1) - len(blacks)
                if needed < 0: return (False, state)
                if needed == len(undecided):
                    for r in undecided:
                        state[r][c] = 1
                        changed = True
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<n and 0<=nc<n:
                                if state[nr][nc] == 1: return (False, state)
                                if state[nr][nc] == 0:
                                    state[nr][nc] =2
                                    changed = True
                if needed == 0:
                    for r in undecided:
                        state[r][c] = 2
                        changed = True
                        v_curr = grid[r][c]
                        for nc in range(n):
                            if nc == c: continue
                            if grid[r][nc] == v_curr:
                                if state[r][nc] == 2: return (False, state)
                                if state[r][nc] == 0:
                                    state[r][nc] = 1
                                    changed = True
                                    for dr2, dc2 in dirs:
                                        nnr, nnc = r+dr2, nc+dc2
                                        if 0<=nnr<n and 0<=nnc<n:
                                            if state[nnr][nnc] ==1: return (False, state)
                                            if state[nnr][nnc] ==0:
                                                state[nnr][nnc] =2
                                                changed = True
    # Final check for adjacent blacks
    for r in range(n):
        for c in range(n):
            if state[r][c] == 1:
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<n and 0<=nc<n and state[nr][nc] ==1:
                        return (False, state)
    return (True, state)

def is_connected(state, n):
    start = None
    white_count = 0
    for r in range(n):
        for c in range(n):
            if state[r][c] == 2:
                if start is None: start = (r,c)
                white_count +=1
    if white_count == 0: return False
    visited = set([start])
    q = [start]
    while q:
        r,c = q.pop(0)
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0<=nr<n and 0<=nc<n and state[nr][nc]==2 and (nr,nc) not in visited:
                visited.add((nr,nc))
                q.append((nr,nc))
    return len(visited) == white_count

def backtrack(state, grid, n):
    valid, new_state = propagate([row[:] for row in state], grid, n)
    if not valid: return None
    all_decided = True
    undecided = []
    for r in range(n):
        for c in range(n):
            if new_state[r][c] == 0:
                all_decided = False
                undecided.append((r,c))
    if all_decided:
        return new_state if is_connected(new_state, n) else None
    # Pick most constrained cell
    best = None
    min_opt = float('inf')
    for (r,c) in undecided:
        opt = 0
        # Check can be black
        can_black = True
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0<=nr<n and 0<=nc<n and new_state[nr][nc] == 1:
                can_black = False
                break
        if can_black: opt +=1
        # Check can be white
        can_white = True
        v = grid[r][c]
        for cc in range(n):
            if new_state[r][cc] == 2 and grid[r][cc] == v:
                can_white = False
                break
        if can_white:
            for rr in range(n):
                if new_state[rr][c] == 2 and grid[rr][c] ==v:
                    can_white = False
                    break
        if can_white: opt +=1
        if opt ==0: return None
        if opt < min_opt:
            min_opt = opt
            best = (r,c)
            if min_opt ==1: break
    r,c = best
    # Try black first
    s1 = [row[:] for row in new_state]
    s1[r][c] = 1
    res = backtrack(s1, grid, n)
    if res: return res
    # Try white
    s2 = [row[:] for row in new_state]
    s2[r][c] = 2
    res = backtrack(s2, grid, n)
    return res

def solve(observation):
    grid = observation['data']
    n = len(grid)
    initial = [[0]*n for _ in range(n)]
    sol = backtrack(initial, grid, n)
    if not sol: return "No Solution"
    out = []
    for r in sol:
        out_row = []
        for cell in r:
            out_row.append('B' if cell == 1 else None)
        out.append(out_row)
    return out

if __name__ == "__main__":
    print(solve(OBSERVATION))
