from collections import defaultdict

def eliminate(possible, r, c, val, N, region, region_cells):
    if val not in possible[r][c]:
        return True
    possible[r][c].remove(val)
    if len(possible[r][c]) == 0:
        return False
    if len(possible[r][c]) == 1:
        remaining = next(iter(possible[r][c]))
        for cc in range(N):
            if cc != c and not eliminate(possible, r, cc, remaining, N, region, region_cells):
                return False
        for rr in range(N):
            if rr != r and not eliminate(possible, rr, c, remaining, N, region, region_cells):
                return False
        for (rr, cc) in region_cells[region[r][c]]:
            if (rr, cc) != (r, c) and not eliminate(possible, rr, cc, remaining, N, region, region_cells):
                return False
    # Check hidden single in row
    positions = []
    for cc in range(N):
        if val in possible[r][cc]:
            positions.append((r, cc))
    if len(positions) == 0:
        return False
    if len(positions) == 1 and not assign(possible, positions[0][0], positions[0][1], val, N, region, region_cells):
        return False
    # Check hidden single in column
    positions = []
    for rr in range(N):
        if val in possible[rr][c]:
            positions.append((rr, c))
    if len(positions) == 0:
        return False
    if len(positions) == 1 and not assign(possible, positions[0][0], positions[0][1], val, N, region, region_cells):
        return False
    # Check hidden single in region
    positions = []
    for (rr, cc) in region_cells[region[r][c]]:
        if val in possible[rr][cc]:
            positions.append((rr, cc))
    if len(positions) == 0:
        return False
    if len(positions) == 1 and not assign(possible, positions[0][0], positions[0][1], val, N, region, region_cells):
        return False
    return True

def assign(possible, r, c, val, N, region, region_cells):
    for v in list(possible[r][c]):
        if v != val and not eliminate(possible, r, c, v, N, region, region_cells):
            return False
    return True

def backtrack(possible, N, region, region_cells):
    min_len = float('inf')
    min_cell = None
    solved = True
    for r in range(N):
        for c in range(N):
            l = len(possible[r][c])
            if l > 1:
                solved = False
                if l < min_len:
                    min_len = l
                    min_cell = (r, c)
    if solved:
        grid = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                grid[r][c] = next(iter(possible[r][c]))
        return grid
    r, c = min_cell
    for val in sorted(possible[r][c]):
        possible_copy = [[set(s) for s in row] for row in possible]
        if assign(possible_copy, r, c, val, N, region, region_cells):
            res = backtrack(possible_copy, N, region, region_cells)
            if res is not None:
                return res
    return None

def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[region[r][c]].append((r, c))
    possible = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                if not assign(possible, r, c, val, N, region, region_cells):
                    return "No Solution"
    result = backtrack(possible, N, region, region_cells)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
