        [None, 1, None, 1, 0, None, None, None, 1, None, None]
    ]
}

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1]*size
        self.stack = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            x_root, y_root = y_root, x_root
        self.stack.append((y_root, x_root, self.rank[x_root]))
        self.parent[y_root] = x_root
        if self.rank[x_root] == self.rank[y_root]:
            self.rank[x_root] += 1
        return True

    def rollback(self, checkpoint):
        while len(self.stack) > checkpoint:
            y_root, x_root, old_rank = self.stack.pop()
            self.parent[y_root] = y_root
            self.rank[x_root] = old_rank

def propagate(grid, clues, N, dot_adj):
    q = deque()
    in_queue = set()
    for r in range(N+1):
        for c in range(N+1):
            if clues[r][c] is not None:
                q.append((r,c))
                in_queue.add((r,c))
    while q:
        r,c = q.popleft()
        in_queue.remove((r,c))
        required = clues[r][c]
        if required is None:
            continue
        current = 0
        unset = []
        for (i,j, val) in dot_adj[r][c]:
            if grid[i][j] == val:
                current += 1
            elif grid[i][j] is None:
                unset.append((i,j, val))
        remaining = required - current
        if remaining < 0:
            return False
        if remaining > len(unset):
            return False
        if remaining == 0:
            for (i,j, val) in unset:
                opposite = '/' if val == '\\' else '\\'
                if grid[i][j] is None:
                    grid[i][j] = opposite
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        nr = i + dr
                        nc = j + dc
                        if (nr, nc) not in in_queue:
                            q.append((nr, nc))
                            in_queue.add((nr, nc))
                elif grid[i][j] == val:
                    return False
        elif remaining == len(unset):
            for (i,j, val) in unset:
                if grid[i][j] is None:
                    grid[i][j] = val
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        nr = i + dr
                        nc = j + dc
                        if (nr, nc) not in in_queue:
                            q.append((nr, nc))
                            in_queue.add((nr, nc))
                elif grid[i][j] != val:
                    return False
    return True

def select_cell(grid, N, dsu, clues, dot_adj):
    min_options = 3
    best_cell = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] is not None:
                continue
            options = 0
            for val in ['/', '\\']:
                if val == '\\':
                    d1 = (i,j)
                    d2 = (i+1,j+1)
                else:
                    d1 = (i,j+1)
                    d2 = (i+1,j)
                id1 = d1[0]*(N+1) + d1[1]
                id2 = d2[0]*(N+1) + d2[1]
                if dsu.find(id1) == dsu.find(id2):
                    continue
                valid = True
                for (dr, dc) in [(0,0), (0,1), (1,0), (1,1)]:
                    r = i + dr
                    c = j + dc
                    req = clues[r][c]
                    if req is None:
                        continue
                    current = 0
                    for (ci, cj, v) in dot_adj[r][c]:
                        if grid[ci][cj] == v:
                            current += 1
                    adds = 0
                    for (ci, cj, v) in dot_adj[r][c]:
                        if ci == i and cj == j and v == val:
                            adds = 1
                            break
                    if current + adds > req:
                        valid = False
                        break
                if valid:
                    options += 1
            if options == 0:
                return (i,j)
            if options < min_options:
                min_options = options
                best_cell = (i,j)
                if min_options == 1:
                    return best_cell
    return best_cell

def backtrack(grid, dsu, N, clues, dot_adj):
    if not propagate(grid, clues, N, dot_adj):
        return None
    all_filled = True
    for row in grid:
        if None in row:
            all_filled = False
            break
    if all_filled:
        return [row.copy() for row in grid]
    cell = select_cell(grid, N, dsu, clues, dot_adj)
    if cell is None:
        return None
    i,j = cell
    for val in ['/', '\\']:
        if val == '\\':
            d1 = (i,j)
            d2 = (i+1,j+1)
        else:
            d1 = (i,j+1)
            d2 = (i+1,j)
        id1 = d1[0]*(N+1) + d1[1]
        id2 = d2[0]*(N+1) + d2[1]
        if dsu.find(id1) == dsu.find(id2):
            continue
        valid = True
        for (dr, dc) in [(0,0), (0,1), (1,0), (1,1)]:
            r = i + dr
            c = j + dc
            req = clues[r][c]
            if req is None:
                continue
            current = 0
            for (ci, cj, v) in dot_adj[r][c]:
                if grid[ci][cj] == v:
                    current += 1
            adds = 0
            for (ci, cj, v) in dot_adj[r][c]:
                if ci == i and cj == j and v == val:
                    adds = 1
                    break
            if current + adds > req:
                valid = False
                break
        if not valid:
            continue
        grid[i][j] = val
        checkpoint = len(dsu.stack)
        dsu.union(id1, id2)
        res = backtrack(grid, dsu, N, clues, dot_adj)
        if res is not None:
            return res
        dsu.rollback(checkpoint)
        grid[i][j] = None
    return None

def solve(observation):
    clues = observation['data']
    N = len(clues) - 1
    if N <= 0:
        return []
    dot_adj = [[[] for _ in range(N+1)] for _ in range(N+1)]
    for r in range(N+1):
        for c in range(N+1):
            if r > 0 and c > 0:
                dot_adj[r][c].append((r-1, c-1, '\\'))
            if r > 0 and c < N:
                dot_adj[r][c].append((r-1, c, '/'))
            if r < N and c > 0:
                dot_adj[r][c].append((r, c-1, '/'))
            if r < N and c < N:
                dot_adj[r][c].append((r, c, '\\'))
    grid = [[None for _ in range(N)] for _ in range(N)]
    dsu_size = (N+1)*(N+1)
    dsu = DSU(dsu_size)
    solution = backtrack(grid, dsu, N, clues, dot_adj)
    return solution if solution is not None else "No Solution"

