                if cons == 'x' and val1 == val2:
                    return (False, grid)
            elif val1 is not None:
                target = val1 if cons == '=' else ('B' if val1 == 'W' else 'W')
                if grid[r][c2] != target:
                    grid[r][c2] = target
                    changed = True
            elif val2 is not None:
                target = val2 if cons == '=' else ('B' if val2 == 'W' else 'W')
                if grid[r][c1] != target:
                    grid[r][c1] = target
