                target = val2 if cons == '=' else ('B' if val2 == 'W' else 'W')
                if grid[r1][c] != target:
                    grid[r1][c] = target
                    changed = True
        # Process consecutive triplet rule for rows
        for r in range(N):
            row = grid[r]
            for c in range(N - 2):
                a, b, d = row[c], row[c+1], row[c+2]
                if a == b and a is not None:
                    if d == a:
                        return (False, grid)
                    if d is None:
                        target = 'B' if a == 'W' else 'W'
                        if row[c+2] != target:
                            row[c+2] = target
                            changed = True
                if b == d and b is not None:
