    if not valid:
        return None
    if is_full(grid, N):
        return grid
    # MRV heuristic
    min_options = 3
    best = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                possible = []
                for val in ['B', 'W']:
                    temp_grid = copy.deepcopy(grid)
                    temp_grid[r][c] = val
