        if best and min_options == 1:
            break
    r, c, possible = best
    for val in possible:
        new_grid = copy.deepcopy(grid)
        new_grid[r][c] = val
        res = backtrack(new_grid, horizontal, vertical, N, half)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']
    N = len(data)
    half = N // 2
    grid = copy.deepcopy(data)
    solution = backtrack(grid, horizontal, vertical, N, half)
    if solution is None:
        return "No Solution"
    return solution

if __name__ == "__main__":
    result = solve(OBSERVATION)
    for row in result:
        print(''.join(row))
