    return None

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    N = len(region_grid)
    # Preprocess region info
    regions = defaultdict(list)
    region_clue = dict()
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            regions[rid].append((r, c))
            if data_grid[r][c] is not None:
                region_clue[rid] = data_grid[r][c]
    # Initialize empty grid
    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    result = backtrack(initial_grid, regions, region_clue, region_grid, N)
    return result if result is not None else "No Solution"

