from collections import defaultdict

def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(data)

    # Precompute list of cells per region
    region_cells = {}
    for r in range(N):
        for c in range(N):
            reg_id = region[r][c]
            if reg_id not in region_cells:
                region_cells[reg_id] = []
            region_cells[reg_id].append((r, c))

    # Initialize possible values for each cell
    possible = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                possible[r][c].add(data[r][c])
            else:
                possible[r][c] = set(range(1, N+1))

    def backtrack(poss):
        # Create deep copy of possible values to modify
        curr_poss = [[s.copy() for s in row] for row in poss]

        while True:
            changed = False

            # Step 1: Process naked singles (only one possible value for cell)
            for r in range(N):
                for c in range(N):
                    if len(curr_poss[r][c]) == 1:
                        val = next(iter(curr_poss[r][c]))
                        # Remove value from same row
                        for col in range(N):
                            if col != c and val in curr_poss[r][col]:
                                curr_poss[r][col].remove(val)
                                changed = True
                        # Remove value from same column
                        for row in range(N):
                            if row != r and val in curr_poss[row][c]:
                                curr_poss[row][c].remove(val)
                                changed = True
                        # Remove value from same region
                        reg_id = region[r][c]
                        for (rr, cc) in region_cells[reg_id]:
                            if (rr, cc) != (r, c) and val in curr_poss[rr][cc]:
                                curr_poss[rr][cc].remove(val)
                                changed = True

            # Early exit if any cell has no possible values
            for r in range(N):
                for c in range(N):
                    if len(curr_poss[r][c]) == 0:
                        return None

            # Step 2: Process hidden singles (only one possible cell for value in row/col/region)
            # Check rows
            for r in range(N):
                val_pos = defaultdict(list)
                for c in range(N):
                    for v in curr_poss[r][c]:
                        val_pos[v].append(c)
                for v, positions in val_pos.items():
                    if len(positions) == 1:
                        c = positions[0]
                        if len(curr_poss[r][c]) > 1:
                            curr_poss[r][c] = {v}
                            changed = True

            # Check columns
            for c in range(N):
                val_pos = defaultdict(list)
                for r in range(N):
                    for v in curr_poss[r][c]:
                        val_pos[v].append(r)
                for v, positions in val_pos.items():
                    if len(positions) == 1:
                        r = positions[0]
                        if len(curr_poss[r][c]) > 1:
                            curr_poss[r][c] = {v}
                            changed = True

            # Check regions
            for reg_id in region_cells:
                val_pos = defaultdict(list)
                for (r, c) in region_cells[reg_id]:
                    for v in curr_poss[r][c]:
                        val_pos[v].append((r, c))
                for v, positions in val_pos.items():
                    if len(positions) == 1:
                        r, c = positions[0]
                        if len(curr_poss[r][c]) > 1:
                            curr_poss[r][c] = {v}
                            changed = True

            # Early exit if any cell has no possible values
            for r in range(N):
                for c in range(N):
                    if len(curr_poss[r][c]) == 0:
                        return None

            # Stop propagation if no more changes
            if not changed:
                break

        # Check if puzzle is fully solved
        solved = True
        result = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if len(curr_poss[r][c]) != 1:
                    solved = False
                    break
                result[r][c] = next(iter(curr_poss[r][c]))
            if not solved:
                break
        if solved:
            return result

        # Find cell with minimum number of possible values for branching
        min_len = N + 1
        min_cell = None
        for r in range(N):
            for c in range(N):
                l = len(curr_poss[r][c])
                if l > 1 and l < min_len:
                    min_len = l
                    min_cell = (r, c)

        r, c = min_cell
        # Try each possible value for the cell
        for val in sorted(curr_poss[r][c]):
            new_poss = [[s.copy() for s in row] for row in curr_poss]
            new_poss[r][c] = {val}
            sub_result = backtrack(new_poss)
            if sub_result is not None:
                return sub_result

        # No valid solution for this branch
        return None

    final_result = backtrack(possible)
    return final_result if final_result is not None else "No Solution"

